  (*** The full-sized Newton step ***)

  X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [38] (37--39) THEN

  X86_STEPS_TAC BIGNUM_MOD_EXEC (40--41) THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP APPROXIMATE_WORD_USHR) THEN
  ASM_REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`t42:int64`; `e42:real`] THEN STRIP_TAC THEN

  X86_STEPS_TAC BIGNUM_MOD_EXEC [42] THEN
  REABBREV_TAC `bf = read RAX s42` THEN

  SUBGOAL_THEN
   `?e. &0 <= e /\ e <= &1 /\
        &(val(bf:int64)):real =
        (&2 pow 127 - &(val(a:int64)) * &(val(z3:int64))) / &2 pow 60 - e`
  (X_CHOOSE_THEN `e32:real` STRIP_ASSUME_TAC) THENL
   [MP_TAC(SPEC `&2 pow 127 - &(val(a:int64)) * &(val(z3:int64)):real`
          INTEGER_POS) THEN
    ANTS_TAC THENL [ASM BOUNDER_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
    ANTS_TAC THENL [REAL_INTEGER_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `d3:num`) THEN
    SUBGOAL_THEN `&d3:real <= &2 pow 88 - &1` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
      ASM BOUNDER_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `d3 < 2 EXP 88` ASSUME_TAC THENL
     [ASM BOUNDER_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `1 <= d3` ASSUME_TAC THENL
     [REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN
      REWRITE_TAC[GSYM REAL_OF_NUM_EQ] THEN
      FIRST_X_ASSUM(fun th ->
        GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [SYM th]) THEN
      REWRITE_TAC[REAL_OF_NUM_CLAUSES; REAL_SUB_0] THEN
      DISCH_THEN(MP_TAC o SYM) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[GSYM int_of_num_th] THEN
    SUBGOAL_THEN `&(val(bf:int64)):int = &((d3 - 1) DIV 2 EXP 60)`
    SUBST1_TAC THENL
     [EXPAND_TAC "bf" THEN
      SIMP_TAC[GSYM WORD_SUBWORD_NOT; GSYM WORD_JOIN_NOT;
               DIMINDEX_64; DIMINDEX_128; ARITH] THEN
      SIMP_TAC[VAL_WORD_SUBWORD_JOIN; DIMINDEX_64; DIMINDEX_128;
               ARITH_LE; ARITH_LT] THEN
      REWRITE_TAC[GSYM INT_OF_NUM_CLAUSES; GSYM INT_OF_NUM_REM;
                  GSYM INT_OF_NUM_DIV; INT_VAL_WORD_NOT; DIMINDEX_64] THEN
      REWRITE_TAC[INT_ARITH
        `e * (e - &1 - h) + e - &1 - l:int = e * e - &1 - (e * h + l)`] THEN
      SIMP_TAC[INT_DIV_REM; INT_POS; INT_POW_LE; GSYM INT_POW_ADD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_ADD_CONV) THEN
      ACCUMULATOR_POP_ASSUM_LIST(MP_TAC o end_itlist CONJ) THEN
      FIRST_ASSUM(MP_TAC o check (is_eq o concl)) THEN
      REWRITE_TAC[IMP_IMP; REAL_EQ_SUB_RADD] THEN
      GEN_REWRITE_TAC (LAND_CONV o DEPTH_CONV) [REAL_OF_NUM_CLAUSES] THEN
      GEN_REWRITE_TAC (LAND_CONV o TOP_DEPTH_CONV)
       [GSYM INT_OF_NUM_CLAUSES] THEN
      REWRITE_TAC[GSYM INT_EQ_SUB_RADD] THEN DISCH_THEN(fun th ->
        REWRITE_TAC[th; INT_ARITH
        `&2 pow 128 - &1 - x:int = (&2 pow 127 - &1) + &2 pow 127 - x`]) THEN
      SUBGOAL_THEN `(&2 pow 127 - &1 + &d3) rem &2 pow 124 = &(d3 - 1)`
      SUBST1_TAC THENL
       [ASM_SIMP_TAC[GSYM INT_OF_NUM_SUB] THEN MATCH_MP_TAC INT_REM_UNIQ THEN
        EXISTS_TAC `&8:int` THEN CONJ_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[INT_SUB_LE; INT_LT_SUB_RADD] THEN
        REWRITE_TAC[INT_OF_NUM_CLAUSES; INT_ABS_NUM] THEN
        REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN ASM BOUNDER_TAC[];
        REWRITE_TAC[INT_OF_NUM_DIV; INT_OF_NUM_CLAUSES] THEN ARITH_TAC];
      ASM_REWRITE_TAC[int_of_num_th]] THEN
    EXISTS_TAC `&((d3 - 1) MOD 2 EXP 60 + 1):real / &2 pow 60` THEN
    SIMP_TAC[REAL_LE_DIV; REAL_POW_LE; REAL_POS] THEN CONJ_TAC THENL
     [SIMP_TAC[REAL_LE_LDIV_EQ; REAL_LT_POW2] THEN
      REWRITE_TAC[REAL_OF_NUM_CLAUSES] THEN ARITH_TAC;
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES; REAL_OF_NUM_MOD] THEN
      ASM_SIMP_TAC[GSYM REAL_OF_NUM_SUB; LE_1] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN

  X86_STEPS_TAC BIGNUM_MOD_EXEC [43] THEN
  FIRST_X_ASSUM(ASSUME_TAC o GEN_REWRITE_RULE RAND_CONV [WORD_MUL_SYM]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[WORD_MUL_MADD_LEMMA]) THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP APPROXIMATE_WORD_MUL) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [ASM PURE_BOUNDER_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `t44:int64` STRIP_ASSUME_TAC) THEN

  X86_STEPS_TAC BIGNUM_MOD_EXEC (44--45) THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP APPROXIMATE_WORD_USHR) THEN
  ASM_REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`t46:int64`; `e46:real`] THEN STRIP_TAC THEN

  X86_STEPS_TAC BIGNUM_MOD_EXEC [46] THEN

  (*** Analysis of provisional result w before the final truncation ***)

  ABBREV_TAC `w = 2 * val(z3:int64) + val(t46:int64)` THEN
  SUBGOAL_THEN
   `&2 pow 128 - &2 pow 62 <= &(val(a:int64)) * &w + &(val a) /\
    &(val(a:int64)) * &w <= &2 pow 128`
  STRIP_ASSUME_TAC THENL
   [ABBREV_TAC `d3 = &2 pow 127 - &(val(a:int64)) * &(val(z3:int64))` THEN
    SUBGOAL_THEN `&0 <= d3 /\ d3:real <= &2 pow 88 - &1` STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "d3" THEN ASM PURE_BOUNDER_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "w" THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
    ASM_REWRITE_TAC[REAL_ARITH
     `a * (&2 * z + ((z / &2 pow 33 - d) * c) / &2 pow 33 - f):real =
      (a * z) * (&2 + c / &2 pow 66) - d * c * a / &2 pow 33 - a * f`] THEN
    FIRST_X_ASSUM(SUBST1_TAC o MATCH_MP (REAL_ARITH
       `&2 pow 127 - a * z = d ==> a * z:real = &2 pow 127 - d`)) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(REAL_ARITH
       `&0 <= a * (&1 - e) /\ l <= b - c
        ==> l:real <= b - c - a * e + a`) THEN
      CONJ_TAC THENL [ASM PURE_BOUNDER_TAC[]; ASM BOUNDER_TAC[]];
      REWRITE_TAC[REAL_ARITH
       `(&2 pow 127 - d) * (&2 + (d / &2 pow 60 - e) / &2 pow 66) =
        (&2 pow 254 - d pow 2) / &2 pow 126 -
        (&2 pow 127 - d) * e / &2 pow 66`] THEN
      SUBST1_TAC(SYM(ASSUME `&(val(bf:int64)) = d3 / &2 pow 60 - e32`)) THEN
      ASM PURE_BOUNDER_TAC[]];
    ALL_TAC] THEN

  (*** Now the computed result with implicit 1 bit ***)

  ABBREV_TAC `z:int64 = word_add (word_shl z3 1) t46` THEN
  SUBGOAL_THEN `&w:real = (&2 pow 64) + &(val(z:int64))` SUBST_ALL_TAC THENL
   [EXPAND_TAC "z" THEN REWRITE_TAC[VAL_WORD_ADD; VAL_WORD_SHL] THEN
    REWRITE_TAC[DIMINDEX_64; EXP_1] THEN CONV_TAC MOD_DOWN_CONV THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `2 EXP 64 <= w /\ w < 2 * 2 EXP 64` MP_TAC THENL
     [REWRITE_TAC[GSYM REAL_OF_NUM_LT; ARITH_RULE `a <= b <=> a < b + 1`];
      SIMP_TAC[GSYM NOT_LE; MOD_CASES; GSYM REAL_OF_NUM_SUB] THEN
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REAL_ARITH_TAC] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN CONJ_TAC THEN
    (MATCH_MP_TAC REAL_LT_LCANCEL_IMP THEN EXISTS_TAC `&(val(a:int64))` THEN
     CONJ_TAC THENL [ASM BOUNDER_TAC[]; ALL_TAC])
    THENL
     [REWRITE_TAC[REAL_ARITH `a * (w + &1):real = a * w + a`] THEN
      TRANS_TAC REAL_LTE_TRANS `&2 pow 128 - &2 pow 62`;
      TRANS_TAC REAL_LET_TRANS `&2 pow 128`] THEN
    ASM_REWRITE_TAC[] THEN ASM BOUNDER_TAC[];
    ALL_TAC] THEN

  (*** In this non-trivial case the increment does not wrap ***)

  X86_STEPS_TAC BIGNUM_MOD_EXEC (47--49) THEN
  REABBREV_TAC `z' = read R9 s49` THEN
  SUBGOAL_THEN `&(val(z':int64)):real = &(val(z:int64)) + &1` ASSUME_TAC THENL
   [EXPAND_TAC "z'" THEN
    SUBGOAL_THEN `val(z:int64) + 1 < 2 EXP 64` MP_TAC THENL
     [REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES];
      SIMP_TAC[GSYM NOT_LT; BITVAL_CLAUSES; ADD_CLAUSES] THEN
      SIMP_TAC[WORD_SUB_0; VAL_WORD_ADD_CASES; DIMINDEX_64; VAL_WORD_1] THEN
      REWRITE_TAC[REAL_OF_NUM_CLAUSES]] THEN
    MATCH_MP_TAC(REAL_ARITH
     `(&2 pow 63 + &1) * (&2 pow 64 + z) <= &2 pow 128
      ==> z + &1 < &2 pow 64`) THEN
    TRANS_TAC REAL_LE_TRANS
     `&(val(a:int64)) * (&2 pow 64 + &(val(z:int64)))` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THEN ASM BOUNDER_TAC[];
    ALL_TAC] THEN

  (*** The final bounds check and selection ***)

  X86_STEPS_TAC BIGNUM_MOD_EXEC (50--53) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[REAL_LT_RDIV_EQ; REAL_LE_LDIV_EQ;
               REAL_ARITH `&2 pow 63 + &1 <= a ==> &0 < a`] THEN
  GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [REAL_MUL_SYM] THEN
  GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [REAL_MUL_SYM] THEN
  REWRITE_TAC[VAL_WORD_ZX_GEN; VAL_WORD_USHR; VAL_WORD; ADD_CLAUSES] THEN
  SIMP_TAC[DIMINDEX_64; DIMINDEX_128; MOD_LT; VAL_BOUND_64; LT_MULT2;
           ARITH_RULE `a < 2 EXP 64 * 2 EXP 64
                       ==> a DIV 2 EXP 64 < 2 EXP 64 /\ a < 2 EXP 128`;
           ARITH_RULE `2 EXP 64 <= h DIV 2 EXP 64 + a <=>
                       2 EXP 128 <= 2 EXP 64 * a + h`] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
  REWRITE_TAC[REAL_OF_NUM_CLAUSES; LT_LE] THEN ASM_REWRITE_TAC[] THEN
  ASM_REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES; bitval] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[WORD_SUB_0] THENL
   [ALL_TAC; ASM_REAL_ARITH_TAC] THEN
  REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1; DIMINDEX_64] THEN
  ONCE_REWRITE_TAC[COND_RAND] THEN SIMP_TAC[GSYM REAL_OF_NUM_SUB] THEN
  ASM_REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN ASM_REAL_ARITH_TAC);;

(* x86 BIGNUM_MOD_X86_RECIP_WIDE -- lift BIGNUM_MOD_X86_RECIP_BLOCK to the full bignum_mod frame,
   threading preserved state (z,m,x mem; RSI/R8/RDI; k-slot; p-slot rsp+48) through the recip block.
   Port of ARM BIGNUM_MOD_RECIP_WIDE (bignum_mod_final.ml:6848): MP the block + ENSURES_INIT +
   X86_BIGSTEP_TAC (consumes the block as one macro-step, NO re-sim of the ~53 recip instrs).

   sim 0xbe(pc+190) -> 0x186(pc+390).  Input: RBX=R11=t0 (rounded window from WINUP), p in
   pp-slot(rsp+48).  Output: w in ww-slot(rsp+40) with the real-division bracket
     bit 63 t0 ==> 2^64 + w < 2^128/t0 <= 2^64 + w + 1.
   Requires BIGNUM_MOD_X86_RECIP_BLOCK loaded first (x86_recip_block_candidate.ml).

   LESSON (cont112): the block POST states the bracket on the STORED SLOT value
   read(memory:>bytes64(rsp+40)) (NOT on read R9), because BIGSTEP abstracts away the store->slot
   link -- putting the bracket on R9 leaves an unprovable `read(slot)=read R9` gap in WIDE.
   Both RBX and R11 must equal t0 at entry (WINUP tail: mov rax,r11; mov r11,rbx => R11=RBX=t0). *)

let BIGNUM_MOD_X86_RECIP_WIDE = prove
 (`!k z n x m a b p t0 pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (x,8 * n) (stackpointer,72)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0xbe) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read RBX s = t0 /\ read R11 s = t0 /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s = 0)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x186) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s = 0 /\
            (bit 63 t0
             ==> &2 pow 64 + &(val(read (memory :> bytes64 (word_add stackpointer (word 40))) s)) <
                   &2 pow 128 / &(val t0) /\
                 &2 pow 128 / &(val t0) <=
                   &2 pow 64 + &(val(read (memory :> bytes64 (word_add stackpointer (word 40))) s)) + &1))
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; R9; R11] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bytes(stackpointer,72)])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`t0:int64`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_RECIP_BLOCK) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
  DISCH_THEN(fun th ->
    ENSURES_INIT_TAC "s0" THEN MP_TAC th THEN X86_BIGSTEP_TAC BIGNUM_MOD_EXEC "s1") THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[]);;


(* x86 PREHEADER sim (minimal POST: reachability 0x186->0x217).  Port of ARM BIGNUM_MOD_PREHEADER.
   sim 0x186(pc+390) -> 0x217(pc+535): recip-of-61 block-index, block-count l=word_min(k+1,1)=1,
   top-block load+shift, first-digit store z[0], field h=(p<64?c>>p:0) in hs-slot, R13=p/64+1.

   KEY LESSON (cont112-113): the FIELD shift `shr rax,cl` (0x1fb) STACK-OVERFLOWS under X86_STEPS
   when RAX is the NESTED block-shifted top-block (word_ushr(word_ushr(word(bigdigit..))bs)p).  FIX:
   ENSURES_SEQUENCE at 0x1f6 splitting PREHEADER into seg1 (0x186->0x1f6) + seg2 (0x1f6->0x217);
   seg1's POST COLLAPSES R11 (block-shifted top word) to a CLEAN word((bigdigit a(n-1)) DIV 2^(bs MOD
   64)) via USHR_WORD_FOLD; then in seg2 the field shift operates on a clean word -> no overflow.
   (A clean word(<num>) operand shifts fine even by symbolic amount; only NESTED word_ushr blows up.)

   Needs: scaffold (Section B: X16_EQ, X7_ID, UDIV61_WORD, BIGDIGIT_BIGNUM_FROM_MEMORY, ...) +
   x86_preheader_helpers.ml (BLOCKSHIFT_FOLD, USHR_WORD_FOLD, PSHIFT_AMT, ...).

   NOTE: this is the MINIMAL (reachability) POST.  The FULL mainloop-entry invariant (RBX=block-shift,
   R12=word 1, R13=p/64+1, hs-slot=field, C0_ID congruence 2^(64k)*carry+z = a DIV 2^blockstart) is a
   straightforward enrichment of the POST -- all intermediate values are already computed in this proof
   (RBX/R12/R13/R11/field all appear in the seg1/seg2 states); just widen the POST conjuncts + close
   each from the corresponding state hyp (block-shift via BLOCKSHIFT_FOLD, field via the seg2 field
   value + SHL_AMT8/USHR_WORD_FOLD, congruence via C0_ID as in ARM PREHEADER final:6983-7014). *)

let WINDOW_FIELD_CLOSE = prove
 (`!V0 p:num. V0 < 2 EXP 64
      ==> (if 64 <= p then word 0 else word_ushr (word V0:int64) (p MOD 64)) =
          word ((V0 DIV 2 EXP p) MOD 2 EXP 64)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL
   [SUBGOAL_THEN `V0 DIV 2 EXP p = 0` SUBST1_TAC THENL
     [MATCH_MP_TAC DIV_LT THEN TRANS_TAC LTE_TRANS `2 EXP 64` THEN
      ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN ASM_ARITH_TAC;
      REWRITE_TAC[MOD_0]];
    SUBGOAL_THEN `p MOD 64 = p` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `word_ushr (word V0:int64) p = word (V0 DIV 2 EXP p)` SUBST1_TAC THENL
     [MATCH_MP_TAC USHR_WORD_FOLD THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN MATCH_MP_TAC MOD_LT THEN
    TRANS_TAC LET_TRANS `V0:num` THEN ASM_REWRITE_TAC[DIV_LE]]);;

let BIGNUM_MOD_X86_PREHEADER = prove
 (`!k z n x m a b w p pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 64 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 60 /\ 1 <= n /\ a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (x,8 * n) (stackpointer,72)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x186) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s = 0)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x217) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read RBX s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read R12 s = word 1 /\ read R13 s = word (p DIV 64 + 1) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 56))) s = word 61 /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s = a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11; RBX; R12; R13] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bytes(stackpointer,72); memory :> bytes(z,8*k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  (* global facts: I0_DIV64 (i0 DIV 64 = n-1), C0_ID (a DIV 2^i0 = block DIV 2^(i0 MOD64)),
     and V0 = a DIV 2^(61 NB) < 2^61 (< 2^64) for the z-assembly word-fit. *)
  MP_TAC(SPEC `n:num` I0_DIV64) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`a:num`;`n:num`;`61 * ((64 * n + 60) DIV 61 - 1)`] C0_ID) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `64 * n <= 61 + 61 * ((64 * n + 60) DIV 61 - 1)` ASSUME_TAC THENL
   [MP_TAC(SPECL [`64 * n`; `61`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN
    UNDISCH_TAC `1 <= n` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) < 2 EXP 61` ASSUME_TAC THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REWRITE_TAC[GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `2 EXP (64 * n)` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[]; REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
      UNDISCH_TAC `64 * n <= 61 + 61 * ((64 * n + 60) DIV 61 - 1)` THEN ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) < 2 EXP 64` ASSUME_TAC THENL
   [TRANS_TAC LT_TRANS `2 EXP 61` THEN ASM_REWRITE_TAC[LT_EXP] THEN ARITH_TAC; ALL_TAC] THEN
  (* ===== SEGMENT 1: 0x186 -> 0x1f6.  POST: R11=word V0 (C0-folded), bignum(z,k)=V0 assembled. ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x1f6`
   `\s. read RIP s = word (pc + 0x1f6) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read RCX s = word p /\
        read R11 s = word (a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1))) /\
        read RBX s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
        read R12 s = word 1 /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 56))) s = word 61 /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[SOME_FLAGS; BIGNUM_FROM_MEMORY_BYTES] THEN ENSURES_INIT_TAC "s0" THEN
    (* z tail zero: bignum(z+8,k-1)=0 from bignum(z,k)=0 *)
    SUBGOAL_THEN `bignum_from_memory (word_add z (word 8), k - 1) s0 = 0` ASSUME_TAC THENL
     [UNDISCH_TAC `read (memory :> bytes (z,8 * k)) s0 = 0` THEN
      REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES] THEN
      GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [BIGNUM_FROM_MEMORY_EXPAND] THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * (n - 1))))) s0 = word (bigdigit a (n - 1))`
      ASSUME_TAC THENL
     [EXPAND_TAC "a" THEN REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES; BIGDIGIT_BIGNUM_FROM_MEMORY] THEN
      ASM_SIMP_TAC[ARITH_RULE `1 <= n ==> n - 1 < n`; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `val(word n:int64) = n` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `n < 2 EXP 60` THEN ARITH_TAC; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--8) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word n:int64) = n`]) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[MATCH_MP BLOCKSHIFT_FOLD (CONJ (ASSUME `1 <= n`) (ASSUME `n < 2 EXP 60`))]) THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (9--9) THEN
    SUBGOAL_THEN `val(word_add (word k) (word 1):int64) = k + 1` ASSUME_TAC THENL
     [REWRITE_TAC[VAL_WORD_ADD; VAL_WORD_1; VAL_WORD; DIMINDEX_64] THEN
      CONV_TAC MOD_DOWN_CONV THEN MATCH_MP_TAC MOD_LT THEN
      UNDISCH_TAC `8 * k <= 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (10--14) THEN
    SUBGOAL_THEN `1 <= val(word_add (word k) (word 1):int64)` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (15--19) THEN
    SUBGOAL_THEN `1 <= k + 1` ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `1 <= k + 1`]) THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (20--20) THEN
    MP_TAC(SPEC `n:num` X7_ID) THEN
    ANTS_TAC THENL [UNDISCH_TAC `1 <= n` THEN UNDISCH_TAC `n < 2 EXP 60` THEN ARITH_TAC; ALL_TAC] THEN
    STRIP_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_sub (word n) (word 1):int64 = word (n - 1)`]) THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * (n - 1))))) s20 = word (bigdigit a (n - 1))`
      ASSUME_TAC THENL
     [EXPAND_TAC "a" THEN REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES; BIGDIGIT_BIGNUM_FROM_MEMORY] THEN
      ASM_SIMP_TAC[ARITH_RULE `1 <= n ==> n - 1 < n`; WORD_VAL] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s20`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ] THEN REWRITE_TAC[ASSIGNS_THM] THEN
      REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT GEN_TAC THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (21--25) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    (* residuals (verified cont129): R11-fold (block-shift word = word V0) and z-assembly (bignum(z,k)=V0).
       Both RHS carry `bigdigit.. DIV 2^(..MOD64)`; fold to `a DIV 2^(61 NB)` via C0_ID (PURE_ONCE) for
       R11, direct expand for z (z[1..]=0 preserved s0->s25). *)
    CONJ_TAC THENL
     [(* R11 fold: turn RHS `word(a DIV..)` into `word(bigdigit.. DIV..)` via C0_ID, PSHIFT_AMT, USHR. *)
      PURE_ONCE_REWRITE_TAC[ASSUME `a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) =
          bigdigit a (n - 1) DIV 2 EXP ((61 * ((64 * n + 60) DIV 61 - 1)) MOD 64)`] THEN
      REWRITE_TAC[PSHIFT_AMT] THEN
      MATCH_MP_TAC USHR_WORD_FOLD THEN REWRITE_TAC[BIGDIGIT_BOUND] THEN
      MP_TAC(SPECL [`61 * ((64 * n + 60) DIV 61 - 1)`; `64`] MOD_LT_EQ) THEN REWRITE_TAC[ARITH_EQ];
      (* z-assembly: bignum(z,k) = val(z[0]) + 2^64*bignum(z+8,k-1) = V0 + 0.  z-tail preserved s0->s25. *)
      SUBGOAL_THEN `read (memory :> bytes (word_add z (word 8), 8 * (k - 1))) s25 =
                    read (memory :> bytes (word_add z (word 8), 8 * (k - 1))) s0` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o check (can
          (term_match [] `(f:x86state->x86state->bool) s0 s25`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ] THEN REWRITE_TAC[ASSIGNS_THM] THEN
        REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT GEN_TAC THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES] THEN
      GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_EXPAND] THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[PSHIFT_AMT] THEN
      SUBGOAL_THEN `word_ushr (word (bigdigit a (n - 1)):int64)
                      ((61 * ((64 * n + 60) DIV 61 - 1)) MOD 64) =
                    word (bigdigit a (n - 1) DIV 2 EXP ((61 * ((64 * n + 60) DIV 61 - 1)) MOD 64))`
        SUBST1_TAC THENL
       [MATCH_MP_TAC USHR_WORD_FOLD THEN REWRITE_TAC[BIGDIGIT_BOUND] THEN
        MP_TAC(SPECL [`61 * ((64 * n + 60) DIV 61 - 1)`; `64`] MOD_LT_EQ) THEN REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
      SUBGOAL_THEN `bignum_from_memory (word_add z (word 8),k - 1) s25 = 0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        ASM_REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES]; ALL_TAC] THEN
      REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; VAL_WORD; DIMINDEX_64] THEN
      MATCH_MP_TAC MOD_LT THEN
      TRANS_TAC LET_TRANS `bigdigit a (n - 1)` THEN REWRITE_TAC[DIV_LE; BIGDIGIT_BOUND]];
    (* ===== SEGMENT 2: 0x1f6 -> 0x217 (field h into sp+64 + R13); clean R11=word V0 operand.  seg2 PRE
       carries bignum(z,k)=V0 (V0:=a DIV 2^(61 NB)) and R11=word V0; only sp+56/sp+64/R13 written, so
       x/m/z bignums PRESERVED (z-bignum reconciled s9->s0 via BIGNUM_FROM_MEMORY frame). ===== *)
    REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
    (* V0 := a DIV 2^(61 NB) < 2^64 (banked in seg1 opening).  Simulate; the field store lands
       `read(sp+64) s9 = if 64<=val(word p) then word 0 else word_ushr(word V0-form)(val(word(val(word p)
       MOD256))MOD64)` -- resolvable ONLY because seg1 POST pins read RCX=word p (the shr count). *)
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--9) THEN ENSURES_FINAL_STATE_TAC THEN
    (* val(word p)=p to normalize field shift-count / cmp; PSHIFT_AMT folds the 256/64-wrapped shift amt. *)
    SUBGOAL_THEN `val(word p:int64) = p` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
    ASM_REWRITE_TAC[PSHIFT_AMT] THEN
    REPEAT CONJ_TAC THENL
     [(* R13 = word(p/64+1) via X12_ID *)
      MATCH_MP_TAC X12_ID THEN ASM_REWRITE_TAC[];
      (* window sp+64: (if 64<=p then 0 else V0f>>>(p MOD64)) = word((V0f DIV 2^p)MOD..).  Fold C0 to
         V0-form (a DIV 2^(61 NB)) both sides, then WINDOW_FIELD_CLOSE (V0<2^64 banked, asm). *)
      REWRITE_TAC[GSYM(ASSUME `a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) =
          bigdigit a (n - 1) DIV 2 EXP ((61 * ((64 * n + 60) DIV 61 - 1)) MOD 64)`)] THEN
      MATCH_MP_TAC WINDOW_FIELD_CLOSE THEN FIRST_ASSUM ACCEPT_TAC;
      (* x-bignum s9 = a: x not written in seg2, reconcile s9->s0 via frame, then asm. *)
      SUBGOAL_THEN `bignum_from_memory(x,n) s9 = bignum_from_memory(x,n) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can
          (term_match [] `(f:x86state->x86state->bool) s0 s9`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ] THEN REWRITE_TAC[ASSIGNS_THM] THEN
        REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT GEN_TAC THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
        ASM_REWRITE_TAC[]];
      (* m-bignum s9 = b: same reconcile. *)
      SUBGOAL_THEN `bignum_from_memory(m,k) s9 = bignum_from_memory(m,k) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can
          (term_match [] `(f:x86state->x86state->bool) s0 s9`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ] THEN REWRITE_TAC[ASSIGNS_THM] THEN
        REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT GEN_TAC THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
        ASM_REWRITE_TAC[]];
      (* V-equation: 2^(64k)*val(word 0) + bignum(z,k) s9 = V0.  val(word 0)=0; z reconciled s9->s0 +
         asm bignum(z,k) s0 = a DIV.. + C0-fold. *)
      REWRITE_TAC[VAL_WORD_0; MULT_CLAUSES; ADD_CLAUSES] THEN
      SUBGOAL_THEN `bignum_from_memory(z,k) s9 = bignum_from_memory(z,k) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can
          (term_match [] `(f:x86state->x86state->bool) s0 s9`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ] THEN REWRITE_TAC[ASSIGNS_THM] THEN
        REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT GEN_TAC THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
        ASM_REWRITE_TAC[]]]]);;


(* x86 INNERLOOP sim (simplified POST: core product-subtract congruence, NO lf/hf logging yet).
   Port of ARM BIGNUM_MOD_INNERLOOP_LOG (final:7272).  Inner multiply-subtract loop over ii=0..dd
   (dd = l-1, the # of z-limbs active this block; 1<=dd for non-first blocks).
   sim 0x265(pc+613) -> 0x2a3(pc+675).  x86 body (0x265..0x29e, 16 instrs):
     mov m[ii],rax; not rax; mul q(rbp); mov z[ii],rcx; add r9(hh),rcx; mov rdx,r9; adc r9,0;
     add rax,rcx; adc r9,0; shrd r11,rcx,3 (funnel top-61); mov r11,z[ii]; cmp r10,pc(r13);
     cmovb lf,r11; cmove hf,r11; mov rcx,r11; inc r10; [cmp rdi,r10; jne @0x29e].
   Register map: RDI=dd, RSI=z, R8=m, R10=ii, RBP=q, R9=hh, R11=funnel(entry 2^3*block), R13=pcode.

   KEY LESSONS (cont113):
   - X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [3;5;7;8;9] (1--16): acc-steps = mul@3, add-r9@5, adc@7,
     add-rax@8, adc@9 (the 2 carry adcs + the initial adds + mul).  Produces acc hyps
     carry_s5/sum_s5, carry_s7/sum_s7, carry_s8/sum_s8, carry_s9/sum_s9, mulhi_s3/mullo_s3.
   - x86 has a 2-STEP high carry (s7 then s9) where ARM NEGADD_STEP wants 1-step (cb9).  Bridge:
     first derive `2^64*(carry_s7+carry_s9)+sum_s9 = carry_s5+mulhi_s3+carry_s8` by REAL_ARITH on
     the two linear carry eqns (hyps 24+26, LINEAR so REAL_ARITH ok), and cb7+cb9<=1; then feed
     NEGADD_STEP with cb9:=carry_s7+carry_s9.
   - Do NOT derive the mul-add relation by raw REAL_ARITH/REAL_RING (nonlinear q*~bi atom fails).
     Use NEGADD_STEP (scaffold): ISPECL [bigdigit zorig i; val hhin; q; 2^64-1-bigdigit b i; sum_s5;
     sum_s8; sum_s9; mullo_s3; mulhi_s3; carry_s5; carry_s8; carry_s7+carry_s9] -> gives
     `2^64*val sum_s9 + val sum_s8 = bigdigit zorig i + val hhin + q*(2^64-1-bigdigit b i)`.
   - Funnel: SUBST GSYM WORD_VAL on sum_s8,cwin; REWRITE[EXTR_FUNNEL_VAL] (matches word_subword
     (word_join(word ss)(word c))(3,64)); then REWRITE[VAL_WORD;DIMINDEX_64] (NOT WORD_VAL, which
     un-does it); SIMP[MOD_LT;VAL_BOUND_64] to drop redundant MOD 2^64.  Then MP INNER_ADVANCE_ADD.
   - Frame preservation (bignum(m,k), z-tail, bignum(z,i)) via the standard MAYCHANGE pull +
     READ_OVER_WRITE_ORTHOGONAL_TAC.

   Needs scaffold (INNER_ADVANCE_ADD, NEGADD_STEP, EXTR_FUNNEL_VAL, BIGDIGIT_BIGNUM_FROM_MEMORY,
   BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS, all 0-hyp).

   TODO for full-mainloop composability: re-add the lf/hf logging conjuncts to the invariant + POST
   (the cmovb lf,r11 / cmove hf,r11) via LF_STEP / HF_STEP_G_POS / HF_STEP_G_NEG (scaffold), mirroring
   ARM INNERLOOP_LOG's X13/X14 logging (final:7288-7312, 7434-7460). *)

(* helper: recognize an accumulator equation for the carry-combine step *)
let isacc th = can (term_match [] `&2 pow 64 * x = y`) (concl th);;

let test_bridge = prove
 (`!i pcode. i < 2 EXP 64 /\ pcode < 2 EXP 64
      ==> ((val(word_sub (word i:int64) (word pcode)) = 0) <=> i = pcode)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[VAL_EQ_0] THEN
  REWRITE_TAC[WORD_SUB_EQ_0] THEN
  ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]);;

let MMADD = prove
 (`!m p q r. r < m ==> (m * q + r) MOD (m * p) = m * (q MOD p) + r`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `p = 0` THENL [ASM_REWRITE_TAC[MULT_CLAUSES; MOD_ZERO]; ALL_TAC] THEN
  MP_TAC(SPECL [`q:num`;`p:num`] DIVISION) THEN ASM_REWRITE_TAC[] THEN ABBREV_TAC `Q = q DIV p` THEN
  ABBREV_TAC `R = q MOD p` THEN STRIP_TAC THEN
  SUBGOAL_THEN `m * q + r = (m * p) * Q + (m * R + r)` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[MOD_MULT_ADD] THEN MATCH_MP_TAC MOD_LT THEN
  SUBGOAL_THEN `m * (R + 1) <= m * p` MP_TAC THENL
   [REWRITE_TAC[LE_MULT_LCANCEL] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[LEFT_ADD_DISTRIB; MULT_CLAUSES] THEN ASM_ARITH_TAC);;

(* the two-word funnel value bridge: split-form (from VAL_WORD_SUBWORD_JOIN_64) = DIV-form (for BLOCKLOAD_MASKED). *)
let JOIN_DIV_BRIDGE = prove
 (`!H L rw. rw < 64 /\ L < 2 EXP 64
     ==> ((2 EXP 64 * H + L) DIV 2 EXP rw) MOD 2 EXP 64 =
         2 EXP (64 - rw) * H MOD 2 EXP rw + L DIV 2 EXP rw`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `2 EXP 64 * H = 2 EXP rw * (2 EXP (64 - rw) * H)` ASSUME_TAC THENL
   [REWRITE_TAC[MULT_ASSOC; GSYM EXP_ADD] THEN AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM_SIMP_TAC[DIV_MULT_ADD; EXP_EQ_0; ARITH_EQ] THEN
  SUBGOAL_THEN `2 EXP 64 = 2 EXP (64 - rw) * 2 EXP rw` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM EXP_ADD] THEN AP_TERM_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `L DIV 2 EXP rw < 2 EXP (64 - rw)` ASSUME_TAC THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
    SUBGOAL_THEN `rw + 64 - rw = 64` SUBST1_TAC THENL [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(SPECL [`2 EXP (64 - rw)`; `2 EXP rw`; `H:num`; `L DIV 2 EXP rw`] MMADD) THEN ASM_REWRITE_TAC[]);;

(* word_shl (word V) 3 = word(2^3 * (V MOD 2^61)) -- the <<3 with low-61 masking. *)
let SHL3_MOD = prove
 (`!V. word_shl (word V:int64) 3 = word (2 EXP 3 * (V MOD 2 EXP 61))`,
  GEN_TAC THEN REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_SHL; VAL_WORD; DIMINDEX_64] THEN
  CONV_TAC MOD_DOWN_CONV THEN REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN
  SUBGOAL_THEN `(2 EXP 3 * V) MOD 2 EXP 64 = 2 EXP 3 * (V MOD 2 EXP 61)`
    (fun t -> GEN_REWRITE_TAC LAND_CONV [t]) THENL
   [SUBGOAL_THEN `2 EXP 64 = 2 EXP 3 * 2 EXP 61` SUBST1_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN REWRITE_TAC[MOD_MULT2] THEN ARITH_TAC; ALL_TAC] THEN
  CONV_TAC SYM_CONV THEN MATCH_MP_TAC MOD_LT THEN
  MP_TAC(SPECL [`V:num`; `2 EXP 61`] MOD_LT_EQ) THEN REWRITE_TAC[ARITH_EQ] THEN ARITH_TAC);;

let MOD64_MOD61 = prove(`!X. X MOD 2 EXP 64 MOD 2 EXP 61 = X MOD 2 EXP 61`,
  GEN_TAC THEN REWRITE_TAC[MOD_MOD_EXP_MIN] THEN CONV_TAC NUM_REDUCE_CONV);;

(* the FULL funnel->block: x86 shrd-funnel (shl 3) = word(2^3 * block), block = (a DIV 2^(qw*64+rw)) MOD 2^61.
   H = hi word (bigdigit a(qw+1) in general; garbage g in boundary rw<=3), L = lo word = bigdigit a qw.
   (all sub-facts extracted as lemmas -> no nested THENL over the 2 disjunct goals from REPEAT STRIP_TAC.) *)
let FUNNEL_BLOCK = prove
 (`!a qw rw H L.
     rw < 64 /\ H < 2 EXP 64 /\ L = bigdigit a qw /\ (rw <= 3 \/ H = bigdigit a (qw + 1))
     ==> word_shl (word_subword (word_join (word H:int64) (word L:int64):int128) (rw,64):int64) 3 =
         word (2 EXP 3 * (a DIV 2 EXP (qw * 64 + rw)) MOD 2 EXP 61)`,
  REPEAT STRIP_TAC THEN
  SUBST1_TAC(GSYM(ISPEC `word_subword (word_join (word H:int64) (word L:int64):int128) (rw,64):int64` WORD_VAL)) THEN
  REWRITE_TAC[SHL3_MOD] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  MP_TAC(ISPECL [`word H:int64`; `word L:int64`; `rw:num`] VAL_WORD_SUBWORD_JOIN_64) THEN
  ASM_SIMP_TAC[LT_IMP_LE] THEN DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[VAL_WORD_EQ; DIMINDEX_64; BIGDIGIT_BOUND] THEN
  MP_TAC(SPECL [`H:num`; `L:num`; `rw:num`] JOIN_DIV_BRIDGE) THEN
  ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  REWRITE_TAC[MOD64_MOD61] THEN
  ONCE_REWRITE_TAC[ARITH_RULE `qw * 64 + rw = 64 * qw + rw`] THEN
  MP_TAC(SPECL [`a:num`; `qw:num`; `rw:num`; `bigdigit a qw`; `H:num`] BLOCKLOAD_MASKED) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[]);;

(* val(word_and(word V)(word 63)) = V MOD 64. *)
let BH_VAND = prove
 (`!V. val(word_and (word V:int64) (word 63)) = V MOD 64`,
  GEN_TAC THEN
  SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
  REWRITE_TAC[MOD_MOD_EXP_MIN] THEN CONV_TAC NUM_REDUCE_CONV);;

(* the shrd variable-count shift folds to rw: val(word(val(word_and(word(qw*64+rw))(word 63))MOD256):byte)MOD64 = rw. *)
let BH_SHIFT_RW = prove
 (`rw < 64
     ==> val (word (val (word_and (word (qw * 64 + rw):int64) (word 63)) MOD 256):byte) MOD 64 = rw`,
  DISCH_TAC THEN
  SUBGOAL_THEN `val (word_and (word (qw * 64 + rw):int64) (word 63)) = rw` SUBST1_TAC THENL
   [REWRITE_TAC[BH_VAND] THEN ONCE_REWRITE_TAC[ADD_SYM] THEN
    SIMP_TAC[MOD_MULT_ADD; MOD_LT; ASSUME `rw < 64`]; ALL_TAC] THEN
  SUBGOAL_THEN `rw MOD 256 = rw` SUBST1_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word rw:byte) = rw` SUBST1_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_8] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]);;

(* val(word_sub(word l)(word 1)) = l-1, for 2<=l<=k+1<2^58 (jz-branch resolver). *)
let BH_LSUB = prove
 (`2 <= l /\ l <= k + 1 /\ k < 2 EXP 58 ==> val(word_sub (word l:int64) (word 1)) = l - 1`,
  STRIP_TAC THEN
  SUBGOAL_THEN `l < 2 EXP 64` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1; VAL_WORD_EQ; DIMINDEX_64;
               ARITH_RULE `2 <= l ==> 1 <= l`] THEN ASM_ARITH_TAC);;

(* QRECON: the q-setup reconcile.  After the block-head mul (w*h -> hi:lo via imul/mulx) + add h, the
   machine holds RBP = R9 = word_add (word_zx (word_ushr (word (val(word w)*val(word h)):int128) 64)) (word h);
   reconcile to the POST's word(((w*h)DIV2^64+h) MOD 2^64) [q = qhat approximation].  0-hyp (needs w,h<2^64).
   (cont119 RECOVERY: this was a lost interactive binding -- the file referenced it but never defined it,
   so a cold reload failed with Unbound value QRECON.  Reconstructed from the exact step-21 RBP term.) *)
let QRECON = prove
 (`!w h. w < 2 EXP 64 /\ h < 2 EXP 64
     ==> word_add (word_zx (word_ushr (word (val(word w:int64) * val(word h:int64)):int128) 64):int64)
                  (word h) =
         word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[VAL_WORD_EQ; DIMINDEX_64] THEN
  REWRITE_TAC[GSYM VAL_EQ] THEN
  REWRITE_TAC[VAL_WORD_ADD; VAL_WORD_ZX_GEN; VAL_WORD_USHR; VAL_WORD;
              DIMINDEX_64; DIMINDEX_128] THEN
  SUBGOAL_THEN `(w * h) MOD 2 EXP 128 = w * h` SUBST1_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN
    TRANS_TAC LTE_TRANS `2 EXP 64 * 2 EXP 64` THEN CONJ_TAC THENL
     [MATCH_MP_TAC LT_MULT2 THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM EXP_ADD] THEN CONV_TAC NUM_REDUCE_CONV]; ALL_TAC] THEN
  CONV_TAC MOD_DOWN_CONV THEN REFL_TAC);;


let OUTER_PRESV_EQ = prove
 (`nonoverlapping (z,8 * k) (x,8 * n) /\ nonoverlapping (z,8 * k) (stackpointer,72)
   ==> !s s'. (MAYCHANGE [RIP; RAX; RCX; RDX; R9; R10; R11; R14; R15] ,,
               MAYCHANGE [memory :> bignum(z,k)] ,,
               MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events]) s s'
              ==> read RSP s' = read RSP s /\ read RBX s' = read RBX s /\ read R12 s' = read R12 s /\
                  read (memory :> bytes64 stackpointer) s' = read (memory :> bytes64 stackpointer) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 16))) s' = read (memory :> bytes64 (word_add stackpointer (word 16))) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 24))) s' = read (memory :> bytes64 (word_add stackpointer (word 24))) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 32))) s' = read (memory :> bytes64 (word_add stackpointer (word 32))) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 40))) s' = read (memory :> bytes64 (word_add stackpointer (word 40))) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 48))) s' = read (memory :> bytes64 (word_add stackpointer (word 48))) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 56))) s' = read (memory :> bytes64 (word_add stackpointer (word 56))) s /\
                  read (memory :> bytes64 (word_add stackpointer (word 64))) s' = read (memory :> bytes64 (word_add stackpointer (word 64))) s /\
                  bignum_from_memory (x,n) s' = bignum_from_memory (x,n) s`,
  REWRITE_TAC[NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; SOME_FLAGS] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
  REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
  REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  REWRITE_TAC[bignum] THEN REPEAT CONJ_TAC THEN READ_OVER_WRITE_ORTHOGONAL_TAC);;

(* ---- 3. INNERLOOP_LOG with FAT POST (bytes_loaded + RSI/R8/RBP/RDI/R13 + z-tail) ---- *)
let BIGNUM_MOD_X86_INNERLOOP_LOG_WIDE = prove
 (`!k z m dd q block zorig b pc pcode lfin.
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      1 <= dd /\ dd <= k /\ k < 2 EXP 58 /\ q < 2 EXP 64 /\ block < 2 EXP 61 /\
      b < 2 EXP (64 * k) /\ 1 <= pcode /\ pcode < 2 EXP 64
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x265) /\
            read RDI s = word dd /\ read RSI s = z /\ read R8 s = m /\
            read R10 s = word 0 /\ read RBP s = word q /\ read R9 s = word q /\
            read R11 s = word (2 EXP 3 * block) /\
            read R13 s = word pcode /\ read R14 s = lfin /\ read R15 s = word 0 /\
            bignum_from_memory (z,k) s = zorig /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x2a3) /\ read R10 s = word dd /\
            read RSI s = z /\ read R8 s = m /\ read RBP s = word q /\
            read RDI s = word dd /\ read R13 s = word pcode /\
            bignum_from_memory (word_add z (word (8 * dd)), k - dd) s = highdigits zorig dd /\
            (1 <= dd
             ==> read R14 s =
                 read (memory :> bytes64 (word_add z (word (8 * (MIN dd pcode - 1))))) s) /\
            (pcode < dd
             ==> read R15 s = read (memory :> bytes64 (word_add z (word (8 * pcode)))) s) /\
            (~(pcode < dd) ==> read R15 s = word 0) /\
            bignum_from_memory (z,dd) s +
            2 EXP (64 * dd) * (val(read R11 s) DIV 8 + 2 EXP 61 * val(read R9 s)) +
            2 EXP 61 * q * lowdigits b dd =
            block + 2 EXP 61 * lowdigits zorig dd + 2 EXP 61 * q * 2 EXP (64 * dd))
       (MAYCHANGE [RIP; RAX; RCX; RDX; R9; R10; R11; R14; R15] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_WHILE_AUP_TAC `0` `dd:num` `pc + 0x265` `pc + 0x29e`
   `\i s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
          read RDI s = word dd /\ read RSI s = z /\ read R8 s = m /\
          read RBP s = word q /\ read R13 s = word pcode /\
          read R10 s = word i /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (word_add z (word (8 * i)), k - i) s = highdigits zorig i /\
          (1 <= i
           ==> read R14 s =
               read (memory :> bytes64 (word_add z (word (8 * (MIN i pcode - 1))))) s) /\
          (pcode < i
           ==> read R15 s = read (memory :> bytes64 (word_add z (word (8 * pcode)))) s) /\
          (~(pcode < i) ==> read R15 s = word 0) /\
          bignum_from_memory (z,i) s +
          2 EXP (64 * i) * (val(read R11 s) DIV 8 + 2 EXP 61 * val(read R9 s)) +
          2 EXP 61 * q * lowdigits b i =
          block + 2 EXP 61 * lowdigits zorig i + 2 EXP 61 * q * 2 EXP (64 * i)` THEN
  CONJ_TAC THENL
   [UNDISCH_TAC `1 <= dd` THEN ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** ENTRY ***)
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0; WORD_ADD_0; ARITH_RULE `8 * 0 = 0`] THEN
    ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[ARITH_RULE `(1 <= 0) <=> F`; ARITH_RULE `(pcode < 0) <=> F`] THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; HIGHDIGITS_0; LOWDIGITS_0] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; ADD_CLAUSES; DIV_1] THEN
    SUBGOAL_THEN `val(word (2 EXP 3 * block):int64) = 2 EXP 3 * block /\ val(word q:int64) = q`
      (fun th -> REWRITE_TAC[th]) THENL
     [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THENL
       [UNDISCH_TAC `block < 2 EXP 61` THEN ARITH_TAC;
        UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC];
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN SIMP_TAC[DIV_MULT; ARITH_EQ] THEN ARITH_TAC];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** BODY ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN VAL_INT64_TAC `pcode:num` THEN
    SUBGOAL_THEN `i:num < k` ASSUME_TAC THENL
     [UNDISCH_TAC `i:num < dd` THEN UNDISCH_TAC `dd:num <= k` THEN ARITH_TAC; ALL_TAC] THEN
    GHOST_INTRO_TAC `hhin:int64` `read R9` THEN
    GHOST_INTRO_TAC `cwin:int64` `read R11` THEN
    GHOST_INTRO_TAC `lfval:int64` `read R14` THEN
    GHOST_INTRO_TAC `hfval:int64` `read R15` THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
    ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
    REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i + 1)`; BIGNUM_FROM_MEMORY_STEP] THEN
    ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * i)))) s0 = word (bigdigit b i)`
      ASSUME_TAC THENL
     [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
      ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * i)))) s0 = word (bigdigit zorig i)`
      ASSUME_TAC THENL
     [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
      GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [3;5;7;8;9] (1--16) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `i < 2 EXP 64` ASSUME_TAC THENL
     [UNDISCH_TAC `i:num < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(val(word_sub (word i:int64) (word pcode)) = 0) <=> i = pcode` ASSUME_TAC THENL
     [MATCH_MP_TAC test_bridge THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [(* [0]: word_add(word i)(word 1) = word(i+1) *) CONV_TAC WORD_RULE;
      (* [1]: bignum(m,k) preserved *)
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s16`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* [2]: z-tail preserved *)
      REWRITE_TAC[ARITH_RULE `k <= i + 1 <=> k - (i + 1) = 0`;
                  ARITH_RULE `k - ((i + 1) + 1) = k - (i + 1) - 1`] THEN
      GEN_REWRITE_TAC I [GSYM BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0 = highdigits zorig (i+1)` MP_TAC THENL
       [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
        GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
        ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
        REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i+1)`] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s16 =
        bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0`
       (fun th -> ASM_REWRITE_TAC[th]) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s16`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* [3]: LF logging *)
      MATCH_MP_TAC(BETA_RULE(ISPECL
        [`\j. read (memory :> bytes64 (word_add z (word (8 * j)))) s16`;
         `word_subword (word_join (sum_s8:int64) (cwin:int64)) (3,64):int64`;
         `lfval:int64`; `i:num`; `pcode:num`] LF_STEP)) THEN
      ASM_REWRITE_TAC[];
      (* [4]: HF logging positive *)
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(BETA_RULE(ISPECL
        [`\j. read (memory :> bytes64 (word_add z (word (8 * j)))) s16`;
         `word_subword (word_join (sum_s8:int64) (cwin:int64)) (3,64):int64`;
         `hfval:int64`; `i:num`; `pcode:num`] HF_STEP_G_POS)) THEN
      ASM_REWRITE_TAC[NOT_LT];
      (* [5]: HF logging negative *)
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(BETA_RULE(ISPECL
        [`\j. read (memory :> bytes64 (word_add z (word (8 * j)))) s16`;
         `word_subword (word_join (sum_s8:int64) (cwin:int64)) (3,64):int64`;
         `hfval:int64`; `i:num`; `pcode:num`] HF_STEP_G_NEG)) THEN
      ASM_REWRITE_TAC[NOT_LT];
      (* [6]: congruence advance *)
      SUBGOAL_THEN `val(word_not(word(bigdigit b i)):int64) = 2 EXP 64 - 1 - bigdigit b i` ASSUME_TAC THENL
       [REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN
        SUBGOAL_THEN `val(word(bigdigit b i):int64) = bigdigit b i` SUBST1_TAC THENL
         [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; REFL_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `val(word q:int64) = q /\ val(word (bigdigit zorig i):int64) = bigdigit zorig i`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND] THEN
        UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `2 EXP 64 * (bitval carry_s7 + bitval carry_s9) + val(sum_s9:int64) =
        bitval carry_s5 + val(mulhi_s3:int64) + bitval carry_s8`
       ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun h26 -> FIRST_X_ASSUM(fun h24 ->
          if free_in `sum_s7:int64` (concl h24) && free_in `sum_s9:int64` (concl h26) &&
             free_in `carry_s9:bool` (concl h26)
          then MP_TAC h24 THEN MP_TAC h26 else failwith "nope")) THEN
        REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `bitval carry_s7 + bitval carry_s9 <= 1` ASSUME_TAC THENL
       [MP_TAC(SPEC `i:num`(SPEC `b:num` BIGDIGIT_BOUND)) THEN
        MP_TAC(ISPEC `mulhi_s3:int64` VAL_BOUND_64) THEN REWRITE_TAC[DIMINDEX_64] THEN
        UNDISCH_TAC `2 EXP 64 * (bitval carry_s7 + bitval carry_s9) + val(sum_s9:int64) =
          bitval carry_s5 + val(mulhi_s3:int64) + bitval carry_s8` THEN
        MP_TAC(ISPEC `carry_s5:bool` BITVAL_BOUND) THEN MP_TAC(ISPEC `carry_s8:bool` BITVAL_BOUND) THEN
        ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `2 EXP 64 * val(sum_s9:int64) + val(sum_s8:int64) =
        bigdigit zorig i + val(hhin:int64) + q * (2 EXP 64 - 1 - bigdigit b i)`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL
         [`bigdigit zorig i`; `val(hhin:int64)`; `q:num`; `2 EXP 64 - 1 - bigdigit b i`;
          `val(sum_s5:int64)`; `val(sum_s8:int64)`; `val(sum_s9:int64)`;
          `val(mullo_s3:int64)`; `val(mulhi_s3:int64)`;
          `bitval carry_s5`; `bitval carry_s8`; `bitval carry_s7 + bitval carry_s9`] NEGADD_STEP) THEN
        ASM_REWRITE_TAC[BITVAL_BOUND; VAL_BOUND_64; BIGDIGIT_BOUND;
                        ARITH_RULE `2 EXP 64 - 1 - x < 2 EXP 64`] THEN
        ANTS_TAC THENL
         [RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word_not(word(bigdigit b i)):int64) = 2 EXP 64 - 1 - bigdigit b i`;
            ASSUME `val(word q:int64) = q`; ASSUME `val(word (bigdigit zorig i):int64) = bigdigit zorig i`]) THEN
          REPEAT CONJ_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
          FIRST_X_ASSUM(fun th -> MP_TAC th THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
            CONV_TAC REAL_RING) ORELSE ALL_TAC;
          DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `bignum_from_memory (z,i) s16 = bignum_from_memory (z,i) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s16`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      SUBST1_TAC(GSYM(ISPEC `sum_s8:int64` WORD_VAL)) THEN
      SUBST1_TAC(GSYM(ISPEC `cwin:int64` WORD_VAL)) THEN
      REWRITE_TAC[EXTR_FUNNEL_VAL] THEN REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN
      SIMP_TAC[MOD_LT; VAL_BOUND_64] THEN REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN
      REWRITE_TAC[LOWDIGITS_CLAUSES] THEN
      MP_TAC(ISPECL
        [`block:num`; `q:num`; `bignum_from_memory (z,i) s0`; `val(cwin:int64)`;
         `val(hhin:int64)`; `val(sum_s8:int64)`; `val(sum_s9:int64)`;
         `lowdigits zorig i`; `lowdigits b i`; `bigdigit zorig i`; `bigdigit b i`; `i:num`]
        INNER_ADVANCE_ADD) THEN
      ASM_REWRITE_TAC[] THEN
      ANTS_TAC THENL [REWRITE_TAC[BIGDIGIT_BOUND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (*** BACKEDGE + EXIT ***)
  CONJ_TAC THENL
   [(*** BACKEDGE ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    SUBGOAL_THEN `val(word dd:int64) = dd` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `dd <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    REWRITE_TAC[GSYM NOT_LT] THEN ASM_REWRITE_TAC[];
    (*** EXIT ***)
    SUBGOAL_THEN `val(word dd:int64) = dd` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `dd <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM NOT_LT] THEN ASM_REWRITE_TAC[]]]);;


(* ---- 4. BLOCKHEAD with FAT POST (bytes_loaded + RSP,RBX->61*ii,R12, 8 slots, bignum(x,n)=a) ----
   Block-head writes NO memory + doesn't touch RSP/R12/RSI/R8/R13; so the OUTER bundle is preserved.
   Two block-position regimes (BLOCKPOS): GENERAL qw+1<n (pin x[qw+1]), BOUNDARY rw<=3 (x[qw+1] garbage,
   masked off).  The FINAL_STATE+ASM_REWRITE auto-discharges all spectator/slot/mem conjuncts (they match
   the carried state); only the 7 value conjuncts remain (RDI=word(l-1); RBP,R9 via QRECON; R11 block-value
   via BH_SHIFT_RW+FUNNEL_BLOCK; bignum x/z/m frames). *)
let BIGNUM_MOD_X86_BLOCKHEAD_WIDE = prove
 (`!k z m x n a b pc p ii w l zv lfv h jjv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\ 2 <= l /\ l <= k + 1 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ h < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x265) /\
           read RDI s = word (l - 1) /\ read RSI s = z /\ read R8 s = m /\
           read R10 s = word 0 /\ read RBP s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
           read R9 s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
           read R11 s = word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word 0 /\
           read RSP s = stackpointer /\ read RBX s = word (61 * ii) /\ read R12 s = word l /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\
           bignum_from_memory (z,k) s = zv /\ bignum_from_memory (m,k) s = b)
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R14; R15] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  let fatbh_close r11tac =
    REPEAT CONJ_TAC THENL
     [SUBGOAL_THEN `1 <= l` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[WORD_SUB];
      ASM_SIMP_TAC[QRECON];
      ASM_SIMP_TAC[QRECON];
      r11tac;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (x,n) s0 = a`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zv`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC] in
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `61 * ii + 61 <= 64 * n` ASSUME_TAC THENL
   [MP_TAC(SPEC `n:num` I0_BOUNDS) THEN ANTS_TAC THENL
     [CONJ_TAC THENL [ASM_REWRITE_TAC[]; UNDISCH_TAC `n < 2 EXP 58` THEN ARITH_TAC]; ALL_TAC] THEN
    UNDISCH_TAC `ii < (64 * n + 60) DIV 61 - 1` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `61 * ii < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `61 * ii + 61 <= 64 * n` THEN UNDISCH_TAC `n < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`n:num`; `ii:num`] BLOCKPOS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
  ABBREV_TAC `qw = (61 * ii) DIV 64` THEN ABBREV_TAC `rw = (61 * ii) MOD 64` THEN
  SUBGOAL_THEN `61 * ii = qw * 64 + rw` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["qw"; "rw"] THEN MP_TAC(SPECL [`61 * ii`; `64`] DIVISION) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `rw < 64` ASSUME_TAC THENL
   [EXPAND_TAC "rw" THEN MP_TAC(SPECL [`61 * ii`; `64`] DIVISION) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `qw < 2 EXP 64` ASSUME_TAC THENL
   [TRANS_TAC LET_TRANS `61 * ii` THEN CONJ_TAC THENL
     [EXPAND_TAC "qw" THEN REWRITE_TAC[DIV_LE]; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word qw:int64) = qw` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `qw + 1 < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `qw < n` THEN UNDISCH_TAC `n < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (qw+1):int64) = qw + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * qw)))) s0 = word (bigdigit a qw)`
   ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (x,n) s0 = a`)] THEN
    REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES; BIGDIGIT_BIGNUM_FROM_MEMORY] THEN
    ASM_SIMP_TAC[WORD_VAL]; ALL_TAC] THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th -> is_disj (concl th))) THENL
   [(*** GENERAL qw+1<n ***)
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--6) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[WORD_RULE
      `word_sub (word (61 * (ii + 1))) (word 61):int64 = word (61 * ii)`]) THEN
    SUBGOAL_THEN `word_ushr (word (61 * ii):int64) 6 = word qw` ASSUME_TAC THENL
     [REWRITE_TAC[word_ushr; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN ONCE_ASM_REWRITE_TAC[ASSUME `61 * ii = qw * 64 + rw`] THEN
      SIMP_TAC[DIV_MULT_ADD; ARITH_EQ] THEN ASM_SIMP_TAC[DIV_LT; ADD_CLAUSES]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word (61 * ii):int64) 6 = word qw`]) THEN
    SUBGOAL_THEN `word_shl (word qw:int64) 3 = word (8 * qw)` ASSUME_TAC THENL
     [REWRITE_TAC[word_shl; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_shl (word qw:int64) 3 = word (8 * qw)`]) THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * qw + 8)))) s6 = word (bigdigit a (qw + 1))`
     ASSUME_TAC THENL
     [SUBGOAL_THEN `word_add x (word (8 * qw + 8)):int64 = word_add x (word (8 * (qw + 1)))` SUBST1_TAC THENL
       [CONV_TAC WORD_RULE; ALL_TAC] THEN
      SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * (qw + 1))))) s6 =
                    read (memory :> bytes64 (word_add x (word (8 * (qw + 1))))) s0` SUBST1_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s6`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (x,n) s0 = a`)] THEN
      REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES; BIGDIGIT_BIGNUM_FROM_MEMORY] THEN
      ASM_SIMP_TAC[WORD_VAL]; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (7--21) THEN
    MP_TAC BH_LSUB THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word_sub (word l:int64) (word 1)) = l - 1`]) THEN
    SUBGOAL_THEN `~(l - 1 = 0)` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `~(l - 1 = 0)`]) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    fatbh_close
     (MP_TAC BH_SHIFT_RW THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ONCE_REWRITE_TAC[GSYM(ASSUME `61 * ii = qw * 64 + rw`)] THEN
      MP_TAC(SPECL [`a:num`; `qw:num`; `rw:num`; `bigdigit a (qw + 1)`; `bigdigit a qw`] FUNNEL_BLOCK) THEN
      ASM_REWRITE_TAC[BIGDIGIT_BOUND]);
    (*** BOUNDARY rw<=3 ***)
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--6) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[WORD_RULE
      `word_sub (word (61 * (ii + 1))) (word 61):int64 = word (61 * ii)`]) THEN
    SUBGOAL_THEN `word_ushr (word (61 * ii):int64) 6 = word qw` ASSUME_TAC THENL
     [REWRITE_TAC[word_ushr; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN ONCE_ASM_REWRITE_TAC[ASSUME `61 * ii = qw * 64 + rw`] THEN
      SIMP_TAC[DIV_MULT_ADD; ARITH_EQ] THEN ASM_SIMP_TAC[DIV_LT; ADD_CLAUSES]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word (61 * ii):int64) 6 = word qw`]) THEN
    SUBGOAL_THEN `word_shl (word qw:int64) 3 = word (8 * qw)` ASSUME_TAC THENL
     [REWRITE_TAC[word_shl; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_shl (word qw:int64) 3 = word (8 * qw)`]) THEN
    ABBREV_TAC `g:int64 = read (memory :> bytes64 (word_add x (word (8 * qw + 8)))) s6` THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (7--21) THEN
    MP_TAC BH_LSUB THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word_sub (word l:int64) (word 1)) = l - 1`]) THEN
    SUBGOAL_THEN `~(l - 1 = 0)` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `~(l - 1 = 0)`]) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    fatbh_close
     (MP_TAC BH_SHIFT_RW THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ONCE_REWRITE_TAC[GSYM(ASSUME `61 * ii = qw * 64 + rw`)] THEN
      SUBST1_TAC(GSYM(ISPEC `g:int64` WORD_VAL)) THEN
      MP_TAC(SPECL [`a:num`; `qw:num`; `rw:num`; `val(g:int64)`; `bigdigit a qw`] FUNNEL_BLOCK) THEN
      ASM_REWRITE_TAC[BIGDIGIT_BOUND; VAL_BOUND_64])]);;


(* ---- 5. PREFIX 0x217 -> 0x2a3 (compose BLOCKHEAD_WIDE ;; INNERLOOP_LOG_WIDE with OUTER glue) ---- *)
let BIGNUM_MOD_X86_PREFIX = prove
 (`!k z m x n a b pc p ii w l zv lfv h jjv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\ 2 <= l /\ l <= k + 1 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ h < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read R10 s = word (l - 1) /\ read RSI s = z /\ read R8 s = m /\
           read RBP s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
           read RDI s = word (l - 1) /\ read R13 s = word (p DIV 64 + 1) /\
           read RSP s = stackpointer /\ read RBX s = word (61 * ii) /\ read R12 s = word l /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\
           bignum_from_memory (word_add z (word (8 * (l-1))), k - (l-1)) s = highdigits zv (l-1) /\
           (1 <= l - 1
            ==> read R14 s =
                read (memory :> bytes64 (word_add z (word (8 * (MIN (l-1) (p DIV 64 + 1) - 1))))) s) /\
           (p DIV 64 + 1 < l - 1
            ==> read R15 s = read (memory :> bytes64 (word_add z (word (8 * (p DIV 64 + 1))))) s) /\
           (~(p DIV 64 + 1 < l - 1) ==> read R15 s = word 0) /\
           bignum_from_memory (z,l-1) s +
           2 EXP (64 * (l-1)) * (val(read R11 s) DIV 8 + 2 EXP 61 * val(read R9 s)) +
           2 EXP 61 * ((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 * lowdigits b (l-1) =
           (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (l-1) +
           2 EXP 61 * ((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 * 2 EXP (64 * (l-1)))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R14; R15] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  (*** seg1: BLOCKHEAD_WIDE 0x217 -> 0x265 (direct ACCEPT of the mid-assertion) ***)
  ENSURES_SEQUENCE_TAC `pc + 0x265`
   `\s. read RDI s = word (l - 1) /\ read RSI s = z /\ read R8 s = m /\
        read R10 s = word 0 /\ read RBP s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
        read R9 s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
        read R11 s = word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) /\
        read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word 0 /\
        read RSP s = stackpointer /\ read RBX s = word (61 * ii) /\ read R12 s = word l /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
        bignum_from_memory (x,n) s = a /\
        bignum_from_memory (z,k) s = zv /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [(* seg1: BLOCKHEAD_WIDE.  MUST REWRITE_RULE[SOME_FLAGS] (the ENSURES_SEQUENCE frames are
        expanded to [CF;..] by the top REWRITE_TAC[SOME_FLAGS] -- the lemma's literal SOME_FLAGS
        won't ACCEPT otherwise). *)
    MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
       `p:num`;`ii:num`;`w:num`;`l:num`;`zv:num`;`lfv:num`;`h:num`;`jjv:num`;
       `stackpointer:int64`] BIGNUM_MOD_X86_BLOCKHEAD_WIDE)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (*** seg2: INNERLOOP_LOG_WIDE 0x265 -> 0x2a3, threading the OUTER spectator bundle ***)
  MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
    [`k:num`; `z:int64`; `m:int64`; `l - 1`;
     `((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64`;
     `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `zv:num`; `b:num`; `pc:num`;
     `p DIV 64 + 1`; `word lfv:int64`] BIGNUM_MOD_X86_INNERLOOP_LOG_WIDE)) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REPEAT CONJ_TAC THEN
    (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l <= k + 1` THEN UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN CONJ_TAC THENL
   [(*** P ==> P' : leg2 PRE (with OUTER) subsumes the il PRE (thin core) ***)
    GEN_TAC THEN BETA_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** frame subsumed ***) SUBSUMED_MAYCHANGE_TAC;
    (*** postcond: leg2 PRE @s /\ il POST @s' /\ frame ==> leg2 POST @s'.  The core (RIP,R10,RSI,R8,
         RBP,RDI,R13,z-tail,logs,congruence) is in the il POST @s'; the OUTER bundle (RSP,RBX,R12,
         slots,x-mem) at s' comes from the PRE reads @s via the frame (inline MAYCHANGE-pull -- the
         polymorphic OUTER_PRESV_EQ won't MATCH_MP against the concrete-typed frame, so prove the
         12 s'=s equations directly). ***)
    REPEAT GEN_TAC THEN BETA_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `read RSP s' = read RSP s /\ read RBX s' = read RBX s /\ read R12 s' = read R12 s /\
      read (memory :> bytes64 stackpointer) s' = read (memory :> bytes64 stackpointer) s /\
      read (memory :> bytes64 (word_add stackpointer (word 16))) s' = read (memory :> bytes64 (word_add stackpointer (word 16))) s /\
      read (memory :> bytes64 (word_add stackpointer (word 24))) s' = read (memory :> bytes64 (word_add stackpointer (word 24))) s /\
      read (memory :> bytes64 (word_add stackpointer (word 32))) s' = read (memory :> bytes64 (word_add stackpointer (word 32))) s /\
      read (memory :> bytes64 (word_add stackpointer (word 40))) s' = read (memory :> bytes64 (word_add stackpointer (word 40))) s /\
      read (memory :> bytes64 (word_add stackpointer (word 48))) s' = read (memory :> bytes64 (word_add stackpointer (word 48))) s /\
      read (memory :> bytes64 (word_add stackpointer (word 56))) s' = read (memory :> bytes64 (word_add stackpointer (word 56))) s /\
      read (memory :> bytes64 (word_add stackpointer (word 64))) s' = read (memory :> bytes64 (word_add stackpointer (word 64))) s /\
      bignum_from_memory (x,n) s' = bignum_from_memory (x,n) s`
     MP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN REPEAT CONJ_TAC THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      STRIP_TAC THEN ASM_REWRITE_TAC[]]]);;


(* x86 DDK regime TAIL sim: 0x2a3 -> 0x371 (SATURATED regime, dd=k, l=k+1).
   Port of ARM BIGNUM_MOD_TAIL_DDK_WIDE_LOG (tail_ddk_wide.ml:82) FUSED with the ARM FIELDSEL
   (fieldsel.ml:33) -- because on x86 the tail 0x2a3->0x371 covers BOTH the ARM tail (0x23c->0x2e8)
   AND the ARM seg-C FIELDSEL (0x2e8->0x304).

   x86<->ARM divergences (see ARM_TAIL_MAP.md):
   - top word (ARM X23=Zt, a register) -> x86 zz-SLOT (rsp+8): the trivnegadd store cmove-redirects
     to [rsp+8] when ii=k, so z-memory is UNtouched and the top spill lands in the zz-slot.
   - the next window (ARM X15 via separate FIELDSEL) -> x86 hs-SLOT (rsp+64): the noel field-combine
     0x33a->0x36c computes h = combine(hf,lf) around bit p and stores to hs.
   - lf/hf logged fields are R14/R15 (ARM X13/X14).

   DDK path (SATURATED, k+1<=(jjv+63)DIV64): ii enters = k, l'=k+1.
     0x2a3 trivnegadd: cmp r10,kk EQUAL -> je offendm TAKEN (skip m-load), store target = zz-slot.
     0x2bc offendm: negate-add with phantom m[k]=0 (~m[k]=2^64-1): zz-slot = extr#3(ztin+hi+q*(2^64-1):cwin).
     0x2e1 block-count bump: jj+=61; l'=MIN(k+1,(jj+124)/64)=k+1 (saturation, DDK_MIN_FOLD).
     0x30d el-store: cmp r10(=k+1),r12(=k+1) EQUAL -> je noel TAKEN (el-store SKIPPED; top already in zz-slot).
     0x33a noel field-combine: lf-tidy then funnel (FIELDCOMBINE_FUNNEL) -> hs-slot = window of (hf':lf').
     0x371 loop test (tail exit).

   Step sequence (VALIDATED cont115s3, 45 steps): see memory bignum-mod-x86-port.md cont115s3.
   Needs: DDK_MIN_FOLD, FIELDCOMBINE_FUNNEL (below); scaffold BIGNUM_MOD_EXEC.  Load after scaffold. *)

(* MIN/cmovae saturation fold: the block-count bump's l'=MIN. *)
let DDK_MIN_FOLD = prove
 (`!k J. k + 1 < 2 EXP 64 /\ J < 2 EXP 64 /\ k + 1 <= J
     ==> (if val (word J:int64) <= val (word_add (word k) (word 1):int64)
          then word J:int64 else word_add (word k) (word 1)) = word (k + 1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `val(word_add (word k) (word 1):int64) = k + 1` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM WORD_ADD] THEN MATCH_MP_TAC VAL_WORD_EQ THEN
    ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word J:int64) = J` SUBST1_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  COND_CASES_TAC THENL
   [REWRITE_TAC[GSYM WORD_ADD] THEN AP_TERM_TAC THEN ASM_ARITH_TAC;
    REWRITE_TAC[WORD_ADD]]);;

(* MIN fold matching the cmovae output AFTER val(word_add(word k)(word 1)) is folded to k+1. *)
let DDK_MIN_FOLD2 = prove
 (`!k J. J < 2 EXP 64 /\ k + 1 <= J
     ==> (if J <= k + 1 then word J:int64 else word (k + 1)) = word (k + 1)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL
   [AP_TERM_TAC THEN ASM_ARITH_TAC; REFL_TAC]);;

(* inner-word normalize: the negate-add residue with phantom m[k]=0 (~m[k]=2^64-1).
   The x86 negate-add produces a 128-bit product word narrowed by word_zx (128->64), so the
   source is int128 (NOT int64 as on ARM); the narrowing is sound since n MOD 2^128 == n (mod 2^64). *)
let DDK_INNERWORD = prove
 (`word_add (word_add (word ztin) (word hi)) (word_zx (word ((2 EXP 64 - 1) * q):int128):int64) =
   word (ztin + hi + q * (2 EXP 64 - 1)):int64`,
  SUBGOAL_THEN `word_zx (word ((2 EXP 64 - 1) * q):int128):int64 = word ((2 EXP 64 - 1) * q)`
    SUBST1_TAC THENL
   [REWRITE_TAC[WORD_ZX_WORD; DIMINDEX_64] THEN
    REWRITE_TAC[WORD_EQ; DIMINDEX_64; CONG; DIMINDEX_128] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `(2:num) EXP 128 = 2 EXP 64 * 2 EXP 64`] THEN
    REWRITE_TAC[MOD_MOD; MULT_EQ_0; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  CONV_TAC WORD_RULE);;

(* the x86 fieldcombine funnel (analog of ARM CSEL_BLOCK_VAL', x86 word_ushr/word_shl/word_neg forms).
   shl count is (64-r) MOD 64 from `neg rcx`.  r = p MOD 64 < 64. *)
let FIELDCOMBINE_FUNNEL = prove
 (`!hi lo r. r < 64 /\ hi < 2 EXP 64 /\ lo < 2 EXP 64
     ==> val((if r = 0
              then word_ushr (word lo:int64) r
              else word_or (word_shl (word hi:int64) ((64 - r) MOD 64))
                   (word_ushr (word lo:int64) r))
             :int64)
         = (2 EXP 64 * hi + lo) DIV 2 EXP r MOD 2 EXP 64`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`hi:num`;`lo:num`;`r:num`] CSEL_BLOCK_VAL) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[word_jushr; word_jshl; DIMINDEX_64] THEN
  SUBGOAL_THEN `val(word r:int64) = r` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `r < 64` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[VAL_WORD_0] THEN
  ASM_SIMP_TAC[MOD_LT] THEN
  SUBGOAL_THEN `val(word_sub (word 0) (word r):int64) MOD 64 = (64 - r) MOD 64` SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB; VAL_WORD_0; VAL_WORD; DIMINDEX_64] THEN
    ASM_SIMP_TAC[MOD_LT; ARITH_RULE `r < 64 ==> r < 2 EXP 64`] THEN
    SUBGOAL_THEN `!x. x MOD 2 EXP 64 MOD 64 = x MOD 64` (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD];
      ALL_TAC] THEN
    REWRITE_TAC[ADD_CLAUSES] THEN
    SUBGOAL_THEN `2 EXP 64 - r = (64 - r) + 64 * (2 EXP 58 - 1)` SUBST1_TAC THENL
     [ASM_ARITH_TAC; ONCE_REWRITE_TAC[ADD_SYM] THEN REWRITE_TAC[MOD_MULT_ADD]]; ALL_TAC] THEN
  GEN_REWRITE_TAC (RAND_CONV o ONCE_DEPTH_CONV) [WORD_OR_SYM] THEN
  DISCH_THEN ACCEPT_TAC);;

(* Shift-amount + if-condition folds for the noel field-combine at s45.  The x86 CL-relative
   shifts leave the count as val(word(val(word(p MOD 64)) MOD 256):byte) MOD 64 (lo, `shr %cl`)
   and val(word(val(word_neg(word(p MOD 64))) MOD 256):byte) MOD 64 (hi, `neg %rcx; shl %cl`).
   All specialize to r := p MOD 64 (< 64 always), so state unconditionally. *)
let DDK_VAL_PMOD = prove
 (`!p. val (word (p MOD 64):int64) = p MOD 64`,
  GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
  MP_TAC(SPECL [`p:num`; `64`] MOD_LT_EQ) THEN ARITH_TAC);;

let DDK_LOSHIFT = prove
 (`!p. val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64 = p MOD 64`,
  GEN_TAC THEN
  SUBGOAL_THEN `p MOD 64 < 64` ASSUME_TAC THENL [REWRITE_TAC[MOD_LT_EQ; ARITH_EQ]; ALL_TAC] THEN
  ASM_SIMP_TAC[DDK_VAL_PMOD; SHL_AMT8]);;

let HISHIFT_GEN = prove
 (`!c. c < 64 ==> val (word (val (word_neg (word c:int64)) MOD 256):byte) MOD 64 = (64 - c) MOD 64`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `c = 0` THEN
  ASM_REWRITE_TAC[WORD_NEG_0; VAL_WORD_0] THENL
   [CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[VAL_WORD_0] THEN CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPEC `c:num` NEG_SHIFT_AMT8) THEN
    ASM_SIMP_TAC[ARITH_RULE `~(c = 0) ==> 0 < c`] THEN
    DISCH_THEN SUBST1_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC MOD_LT THEN UNDISCH_TAC `~(c = 0)` THEN UNDISCH_TAC `c < 64` THEN ARITH_TAC]);;

let DDK_HISHIFT = prove
 (`!p. val (word (val (word_neg (word (p MOD 64):int64)) MOD 256):byte) MOD 64 = (64 - p MOD 64) MOD 64`,
  GEN_TAC THEN MATCH_MP_TAC HISHIFT_GEN THEN REWRITE_TAC[MOD_LT_EQ; ARITH_EQ]);;

(* Word-level funnel: the noel combine as a WORD equation over arbitrary int64 fields H (hf) L (lf),
   shift r := p MOD 64.  r=0 branch = ushr-by-0 = word(val L) = L (window = L DIV 1); r!=0 uses
   FIELDCOMBINE_FUNNEL (val form) via GSYM WORD_VAL round-trip. *)
let FIELDCOMBINE_FUNNEL_W = prove
 (`!H L r. r < 64
     ==> (if r = 0
          then word_ushr (L:int64) r
          else word_or (word_shl (H:int64) ((64 - r) MOD 64)) (word_ushr L r))
         = word ((2 EXP 64 * val H + val L) DIV 2 EXP r MOD 2 EXP 64):int64`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `r = 0` THEN ASM_REWRITE_TAC[] THENL
   [REWRITE_TAC[WORD_USHR_ZERO; EXP; DIV_1] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 * val(H:int64) + val(L:int64) = val L + val H * 2 EXP 64`] THEN
    REWRITE_TAC[MOD_MULT_ADD] THEN
    SUBGOAL_THEN `val(L:int64) MOD 2 EXP 64 = val L` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN REWRITE_TAC[VAL_BOUND_64]; ALL_TAC] THEN
    REWRITE_TAC[WORD_VAL];
    GEN_REWRITE_TAC I [GSYM VAL_EQ] THEN
    MP_TAC(SPECL [`val(H:int64)`;`val(L:int64)`;`r:num`] FIELDCOMBINE_FUNNEL) THEN
    ASM_REWRITE_TAC[VAL_BOUND_64; WORD_VAL] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VAL_WORD; DIMINDEX_64; MOD_MOD_REFL]]);;

(* The hs-slot close, fully assembled over ABSTRACT logged fields H (hf') L (lf'): the exact noel
   funnel term at s45 (raw byte-shift counts, val(word(p MOD 64))=0 guard) = the POST window
   word((2^64*val H + val L) DIV 2^(p MOD 64) MOD 2^64).  Folds the shift counts (DDK_LOSHIFT/HISHIFT)
   + the guard (DDK_VAL_PMOD) then applies FIELDCOMBINE_FUNNEL_W.  MATCH_ACCEPT'd in the tail POST once
   H,L instantiate to the collapsed R15/R14 fields (raw word-0-first if-order, matching the state). *)
let DDK_HS_CLOSE = prove
 (`!(H:int64) (L:int64) p.
     (if val (word (p MOD 64):int64) = 0
      then word_ushr L (val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64)
      else word_or (word_shl H (val (word (val (word_neg (word (p MOD 64):int64)) MOD 256):byte) MOD 64))
                   (word_ushr L (val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64)))
     = word ((2 EXP 64 * val H + val L) DIV 2 EXP (p MOD 64) MOD 2 EXP 64):int64`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[DDK_LOSHIFT; DDK_HISHIFT; DDK_VAL_PMOD] THEN
  MP_TAC(SPECL [`H:int64`;`L:int64`;`p MOD 64`] FIELDCOMBINE_FUNNEL_W) THEN
  REWRITE_TAC[MOD_LT_EQ; ARITH_EQ] THEN DISCH_THEN ACCEPT_TAC);;


(* The DDK tail sim.  POST carries (raw-value form):
     R10 = word(k+1) [ii after], R12 = word(k+1) [l'], jj-slot = jjv+61,
     zz-slot(rsp+8) = extr#3(W:cwin) with W = ztin+hi+q*(2^64-1)  [the top word],
     hs-slot(rsp+64) = window = word((2^64*hf' + lf') DIV 2^(p MOD 64) MOD 2^64),
     R14=lf', R15=hf' [tidied logged fields, nested-if], z-mem UNchanged, m-mem/spectators preserved.
   where lf' = (if k+1=pcode then W3 else if pcode<=k+1 then (if k<pcode then W3 else lfv) else 0),
         hf' = (if k=pcode then W3 else hfv), W3 = extr#3(W:cwin).
   The block lemma (DDK_304_WIN) resolves the nested-ifs + value-closes via TAIL_EXTR_VAL /
   VALUE_BRIDGE_DDK / WINDOW_FROM_LOGGED (all [AI], in scaffold). *)
let BIGNUM_MOD_X86_TAIL_DDK = prove
 (`!k z m pc q hi cwin ztin b zpre jjv pcode p lfv hfv rbxv stackpointer.
     ~(k = 0) /\ k < 2 EXP 58 /\ b < 2 EXP (64 * k) /\ q < 2 EXP 64 /\
     jjv + 124 < 2 EXP 64 /\ k + 1 <= (jjv + 63) DIV 64 /\ pcode < 2 EXP 64 /\ p < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (stackpointer,72) /\
     nonoverlapping (m,8 * k) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word rbxv /\
           read R10 s = word k /\ read RDI s = word k /\ read RBP s = word q /\
           read R9 s = word hi /\ read R11 s = word cwin /\ read R13 s = word pcode /\
           read R12 s = word (k + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word ztin /\
           bignum_from_memory (m,k) s = b /\ bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
           read RIP s = word (pc + 0x371) /\ read R10 s = word (k + 1) /\ read R12 s = word (k + 1) /\
           read RSP s = stackpointer /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word pcode /\ read RBX s = word rbxv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (jjv + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s =
             word_subword (word_join
               (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64) /\
           read R15 s = (if k = pcode
                         then word_subword (word_join (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64)
                         else word hfv) /\
           read R14 s = (if k + 1 = pcode
                         then word_subword (word_join (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64)
                         else if pcode <= k + 1
                         then (if k < pcode
                               then word_subword (word_join (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64)
                               else word lfv)
                         else word 0) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word ((2 EXP 64 *
                    val ((if k = pcode
                          then word_subword (word_join (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64)
                          else word hfv):int64) +
                    val ((if k + 1 = pcode
                          then word_subword (word_join (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64)
                          else if k + 1 < pcode
                          then word 0
                          else if k < pcode
                          then word_subword (word_join (word (ztin + hi + q * (2 EXP 64 - 1)):int64) (word cwin:int64):int128) (3,64)
                          else word lfv):int64))
                   DIV 2 EXP (p MOD 64) MOD 2 EXP 64) /\
           bignum_from_memory (z,k) s = zpre /\ bignum_from_memory (m,k) s = b)
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (k+1):int64) = k + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word q:int64) = q` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--6) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `read ZF s6`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (7--24) THEN
  (*** jj-bump folds ***)
  SUBGOAL_THEN `word_ushr (word_add (word jjv) (word 124):int64) 6 = word((jjv + 124) DIV 64)`
    ASSUME_TAC THENL
   [REWRITE_TAC[word_ushr; GSYM WORD_ADD] THEN AP_TERM_TAC THEN
    SUBGOAL_THEN `val(word(jjv + 124):int64) = jjv + 124` SUBST1_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`]]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word((jjv + 124) DIV 64):int64) = (jjv + 124) DIV 64` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `k + 1 <= (jjv + 124) DIV 64` ASSUME_TAC THENL
   [TRANS_TAC LE_TRANS `(jjv + 63) DIV 64` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC DIV_MONO THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word_add (word jjv) (word 124):int64) 6 = word((jjv + 124) DIV 64)`]) THEN
  (*** cmp rdi,rax ; cmovae rdi,rax ; mov r12,rdi (steps 25--27); THEN fold R10 & R12 to word(k+1)
       BEFORE the cmp@step 28 -- so the cmp produces a CLEAN self-subtract flag (ZF=T) that X86_STEPS
       resolves itself, and the je@29 steps with no mk_comb.  (Folding AFTER the cmp leaves the state's
       flag term complex -> je chokes.  THE x86 TAKEN-Jcc IDIOM: make the cmp operands clean BEFORE the
       cmp so the flag is auto-resolved; no manual ZF-canonicalize needed.) ***)
  SUBGOAL_THEN `(jjv + 124) DIV 64 < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (25--27) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[WORD_RULE `word_add (word k) (word 1):int64 = word(k+1)`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word (k+1):int64) = k + 1`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word((jjv + 124) DIV 64):int64) = (jjv + 124) DIV 64`]) THEN
  SUBGOAL_THEN
    `(if (jjv + 124) DIV 64 <= k + 1 then word ((jjv + 124) DIV 64):int64 else word (k + 1)) = word (k + 1)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC DDK_MIN_FOLD2 THEN CONJ_TAC THENL
     [UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME
    `(if (jjv + 124) DIV 64 <= k + 1 then word ((jjv + 124) DIV 64):int64 else word (k + 1)) = word (k + 1)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (28--28) THEN
  (*** je noel TAKEN (ZF=T auto-resolved from clean cmp); lf-tidy 29--33 ***)
  X86_STEPS_TAC BIGNUM_MOD_EXEC (29--33) THEN
  SUBGOAL_THEN `word_and (word p:int64) (word 63) = word (p MOD 64)` ASSUME_TAC THENL
   [SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
    AP_TERM_TAC THEN REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD]; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (34--45) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (*** POST close.  Bridges: inner-word normalize (DDK_INNERWORD), csel-flag -> num-eq/lt. ***)
  SUBGOAL_THEN `(val(word_sub (word k:int64) (word pcode)) = 0) <=> k = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT; ARITH_RULE `k < 2 EXP 58 ==> k < 2 EXP 64`]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word (k+1):int64) (word pcode)) = 0) <=> k + 1 = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT; ARITH_RULE `k < 2 EXP 58 ==> k + 1 < 2 EXP 64`]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (k+1):int64) = k + 1 /\ val(word pcode:int64) = pcode` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THENL
     [UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ASM_REWRITE_TAC[WORD_ZX_TRIVIAL; ARITH_RULE `18446744073709551615 = 2 EXP 64 - 1`;
    WORD_RULE `word_add (word jjv) (word 61):int64 = word(jjv + 61)`;
    WORD_RULE `word_add (word_add (word ztin) (word hi)) (word ((2 EXP 64 - 1) * q):int64):int64 = word(ztin + hi + q * (2 EXP 64 - 1))`;
    GSYM NOT_LT] THEN
  REWRITE_TAC[DDK_INNERWORD] THEN
  (* After DDK_INNERWORD the zz-slot and R15 value conjuncts collapse to X=X (auto-closed by the
     rewrite), and ENSURES_FINAL_STATE_TAC already absorbed the MAYCHANGE frame (R12 is now IN the
     POST frame -- that was the seqapply blocker).  Three conjuncts survive:
       (1) R14 nested-if:  branch-order mismatch (if..<..then 0 else..) vs (if ~(..<..) then.. else 0)
           -- COND_CASES twice + ASM_REWRITE (uses GSYM NOT_LT already applied);
       (2,3) bignum(z,k) s45 = zpre  and  bignum(m,k) s45 = b  -- frame-pull: z/m memory UNtouched
           in DDK, so rewrite RHS via the s0 hypotheses (SYM) then discharge the read-equality against
           the accumulated MAYCHANGE transition (s0->s45) by READ_OVER_WRITE_ORTHOGONAL_TAC. *)
  REPEAT CONJ_TAC THENL
   [COND_CASES_TAC THEN REWRITE_TAC[] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[];
    MATCH_ACCEPT_TAC DDK_HS_CLOSE;
    ALL_TAC; ALL_TAC] THEN
  (FIRST_X_ASSUM(fun th -> (if concl th = `bignum_from_memory (z,k) s0 = zpre` ||
                               concl th = `bignum_from_memory (m,k) s0 = b`
     then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
   REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
   FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s45`) o concl)) THEN
   REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
   REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
   REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC));;


(* x86 FLAT regime TAIL sim: 0x2a3 -> 0x371 (l STAYS: 2<=l<=k, dd=l-1, l'=dd+1=(jjv+124)/64).
   Port of ARM TAIL_FLAT_WIDE_LOG (tail_ddlt_wide.ml:509) FUSED with the ARM FIELDSEL, analogous to
   the completed BIGNUM_MOD_X86_TAIL_DDK.

   FLAT vs DDK control-flow (the ONLY sim divergence -- see ARM_TAIL_MAP.md + X86_MAINLOOP_PLAN.md):
   - trivnegadd `cmp r10,kk; je offendm`: DDK has r10=k=kk -> je TAKEN (skip m-load, phantom m=0).
     FLAT has r10=dd, kk=k, dd<k -> je NOT taken -> the `mov rax,[m+8*dd]` m-load EXECUTES, and the
     negate-add uses ~m[dd] = 2^64-1-bigdigit b dd (NOT 2^64-1).  So the FLAT top word is
     W = bigdigit zpre dd + hi + q*(2^64-1-bigdigit b dd)  (vs DDK's ztin + hi + q*(2^64-1)).
   - store target: DDK cmove's rdi to zz-slot (rsp+8, ii=k); FLAT keeps rdi=[z+8*dd] (dd<k) -> the
     last-limb store lands in z[dd] (MEMORY).  zz-slot UNchanged (=word ztin).
   - block-count bump l'=MIN(k+1,(jj+124)/64): FLAT has (jj+124)/64 = dd+1 <= k < k+1, so l'=dd+1.
   - el-store `cmp r10,r12; je noel`: after inc r10 (r10=dd+1), r12=l'=dd+1 -> EQUAL -> je noel TAKEN
     (el-store SKIPPED, same as DDK).
   - noel field-combine 0x33a->0x36c: same as DDK -> hs-slot = window of (hf':lf').

   POST (raw-value form, x86 regs; = ARM TAIL_FLAT_WIDE_LOG POST + fused window):
     R10=word(dd+1) [ii after], R12=word(dd+1) [l'], jj-slot=word(jjv+61), zz-slot(rsp+8)=word ztin
     [UNCHANGED], z[dd]=extr#3(W:cwin), bignum(z,dd)=lowdigits zpre dd,
     bignum(z,dd+1..)=highdigits zpre (dd+1), R15=(if dd=pcode then extr#3 else word hfv),
     R14=(if dd+1=pcode then extr#3 else if pcode<=dd+1 then (if dd<pcode then extr#3 else word lfv) else 0),
     hs-slot(rsp+64)=window((2^64*val R15' + val R14') DIV 2^(p MOD64) MOD 2^64), m-mem/spectators preserved.
   where W = bigdigit zpre dd + hi + q*(2^64-1-bigdigit b dd), extr#3 = word_subword(word_join(word W)(word cwin))(3,64).

   Shared helpers with DDK (regime-independent): FIELDCOMBINE_FUNNEL(_W), DDK_VAL_PMOD, DDK_LOSHIFT,
   HISHIFT_GEN, DDK_HISHIFT, DDK_HS_CLOSE.  Re-derived here so this file is self-contained after scaffold.
   FLAT-specific: FLAT_MIN_FOLD (l'=dd+1 exact), FLAT_INNERWORD (the ~m[dd] negate-add residue). *)

(* ---- shared shift/funnel helpers (identical to x86_tail_ddk_candidate.ml) ---- *)
let DDK_VAL_PMOD = prove
 (`!p. val (word (p MOD 64):int64) = p MOD 64`,
  GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
  MP_TAC(SPECL [`p:num`; `64`] MOD_LT_EQ) THEN ARITH_TAC);;

let DDK_LOSHIFT = prove
 (`!p. val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64 = p MOD 64`,
  GEN_TAC THEN
  SUBGOAL_THEN `p MOD 64 < 64` ASSUME_TAC THENL [REWRITE_TAC[MOD_LT_EQ; ARITH_EQ]; ALL_TAC] THEN
  ASM_SIMP_TAC[DDK_VAL_PMOD; SHL_AMT8]);;

let HISHIFT_GEN = prove
 (`!c. c < 64 ==> val (word (val (word_neg (word c:int64)) MOD 256):byte) MOD 64 = (64 - c) MOD 64`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `c = 0` THEN
  ASM_REWRITE_TAC[WORD_NEG_0; VAL_WORD_0] THENL
   [CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[VAL_WORD_0] THEN CONV_TAC NUM_REDUCE_CONV;
    MP_TAC(SPEC `c:num` NEG_SHIFT_AMT8) THEN
    ASM_SIMP_TAC[ARITH_RULE `~(c = 0) ==> 0 < c`] THEN
    DISCH_THEN SUBST1_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC MOD_LT THEN UNDISCH_TAC `~(c = 0)` THEN UNDISCH_TAC `c < 64` THEN ARITH_TAC]);;

let DDK_HISHIFT = prove
 (`!p. val (word (val (word_neg (word (p MOD 64):int64)) MOD 256):byte) MOD 64 = (64 - p MOD 64) MOD 64`,
  GEN_TAC THEN MATCH_MP_TAC HISHIFT_GEN THEN REWRITE_TAC[MOD_LT_EQ; ARITH_EQ]);;

let FIELDCOMBINE_FUNNEL = prove
 (`!hi lo r. r < 64 /\ hi < 2 EXP 64 /\ lo < 2 EXP 64
     ==> val((if r = 0
              then word_ushr (word lo:int64) r
              else word_or (word_shl (word hi:int64) ((64 - r) MOD 64))
                   (word_ushr (word lo:int64) r))
             :int64)
         = (2 EXP 64 * hi + lo) DIV 2 EXP r MOD 2 EXP 64`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`hi:num`;`lo:num`;`r:num`] CSEL_BLOCK_VAL) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[word_jushr; word_jshl; DIMINDEX_64] THEN
  SUBGOAL_THEN `val(word r:int64) = r` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `r < 64` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[VAL_WORD_0] THEN
  ASM_SIMP_TAC[MOD_LT] THEN
  SUBGOAL_THEN `val(word_sub (word 0) (word r):int64) MOD 64 = (64 - r) MOD 64` SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB; VAL_WORD_0; VAL_WORD; DIMINDEX_64] THEN
    ASM_SIMP_TAC[MOD_LT; ARITH_RULE `r < 64 ==> r < 2 EXP 64`] THEN
    SUBGOAL_THEN `!x. x MOD 2 EXP 64 MOD 64 = x MOD 64` (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD];
      ALL_TAC] THEN
    REWRITE_TAC[ADD_CLAUSES] THEN
    SUBGOAL_THEN `2 EXP 64 - r = (64 - r) + 64 * (2 EXP 58 - 1)` SUBST1_TAC THENL
     [ASM_ARITH_TAC; ONCE_REWRITE_TAC[ADD_SYM] THEN REWRITE_TAC[MOD_MULT_ADD]]; ALL_TAC] THEN
  GEN_REWRITE_TAC (RAND_CONV o ONCE_DEPTH_CONV) [WORD_OR_SYM] THEN
  DISCH_THEN ACCEPT_TAC);;

let FIELDCOMBINE_FUNNEL_W = prove
 (`!H L r. r < 64
     ==> (if r = 0
          then word_ushr (L:int64) r
          else word_or (word_shl (H:int64) ((64 - r) MOD 64)) (word_ushr L r))
         = word ((2 EXP 64 * val H + val L) DIV 2 EXP r MOD 2 EXP 64):int64`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `r = 0` THEN ASM_REWRITE_TAC[] THENL
   [REWRITE_TAC[WORD_USHR_ZERO; EXP; DIV_1] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 * val(H:int64) + val(L:int64) = val L + val H * 2 EXP 64`] THEN
    REWRITE_TAC[MOD_MULT_ADD] THEN
    SUBGOAL_THEN `val(L:int64) MOD 2 EXP 64 = val L` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN REWRITE_TAC[VAL_BOUND_64]; ALL_TAC] THEN
    REWRITE_TAC[WORD_VAL];
    GEN_REWRITE_TAC I [GSYM VAL_EQ] THEN
    MP_TAC(SPECL [`val(H:int64)`;`val(L:int64)`;`r:num`] FIELDCOMBINE_FUNNEL) THEN
    ASM_REWRITE_TAC[VAL_BOUND_64; WORD_VAL] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VAL_WORD; DIMINDEX_64; MOD_MOD_REFL]]);;

let DDK_HS_CLOSE = prove
 (`!(H:int64) (L:int64) p.
     (if val (word (p MOD 64):int64) = 0
      then word_ushr L (val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64)
      else word_or (word_shl H (val (word (val (word_neg (word (p MOD 64):int64)) MOD 256):byte) MOD 64))
                   (word_ushr L (val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64)))
     = word ((2 EXP 64 * val H + val L) DIV 2 EXP (p MOD 64) MOD 2 EXP 64):int64`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[DDK_LOSHIFT; DDK_HISHIFT; DDK_VAL_PMOD] THEN
  MP_TAC(SPECL [`H:int64`;`L:int64`;`p MOD 64`] FIELDCOMBINE_FUNNEL_W) THEN
  REWRITE_TAC[MOD_LT_EQ; ARITH_EQ] THEN DISCH_THEN ACCEPT_TAC);;

(* FLAT_HS_CLOSE: the x86 field-combine funnel with the r=0 branch's lo-shift amount HARDCODED to
   `val(word(0 MOD 256)) MOD 64` -- the x86 stepper inlines `val(word(p MOD 64))=0` into the then-arm.
   Derived from DDK_HS_CLOSE by COND_CASES (under val(word(p MOD 64))=0 the two forms coincide).
   Regime-independent (H,L opaque int64); shared by the FLAT/B/C tails' hs-slot close. *)
let FLAT_HS_CLOSE = prove
 (`!(H:int64) (L:int64) p.
     (if val (word (p MOD 64):int64) = 0
      then word_ushr L (val (word (0 MOD 256):byte) MOD 64)
      else word_or (word_shl H (val (word (val (word_neg (word (p MOD 64):int64)) MOD 256):byte) MOD 64))
                   (word_ushr L (val (word (val (word (p MOD 64):int64) MOD 256):byte) MOD 64)))
     = word ((2 EXP 64 * val H + val L) DIV 2 EXP (p MOD 64) MOD 2 EXP 64):int64`,
  REPEAT GEN_TAC THEN COND_CASES_TAC THEN
  MP_TAC(SPECL [`H:int64`;`L:int64`;`p:num`] DDK_HS_CLOSE) THEN ASM_REWRITE_TAC[]);;

(* ---- FLAT-specific helpers ---- *)

(* FLAT block-count MIN: (jjv+124)/64 = dd+1 <= k < k+1, so the cmovae MIN(k+1, (jj+124)/64) picks dd+1. *)
let FLAT_MIN_FOLD = prove
 (`!k dd J. dd + 1 <= k /\ k < 2 EXP 58 /\ J = dd + 1
     ==> (if J <= k + 1 then word J:int64 else word (k + 1)) = word (dd + 1)`,
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  COND_CASES_TAC THENL [REFL_TAC; UNDISCH_TAC `~(dd + 1 <= k + 1)` THEN ASM_ARITH_TAC]);;

(* FLAT_MIN_FOLD2: no-J-abstraction variant that MATCH_MP_TAC's cleanly against the R12 el-store cmp
   goal (the `dd` in both J-position and RHS confuses MATCH_MP_TAC unification in FLAT_MIN_FOLD). *)
let FLAT_MIN_FOLD2 = prove
 (`!k dd. dd + 1 <= k
     ==> (if dd + 1 <= k + 1 then word (dd + 1):int64 else word (k + 1)) = word (dd + 1)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL [REFL_TAC; ASM_ARITH_TAC]);;

(* FLAT inner-word normalize: the negate-add residue with the REAL m[dd] (not phantom 0).
   `not rax` (rax = m[dd] = bigdigit b dd) -> word_not(word bd), val = 2^64-1-bd; mul by q, narrow 128->64.
   Result = word(zd + hi + q*(2^64-1-bd)) where zd = bigdigit zpre dd, bd = bigdigit b dd. *)
let FLAT_INNERWORD = prove
 (`!zd hi q bd. bd < 2 EXP 64
     ==> word_add (word_add (word zd) (word hi))
           (word_zx (word (val(word_not(word bd:int64)) * q):int128):int64) =
         word (zd + hi + q * (2 EXP 64 - 1 - bd)):int64`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `val(word_not(word bd:int64)) = 2 EXP 64 - 1 - bd` SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN ASM_SIMP_TAC[VAL_WORD_EQ; DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `word_zx (word ((2 EXP 64 - 1 - bd) * q):int128):int64 = word ((2 EXP 64 - 1 - bd) * q)`
    SUBST1_TAC THENL
   [REWRITE_TAC[WORD_ZX_WORD; DIMINDEX_64] THEN
    REWRITE_TAC[WORD_EQ; DIMINDEX_64; CONG; DIMINDEX_128] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `(2:num) EXP 128 = 2 EXP 64 * 2 EXP 64`] THEN
    REWRITE_TAC[MOD_MOD; MULT_EQ_0; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[MULT_SYM] THEN CONV_TAC WORD_RULE);;


(* ---- the FLAT regime tail sim 0x2a3 -> 0x371 ----
   POST carries (raw-value form): R10=R12=word(dd+1); jj-slot=word(jjv+61); zz-slot=word ztin
   [UNCHANGED -- FLAT stores the top word into z[dd] MEMORY, not the zz-slot]; z[dd]=extr#3(W:cwin)
   with W = bigdigit zpre dd + hi + q*(2^64-1-bigdigit b dd); bignum(z,dd)=lowdigits zpre dd;
   bignum(z+8*(dd+1),k-(dd+1))=highdigits zpre (dd+1); R15/R14 nested-if logged fields;
   hs-slot(rsp+64)=window((2^64*val R15' + val R14') DIV 2^(p MOD64) MOD 2^64); m-mem preserved.
   The z-array MAYCHANGE is [memory :> bignum(z,k)] (z[dd] written), the ONLY memory divergence from DDK. *)
let BIGNUM_MOD_X86_TAIL_FLAT = prove
 (`!k z m pc q hi cwin ztin b zpre jjv pcode dd p lfv hfv rbxv stackpointer.
     ~(k = 0) /\ k < 2 EXP 58 /\ b < 2 EXP (64 * k) /\ q < 2 EXP 64 /\
     jjv + 124 < 2 EXP 64 /\ dd + 1 <= k /\ (jjv + 124) DIV 64 = dd + 1 /\
     pcode < 2 EXP 64 /\ p < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (stackpointer,72) /\
     nonoverlapping (m,8 * k) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word rbxv /\
           read R10 s = word dd /\ read RDI s = word dd /\ read RBP s = word q /\
           read R9 s = word hi /\ read R11 s = word cwin /\ read R13 s = word pcode /\
           read R12 s = word (dd + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word ztin /\
           bignum_from_memory (m,k) s = b /\ bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
           read RIP s = word (pc + 0x371) /\ read R10 s = word (dd + 1) /\ read R12 s = word (dd + 1) /\
           read RSP s = stackpointer /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word pcode /\ read RBX s = word rbxv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (jjv + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word ztin /\
           read (memory :> bytes64 (word_add z (word (8 * dd)))) s =
             word_subword (word_join
               (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64) /\
           read R15 s = (if dd = pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else word hfv) /\
           read R14 s = (if dd + 1 = pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else if dd + 1 < pcode
                         then word 0
                         else if dd < pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else word lfv) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word ((2 EXP 64 *
                    val ((if dd = pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else word hfv):int64) +
                    val ((if dd + 1 = pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else if dd + 1 < pcode
                          then word 0
                          else if dd < pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else word lfv):int64))
                   DIV 2 EXP (p MOD 64) MOD 2 EXP 64) /\
           bignum_from_memory (z,dd) s = lowdigits zpre dd /\
           bignum_from_memory (word_add z (word (8 * (dd + 1))), k - (dd + 1)) s = highdigits zpre (dd + 1) /\
           bignum_from_memory (m,k) s = b)
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `dd:num < k` ASSUME_TAC THENL [UNDISCH_TAC `dd + 1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `dd < 2 EXP 64` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`dd < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `dd + 1 < 2 EXP 64` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`dd + 1 <= k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word dd:int64) = dd` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+1):int64) = dd + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (k+1):int64) = k + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word q:int64) = q` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* preserved block-count fold: word_ushr(jj+124) 6 = word(dd+1), from jj+124<2^64 & (jj+124)/64=dd+1 *)
  SUBGOAL_THEN `word_ushr (word_add (word jjv) (word 124):int64) 6 = word (dd + 1)` ASSUME_TAC THENL
   [REWRITE_TAC[word_ushr; GSYM WORD_ADD] THEN
    SUBGOAL_THEN `val(word(jjv + 124):int64) = jjv + 124` SUBST1_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN AP_TERM_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ENSURES_INIT_TAC "s0" THEN
  (* pin the m[dd] and z[dd] limbs at s0 (FLAT reads BOTH: the m-load executes, dd<k) *)
  SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * dd)))) s0 = word (bigdigit b dd)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * dd)))) s0 = word (bigdigit zpre dd)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--5) THEN
  (*** trivnegadd `cmp r10,kk; je offendm`: FLAT r10=dd, kk=k, dd<k -> je NOT taken (m-load runs).
       Establish ~(val(word_sub dd k)=0) so the je@6 falls through with a resolved flag. ***)
  SUBGOAL_THEN `~(val(word_sub (word dd:int64) (word k)) = 0)` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `dd < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `~(val(word_sub (word dd:int64) (word k)) = 0)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (6--24) THEN
  (*** block-count bump l' = MIN(k+1,(jj+124)/64) = dd+1: cmp rdi,rax; cmovae rdi,rax; mov r12,rdi.
       Fold ushr->word(dd+1) FIRST so R12/RDI carry the clean MIN-if, then FLAT_MIN_FOLD2 (dd+1<=k). ***)
  X86_STEPS_TAC BIGNUM_MOD_EXEC (25--27) THEN
  (* RAX picks up the raw word_ushr during 25--27 (the block-count shr), which then propagates into
     RDI/R12 via cmovae/mov -- so the ushr->word(dd+1) fold MUST happen HERE (post-27), not before. *)
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word_add (word jjv) (word 124):int64) 6 = word (dd + 1)`;
                              WORD_RULE `word_add (word dd) (word 1):int64 = word(dd+1)`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word (dd+1):int64) = dd + 1`;
                              ASSUME `val(word (k+1):int64) = k + 1`]) THEN
  SUBGOAL_THEN
    `(if dd + 1 <= k + 1 then word (dd + 1):int64 else word (k + 1)) = word (dd + 1)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC FLAT_MIN_FOLD2 THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME
    `(if dd + 1 <= k + 1 then word (dd + 1):int64 else word (k + 1)) = word (dd + 1)`]) THEN
  (*** el-store `cmp r10,r12; je noel`: r10=r12=word(dd+1) -> EQUAL -> je noel TAKEN (el-store SKIPPED).
       cmp@28 auto-resolves ZF=T from the clean self-subtract; je@29 + noel target@30. ***)
  X86_STEPS_TAC BIGNUM_MOD_EXEC (28--30) THEN
  (*** noel field-combine 0x33a->0x371 (identical to DDK): lf-tidy 31--35 then funnel store 36--46. ***)
  X86_STEPS_TAC BIGNUM_MOD_EXEC (31--35) THEN
  SUBGOAL_THEN `word_and (word p:int64) (word 63) = word (p MOD 64)` ASSUME_TAC THENL
   [SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
    AP_TERM_TAC THEN REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD]; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (36--46) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (*** POST close.  Bridges: FLAT_INNERWORD (~m[dd] negate-add residue), csel-flag -> num-eq. ***)
  SUBGOAL_THEN `bigdigit b dd < 2 EXP 64` ASSUME_TAC THENL
   [REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word pcode:int64) = pcode` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  (* RE-ADD val(word(dd+1))=dd+1: the sim trued-out the original -- WITHOUT it, R14's nested-if
     `if val(word(dd+1)) < val(word pcode)` won't fold to `if dd+1 < pcode` and INNERWORD stalls. *)
  SUBGOAL_THEN `val(word (dd+1):int64) = dd + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word dd:int64) (word pcode)) = 0) <=> dd = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word (dd+1):int64) (word pcode)) = 0) <=> dd + 1 = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  ASM_REWRITE_TAC[WORD_RULE `word_add (word jjv) (word 61):int64 = word(jjv + 61)`; GSYM NOT_LT] THEN
  ASM_SIMP_TAC[FLAT_INNERWORD] THEN
  (* hs-slot window: the noel field-combine funnel over the logged fields R15'(hf') L=R14'(lf');
     FLAT_HS_CLOSE = DDK_HS_CLOSE with the r=0 lo-shift amount hardcoded (x86 stepper inlines it). *)
  CONJ_TAC THENL [MATCH_ACCEPT_TAC FLAT_HS_CLOSE; ALL_TAC] THEN
  (* three memory frame-pulls: z[<dd] (lowdigits), z[>dd] (highdigits), m (untouched).  z[dd] IS
     written, but the ranges below dd and above dd exclude index dd -> READ_OVER_WRITE_ORTHOGONAL. *)
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `bignum_from_memory (z,dd) s46 = bignum_from_memory (z,dd) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s46`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
      REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
      SUBGOAL_THEN `MIN k dd = dd` (fun th -> REWRITE_TAC[th]) THEN
      (UNDISCH_TAC `dd:num < k` THEN ARITH_TAC)];
    SUBGOAL_THEN `bignum_from_memory (word_add z (word (8 * (dd + 1))), k - (dd + 1)) s46 =
                  bignum_from_memory (word_add z (word (8 * (dd + 1))), k - (dd + 1)) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s46`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
      REWRITE_TAC[GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY]];
    SUBGOAL_THEN `bignum_from_memory (m,k) s46 = bignum_from_memory (m,k) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s46`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_ASSUM ACCEPT_TAC]]);;


(* x86 B regime TAIL sim: 0x2a3 -> 0x371 (GROW: 2<=l, dd+1<k, l'=dd+2=(jjv+124)/64).
   Port of ARM TAIL_DDLT_B_WIDE_LOG (tail_ddlt_wide.ml:342) FUSED with the ARM FIELDSEL.

   B vs FLAT control-flow (the sim divergences -- see ARM_TAIL_MAP.md + cont117 memory):
   - trivnegadd `cmp r10,kk; je offendm`: dd<k -> je NOT taken -> m-load runs (same as FLAT).  Top word
     W = bigdigit zpre dd + hi + q*(2^64-1-bigdigit b dd).
   - block-count bump l'=MIN(k+1,(jj+124)/64): B has (jj+124)/64 = dd+2 <= k+1 (dd+1<k), so l'=dd+2.
   - el-store `cmp r10,r12; je noel` (r10=dd+1, r12=dd+2) NOT equal -> je noel NOT taken -> the el-store
     EXECUTES.  It computes rax=lea(z,8*r10); rdi=lea(rsp+8); cmp [rsp],r10; cmove rdi,rax (SATURATED
     would pick rsp+8; B picks rax=z+8*(dd+1) since dd+1<k); mov [rax],r11 -> z[dd+1] = ushr#3(W).
     Then cmovb lf,r11 / cmove hf,r11 / inc r10 (r10->dd+2).
   - noel field-combine 0x33e->0x371: lf-tidy + funnel (same shape as FLAT/DDK) -> hs-slot window.

   POST (raw-value form): R10=R12=word(dd+2); jj-slot=word(jjv+61); zz-slot=word ztin [UNCHANGED];
     z[dd]=extr#3(W:cwin), z[dd+1]=ushr#3(W); bignum(z,dd)=lowdigits zpre dd,
     bignum(z+8*(dd+2),k-(dd+2))=highdigits zpre (dd+2); R15/R14 nested-if logged fields (3-level R14);
     hs-slot(rsp+64)=window((2^64*val R15' + val R14') DIV 2^(p MOD64) MOD 2^64).
   where W = bigdigit zpre dd + hi + q*(2^64-1-bigdigit b dd), extr#3 = word_subword(word_join(word W)
     (word cwin))(3,64), ushr#3 = word_ushr(word W)3.

   Depends on the shared helpers from x86_tail_flat_candidate.ml (DDK_HS_CLOSE, FLAT_HS_CLOSE,
   FLAT_INNERWORD, FIELDCOMBINE_FUNNEL(_W), DDK_VAL_PMOD/LOSHIFT/HISHIFT, HISHIFT_GEN) -- loaded before
   this file in RELOAD.  B-specific helpers proved here: B_MIN_FOLD, B_NEQ, B_NEQ_K2, B_INNERWORD_USHR. *)

(* ---- B-specific helpers ---- *)

(* block-count MIN: (jjv+124)/64=dd+2, MIN(k+1,dd+2)=dd+2 since dd+2<=k+1 (from dd+1<k). *)
let B_MIN_FOLD = prove
 (`!k dd. dd + 1 < k
     ==> (if dd + 2 <= k + 1 then word (dd + 2):int64 else word (k + 1)) = word (dd + 2)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL [REFL_TAC; ASM_ARITH_TAC]);;

(* el-store je-not-taken: cmp r10,r12 = cmp(dd+1,dd+2) NOT equal. *)
let B_NEQ = prove
 (`!dd k. dd + 1 < k /\ k < 2 EXP 58 ==> ~(val(word_sub (word (dd+1):int64) (word (dd+2))) = 0)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `val(word (dd+1):int64) = dd + 1 /\ val(word (dd+2):int64) = dd + 2` MP_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN
  UNDISCH_TAC `val(word_sub (word (dd+1):int64) (word (dd+2))) = 0` THEN
  REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
  DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN ASM_REWRITE_TAC[] THEN ARITH_TAC);;

(* el-store cmove-guard: cmp [rsp](=kk=word k),r10(=word(dd+1)) -> ZF <=> val(word_sub(word(dd+1))
   (word k))=0.  NOT taken (dd+1<k) so cmove leaves rax=z+8*(dd+1) [store to MEMORY, not zz-slot]. *)
let B_NEQ_K2 = prove
 (`!dd k. dd + 1 < k /\ k < 2 EXP 58 ==> ~(val(word_sub (word (dd+1):int64) (word k)) = 0)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `val(word k:int64) = k /\ val(word (dd+1):int64) = dd + 1` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  UNDISCH_TAC `val(word_sub (word (dd+1):int64) (word k)) = 0` THEN
  REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
  DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `dd + 1 < k` THEN ARITH_TAC);;

(* z[dd+1] top-shift word normalize: word_ushr of the negate-add residue by 3 (reuses FLAT_INNERWORD). *)
let B_INNERWORD_USHR = prove
 (`!zd hi q bd. bd < 2 EXP 64
     ==> word_ushr (word_add (word_add (word zd) (word hi))
           (word_zx (word (val(word_not(word bd:int64)) * q):int128):int64)) 3 =
         word_ushr (word (zd + hi + q * (2 EXP 64 - 1 - bd)):int64) 3`,
  REPEAT STRIP_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  MATCH_MP_TAC FLAT_INNERWORD THEN ASM_REWRITE_TAC[]);;


(* ---- the B regime tail sim 0x2a3 -> 0x371 (with hs-slot window, uniform with DDK/FLAT) ---- *)
let BIGNUM_MOD_X86_TAIL_B = prove
 (`!k z m pc q hi cwin ztin b zpre jjv pcode dd p lfv hfv rbxv stackpointer.
     ~(k = 0) /\ k < 2 EXP 58 /\ b < 2 EXP (64 * k) /\ q < 2 EXP 64 /\
     jjv + 124 < 2 EXP 64 /\ dd + 1 < k /\ (jjv + 124) DIV 64 = dd + 2 /\
     pcode < 2 EXP 64 /\ p < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (stackpointer,72) /\
     nonoverlapping (m,8 * k) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word rbxv /\
           read R10 s = word dd /\ read RDI s = word dd /\ read RBP s = word q /\
           read R9 s = word hi /\ read R11 s = word cwin /\ read R13 s = word pcode /\
           read R12 s = word (dd + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word ztin /\
           bignum_from_memory (m,k) s = b /\ bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
           read RIP s = word (pc + 0x371) /\ read R10 s = word (dd + 2) /\ read R12 s = word (dd + 2) /\
           read RSP s = stackpointer /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word pcode /\ read RBX s = word rbxv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (jjv + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word ztin /\
           read (memory :> bytes64 (word_add z (word (8 * dd)))) s =
             word_subword (word_join
               (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64) /\
           read (memory :> bytes64 (word_add z (word (8 * (dd + 1))))) s =
             word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3 /\
           read R15 s = (if dd + 1 = pcode
                         then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                         else if dd = pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else word hfv) /\
           read R14 s = (if dd + 2 = pcode
                         then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                         else if dd + 2 < pcode
                         then word 0
                         else if dd + 1 < pcode
                         then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                         else if dd < pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else word lfv) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word ((2 EXP 64 *
                    val ((if dd + 1 = pcode
                          then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                          else if dd = pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else word hfv):int64) +
                    val ((if dd + 2 = pcode
                          then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                          else if dd + 2 < pcode
                          then word 0
                          else if dd + 1 < pcode
                          then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                          else if dd < pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else word lfv):int64))
                   DIV 2 EXP (p MOD 64) MOD 2 EXP 64) /\
           bignum_from_memory (z,dd) s = lowdigits zpre dd /\
           bignum_from_memory (word_add z (word (8 * (dd + 2))), k - (dd + 2)) s = highdigits zpre (dd + 2) /\
           bignum_from_memory (m,k) s = b)
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `dd:num < k` ASSUME_TAC THENL [UNDISCH_TAC `dd + 1 < k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word dd:int64) = dd` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+2):int64) = dd + 2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (k+1):int64) = k + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word q:int64) = q` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `word_ushr (word_add (word jjv) (word 124):int64) 6 = word (dd + 2)` ASSUME_TAC THENL
   [REWRITE_TAC[word_ushr; GSYM WORD_ADD] THEN
    SUBGOAL_THEN `val(word(jjv + 124):int64) = jjv + 124` SUBST1_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN AP_TERM_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * dd)))) s0 = word (bigdigit b dd)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * dd)))) s0 = word (bigdigit zpre dd)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--5) THEN
  SUBGOAL_THEN `~(val(word_sub (word dd:int64) (word k)) = 0)` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `dd < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `~(val(word_sub (word dd:int64) (word k)) = 0)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (6--27) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word_add (word jjv) (word 124):int64) 6 = word (dd + 2)`;
                              WORD_RULE `word_add (word dd) (word 1):int64 = word(dd+1)`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word (dd+2):int64) = dd + 2`;
                              ASSUME `val(word (k+1):int64) = k + 1`]) THEN
  SUBGOAL_THEN `(if dd + 2 <= k + 1 then word (dd + 2):int64 else word (k + 1)) = word (dd + 2)`
   ASSUME_TAC THENL [MATCH_MP_TAC B_MIN_FOLD THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME
    `(if dd + 2 <= k + 1 then word (dd + 2):int64 else word (k + 1)) = word (dd + 2)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (28--28) THEN
  MP_TAC(SPECL [`dd:num`;`k:num`] B_NEQ) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (29--35) THEN
  (* re-add val(word(dd+1))=dd+1 + the store-target nonoverlapping BEFORE the el-store cmove+store;
     the cmove @0x329 selects rax=z+8*(dd+1) (dd+1<k, not zz-slot) -- resolve its guard via B_NEQ_K2. *)
  SUBGOAL_THEN `val(word (dd+1):int64) = dd + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `nonoverlapping (word pc:int64,0x4da) (word_add z (word (8 * (dd + 1))):int64,8)` ASSUME_TAC THENL
   [SUBGOAL_THEN `8 * (dd + 1) + 8 <= 8 * k` MP_TAC THENL
     [UNDISCH_TAC `dd + 1 < k` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_TAC THEN NONOVERLAPPING_TAC; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (36--37) THEN
  MP_TAC(SPECL [`dd:num`;`k:num`] B_NEQ_K2) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `~(val(word_sub (word (dd+1):int64) (word k)) = 0)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (38--48) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[WORD_RULE `word_add (word (dd+1)) (word 1):int64 = word(dd+2)`]) THEN
  SUBGOAL_THEN `word_and (word p:int64) (word 63) = word (p MOD 64)` ASSUME_TAC THENL
   [SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
    AP_TERM_TAC THEN REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD]; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (49--58) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (*** POST close: bounds + 3 val_sub bridges (dd/dd+1/dd+2 vs pcode) + INNERWORD normalizes. ***)
  SUBGOAL_THEN `dd < 2 EXP 64 /\ dd + 1 < 2 EXP 64 /\ dd + 2 < 2 EXP 64` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MAP_EVERY UNDISCH_TAC [`dd + 1 < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit b dd < 2 EXP 64` ASSUME_TAC THENL
   [REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word pcode:int64) = pcode` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+1):int64) = dd + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+2):int64) = dd + 2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word dd:int64) (word pcode)) = 0) <=> dd = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word (dd+1):int64) (word pcode)) = 0) <=> dd + 1 = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word (dd+2):int64) (word pcode)) = 0) <=> dd + 2 = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  ASM_REWRITE_TAC[WORD_RULE `word_add (word jjv) (word 61):int64 = word(jjv + 61)`; GSYM NOT_LT] THEN
  ASM_SIMP_TAC[FLAT_INNERWORD; B_INNERWORD_USHR] THEN
  (* hs-slot window via FLAT_HS_CLOSE, then 3 memory frame-pulls (z[<dd], z[>dd+1], m). *)
  CONJ_TAC THENL [MATCH_ACCEPT_TAC FLAT_HS_CLOSE; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `bignum_from_memory (z,dd) s58 = bignum_from_memory (z,dd) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s58`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
      REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
      SUBGOAL_THEN `MIN k dd = dd` (fun th -> REWRITE_TAC[th]) THEN
      (UNDISCH_TAC `dd + 1 < k` THEN ARITH_TAC)];
    SUBGOAL_THEN `bignum_from_memory (word_add z (word (8 * (dd + 2))), k - (dd + 2)) s58 =
                  bignum_from_memory (word_add z (word (8 * (dd + 2))), k - (dd + 2)) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s58`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
      REWRITE_TAC[GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY]];
    SUBGOAL_THEN `bignum_from_memory (m,k) s58 = bignum_from_memory (m,k) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s58`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_ASSUM ACCEPT_TAC]]);;


(* x86 C regime TAIL sim: 0x2a3 -> 0x371 (GROW/SAT: l=k, dd+1=k, l'=dd+2=k+1=(jjv+124)/64).
   Port of ARM TAIL_DDLT_C_WIDE_LOG (tail_ddlt_wide.ml:644) FUSED with the ARM FIELDSEL.

   C vs B control-flow: C is a HYBRID of B (el-store executes) + DDK (store lands in zz-slot):
   - trivnegadd je NOT taken (dd<k) -> m-load runs; top word W = bigdigit zpre dd + hi + q*(2^64-1-
     bigdigit b dd), same as B/FLAT.
   - block-count l' = MIN(k+1,(jj+124)/64) = dd+2 (= k+1 since dd+1=k).  C_MIN_FOLD.
   - el-store `cmp r10,r12` (r10=dd+1, r12=dd+2) NOT equal -> je noel NOT taken -> el-store EXECUTES
     (C_NEQ), same as B.  BUT the store-target cmove `cmp [rsp],r10` has r10=dd+1=k=[rsp] -> ZF=T ->
     cmove TAKEN -> rax = rsp+8 (zz-slot), NOT z[dd+1] (C_EQ_K).  So the new word ushr#3(W) lands in
     the TOP zz-slot (rsp+8), like DDK -- NO z[dd+1] memory write, NO self-modify/nonoverlapping issue.
   - noel field-combine 0x33e->0x371: same funnel -> hs-slot window.

   POST: R10=R12=word(dd+2); jj-slot=word(jjv+61); zz-slot(rsp+8)=ushr#3(W) [the new TOP word];
     z[dd]=extr#3(W:cwin); bignum(z,dd)=lowdigits zpre dd (NO highdigits -- dd+1=k is the top);
     R15/R14 nested-if logged fields (in k/k+1/dd vs pcode); hs-slot(rsp+64)=window(...).
   where W = bigdigit zpre dd + hi + q*(2^64-1-bigdigit b dd), extr#3 = word_subword(word_join(word W)
     (word cwin))(3,64), ushr#3 = word_ushr(word W)3.

   Depends on shared helpers from x86_tail_flat_candidate.ml (FLAT_HS_CLOSE, FLAT_INNERWORD, ...) and
   B_INNERWORD_USHR from x86_tail_b_candidate.ml -- both loaded before this file in RELOAD.
   C-specific helpers proved here: C_MIN_FOLD, C_NEQ, C_EQ_K. *)

(* ---- C-specific helpers (dd+1=k form) ---- *)

(* block-count MIN: (jjv+124)/64=dd+2, MIN(k+1,dd+2)=dd+2 (dd+2<=k+1 with equality since dd+1=k). *)
let C_MIN_FOLD = prove
 (`!k dd. dd + 1 = k
     ==> (if dd + 2 <= k + 1 then word (dd + 2):int64 else word (k + 1)) = word (dd + 2)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL [REFL_TAC; ASM_ARITH_TAC]);;

(* el-store je-not-taken: cmp r10,r12 = cmp(dd+1,dd+2) NOT equal (dd+1 <> dd+2 always). *)
let C_NEQ = prove
 (`!dd k. dd + 1 = k /\ k < 2 EXP 58 ==> ~(val(word_sub (word (dd+1):int64) (word (dd+2))) = 0)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `val(word (dd+1):int64) = dd + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 = k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+2):int64) = dd + 2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 = k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  UNDISCH_TAC `val(word_sub (word (dd+1):int64) (word (dd+2))) = 0` THEN
  REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
  DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN
  REWRITE_TAC[ASSUME `val(word (dd+1):int64) = dd + 1`; ASSUME `val(word (dd+2):int64) = dd + 2`] THEN
  ARITH_TAC);;

(* el-store cmove-guard TRUE for C: cmp [rsp](=word k),r10(=word(dd+1)); dd+1=k -> ZF=T -> cmove TAKEN
   -> rax=rsp+8 (zz-slot store).  val(word_sub(word(dd+1))(word k))=0. *)
let C_EQ_K = prove
 (`!dd k. dd + 1 = k /\ k < 2 EXP 58 ==> val(word_sub (word (dd+1):int64) (word k)) = 0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
  AP_TERM_TAC THEN ASM_REWRITE_TAC[]);;


(* ---- the C regime tail sim 0x2a3 -> 0x371 (with hs-slot window, uniform with DDK/FLAT/B) ---- *)
let BIGNUM_MOD_X86_TAIL_C = prove
 (`!k z m pc q hi cwin ztin b zpre jjv pcode dd p lfv hfv rbxv stackpointer.
     ~(k = 0) /\ k < 2 EXP 58 /\ b < 2 EXP (64 * k) /\ q < 2 EXP 64 /\
     jjv + 124 < 2 EXP 64 /\ dd + 1 = k /\ (jjv + 124) DIV 64 = dd + 2 /\
     pcode < 2 EXP 64 /\ p < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (stackpointer,72) /\
     nonoverlapping (m,8 * k) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word rbxv /\
           read R10 s = word dd /\ read RDI s = word dd /\ read RBP s = word q /\
           read R9 s = word hi /\ read R11 s = word cwin /\ read R13 s = word pcode /\
           read R12 s = word (dd + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word ztin /\
           bignum_from_memory (m,k) s = b /\ bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
           read RIP s = word (pc + 0x371) /\ read R10 s = word (dd + 2) /\ read R12 s = word (dd + 2) /\
           read RSP s = stackpointer /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word pcode /\ read RBX s = word rbxv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (jjv + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s =
             word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3 /\
           read (memory :> bytes64 (word_add z (word (8 * dd)))) s =
             word_subword (word_join
               (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64) /\
           read R15 s = (if k = pcode
                         then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                         else if dd = pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else word hfv) /\
           read R14 s = (if k + 1 = pcode
                         then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                         else if k + 1 < pcode
                         then word 0
                         else if k < pcode
                         then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                         else if dd < pcode
                         then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                         else word lfv) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word ((2 EXP 64 *
                    val ((if k = pcode
                          then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                          else if dd = pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else word hfv):int64) +
                    val ((if k + 1 = pcode
                          then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                          else if k + 1 < pcode
                          then word 0
                          else if k < pcode
                          then word_ushr (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) 3
                          else if dd < pcode
                          then word_subword (word_join (word (bigdigit zpre dd + hi + q * (2 EXP 64 - 1 - bigdigit b dd)):int64) (word cwin:int64):int128) (3,64)
                          else word lfv):int64))
                   DIV 2 EXP (p MOD 64) MOD 2 EXP 64) /\
           bignum_from_memory (z,dd) s = lowdigits zpre dd /\
           bignum_from_memory (m,k) s = b)
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `dd:num < k` ASSUME_TAC THENL [UNDISCH_TAC `dd + 1 = k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word dd:int64) = dd` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+2):int64) = dd + 2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MAP_EVERY UNDISCH_TAC [`dd + 1 = k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (k+1):int64) = k + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word q:int64) = q` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `word_ushr (word_add (word jjv) (word 124):int64) 6 = word (dd + 2)` ASSUME_TAC THENL
   [REWRITE_TAC[word_ushr; GSYM WORD_ADD] THEN
    SUBGOAL_THEN `val(word(jjv + 124):int64) = jjv + 124` SUBST1_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `jjv + 124 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN AP_TERM_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * dd)))) s0 = word (bigdigit b dd)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * dd)))) s0 = word (bigdigit zpre dd)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--5) THEN
  SUBGOAL_THEN `~(val(word_sub (word dd:int64) (word k)) = 0)` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `dd < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `~(val(word_sub (word dd:int64) (word k)) = 0)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (6--27) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word_add (word jjv) (word 124):int64) 6 = word (dd + 2)`;
                              WORD_RULE `word_add (word dd) (word 1):int64 = word(dd+1)`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word (dd+2):int64) = dd + 2`;
                              ASSUME `val(word (k+1):int64) = k + 1`]) THEN
  SUBGOAL_THEN `(if dd + 2 <= k + 1 then word (dd + 2):int64 else word (k + 1)) = word (dd + 2)`
   ASSUME_TAC THENL [MATCH_MP_TAC C_MIN_FOLD THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME
    `(if dd + 2 <= k + 1 then word (dd + 2):int64 else word (k + 1)) = word (dd + 2)`]) THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (28--28) THEN
  MP_TAC(SPECL [`dd:num`;`k:num`] C_NEQ) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (29--58) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (*** POST close: fold k+1=dd+2 (dd+1=k), word_and, val facts, bounds, 3 val_sub bridges. ***)
  SUBGOAL_THEN `word_add (word k) (word 1):int64 = word (dd + 2)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM WORD_ADD] THEN AP_TERM_TAC THEN
    UNDISCH_TAC `dd + 1 = k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_add (word k) (word 1):int64 = word (dd + 2)`]) THEN
  SUBGOAL_THEN `word_and (word p:int64) (word 63) = word (p MOD 64)` ASSUME_TAC THENL
   [SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
    AP_TERM_TAC THEN REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_and (word p:int64) (word 63) = word (p MOD 64)`]) THEN
  SUBGOAL_THEN `dd < 2 EXP 64 /\ k < 2 EXP 64 /\ dd + 2 < 2 EXP 64` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MAP_EVERY UNDISCH_TAC [`dd + 1 = k`; `dd < k`; `k < 2 EXP 58`] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit b dd < 2 EXP 64` ASSUME_TAC THENL
   [REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word pcode:int64) = pcode` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (dd+2):int64) = dd + 2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word dd:int64) (word pcode)) = 0) <=> dd = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word k:int64) (word pcode)) = 0) <=> k = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `(val(word_sub (word (dd+2):int64) (word pcode)) = 0) <=> dd + 2 = pcode` ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    ASM_SIMP_TAC[WORD_EQ; DIMINDEX_64; CONG; MOD_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `k + 1 = dd + 2` ASSUME_TAC THENL
   [UNDISCH_TAC `dd + 1 = k` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[WORD_RULE `word_add (word jjv) (word 61):int64 = word(jjv + 61)`; GSYM NOT_LT] THEN
  ASM_SIMP_TAC[FLAT_INNERWORD; B_INNERWORD_USHR] THEN
  SUBGOAL_THEN `val(word_add (word k) (word 1):int64) = dd + 2` ASSUME_TAC THENL
   [REWRITE_TAC[ASSUME `word_add (word k) (word 1):int64 = word (dd + 2)`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ASSUME `word_add (word k) (word 1):int64 = word (dd + 2)`;
             ASSUME `val(word_add (word k) (word 1):int64) = dd + 2`;
             ASSUME `word_and (word p:int64) (word 63) = word (p MOD 64)`] THEN
  ASM_REWRITE_TAC[] THEN
  (* hs-slot window via FLAT_HS_CLOSE, then 2 memory frame-pulls (z[<dd] lowdigits, m). *)
  CONJ_TAC THENL [MATCH_ACCEPT_TAC FLAT_HS_CLOSE; ALL_TAC] THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN `bignum_from_memory (z,dd) s58 = bignum_from_memory (z,dd) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s58`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (z,k) s0 = zpre`)] THEN
      REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
      SUBGOAL_THEN `MIN k dd = dd` (fun th -> REWRITE_TAC[th]) THEN
      (UNDISCH_TAC `dd < k` THEN ARITH_TAC)];
    SUBGOAL_THEN `bignum_from_memory (m,k) s58 = bignum_from_memory (m,k) s0`
     SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can
        (term_match [] `(f:x86state->x86state->bool) s0 s58`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_ASSUM ACCEPT_TAC]]);;


(* x86 block-composition value bridges -- arch-independent (num-level) lemmas the 9 regime blocks need,
   ported verbatim from the ARM sources (armstate -> x86state in the `s:...` annotations only; the
   BIGNUM_FROM_MEMORY_* / bigdigit / lowdigits machinery is arch-generic).  These assemble the raw
   tail stores (z[dd]=extr#3(W), z[dd+1]/zz-slot=ushr#3(W)) into the full block value
   2^(64k)*Ztop + bignum(z,k) = 2^61*zv + block (- qh*b for the general case).

   Sources: STORE_IS_BIGDIGIT (win_block_helpers.ml), C_ZK_FROM_STORES (block_c_304_win.ml:59),
   GROWING_ZK_FROM_STORES_GEN (cgen_helpers.ml).  Depend on scaffold Section-B: EXTR_FUNNEL_VAL,
   VALUE_GROW_STEP, C_TOP_FUNNEL_GEN, C_ASSEMBLE_GEN, HIGHZ_VANISH, BIGNUM_ASSEMBLE_2 (all present). *)

(* STORE_IS_BIGDIGIT: a stored digit read back is word(bigdigit v j) for j<k. *)
let STORE_IS_BIGDIGIT = prove
 (`!z k s v j. bignum_from_memory (z,k) s = v /\ j < k
    ==> read (memory :> bytes64 (word_add z (word (8 * j)))) s = word (bigdigit v j)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
  MP_TAC(ISPECL [`k:num`; `z:int64`; `s:x86state`; `j:num`] BIGDIGIT_BIGNUM_FROM_MEMORY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[WORD_VAL]);;

(* C_ZK_FROM_STORES: the C-regime value assembly -- top word spills into Xtop (=val of the zz-slot). *)
let C_ZK_FROM_STORES = prove
 (`!z k zpre zv b block cwinw W Xtop s.
    2 <= k /\ zv < 2 EXP (64 * k) /\ block < 2 EXP 61 /\ cwinw < 2 EXP 64 /\
    lowdigits zpre (k-1) + 2 EXP (64 * (k-1)) * (cwinw DIV 8 + 2 EXP 61 * 0) +
      2 EXP 61 * (0 * lowdigits b (k-1)) =
      block + 2 EXP 61 * lowdigits zv (k-1) + 2 EXP 61 * (0 * 2 EXP (64 * (k-1))) /\
    2 EXP 64 * 0 + W = bigdigit zv (k-1) + 0 + 0 * (2 EXP 64 - 1 - bigdigit b (k-1)) /\
    bignum_from_memory (z,k-1) s = lowdigits zpre (k-1) /\
    read (memory :> bytes64 (word_add z (word (8 * (k-1))))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64) /\
    Xtop = val(word_ushr (word W:int64) 3)
    ==> 2 EXP (64 * k) * Xtop + bignum_from_memory (z,k) s = 2 EXP 61 * zv + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `val(word cwinw:int64) = cwinw` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN
   `bignum_from_memory (z,k) s =
      bignum_from_memory (z,k-1) s +
      2 EXP (64 * (k-1)) * val(read (memory :> bytes64 (word_add z (word (8 * (k-1))))) s)`
    SUBST1_TAC THENL
   [MP_TAC(ISPECL [`k - 1`; `z:int64`; `s:x86state`] BIGNUM_FROM_MEMORY_STEP) THEN
    SUBGOAL_THEN `(k - 1) + 1 = k` SUBST1_TAC THENL
     [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[EXTR_FUNNEL_VAL; VAL_WORD_USHR] THEN
  SUBGOAL_THEN `val(word W:int64) = W` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `2 EXP 64 * 0 + W = bigdigit zv (k-1) + 0 + 0 * (2 EXP 64 - 1 - bigdigit b (k-1))` THEN
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`k:num`; `k - 1`; `0`; `block:num`; `zv:num`; `b:num`; `cwinw:num`;
                 `0`; `W:num`; `0`; `lowdigits zpre (k-1)`] VALUE_GROW_STEP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(k - 1) + 1 = k` SUBST1_TAC THENL [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `lowdigits zv k = zv` SUBST1_TAC THENL
   [REWRITE_TAC[lowdigits] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN ARITH_TAC);;

(* BIGNUM_ASSEMBLE_2: two-digit assembly (arch-independent; from arm_core_KK.ml). *)
let BIGNUM_ASSEMBLE_2 = prove
 (`!z dd s.
     bignum_from_memory (z,dd + 2) s =
     bignum_from_memory (z,dd) s +
     2 EXP (64 * dd) * val (read (memory :> bytes64 (word_add z (word (8 * dd)))) s) +
     2 EXP (64 * (dd + 1)) * val (read (memory :> bytes64 (word_add z (word (8 * (dd + 1))))) s)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `dd + 2 = (dd + 1) + 1` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[BIGNUM_FROM_MEMORY_STEP] THEN
  MP_TAC(SPECL [`dd:num`; `z:int64`; `s:x86state`] BIGNUM_FROM_MEMORY_STEP) THEN
  ARITH_TAC);;

(* GROWING_ZK_FROM_STORES_GEN: the B/grow-regime value assembly (general qh) -- new word to z[l]. *)
let GROWING_ZK_FROM_STORES_GEN = prove
 (`!z k l zpre zv b block hi cwinw W LOW qh s.
    2 <= l /\ l < k /\ b < 2 EXP (64 * l) /\ zv < 2 EXP (64 * l) /\ block < 2 EXP 61 /\
    cwinw < 2 EXP 64 /\ qh * b <= zv /\
    highdigits zpre (l - 1) = highdigits zv (l - 1) /\
    lowdigits zpre (l-1) + 2 EXP (64 * (l-1)) * (cwinw DIV 8 + 2 EXP 61 * hi) +
      2 EXP 61 * (qh * lowdigits b (l-1)) =
      block + 2 EXP 61 * lowdigits zv (l-1) + 2 EXP 61 * (qh * 2 EXP (64 * (l-1))) /\
    2 EXP 64 * qh + LOW = W /\ LOW < 2 EXP 64 /\
    W = bigdigit zv (l-1) + hi + qh * (2 EXP 64 - 1 - bigdigit b (l-1)) /\
    bignum_from_memory (z,l-1) s = lowdigits zpre (l-1) /\
    bignum_from_memory (word_add z (word (8 * (l+1))), k - (l+1)) s = highdigits zpre (l+1) /\
    read (memory :> bytes64 (word_add z (word (8 * (l-1))))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64) /\
    read (memory :> bytes64 (word_add z (word (8 * l)))) s = word_ushr (word W:int64) 3
    ==> bignum_from_memory (z,k) s = 2 EXP 61 * (zv - qh * b) + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `highdigits zpre (l + 1) = 0` ASSUME_TAC THENL
   [MATCH_MP_TAC HIGHZ_VANISH THEN EXISTS_TAC `zv:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(l + 1) + (k - (l + 1)) = k` ASSUME_TAC THENL
   [UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s = bignum_from_memory (z,l+1) s` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `l + 1`; `k - (l + 1)`; `s:x86state`] BIGNUM_FROM_MEMORY_SPLIT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES];
    ALL_TAC] THEN
  SUBGOAL_THEN `word W:int64 = word LOW` ASSUME_TAC THENL
   [MATCH_MP_TAC C_TOP_FUNNEL_GEN THEN EXISTS_TAC `qh:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,l + 1) s =
    bignum_from_memory (z,l-1) s +
    2 EXP (64 * (l-1)) * val (read (memory :> bytes64 (word_add z (word (8 * (l-1))))) s) +
    2 EXP (64 * ((l-1)+1)) * val (read (memory :> bytes64 (word_add z (word (8 * ((l-1)+1))))) s)`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `l - 1`; `s:x86state`] BIGNUM_ASSEMBLE_2) THEN
    SUBGOAL_THEN `(l - 1) + 2 = l + 1` SUBST1_TAC THENL
     [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `l - 1 + 1 = l` SUBST1_TAC THENL [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ASSUME `word W:int64 = word LOW`; EXTR_FUNNEL_VAL; VAL_WORD_USHR] THEN
  SUBGOAL_THEN `val(word LOW:int64) = LOW /\ val(word cwinw:int64) = cwinw` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN
  MP_TAC(ISPECL [`lowdigits zpre (l-1)`; `cwinw:num`; `hi:num`; `qh:num`; `b:num`; `zv:num`;
                 `block:num`; `LOW:num`; `l:num`] C_ASSEMBLE_GEN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN
    FIRST_ASSUM(fun th -> if concl th =
      `lowdigits zpre (l-1) + 2 EXP (64 * (l-1)) * (cwinw DIV 8 + 2 EXP 61 * hi) +
       2 EXP 61 * (qh * lowdigits b (l-1)) =
       block + 2 EXP 61 * lowdigits zv (l-1) + 2 EXP 61 * (qh * 2 EXP (64 * (l-1)))`
      then MP_TAC th else NO_TAC) THEN REWRITE_TAC[MULT_ASSOC];
    ALL_TAC] THEN
  FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,l-1) s = lowdigits zpre (l-1)`
    then REWRITE_TAC[th] else NO_TAC) THEN
  DISCH_THEN(fun th -> MP_TAC th) THEN ARITH_TAC);;

(* C_TOPWORD_AGREE: the top word z[k-1] is untouched by the inner loop, so bignum(z,k)-at-tail-entry
   (=zc) agrees with the block-input zpre in digit k-1.  From PREFIX's highdigits(z+8*(k-1),1)=highdigits
   zpre(k-1) (the top part of z still holds zpre's top digit) + STORE-read of zc. *)
let C_TOPWORD_AGREE = prove
 (`!z k zpre zc s.
     2 <= k /\
     bignum_from_memory (word_add z (word (8 * (k - 1))), k - (k - 1)) s = highdigits zpre (k - 1) /\
     bignum_from_memory (z,k) s = zc
     ==> bigdigit zc (k - 1) = bigdigit zpre (k - 1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `k - (k - 1) = 1` ASSUME_TAC THENL [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit zc (k - 1) = val(read (memory :> bytes64 (word_add z (word (8 * (k - 1))))) s)`
    SUBST1_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc` then SUBST1_TAC(SYM th) else NO_TAC) THEN
    ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; ARITH_RULE `2 <= k ==> k - 1 < k`]; ALL_TAC] THEN
  MP_TAC(ISPECL [`zpre:num`; `k - 1`; `0`] BIGDIGIT_HIGHDIGITS) THEN REWRITE_TAC[ADD_CLAUSES] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  FIRST_ASSUM(fun th -> if lhs(concl th) = `bignum_from_memory (word_add z (word (8 * (k - 1))),k - (k - 1)) s`
    then SUBST1_TAC(SYM th) else NO_TAC) THEN
  ASM_REWRITE_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; MULT_CLAUSES; WORD_ADD_0; ARITH_RULE `0 < 1`]);;

(* CBLK_TOPSPLIT: package CBLK_UNIQ+CBLK_SPLIT -- from the full-value identity 2^(64k)*V+B=Zf (Zf a
   (k+1)-digit value, B a k-digit value) conclude V is Zf's top digit and B its low k digits.  Avoids
   the fragile SUBGOAL_THEN+STRIP_ASSUME plumbing at the block call site (just MP_TAC + STRIP). *)
let CBLK_TOPSPLIT = prove
 (`!k V B Zf. 2 <= k /\ Zf < 2 EXP (64 * (k + 1)) /\ B < 2 EXP (64 * k) /\
              2 EXP (64 * k) * V + B = Zf
     ==> V = bigdigit Zf k /\ B = lowdigits Zf k`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`2 EXP (64 * k)`; `V:num`; `B:num`; `bigdigit Zf k`; `lowdigits Zf k`] CBLK_UNIQ) THEN
  REWRITE_TAC[LT_NZ; EXP_EQ_0; ARITH_EQ; LOWDIGITS_BOUND] THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`Zf:num`; `k:num`] CBLK_SPLIT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* C_BLOCK_VALUE_CLOSE: the C-block value assembly, packaging C_ZK_FROM_STORES with the *0-term
   massaging + invariant substitution done internally.  Takes the block's raw hyps (invariant in
   bignum(z,k-1) form, bignum(z,k-1)=lowdigits zc, the bigdigit bridge, the z[k-1] store) at one state s
   and yields 2^(64k)*Xtop + bignum(z,k)s = 2^61*zpre + blk.  Reduces the block call to one MP_TAC. *)
let C_BLOCK_VALUE_CLOSE = prove
 (`!z k zpre zc cwinw blk Xtop s.
     2 <= k /\ zpre < 2 EXP (64 * k) /\ blk < 2 EXP 61 /\ val(cwinw:int64) < 2 EXP 64 /\
     bignum_from_memory (z,k-1) s + 2 EXP (64 * (k-1)) * (val cwinw DIV 8) =
       blk + 2 EXP 61 * lowdigits zpre (k-1) /\
     bignum_from_memory (z,k-1) s = lowdigits zc (k-1) /\
     bigdigit zc (k-1) = bigdigit zpre (k-1) /\
     read (memory :> bytes64 (word_add z (word (8 * (k-1))))) s =
       word_subword (word_join (word (bigdigit zc (k-1)):int64) (word (val cwinw):int64):int128) (3,64) /\
     Xtop = val(word_ushr (word (bigdigit zc (k-1)):int64) 3)
     ==> 2 EXP (64 * k) * Xtop + bignum_from_memory (z,k) s = 2 EXP 61 * zpre + blk`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `zpre:num`; `(0:num)`; `blk:num`; `val(cwinw:int64)`;
                 `bigdigit zc (k-1)`; `Xtop:num`; `s:x86state`] C_ZK_FROM_STORES) THEN
  ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
  ANTS_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k - 1) s = lowdigits zc (k - 1)`
      then GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [SYM th] else NO_TAC) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* FLAT_ZK_FROM_STORES: the FLAT-regime value assembly (l STAYS, X23'=0, no top-word spill).
   Single store z[dd]=extr#3(W); bignum(z,k)' = 2^61*zv+block DIRECTLY (fits in dd+1<=k words).
   Ported verbatim from block_flat_304_win.ml:80 (armstate->x86state). *)
let FLAT_ZK_FROM_STORES = prove
 (`!z k zpre zv b block cwinw W dd s.
    dd + 1 <= k /\ zv < 2 EXP (64 * (dd + 1)) /\ block < 2 EXP 61 /\ cwinw < 2 EXP 64 /\
    2 EXP 61 * zv + block < 2 EXP (64 * (dd + 1)) /\
    highdigits zpre (dd + 1) = 0 /\
    lowdigits zpre dd + 2 EXP (64 * dd) * (cwinw DIV 8 + 2 EXP 61 * 0) +
      2 EXP 61 * (0 * lowdigits b dd) =
      block + 2 EXP 61 * lowdigits zv dd + 2 EXP 61 * (0 * 2 EXP (64 * dd)) /\
    2 EXP 64 * 0 + W = bigdigit zv dd + 0 + 0 * (2 EXP 64 - 1 - bigdigit b dd) /\
    bignum_from_memory (z,dd) s = lowdigits zpre dd /\
    bignum_from_memory (word_add z (word (8 * (dd + 1))), k - (dd + 1)) s = highdigits zpre (dd + 1) /\
    read (memory :> bytes64 (word_add z (word (8 * dd)))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64)
    ==> bignum_from_memory (z,k) s = 2 EXP 61 * zv + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `val(word cwinw:int64) = cwinw /\ val(word W:int64) = W` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    ASM_REWRITE_TAC[] THEN
    (UNDISCH_TAC `2 EXP 64 * 0 + W = bigdigit zv dd + 0 + 0 * (2 EXP 64 - 1 - bigdigit b dd)` THEN
     REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[BIGDIGIT_BOUND]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`dd + 1`; `dd:num`; `0`; `block:num`; `zv:num`; `b:num`; `cwinw:num`;
                 `0`; `W:num`; `0`; `lowdigits zpre dd`] VALUE_GROW_STEP) THEN
  ASM_REWRITE_TAC[ARITH_RULE `dd < dd + 1`; BIGDIGIT_BOUND] THEN
  SUBGOAL_THEN `lowdigits zv (dd + 1) = zv` SUBST1_TAC THENL
   [REWRITE_TAC[lowdigits] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_TAC THEN
  SUBGOAL_THEN `W DIV 2 EXP 3 = 0` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (64 * (dd + 1)) * (W DIV 2 EXP 3) < 2 EXP (64 * (dd + 1)) * 1` MP_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES] THEN
      TRANS_TAC LET_TRANS `2 EXP 61 * zv + block` THEN CONJ_TAC THENL
       [FIRST_X_ASSUM(fun th -> if is_eq(concl th) &&
           can (find_term (fun t -> t = `W DIV 2 EXP 3`)) (concl th) &&
           can (find_term (fun t -> t = `2 EXP 61 * zv`)) (concl th)
          then MP_TAC th else NO_TAC) THEN ARITH_TAC;
        ASM_REWRITE_TAC[]];
      SIMP_TAC[LT_MULT_LCANCEL; EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s = bignum_from_memory (z,dd+1) s` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `dd + 1`; `k - (dd + 1)`; `s:x86state`] BIGNUM_FROM_MEMORY_SPLIT) THEN
    SUBGOAL_THEN `(dd + 1) + (k - (dd + 1)) = k` SUBST1_TAC THENL
     [UNDISCH_TAC `dd + 1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`dd:num`; `z:int64`; `s:x86state`] BIGNUM_FROM_MEMORY_STEP) THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[EXTR_FUNNEL_VAL] THEN
  UNDISCH_TAC `(lowdigits zpre dd +
               2 EXP (64 * dd) * (2 EXP 61 * W MOD 2 EXP 3 + cwinw DIV 8)) +
               2 EXP (64 * (dd + 1)) * W DIV 2 EXP 3 = block + 2 EXP 61 * zv` THEN
  ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN ARITH_TAC);;

(* GROWING_ZK_FROM_STORES: the B/GROW-regime value assembly, qh=0 SPECIALIZATION (window=0).  Unlike
   GROWING_ZK_FROM_STORES_GEN it does NOT require b<2^(64*l) (the qh*b terms vanish), and derives hiw=0
   internally.  Two stores z[l-1]=extr#3(W), z[l]=ushr#3(W); bignum(z,k)s = 2^61*zv+block.  Ported verbatim
   from growing_zk_from_stores.ml:20 (armstate->x86state).  Deps GROWING_ZK_EQ/HI_ZERO/HIGHZ_VANISH/
   BIGNUM_ASSEMBLE_2/EXTR_FUNNEL_VAL (scaffold + this file). *)
let GROWING_ZK_FROM_STORES = prove
 (`!z k l zpre zv b block hiw cwinw W s.
    2 <= l /\ l < k /\ zv < 2 EXP (64 * l) /\ block < 2 EXP 61 /\ cwinw < 2 EXP 64 /\
    highdigits zpre (l - 1) = highdigits zv (l - 1) /\
    lowdigits zpre (l-1) + 2 EXP (64 * (l-1)) * (cwinw DIV 8 + 2 EXP 61 * hiw) +
      2 EXP 61 * (0 * lowdigits b (l-1)) =
      block + 2 EXP 61 * lowdigits zv (l-1) + 2 EXP 61 * (0 * 2 EXP (64 * (l-1))) /\
    2 EXP 64 * 0 + W = bigdigit zv (l-1) + hiw + 0 * (2 EXP 64 - 1 - bigdigit b (l-1)) /\
    bignum_from_memory (z,l-1) s = lowdigits zpre (l-1) /\
    bignum_from_memory (word_add z (word (8 * (l+1))), k - (l+1)) s = highdigits zpre (l+1) /\
    read (memory :> bytes64 (word_add z (word (8 * (l-1))))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64) /\
    read (memory :> bytes64 (word_add z (word (8 * l)))) s =
      word_ushr (word W:int64) 3
    ==> bignum_from_memory (z,k) s = 2 EXP 61 * zv + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `hiw = 0` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`lowdigits zpre (l-1)`; `cwinw:num`; `hiw:num`; `block:num`;
                   `lowdigits zv (l-1)`; `l - 1`; `lowdigits b (l-1)`] HI_ZERO) THEN
    ASM_REWRITE_TAC[LOWDIGITS_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `highdigits zpre (l + 1) = 0` ASSUME_TAC THENL
   [MATCH_MP_TAC HIGHZ_VANISH THEN EXISTS_TAC `zv:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(l + 1) + (k - (l + 1)) = k` ASSUME_TAC THENL
   [UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s = bignum_from_memory (z,l+1) s` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `l + 1`; `k - (l + 1)`; `s:x86state`] BIGNUM_FROM_MEMORY_SPLIT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES]; ALL_TAC] THEN
  ABBREV_TAC `dd = l - 1` THEN
  SUBGOAL_THEN `l = dd + 1` SUBST_ALL_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`2 <= l`; `l - 1 = dd`] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `(dd + 1) + 1 = dd + 2`] THEN
  MP_TAC(ISPECL [`z:int64`; `dd:num`; `s:x86state`] BIGNUM_ASSEMBLE_2) THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[EXTR_FUNNEL_VAL; VAL_WORD_USHR] THEN
  SUBGOAL_THEN `val(word W:int64) = W` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `2 EXP 64 * 0 + W = bigdigit zv dd + 0 + 0 * (2 EXP 64 - 1 - bigdigit b dd)` THEN
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word cwinw:int64) = cwinw` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  MP_TAC(ISPECL [`lowdigits zpre dd`; `W:num`; `cwinw:num`; `block:num`; `zv:num`; `dd:num`; `b:num`]
                GROWING_ZK_EQ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN
    FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,dd) s = lowdigits zpre dd`
      then GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [SYM th] else NO_TAC) THEN
    FIRST_X_ASSUM ACCEPT_TAC;
    REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN DISCH_THEN(fun th -> MP_TAC th) THEN ARITH_TAC]);;

(* FLAT_ZK_FROM_STORES_GEN: the FLAT-regime value assembly, GENERAL qh (l STAYS, X23'=0, no top-word spill).
   Single store z[l-1]=extr#3(W); bignum(z,k)' = 2^61*(zv-qh*b)+block DIRECTLY (fits l<=k words, W DIV 8=0
   since Zf'<2^(64l)).  The FLATGEN_ALL analog of FLAT_ZK_FROM_STORES (qh=0) -- keeps the qh*b term.
   Ported verbatim from cgen_helpers.ml:440 (armstate->x86state).  Deps C_ASSEMBLE_GEN/EXTR_FUNNEL_VAL/
   BIGNUM_FROM_MEMORY_SPLIT/STEP/VAL_WORD_EQ (all scaffold). *)
let FLAT_ZK_FROM_STORES_GEN = prove
 (`!z k zpre zv b block cwinw W hi qh l s.
    2 <= l /\ l <= k /\ b < 2 EXP (64 * l) /\ zv < 2 EXP (64 * l) /\ block < 2 EXP 61 /\
    cwinw < 2 EXP 64 /\ W < 2 EXP 64 /\ qh * b <= zv /\
    2 EXP 61 * (zv - qh * b) + block < 2 EXP (64 * l) /\ highdigits zpre l = 0 /\
    lowdigits zpre (l-1) + 2 EXP (64 * (l-1)) * (cwinw DIV 8 + 2 EXP 61 * hi) +
      2 EXP 61 * qh * lowdigits b (l-1) =
      block + 2 EXP 61 * lowdigits zv (l-1) + 2 EXP 61 * qh * 2 EXP (64 * (l-1)) /\
    2 EXP 64 * qh + W = bigdigit zv (l-1) + hi + qh * (2 EXP 64 - 1 - bigdigit b (l-1)) /\
    bignum_from_memory (z,l-1) s = lowdigits zpre (l-1) /\
    bignum_from_memory (word_add z (word (8 * l)), k - l) s = highdigits zpre l /\
    read (memory :> bytes64 (word_add z (word (8 * (l-1))))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64)
    ==> bignum_from_memory (z,k) s = 2 EXP 61 * (zv - qh * b) + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`lowdigits zpre (l-1)`; `cwinw:num`; `hi:num`; `qh:num`; `b:num`; `zv:num`;
                 `block:num`; `W:num`; `l:num`] C_ASSEMBLE_GEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `W DIV 2 EXP 3 = 0` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (64 * l) * (W DIV 2 EXP 3) < 2 EXP (64 * l) * 1` MP_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES] THEN
      UNDISCH_TAC `2 EXP 61 * (zv - qh * b) + block < 2 EXP (64 * l)` THEN
      UNDISCH_TAC `2 EXP (64 * l) * W DIV 2 EXP 3 + lowdigits zpre (l - 1) +
           2 EXP (64 * (l - 1)) * (2 EXP 61 * W MOD 2 EXP 3 + cwinw DIV 8) =
           2 EXP 61 * (zv - qh * b) + block` THEN ARITH_TAC;
      SIMP_TAC[LT_MULT_LCANCEL; EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s = bignum_from_memory (z,l) s` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `l:num`; `k - l`; `s:x86state`] BIGNUM_FROM_MEMORY_SPLIT) THEN
    SUBGOAL_THEN `l + (k - l) = k` SUBST1_TAC THENL
     [UNDISCH_TAC `l <= k` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES];
    ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,l) s = bignum_from_memory (z,(l-1)+1) s` SUBST1_TAC THENL
   [AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`l - 1`; `z:int64`; `s:x86state`] BIGNUM_FROM_MEMORY_STEP) THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[EXTR_FUNNEL_VAL] THEN
  SUBGOAL_THEN `val(word cwinw:int64) = cwinw /\ val(word W:int64) = W` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN
  UNDISCH_TAC `2 EXP (64 * l) * W DIV 2 EXP 3 + lowdigits zpre (l - 1) +
      2 EXP (64 * (l - 1)) * (2 EXP 61 * W MOD 2 EXP 3 + cwinw DIV 8) =
      2 EXP 61 * (zv - qh * b) + block` THEN
  ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
  SUBGOAL_THEN `(l - 1) + 1 = l` SUBST1_TAC THENL [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  ARITH_TAC);;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_DDK_WIN -- the SATURATED (DDK) main-loop block.
   One full main-loop iteration (pc+0x217 -> pc+0x371) in the DDK regime (l = k+1,
   l-1 = k saturated; top quotient/remainder word spills to the zz-slot rsp+8).

   x86 vs ARM structure: ARM BLOCK_DDK_304_WIN is a 3-segment compose
     seg-A (PREFIX 0x1a4->0x23c) ;; seg-B (TAIL 0x23c->0x2e8) ;; seg-C (FIELDSEL 0x2e8->0x304).
   On x86 the noel field-combine is INSIDE the tail, so BIGNUM_MOD_X86_TAIL_DDK already fuses
   seg-B+seg-C.  Hence this block is a 2-segment compose:
     seg-A : BIGNUM_MOD_X86_PREFIX          (0x217 -> 0x2a3)
     seg-B : BIGNUM_MOD_X86_TAIL_DDK        (0x2a3 -> 0x371, tail+fieldsel fused)
   plus the SAME Section-B value bridges the ARM block uses (all in the x86 scaffold, 0-hyp):
     DDK_QHAT_LT, RECIP_T0_FROM_D, ROUNDUP_T0_LE, DDK_R_LT_D, DDK_NOBORROW_THREADED_GEN,
     TAIL_CARRY_EQ_Q, DDK_TOP_FUNNEL, DDK_VALUE_CLOSE_D, DDK_VALUE_JJ,
     TAIL_LOGIN_TO_ZPRE_SAT, DDK_LOGDIGIT_FINALIZE_NC (local), WINDOW_FROM_LOGGED.

   x86 register/slot map (vs ARM):  z=RSI(X1) m=R8(X4) ; top word Ztin -> zz-slot rsp+8 (ARM X23);
     window h -> hs-slot rsp+64 (ARM X15) ; q=RBP ; hi(carry)=R9(X5) ; cwin=R11(X22) ;
     lf=R14(X13) hf=R15(X14) ; pcode=R13(X12) ; l=R12(X19) ; ii-count=R10(X8) ; jj-slot rsp+56 (X17).
   ============================================================================ *)

(* DDK_LOGDIGIT_FINALIZE_NC: identical to ARM block_ddk_304_win.ml:38 (arch-independent, num-level).
   Resolves the two logged fields R14'/R15' to bigdigit of the finalized accumulator digits
   (pcode-1, pcode).  Drops the never-needed `k=pcode ==> hfin=Ztp` conditional. *)
let DDK_LOGDIGIT_FINALIZE_NC = prove
 (`!Ztp zpre k pcode lfin hfin.
    Ztp < 2 EXP 64 /\ zpre < 2 EXP (64 * k) /\ 1 <= pcode /\ pcode <= k + 1 /\
    (pcode <= k ==> lfin = bigdigit zpre (pcode - 1)) /\
    (pcode < k ==> hfin = bigdigit zpre pcode) /\
    (k + 1 = pcode ==> hfin = 0)
    ==> (if k = pcode then word Ztp:int64 else word hfin) =
        word (bigdigit (2 EXP (64 * k) * Ztp + zpre) pcode) /\
        (if k + 1 = pcode then word Ztp:int64
         else if pcode <= k + 1 then (if k < pcode then word Ztp else word lfin)
              else word 0) =
        word (bigdigit (2 EXP (64 * k) * Ztp + zpre) (pcode - 1))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `bigdigit (2 EXP (64 * k) * Ztp + zpre) k = Ztp` ASSUME_TAC THENL
   [MATCH_MP_TAC BIGDIGIT_TOP_SAT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!j. j < k ==> bigdigit (2 EXP (64 * k) * Ztp + zpre) j = bigdigit zpre j` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC BIGDIGIT_AGREE_BELOW THEN EXISTS_TAC `k:num` THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[lowdigits] THEN
    SUBGOAL_THEN `(2 EXP (64 * k) * Ztp + zpre) MOD 2 EXP (64 * k) = zpre MOD 2 EXP (64 * k)`
      SUBST1_TAC THENL [REWRITE_TAC[MOD_MULT_ADD]; ALL_TAC] THEN
    ASM_SIMP_TAC[MOD_LT];
    ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit (2 EXP (64 * k) * Ztp + zpre) (k + 1) = 0` ASSUME_TAC THENL
   [REWRITE_TAC[bigdigit] THEN
    SUBGOAL_THEN `(2 EXP (64 * k) * Ztp + zpre) DIV 2 EXP (64 * (k + 1)) = 0`
      (fun th -> REWRITE_TAC[th; MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0]) THEN
    MATCH_MP_TAC DIV_LT THEN
    REWRITE_TAC[ARITH_RULE `64 * (k + 1) = 64 * k + 64`; EXP_ADD] THEN
    MATCH_MP_TAC VAL_LT_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [COND_CASES_TAC THENL
     [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
      FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      ASM_CASES_TAC `k + 1 = pcode` THENL
       [SUBGOAL_THEN `hfin = 0` SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
        FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN `pcode < k` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[] THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
        FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC]];
    ASM_CASES_TAC `k + 1 = pcode` THENL
     [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN
      SUBGOAL_THEN `pcode - 1 = k` SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
      CONV_TAC SYM_CONV THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `pcode <= k + 1 /\ ~(k < pcode)` STRIP_ASSUME_TAC THENL
       [ASM_ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN
      SUBGOAL_THEN `lfin = bigdigit zpre (pcode - 1)` SUBST1_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
      CONV_TAC SYM_CONV THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC]]);;

(* DDK_LF_REORDER: pure if-guard reorder identity.  The x86 window's LF' field-selector uses the
   raw `k+1<pcode then word 0` branch order (from the state's nested-if), whereas
   DDK_LOGDIGIT_FINALIZE_NC's 2nd conclusion uses the `pcode<=k+1 then (..) else word 0` order.
   They are value-identical; this bridges them so the finalize CONJUNCT2 applies to the window's LF'. *)
let DDK_LF_REORDER = prove
 (`!(A:int64) B r c.
     (if r + 1 = c then A else if r + 1 < c then word 0 else if r < c then A else B) =
     (if r + 1 = c then A else if c <= r + 1 then (if r < c then A else B) else word 0)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `r + 1 = c` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `r + 1 < c` THEN ASM_REWRITE_TAC[] THENL
   [SUBGOAL_THEN `~(c <= r + 1)` (fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `r + 1 < c` THEN ARITH_TAC;
    SUBGOAL_THEN `c <= r + 1` (fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `~(r + 1 < c)` THEN ARITH_TAC]);;


(* BIGNUM_MOD_X86_PREFIX_Z8: PREFIX (0x217->0x2a3) with the top-word zz-slot (rsp+8) threaded
   through the POST.  sp+8 is preserved by PREFIX (not in its frame: only regs + bignum(z,k) change),
   so this is PREFIX + a frame-pull of the sp+8 read.  Needed because TAIL_DDK's PRE reads sp+8 = word
   Ztin (the incoming main-loop accumulator top word), which the base PREFIX POST does not expose.
   Reusable across ALL 9 regime blocks.  (ENSURES_SUBLEMMA_THM: 3 branches P=>P'/subsumed/POST-impl;
   POST-impl closes the sp8@s' conjunct via frame-pull -- KEY: REWRITE_TAC[bignum] BEFORE
   READ_OVER_WRITE_ORTHOGONAL_TAC, else the write(memory:>bignum(z,k)) chain throws dest_comb.) *)
let BIGNUM_MOD_X86_PREFIX_Z8 = prove
 (`!k z m x n a b pc p ii w l zv lfv h jjv Ztin stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\ 2 <= l /\ l <= k + 1 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ h < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read R10 s = word (l - 1) /\ read RSI s = z /\ read R8 s = m /\
           read RBP s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
           read RDI s = word (l - 1) /\ read R13 s = word (p DIV 64 + 1) /\
           read RSP s = stackpointer /\ read RBX s = word (61 * ii) /\ read R12 s = word l /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\
           bignum_from_memory (word_add z (word (8 * (l-1))), k - (l-1)) s = highdigits zv (l-1) /\
           (1 <= l - 1
            ==> read R14 s =
                read (memory :> bytes64 (word_add z (word (8 * (MIN (l-1) (p DIV 64 + 1) - 1))))) s) /\
           (p DIV 64 + 1 < l - 1
            ==> read R15 s = read (memory :> bytes64 (word_add z (word (8 * (p DIV 64 + 1))))) s) /\
           (~(p DIV 64 + 1 < l - 1) ==> read R15 s = word 0) /\
           bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,l-1) s +
           2 EXP (64 * (l-1)) * (val(read R11 s) DIV 8 + 2 EXP 61 * val(read R9 s)) +
           2 EXP 61 * ((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 * lowdigits b (l-1) =
           (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (l-1) +
           2 EXP 61 * ((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 * 2 EXP (64 * (l-1)))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R14; R15] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
    [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
     `l:num`; `zv:num`; `lfv:num`; `h:num`; `jjv:num`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX)) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    SUBSUMED_MAYCHANGE_TAC;
    REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    (* two residual conjuncts: sp8@s' = word Ztin, and bignum(m,k)@s' = b.  Both frame-pulls
       from the PRE (sp+8 and m-memory both preserved -- neither in the PREFIX frame). *)
    REPEAT CONJ_TAC THEN
    (FIRST_X_ASSUM(fun th -> if concl th = `read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin`
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) ORELSE
     (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s = b`
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES])) THEN
    FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
    REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
    REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
    REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC]);;


(* ============================================================================
   BIGNUM_MOD_X86_BLOCK_DDK_WIN -- the full DDK main-loop block 0x217 -> 0x371.
   2-segment compose: seg-A PREFIX_Z8 (0x217->0x2a3) ;; seg-B TAIL_DDK (0x2a3->0x371),
   + the DDK value bridges.  The top word lives in the zz-slot (rsp+8); the window in hs (rsp+64).
   Invariant carried: V = 2^(64k)*val(read(sp+8)) + bignum(z,k), congruence V==a DIV 2^(61 ii) (mod b),
   V < b*2^64, V < 2^(X17v+61), window read(sp+64) = word((V DIV 2^p) MOD 2^64).

   NB the ENSURES_SEQUENCE midpoint is computed by an inline OCaml let (filter bytes_loaded+RIP from
   PREFIX_Z8 POST, (k+1)-1->k) -- keeps the two seg-A/seg-B PREFIX_Z8 instantiations in exact sync. *)
let BIGNUM_MOD_X86_BLOCK_DDK_WIN = prove
 (`!k z m x n a b pc p ii w d Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ k + 1 <= (X17v + 63) DIV 64 /\
     zpre < 2 EXP (64 * k) /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Ztin + zpre /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word (k + 1) /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
           read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (k + 1) /\ read R12 s = word (k + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * (k + 1)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  (* --- setup: recip-of-t0 real bracket (for DDK_QHAT_LT) + qhat<2^64 --- *)
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
    ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 EXP (64 * k) * Ztin + zpre`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* --- ENSURES_SEQUENCE at 0x2a3; midpoint = PREFIX_Z8 POST minus {bytes_loaded, RIP}, (k+1)-1->k. --- *)
  ENSURES_SEQUENCE_TAC `pc + 0x2a3`
   (let pz8 = ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `k + 1`; `zpre:num`; `lfv:num`; `((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64`;
       `X17v:num`; `Ztin:num`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8 in
    let ppost = el 2 (snd(strip_comb(snd(dest_imp(concl pz8))))) in
    let midvar, midbody = dest_abs ppost in
    let keep c = not(is_comb c && (try fst(dest_const(fst(strip_comb c)))="bytes_loaded" with _->false)) &&
                 not(is_eq c && (is_comb(lhs c) && rand(lhs c) = `RIP`)) in
    let body' = list_mk_conj (filter keep (conjuncts midbody)) in
    mk_abs(midvar, rand(concl(REWRITE_CONV[ARITH_RULE `(k + 1) - 1 = k`] body')))) THEN
  CONJ_TAC THENL
   [(* ===== seg-A: PREFIX_Z8 0x217 -> 0x2a3 ===== *)
    MP_TAC(REWRITE_RULE[SOME_FLAGS; ARITH_RULE `(k+1)-1 = k`] (ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `k + 1`; `zpre:num`; `lfv:num`; `((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64`;
       `X17v:num`; `Ztin:num`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
      (UNDISCH_TAC `1 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== seg-B: TAIL_DDK 0x2a3 -> 0x371 + value bridges ===== *)
  GHOST_INTRO_TAC `hiw:int64` `read R9` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read R11` THEN
  GHOST_INTRO_TAC `lfw:int64` `read R14` THEN
  GHOST_INTRO_TAC `hfw:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
   [`k:num`; `z:int64`; `m:int64`; `pc:num`;
    `((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) MOD 2 EXP 64`;
    `val(hiw:int64)`; `val(cwinw:int64)`; `Ztin:num`; `b:num`; `zc:num`;
    `X17v:num`; `p DIV 64 + 1`; `p:num`; `val(lfw:int64)`; `val(hfw:int64)`; `61 * ii`; `stackpointer:int64`]
   BIGNUM_MOD_X86_TAIL_DDK)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (UNDISCH_TAC `1 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL];
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  (* ---- POST-implication: the value-bridge chain ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  ABBREV_TAC `h = ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64` THEN
  ABBREV_TAC `q = (w * h) DIV 2 EXP 64 + h` THEN
  SUBGOAL_THEN `lowdigits b k = b /\ lowdigits zpre k = zpre /\ q MOD 2 EXP 64 = q` STRIP_ASSUME_TAC THENL
