  SUBGOAL_THEN `h < 2 EXP 64` ASSUME_TAC THENL
   [EXPAND_TAC "h" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(2 EXP (64 * k) * Ztin + zpre) - q * b < 2 EXP (p + 2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`b:num`; `p:num`; `d:num`; `2 EXP (64 * k) * Ztin + zpre`;
                  `h:num`; `q:num`; `w:num`; `zr:num`] DDK_R_LT_D) THEN
    ANTS_TAC THENL
