  SUBGOAL_THEN `2 EXP 64 * q + ((Ztin + val(hiw:int64)) - q) = Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`Ztin:num`; `val(hiw:int64)`; `q:num`] TAIL_CARRY_EQ_Q) THEN
    ANTS_TAC THENL
