    TRY(CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC) THEN TRY REFL_TAC THEN
    TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
    TRY(FIRST_ASSUM(fun th -> if concl th = `h = (2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p`
