  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
  SUBGOAL_THEN
   `2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) + zc
      < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) + zc =
      zc + 2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8)`
     (fun th -> REWRITE_TAC[th]) THENL [ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`Ztin:num`; `zpre:num`; `zc:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
                   `q:num`; `val(hiw:int64)`; `val(cwinw:int64)`; `(Ztin + val(hiw:int64)) - q`;
                   `b:num`; `k:num`; `X17v:num`] DDK_VALUE_JJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) + zc =
    zc + 2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8)`
   ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  (* width bound V' < 2^(64*(k+1)) for the loop invariant: from V' < b*2^64 (banked from
