    REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
    FIRST_X_ASSUM(fun th -> if concl th = `read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w`
      then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
    FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
    REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
    REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
    REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
