    ANTS_TAC THENL
     [ASM_REWRITE_TAC[VAL_BOUND_64; ARITH_RULE `1 <= p DIV 64 + 1`]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    TRY(FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 <= k ==> val(lfw:int64) = bigdigit zc ((p DIV 64 + 1) - 1)`
        then MP_TAC th else NO_TAC) THEN
      ASM_REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN NO_TAC) THEN
    TRY(SUBGOAL_THEN `zc + 2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) =
