      SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
      ONCE_REWRITE_TAC[ARITH_RULE `61 + X17v = X17v + 61`] THEN ASM_REWRITE_TAC[] THEN NO_TAC) THEN
    SUBGOAL_THEN `!j. val(word (bigdigit (zc + 2 EXP (64 * k) *
        (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8)) j):int64) =
