    REWRITE_TAC[WINDOW_FROM_LOGGED]]);;



(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_C_WIN -- the C-regime (l=k, dd=k-1, GROW-to-saturation) main-loop block.
   One full main-loop iteration pc+0x217 -> pc+0x371 in the C regime: window=0 (=> Zt=0, qh=0, hi=0),
   (X17v+124)/64 = k+1, so l'=dd+2=k+1; the newly-live top word ushr#3(W) spills to the zz-slot rsp+8
   (NOT z[dd+1]), z[dd]=extr#3(W).  W = bigdigit zpre (k-1) (the untouched top word), since window=0.

   2-segment compose (like BLOCK_DDK_WIN):
     seg-A : BIGNUM_MOD_X86_PREFIX_Z8[l:=k, h:=0]   (0x217 -> 0x2a3)
     seg-B : BIGNUM_MOD_X86_TAIL_C                   (0x2a3 -> 0x371, tail+fieldsel fused)
   + C value bridges (all in x86_block_helpers / scaffold): C_ZK_FROM_STORES, CBLK_SPLIT, CBLK_UNIQ,
     GROWING_VALUE_CLOSE_TIGHT, JJ_STEP, HI_ZERO, INV2_TOP_ZERO, WINDOW_ZERO_IMP_LT, STORE_IS_BIGDIGIT,
     LOGDIGIT_FINALIZE_BRIDGE, TAIL_LOGIN_TO_ZPRE, WINDOW_FROM_LOGGED, C_BLOCK_VALUE_CLOSE, CBLK_TOPSPLIT,
     C_TOPWORD_AGREE.

   NB: NO separate living-value binder (unlike ARM block_c_304_win.ml) -- the x86 PREFIX_Z8 folds
   zv=zpre when Ztin=0, and the top word z[k-1] is untouched by the inner loop so holds bigdigit zpre(k-1).

   KEY LESSON (cont118): do NOT `RULE_ASSUM_TAC(REWRITE_RULE[bigdigit zc(k-1)=bigdigit zpre(k-1)])` before
   C_BLOCK_VALUE_CLOSE -- it rewrites the STORE hyps to bigdigit zpre form, but C_BLOCK_VALUE_CLOSE (and
   LOGDIGIT_FINALIZE_BRIDGE) consume the store facts in bigdigit zc form + the bridge as a SEPARATE hyp.
   Instead keep the bridge live; CBLK_TOPSPLIT's ASM_REWRITE later rewrites the window fields zc->zpre.
   ============================================================================ *)

(* C_LF_REORDER: the C-regime R14' if-order (5-level) reorder into the LOGDIGIT_FINALIZE_BRIDGE
   CONJUNCT2 order (`c <= r+1 then (..) else word 0`).  Analog of DDK_LF_REORDER (which is 3-level).
   Value-identical; bridges the state's nested-if window LF' field. *)
let C_LF_REORDER = prove
 (`!(W:int64) X L r c.
     (if r + 1 = c then W else if r + 1 < c then word 0
      else if r < c then W else if r - 1 < c then X else L) =
     (if r + 1 = c then W
      else if c <= r + 1 then (if r < c then W else if r - 1 < c then X else L)
      else word 0)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `r + 1 = c` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `r + 1 < c` THEN ASM_REWRITE_TAC[] THENL
   [SUBGOAL_THEN `~(c <= r + 1)` (fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `r + 1 < c` THEN ARITH_TAC;
    SUBGOAL_THEN `c <= r + 1` (fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `~(r + 1 < c)` THEN ARITH_TAC]);;


let BIGNUM_MOD_X86_BLOCK_C_WIN = prove
 (`!k z m x n a b pc p ii w Ztin zpre X17v lfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = k + 1 /\
     zpre < 2 EXP (64 * k) /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * k) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64 = 0 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word k /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word 0 /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (k + 1) /\ read R12 s = word (k + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * (k + 1)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `Ztin = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zpre:num`; `k:num`] THEN
    ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `zpre < 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC WINDOW_ZERO_IMP_LT THEN ASM_REWRITE_TAC[] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2a3`
   (let pz8 = ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `k:num`; `zpre:num`; `lfv:num`; `0`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8 in
    let ppost = el 2 (snd(strip_comb(snd(dest_imp(concl pz8))))) in
    let midvar, midbody = dest_abs ppost in
    let keep c = not(is_comb c && (try fst(dest_const(fst(strip_comb c)))="bytes_loaded" with _->false)) &&
                 not(is_eq c && (is_comb(lhs c) && rand(lhs c) = `RIP`)) in
    let body' = list_mk_conj (filter keep (conjuncts midbody)) in
    mk_abs(midvar, body')) THEN
  CONJ_TAC THENL
   [(* ===== seg-A: PREFIX_Z8[l:=k, h:=0] 0x217 -> 0x2a3 ===== *)
    MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `k:num`; `zpre:num`; `lfv:num`; `0`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
      (UNDISCH_TAC `2 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== seg-B: TAIL_C 0x2a3 -> 0x371 + value bridges ===== *)
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; ARITH_RULE `0 DIV 2 EXP 64 = 0`; MOD_0] THEN
  GHOST_INTRO_TAC `hiw:int64` `read R9` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read R11` THEN
  GHOST_INTRO_TAC `lfw:int64` `read R14` THEN
  GHOST_INTRO_TAC `hfw:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
   [`k:num`; `z:int64`; `m:int64`; `pc:num`; `0`; `val(hiw:int64)`; `val(cwinw:int64)`; `0`;
    `b:num`; `zc:num`; `X17v:num`; `p DIV 64 + 1`; `k - 1`; `p:num`; `val(lfw:int64)`; `val(hfw:int64)`;
    `61 * ii`; `stackpointer:int64`] BIGNUM_MOD_X86_TAIL_C)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
    (UNDISCH_TAC `2 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = k + 1` THEN UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [(* PRE-impl: midpoint P ==> TAIL_C PRE.  GEN+STRIP+ASM_REWRITE; leaves `word k = word(k-1+1)`. *)
    GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL] THEN
    AP_TERM_TAC THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC;
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  (* ---- POST-implication: the C value-bridge chain ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  ABBREV_TAC `blk = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  SUBGOAL_THEN `val(hiw:int64) = 0` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`bignum_from_memory (z,k-1) s`; `val(cwinw:int64)`; `val(hiw:int64)`; `blk:num`;
                  `lowdigits zpre (k-1)`; `k - 1`; `lowdigits b (k-1)`] HI_ZERO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN REPEAT CONJ_TAC THEN
       TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
       TRY(REWRITE_TAC[LOWDIGITS_BOUND] THEN NO_TAC) THEN
       TRY(FIRST_ASSUM ACCEPT_TAC);
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(hiw:int64) = 0`; MULT_CLAUSES; ADD_CLAUSES]) THEN
  (* bridge (kept LIVE, NOT rewritten into the store hyps): bigdigit zc(k-1) = bigdigit zpre(k-1). *)
  SUBGOAL_THEN `bigdigit zc (k - 1) = bigdigit zpre (k - 1)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`z:int64`; `k:num`; `zpre:num`; `zc:num`; `s:x86state`] C_TOPWORD_AGREE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* bignum(z,k-1)s = lowdigits zc(k-1) [from bignum(z,k)s=zc, k-1<=k] *)
  SUBGOAL_THEN `bignum_from_memory (z,k-1) s = lowdigits zc (k-1)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc` then
      REWRITE_TAC[GSYM th] else NO_TAC) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (k-1) = k-1` (fun th -> REWRITE_TAC[th]) THEN
    (UNDISCH_TAC `2 <= k` THEN ARITH_TAC); ALL_TAC] THEN
  (* bignum(z,k-1) preserved s->s': both = lowdigits zc(k-1) *)
  SUBGOAL_THEN `bignum_from_memory (z,k-1) s' = bignum_from_memory (z,k-1) s` ASSUME_TAC THENL
   [FIRST_ASSUM(fun t1 -> if concl t1 = `bignum_from_memory (z,k - 1) s' = lowdigits zc (k - 1)`
      then FIRST_ASSUM(fun t2 -> if concl t2 = `bignum_from_memory (z,k - 1) s = lowdigits zc (k - 1)`
        then ACCEPT_TAC(TRANS t1 (SYM t2)) else NO_TAC) else NO_TAC); ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k-1) s' + 2 EXP (64 * (k-1)) * (val(cwinw:int64) DIV 8) =
                blk + 2 EXP 61 * lowdigits zpre (k-1)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k - 1) s' = bignum_from_memory (z,k - 1) s`
      then REWRITE_TAC[th] else NO_TAC) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* value assembly via C_BLOCK_VALUE_CLOSE (stores in bigdigit zc form + bridge as separate hyp) *)
  SUBGOAL_THEN
   `2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64) +
    bignum_from_memory (z,k) s' = 2 EXP 61 * zpre + blk` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`z:int64`; `k:num`; `zpre:num`; `zc:num`; `cwinw:int64`; `blk:num`;
       `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64)`; `s':x86state`]
       C_BLOCK_VALUE_CLOSE) THEN
    REWRITE_TAC[VAL_BOUND_64] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `2 EXP 61 * zpre + blk < 2 EXP (64 * (k + 1))` ASSUME_TAC THENL
   [MATCH_MP_TAC ZF_BOUND_GROW THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]]; ALL_TAC] THEN
  ABBREV_TAC `Zf = 2 EXP 61 * zpre + blk` THEN
  (* split Zf: val(zz-slot')=bigdigit Zf k, bignum(z,k)s'=lowdigits Zf k.  CBLK's ASM_REWRITE
     folds V->Zf everywhere in the goal AND rewrites the window fields bigdigit zc -> bigdigit zpre. *)
  MP_TAC(ISPECL [`k:num`;
                 `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64)`;
                 `bignum_from_memory (z,k) s'`; `Zf:num`] CBLK_TOPSPLIT) THEN
  ASM_REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND] THEN STRIP_TAC THEN
  (* congruence + <b*2^64 via GROWING_VALUE_CLOSE_TIGHT *)
  MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zpre:num`; `Zf:num`; `blk:num`]
                GROWING_VALUE_CLOSE_TIGHT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    TRY(EXPAND_TAC "blk" THEN REFL_TAC) THEN
    TRY(FIRST_ASSUM(fun th -> if concl th = `2 EXP 61 * zpre + blk = Zf` then ACCEPT_TAC(SYM th) else NO_TAC)) THEN
    TRY(FIRST_ASSUM ACCEPT_TAC); ALL_TAC] THEN
  STRIP_TAC THEN
  (* jj-bound: Zf < 2^(X17v+61) via JJ_STEP(qh=0) *)
  SUBGOAL_THEN `Zf < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `0`; `b:num`; `blk:num`; `X17v:num`] JJ_STEP) THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; SUB_0] THEN
    ANTS_TAC THENL [EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th = `2 EXP 61 * zpre + blk = Zf` then REWRITE_TAC[th] else NO_TAC); ALL_TAC] THEN
  (* width bound Zf < 2^(64*(k+1)) for the loop invariant: Zf < b*2^64 + b < 2^(64*k). *)
  SUBGOAL_THEN `Zf < 2 EXP (64 * (k + 1))` ASSUME_TAC THENL
   [MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `b * 2 EXP 64` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[ARITH_RULE `64 * (k + 1) = 64 * k + 64`; EXP_ADD] THEN
      ONCE_REWRITE_TAC[MULT_SYM] THEN REWRITE_TAC[LE_MULT_LCANCEL] THEN
      DISJ2_TAC THEN ASM_SIMP_TAC[LT_IMP_LE]]; ALL_TAC] THEN
  (* fold k-1+2 = k+1 for R10'/R12'; then split the block POST.  NB: do NOT introduce (k-1)+1=k
     here -- it perturbs Bridge B's ASM_REWRITE/ASM_SIMP (k-1 tangling); introduce it just-in-time
     before the FINALIZE guard-alignment (PURE_REWRITE) instead. *)
  SUBGOAL_THEN `k - 1 + 2 = k + 1` ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  (* remaining: g0-g4 sp-slots + g5 bignum(x,n) [frame-pull]; g6 window. *)
  (* --- the 6 frame-pulls (sp+16/24/32/40/48, bignum(x,n)) --- *)
  TRY((W(fun (asl,w) ->
        FIRST_X_ASSUM(fun th ->
          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC THEN NO_TAC)) THEN
  (* --- g6 window: bigdigit zpre form.  Resolve stores/logged fields to bigdigit Zf, finalize. --- *)
  (* Bridge A: ushr#3 = word(bigdigit Zf k) [from the CBLK val-fact]. *)
  SUBGOAL_THEN `word_ushr (word (bigdigit zpre (k-1)):int64) 3 = word (bigdigit Zf k):int64` ASSUME_TAC THENL
   [GEN_REWRITE_TAC LAND_CONV [GSYM WORD_VAL] THEN AP_TERM_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* Bridge B: extr#3 (the z[k-1] store) = word(bigdigit Zf (k-1)) [via STORE_IS_BIGDIGIT + BIGDIGIT_LOWDIGITS].
     NB: the actual store HYP is in bigdigit zc form (tail POST; ASM_REWRITE rewrites only the GOAL, not
     hyps).  So rewrite the SUBGOAL's zpre->zc (C_TOPWORD bridge) first, then match the zc store hyp. *)
  SUBGOAL_THEN
   `word_subword (word_join (word (bigdigit zpre (k-1)):int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
    word (bigdigit Zf (k - 1)):int64` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bigdigit zc (k - 1) = bigdigit zpre (k - 1)`)] THEN
    FIRST_ASSUM(fun th -> if concl th =
       `read (memory :> bytes64 (word_add z (word (8 * (k - 1))))) s' =
        word_subword (word_join (word (bigdigit zc (k - 1)):int64) (word (val(cwinw:int64)):int64):int128) (3,64)`
      then SUBST1_TAC(SYM th) else NO_TAC) THEN
    MP_TAC(ISPECL [`z:int64`; `k:num`; `s':x86state`; `lowdigits Zf k`; `k - 1`] STORE_IS_BIGDIGIT) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; UNDISCH_TAC `2 <= k` THEN ARITH_TAC]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    AP_TERM_TAC THEN ASM_SIMP_TAC[BIGDIGIT_LOWDIGITS; ARITH_RULE `2 <= k ==> k - 1 < k`]; ALL_TAC] THEN
  (* entry logging -> lfw/hfw = bigdigit zc digits (dd = k-1).  MUST use zc (=bignum(z,k)@s, the
     tail-entry ghost), NOT zpre -- TAIL_LOGIN_TO_ZPRE reads z-memory at s where bignum(z,k)s=zc. *)
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `k - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`; `s:x86state`]
                TAIL_LOGIN_TO_ZPRE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN
  (* rewrite the window's stores -> bigdigit Zf; collapse word(val lfw/hfw) -> lfw/hfw (WORD_VAL)
     to match LOGDIGIT_FINALIZE_BRIDGE's int64 leaves; then reorder R14', apply the bridge. *)
  REWRITE_TAC[ASSUME `word_ushr (word (bigdigit zpre (k-1)):int64) 3 = word (bigdigit Zf k):int64`;
              ASSUME `word_subword (word_join (word (bigdigit zpre (k-1)):int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
                      word (bigdigit Zf (k - 1)):int64`;
              WORD_VAL] THEN
  (* the R15' HF' field-order matches FINALIZE CONJUNCT1 after k=pcode/k-1=pcode; R14' needs C_LF_REORDER *)
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [C_LF_REORDER] THEN
  (* the lowdigits Zf(k-1) = lowdigits zc(k-1) bridge for LOGDIGIT_FINALIZE_BRIDGE's ANTS. *)
  SUBGOAL_THEN `lowdigits Zf (k - 1) = lowdigits zc (k - 1)` ASSUME_TAC THENL
   [SUBGOAL_THEN `lowdigits Zf (k - 1) = lowdigits (lowdigits Zf k) (k - 1)` SUBST1_TAC THENL
     [REWRITE_TAC[LOWDIGITS_LOWDIGITS] THEN AP_TERM_TAC THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = lowdigits Zf k`
      then REWRITE_TAC[SYM th] else NO_TAC) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (k - 1) = k - 1` SUBST1_TAC THENL
     [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* apply LOGDIGIT_FINALIZE_BRIDGE (zpre:=zc); ANTS_TAC splits into (ant) + (concl => window). *)
  MP_TAC(ISPECL [`Zf:num`; `zc:num`; `k - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`]
            LOGDIGIT_FINALIZE_BRIDGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ASSUME `k - 1 + 2 = k + 1`; ARITH_RULE `1 <= p DIV 64 + 1`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* align the bridge conclusion's k-1+1 / k-1+2 guards to k / k+1 (as the window uses), then MP. *)
  SUBGOAL_THEN `k - 1 + 1 = k` ASSUME_TAC THENL [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  PURE_REWRITE_TAC[ASSUME `k - 1 + 1 = k`; ASSUME `k - 1 + 2 = k + 1`] THEN
  DISCH_THEN(CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THEN
  REWRITE_TAC[WORD_VAL] THEN
  REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN
  (* fold val(word(bigdigit Zf j)) -> bigdigit Zf j, then WINDOW_FROM_LOGGED closes. *)
  SUBGOAL_THEN `!j. val(word (bigdigit Zf j):int64) = bigdigit Zf j` (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; ALL_TAC] THEN
  REWRITE_TAC[WINDOW_FROM_LOGGED]);;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_FLATGEN_WIN -- GENERALIZED FLAT-regime (l STAYS, window=0) block.
   pc+0x217 -> pc+0x371, FLAT regime: window=0 (=> Zt=0, qh=0, hi=0), (X17v+124)/64 = l,
   l < p DIV64+1 (window=0, b-free), dd=l-1, output length UNCHANGED (l'=l).  NO top-word spill
   (zz-slot rsp+8 stays word Ztin=0); funnel top word extr#3(W) -> z[dd] MEMORY, z[dd+1..k-1] preserved.
   bignum(z,k)' = 2^61*zpre+blk DIRECTLY (fits dd+1=l<=k words) -- no CBLK-split.

   Port of ARM BIGNUM_MOD_BLOCK_FLAT_GEN_304_WIN (block_flat_gen_304_win.ml), the l<pcode dispatch leaf.
   *** DONE (cont119): 0-hyp, axioms=3, in RELOAD. ***

   2-segment compose (like BLOCK_C_WIN):
     seg-A : BIGNUM_MOD_X86_PREFIX_Z8[l:=l, h:=0]   (0x217 -> 0x2a3)
     seg-B : BIGNUM_MOD_X86_TAIL_FLAT               (0x2a3 -> 0x371, tail+fieldsel fused)
   + FLAT value bridge FLAT_ZK_FROM_STORES (x86_block_helpers) + FLAT_HZ_ZERO (below) + INV2_TOP_ZERO/
     WINDOW_ZERO_IMP_LT/HI_ZERO/GROWING_VALUE_CLOSE_TIGHT/JJ_STEP.

   VALUE-CLOSE (verified cont118): X23'/zz-slot=word 0 (no spill) so 2^(64k)*val(sp8')=0, block value =
   bignum(z,k)s'.  FLAT_ZK_FROM_STORES (helper-zpre:=zc [tail-entry ghost], helper-zv:=zpre [block input],
   helper-W:=bigdigit zc(l-1), dd:=l-1) assembles bignum(z,k)s'=2^61*zpre+blk.  highdigits zc l=0 via
   FLAT_HZ_ZERO; bigdigit zc(l-1)=bigdigit zpre(l-1) via AP_TERM(\h.bigdigit h 0); recast invariant to
   lowdigits zc(l-1) form (RHS stays zpre).  cong/<b*2^64 via GROWING_VALUE_CLOSE_TIGHT; <2^(X17v+61) via
   JJ_STEP(qh=0).

   WINDOW-CLOSE (cont119, SIMPLER than C -- no LOGDIGIT_FINALIZE/WINDOW_FROM_LOGGED needed): l<pcode collapses
   the tail's R14' field to word 0 (the `l<p DIV64+1 then word 0` branch); l-1<pcode makes R15' = word(val hfw),
   and hfw=word 0 (block hyp `~(pcode<l-1)==>hfw=word 0`, since pcode>l-1) so R15'=word 0.  Thus window LHS =
   word((2^64*0+0) DIV 2^(p MOD64) MOD 2^64) = word 0.  RHS = word((Zf DIV 2^p) MOD 2^64) with Zf=2^61*zpre+blk
   < 2^(64*l) <= 2^p (64*l<=p from l<=p DIV64) so Zf DIV 2^p=0, RHS=word 0.  Both word 0.
   ============================================================================ *)

(* FLAT_HZ_ZERO: the tail-entry ghost zc has vanishing high segment above l (z[l..k-1] held zpre's
   digits l..k-1 which are 0 since zpre<2^(64l)).  From the PREFIX preserved segment bridge. 0-hyp. *)
let FLAT_HZ_ZERO = prove
 (`!zc zpre l. 2 <= l /\ highdigits zc (l - 1) = highdigits zpre (l - 1) /\ zpre < 2 EXP (64 * l)
    ==> highdigits zc l = 0`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `highdigits zc l = highdigits (highdigits zc (l-1)) 1` SUBST1_TAC THENL
   [REWRITE_TAC[HIGHDIGITS_HIGHDIGITS] THEN AP_TERM_TAC THEN
    UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[HIGHDIGITS_HIGHDIGITS] THEN
  SUBGOAL_THEN `(l-1) + 1 = l` SUBST1_TAC THENL
   [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[highdigits] THEN MATCH_MP_TAC DIV_LT THEN ASM_REWRITE_TAC[]);;


let BIGNUM_MOD_X86_BLOCK_FLATGEN_WIN = prove
 (`!k z m x n a b pc p ii w l Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = l /\ l < p DIV 64 + 1 /\
     2 EXP 61 * zpre + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l) /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64 = 0 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word 0 /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word l /\ read R12 s = word l /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * l) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `Ztin = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zpre:num`; `l:num`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l <= k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `zpre < 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC WINDOW_ZERO_IMP_LT THEN ASM_REWRITE_TAC[] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2a3`
   (let pz8 = ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `l:num`; `zpre:num`; `lfv:num`; `0`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8 in
    let ppost = el 2 (snd(strip_comb(snd(dest_imp(concl pz8))))) in
    let midvar, midbody = dest_abs ppost in
    let keep c = not(is_comb c && (try fst(dest_const(fst(strip_comb c)))="bytes_loaded" with _->false)) &&
                 not(is_eq c && (is_comb(lhs c) && rand(lhs c) = `RIP`)) in
    let body' = list_mk_conj (filter keep (conjuncts midbody)) in
    mk_abs(midvar, body')) THEN
  CONJ_TAC THENL
   [(* ===== seg-A: PREFIX_Z8[l:=l, h:=0] 0x217 -> 0x2a3 ===== *)
    MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `l:num`; `zpre:num`; `lfv:num`; `0`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
      (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== seg-B: TAIL_FLAT 0x2a3 -> 0x371 + value bridge ===== *)
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; ARITH_RULE `0 DIV 2 EXP 64 = 0`; MOD_0] THEN
  GHOST_INTRO_TAC `hiw:int64` `read R9` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read R11` THEN
  GHOST_INTRO_TAC `lfw:int64` `read R14` THEN
  GHOST_INTRO_TAC `hfw:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
   [`k:num`; `z:int64`; `m:int64`; `pc:num`; `0`; `val(hiw:int64)`; `val(cwinw:int64)`; `0`;
    `b:num`; `zc:num`; `X17v:num`; `p DIV 64 + 1`; `l - 1`; `p:num`; `val(lfw:int64)`; `val(hfw:int64)`;
    `61 * ii`; `stackpointer:int64`] BIGNUM_MOD_X86_TAIL_FLAT)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
    (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = l` THEN UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [(* PRE-impl: midpoint P ==> TAIL_FLAT PRE.  leaves `word l = word(l-1+1)`. *)
    GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL] THEN
    AP_TERM_TAC THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC;
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  (* ---- POST-implication: the FLAT value-bridge chain ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  ABBREV_TAC `blk = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  SUBGOAL_THEN `val(hiw:int64) = 0` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`bignum_from_memory (z,l-1) s`; `val(cwinw:int64)`; `val(hiw:int64)`; `blk:num`;
                  `lowdigits zpre (l-1)`; `l - 1`; `lowdigits b (l-1)`] HI_ZERO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN REPEAT CONJ_TAC THEN
       TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
       TRY(REWRITE_TAC[LOWDIGITS_BOUND] THEN NO_TAC) THEN
       TRY(FIRST_ASSUM ACCEPT_TAC);
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(hiw:int64) = 0`; MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `(l - 1) + 1 = l` ASSUME_TAC THENL [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `(l - 1) + 1 = l`]) THEN
  SUBGOAL_THEN `highdigits zpre l = 0` ASSUME_TAC THENL
   [REWRITE_TAC[highdigits] THEN
    SUBGOAL_THEN `zpre DIV 2 EXP (64 * l) = 0` (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC DIV_LT THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `highdigits zc (l-1) = highdigits zpre (l-1)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th =
       `bignum_from_memory (word_add z (word (8 * (l - 1))),k - (l - 1)) s = highdigits zpre (l - 1)`
     then MP_TAC th else NO_TAC) THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `highdigits zc l = 0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`zc:num`; `zpre:num`; `l:num`] FLAT_HZ_ZERO) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,l-1) s = lowdigits zc (l-1)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc` then
      REWRITE_TAC[GSYM th] else NO_TAC) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (l-1) = l-1` (fun th -> REWRITE_TAC[th]) THEN
    (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l <= k`] THEN ARITH_TAC); ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit zc (l-1) = bigdigit zpre (l-1)` ASSUME_TAC THENL
   [MP_TAC(AP_TERM `\h. bigdigit h 0` (ASSUME `highdigits zc (l - 1) = highdigits zpre (l - 1)`)) THEN
    REWRITE_TAC[BIGDIGIT_HIGHDIGITS; ADD_CLAUSES]; ALL_TAC] THEN
  SUBGOAL_THEN
   `lowdigits zc (l-1) + 2 EXP (64 * (l-1)) * (val(cwinw:int64) DIV 8) =
    blk + 2 EXP 61 * lowdigits zpre (l-1)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,l - 1) s = lowdigits zc (l - 1)`
      then REWRITE_TAC[GSYM th] else NO_TAC) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s' = 2 EXP 61 * zpre + blk` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `zpre:num`; `b:num`; `blk:num`;
       `val(cwinw:int64)`; `bigdigit zc (l-1)`; `l - 1`; `s':x86state`] FLAT_ZK_FROM_STORES) THEN
    (* fold the FLAT_ZK antecedent's dd+1 = (l-1)+1 -> l (the (l-1)+1=l hyp was consumed by an earlier
       RULE_ASSUM, so re-supply it as an ARITH_RULE rewrite here). *)
    SUBGOAL_THEN `(l - 1) + 1 = l` ASSUME_TAC THENL
     [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; VAL_BOUND_64] THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
      TRY(UNDISCH_TAC `l <= k` THEN ARITH_TAC);
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* zz-slot' = word 0 (Ztin=0), so 2^(64k)*val(sp8')=0; block value = bignum(z,k)s' = 2^61*zpre+blk. *)
  SUBGOAL_THEN `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64) = 0` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[VAL_WORD_0]; ALL_TAC] THEN
  (* cong + <b*2^64 via GROWING_VALUE_CLOSE_TIGHT; <2^(X17v+61) via JJ_STEP(qh=0). *)
  MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zpre:num`; `2 EXP 61 * zpre + blk`; `blk:num`]
                GROWING_VALUE_CLOSE_TIGHT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    TRY(EXPAND_TAC "blk" THEN REFL_TAC) THEN
    TRY REFL_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC); ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `2 EXP 61 * zpre + blk < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `0`; `b:num`; `blk:num`; `X17v:num`] JJ_STEP) THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; SUB_0] THEN
    ANTS_TAC THENL [EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  (* window prep: Zf<2^p (64*l<=p), hfw=word 0, l</l-1<pcode branch facts. *)
  SUBGOAL_THEN `64 * l <= p` ASSUME_TAC THENL
   [SUBGOAL_THEN `l <= p DIV 64` MP_TAC THENL
     [UNDISCH_TAC `l < p DIV 64 + 1` THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`p:num`; `64`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `2 EXP 61 * zpre + blk < 2 EXP p` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `hfw:int64 = word 0` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th = `~(p DIV 64 + 1 < l - 1) ==> hfw = word 0:int64`
      then MP_TAC th else NO_TAC) THEN
    ANTS_TAC THENL [UNDISCH_TAC `l < p DIV 64 + 1` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `hfw:int64 = word 0`]) THEN
  (* fold V := block value -> 2^61*zpre+blk everywhere; then split POST + close. *)
  SUBGOAL_THEN
   `2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64) +
    bignum_from_memory (z,k) s' = 2 EXP 61 * zpre + blk` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  (* remaining: sp+16/24/32/40/48, bignum(x,n) frame-pulls; window. *)
  TRY((W(fun (asl,w) ->
        FIRST_X_ASSUM(fun th ->
          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC THEN NO_TAC)) THEN
  (* --- window: both logged fields collapse to word 0; RHS = word 0 (Zf<2^p). --- *)
  SUBGOAL_THEN `~(l = p DIV 64 + 1) /\ ~(l - 1 = p DIV 64 + 1) /\ l < p DIV 64 + 1` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN (UNDISCH_TAC `l < p DIV 64 + 1` THEN ARITH_TAC); ALL_TAC] THEN
  ASM_REWRITE_TAC[VAL_WORD_0; MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0] THEN
  SUBGOAL_THEN `(2 EXP 61 * zpre + blk) DIV 2 EXP p = 0` (fun th -> REWRITE_TAC[th; MOD_0]) THEN
  MATCH_MP_TAC DIV_LT THEN FIRST_ASSUM ACCEPT_TAC);;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_BGROW_WIN -- the B/GROW-regime (window=0, l grows to l+1) main-loop block.
   pc+0x217 -> pc+0x371, B_GROW: window=0 (=> Zt=0, qh=0, hi=0), (X17v+124)/64 = l+1, 2<=l<k, dd=l-1,
   output length GROWS l->l+1.  NO top-word spill (zz-slot rsp+8 stays word Ztin=0); the NEW top word
   ushr#3(W) lands in z[dd+1]=z[l] MEMORY (cmove picks z+8*(dd+1) since dd+1<k), z[dd]=extr#3(W).
   bignum(z,k)' = 2^61*zpre+blk DIRECTLY (X23'=0, fits l+1<=k words) -- via GROWING_ZK_FROM_STORES_GEN.

   Port of ARM BIGNUM_MOD_BLOCK_B_GROW_304_WIN (block_b_grow_304_win.ml).

   Combines: FLAT_GEN value skeleton (X23'/zz-slot=word 0 so 2^(64k)*val(sp8')=0, block value=bignum(z,k)s')
   + GROWING_ZK_FROM_STORES_GEN (TWO stores z[dd],z[dd+1]; qh=0,hi=0 window=0) for the assembly
   + C-block window close (stores->bigdigit Zf via STORE_IS_BIGDIGIT, C_LF_REORDER, LOGDIGIT_FINALIZE_BRIDGE,
     WINDOW_FROM_LOGGED).

   2-segment compose: seg-A PREFIX_Z8[l:=l,h:=0] (0x217->0x2a3) ;; seg-B TAIL_B (0x2a3->0x371) + bridges.
   Deps: PREFIX_Z8, TAIL_B, GROWING_ZK_FROM_STORES_GEN, INV2_TOP_ZERO, WINDOW_ZERO_IMP_LT, HI_ZERO,
   ZF_BOUND_GROW, GROWING_VALUE_CLOSE_TIGHT, JJ_STEP, STORE_IS_BIGDIGIT, CBLK_TOPSPLIT(no -- no spill),
   C_LF_REORDER, TAIL_LOGIN_TO_ZPRE, LOGDIGIT_FINALIZE_BRIDGE, WINDOW_FROM_LOGGED, BIGDIGIT_LOWDIGITS.
   ============================================================================ *)

let BIGNUM_MOD_X86_BLOCK_BGROW_WIN = prove
 (`!k z m x n a b pc p ii w l Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l < k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = l + 1 /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64 = 0 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word 0 /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (l + 1) /\ read R12 s = word (l + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * (l + 1)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `Ztin = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zpre:num`; `l:num`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `zpre < 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC WINDOW_ZERO_IMP_LT THEN ASM_REWRITE_TAC[] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2a3`
   (let pz8 = ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `l:num`; `zpre:num`; `lfv:num`; `0`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8 in
    let ppost = el 2 (snd(strip_comb(snd(dest_imp(concl pz8))))) in
    let midvar, midbody = dest_abs ppost in
    let keep c = not(is_comb c && (try fst(dest_const(fst(strip_comb c)))="bytes_loaded" with _->false)) &&
                 not(is_eq c && (is_comb(lhs c) && rand(lhs c) = `RIP`)) in
    let body' = list_mk_conj (filter keep (conjuncts midbody)) in
    mk_abs(midvar, body')) THEN
  CONJ_TAC THENL
   [(* ===== seg-A: PREFIX_Z8[l:=l, h:=0] 0x217 -> 0x2a3 ===== *)
    MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `l:num`; `zpre:num`; `lfv:num`; `0`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
      (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== seg-B: TAIL_B 0x2a3 -> 0x371 + value bridge ===== *)
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; ARITH_RULE `0 DIV 2 EXP 64 = 0`; MOD_0] THEN
  GHOST_INTRO_TAC `hiw:int64` `read R9` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read R11` THEN
  GHOST_INTRO_TAC `lfw:int64` `read R14` THEN
  GHOST_INTRO_TAC `hfw:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
   [`k:num`; `z:int64`; `m:int64`; `pc:num`; `0`; `val(hiw:int64)`; `val(cwinw:int64)`; `0`;
    `b:num`; `zc:num`; `X17v:num`; `p DIV 64 + 1`; `l - 1`; `p:num`; `val(lfw:int64)`; `val(hfw:int64)`;
    `61 * ii`; `stackpointer:int64`] BIGNUM_MOD_X86_TAIL_B)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
    (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = l + 1` THEN UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [(* PRE-impl: midpoint P ==> TAIL_B PRE.  leaves word l = word(l-1+1). *)
    GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL] THEN
    AP_TERM_TAC THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC;
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  (* ---- POST-implication: the B_GROW value-bridge chain ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  ABBREV_TAC `blk = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  SUBGOAL_THEN `val(hiw:int64) = 0` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`bignum_from_memory (z,l-1) s`; `val(cwinw:int64)`; `val(hiw:int64)`; `blk:num`;
                  `lowdigits zpre (l-1)`; `l - 1`; `lowdigits b (l-1)`] HI_ZERO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN REPEAT CONJ_TAC THEN
       TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
       TRY(REWRITE_TAC[LOWDIGITS_BOUND] THEN NO_TAC) THEN
       TRY(FIRST_ASSUM ACCEPT_TAC);
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(hiw:int64) = 0`; MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `(l - 1) + 1 = l /\ (l - 1) + 2 = l + 1` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `(l - 1) + 1 = l`; ASSUME `(l - 1) + 2 = l + 1`]) THEN
  (* highdigits/lowdigit bridges zc<->zpre (top segment preserved by the inner loop through dd) *)
  SUBGOAL_THEN `highdigits zc (l-1) = highdigits zpre (l-1)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th =
       `bignum_from_memory (word_add z (word (8 * (l - 1))),k - (l - 1)) s = highdigits zpre (l - 1)`
     then MP_TAC th else NO_TAC) THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,l-1) s = lowdigits zc (l-1)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc` then
      REWRITE_TAC[GSYM th] else NO_TAC) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (l-1) = l-1` (fun th -> REWRITE_TAC[th]) THEN
    (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l < k`] THEN ARITH_TAC); ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit zc (l-1) = bigdigit zpre (l-1)` ASSUME_TAC THENL
   [MP_TAC(AP_TERM `\h. bigdigit h 0` (ASSUME `highdigits zc (l - 1) = highdigits zpre (l - 1)`)) THEN
    REWRITE_TAC[BIGDIGIT_HIGHDIGITS; ADD_CLAUSES]; ALL_TAC] THEN
  (* recast the tail invariant (bignum(z,l-1)s form) into GROWING_ZK_FROM_STORES's state-free hiw form:
     lowdigits zc(l-1) + 2^(64(l-1))*(val cwinw/8 + 2^61*val hiw) + 2^61*(0*lowdigits b(l-1))
       = blk + 2^61*lowdigits zpre(l-1) + 2^61*(0*2^(64(l-1))). *)
  SUBGOAL_THEN
   `lowdigits zc (l-1) + 2 EXP (64 * (l-1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * 0) +
    2 EXP 61 * (0 * lowdigits b (l-1)) =
    blk + 2 EXP 61 * lowdigits zpre (l-1) + 2 EXP 61 * (0 * 2 EXP (64 * (l-1)))` ASSUME_TAC THENL
   [REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,l - 1) s = lowdigits zc (l - 1)`
      then REWRITE_TAC[GSYM th] else NO_TAC) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* value: bignum(z,k)s' = 2^61*zpre+blk via GROWING_ZK_FROM_STORES (qh=0 version; derives hiw=0 internally,
     needs NO b<2^(64*l); W=bigdigit zc(l-1) matches the ZC store, hiw:=0 [val hiw folded]). *)
  SUBGOAL_THEN `bignum_from_memory (z,k) s' = 2 EXP 61 * zpre + blk` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `k:num`; `l:num`; `zc:num`; `zpre:num`; `b:num`; `blk:num`;
       `0`; `val(cwinw:int64)`; `bigdigit zc (l-1)`; `s':x86state`]
       GROWING_ZK_FROM_STORES) THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; VAL_BOUND_64] THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(UNDISCH_TAC `l < k` THEN ARITH_TAC) THEN
      TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC);
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* zz-slot' = word 0, so 2^(64k)*val(sp8')=0 and the block value = bignum(z,k)s'. *)
  SUBGOAL_THEN `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64) = 0` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[VAL_WORD_0]; ALL_TAC] THEN
  (* cong + <b*2^64 via GROWING_VALUE_CLOSE_TIGHT; <2^(X17v+61) via JJ_STEP(qh=0). *)
  MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zpre:num`; `2 EXP 61 * zpre + blk`; `blk:num`]
                GROWING_VALUE_CLOSE_TIGHT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    TRY(EXPAND_TAC "blk" THEN REFL_TAC) THEN TRY REFL_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC); ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `2 EXP 61 * zpre + blk < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `0`; `b:num`; `blk:num`; `X17v:num`] JJ_STEP) THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; SUB_0] THEN
    ANTS_TAC THENL [EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  (* ZF-bound for LOGDIGIT_FINALIZE: Zf < 2^(64*(l+1)). *)
  SUBGOAL_THEN `2 EXP 61 * zpre + blk < 2 EXP (64 * (l + 1))` ASSUME_TAC THENL
   [MATCH_MP_TAC ZF_BOUND_GROW THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]]; ALL_TAC] THEN
  ABBREV_TAC `Zf = 2 EXP 61 * zpre + blk` THEN
  (* the two stores = word(bigdigit Zf (l-1)/l), via bignum(z,k)s'=lowdigits...=Zf + STORE_IS_BIGDIGIT. *)
  SUBGOAL_THEN `bignum_from_memory (z,k) s' = Zf` ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `Zf < 2 EXP (64 * k)` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `2 EXP (64 * (l + 1))` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
    UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' = word (bigdigit Zf (l - 1)) /\
    read (memory :> bytes64 (word_add z (word (8 * l)))) s' = word (bigdigit Zf l)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC STORE_IS_BIGDIGIT THEN EXISTS_TAC `k:num` THEN
    ASM_REWRITE_TAC[] THEN (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l < k`] THEN ARITH_TAC); ALL_TAC] THEN
  (* bridge the tail's storeWORD forms to word(bigdigit Zf ..): both z[l-1] reads (tail store form and the
     STORE_IS_BIGDIGIT form) are equal, so their RHSs are equal.  Robust: rewrite the STORE_IS_BIGDIGIT
     read-hyp (=word(bigdigit Zf ..)) with the tail store-hyp (GSYM) to expose the storeword=word(bigdigit Zf). *)
  SUBGOAL_THEN
   `word_subword (word_join (word (bigdigit zc (l-1)):int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
    word (bigdigit Zf (l - 1))` ASSUME_TAC THENL
   [FIRST_ASSUM(fun t2 -> if concl t2 =
      `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' = word (bigdigit Zf (l - 1))`
      then FIRST_ASSUM(fun t1 -> if is_eq(concl t1) &&
             lhs(concl t1) = `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s'` &&
             (try fst(dest_const(fst(strip_comb(rand(concl t1))))) = "word_subword" with _ -> false)
           then ACCEPT_TAC(TRANS (SYM t1) t2) else NO_TAC)
      else NO_TAC); ALL_TAC] THEN
  SUBGOAL_THEN
   `word_ushr (word (bigdigit zc (l-1)):int64) 3 = word (bigdigit Zf l)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun t2 -> if concl t2 =
      `read (memory :> bytes64 (word_add z (word (8 * l)))) s' = word (bigdigit Zf l)`
      then FIRST_ASSUM(fun t1 -> if is_eq(concl t1) &&
             lhs(concl t1) = `read (memory :> bytes64 (word_add z (word (8 * l)))) s'` &&
             (try fst(dest_const(fst(strip_comb(rand(concl t1))))) = "word_ushr" with _ -> false)
           then ACCEPT_TAC(TRANS (SYM t1) t2) else NO_TAC)
      else NO_TAC); ALL_TAC] THEN
  (* entry logging -> lfw/hfw = bigdigit zc digits (dd=l-1); TAIL_LOGIN_TO_ZPRE with zc. *)
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `l - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`; `s:x86state`]
                TAIL_LOGIN_TO_ZPRE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN
    (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l < k`] THEN ARITH_TAC); ALL_TAC] THEN
  STRIP_TAC THEN
  (* lowdigits Zf(l-1)=lowdigits zc(l-1) for LOGDIGIT_FINALIZE ANTS. *)
  SUBGOAL_THEN `lowdigits Zf (l - 1) = lowdigits zc (l - 1)` ASSUME_TAC THENL
   [SUBGOAL_THEN `lowdigits Zf (l - 1) = lowdigits (lowdigits Zf l) (l - 1)` SUBST1_TAC THENL
     [REWRITE_TAC[LOWDIGITS_LOWDIGITS] THEN AP_TERM_TAC THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits Zf l = bignum_from_memory (z,l) s'` SUBST1_TAC THENL
     [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = Zf` then MP_TAC th else NO_TAC) THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
      SUBGOAL_THEN `MIN k l = l` (fun th -> REWRITE_TAC[th]) THEN (UNDISCH_TAC `l < k` THEN ARITH_TAC);
      ALL_TAC] THEN
    (* bignum(z,l)s' -- but tail gives bignum(z,l-1)s'. lowdigits(bignum(z,l)s')(l-1)=bignum(z,l-1)s'=lowdigits zc(l-1) *)
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN l (l - 1) = l - 1` (fun th -> REWRITE_TAC[th]) THENL
     [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,l - 1) s' = lowdigits zc (l - 1)`
      then ACCEPT_TAC th else NO_TAC); ALL_TAC] THEN
  (* fold k-1+... for R10'/R12', split POST.  The three value conjuncts carry an unfolded
     2^(64k)*0+Zf (X23'=word 0 so the zz-slot term vanishes): fold MULT/ADD_CLAUSES then accept
     the Zf-hyp.  (On the window/frame goals the fold is a no-op that TRY reverts.) *)
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN TRY(REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN FIRST_ASSUM ACCEPT_TAC) THEN
  (* frame-pulls: sp+16/24/32/40/48, bignum(x,n). *)
  TRY((W(fun (asl,w) ->
        FIRST_X_ASSUM(fun th ->
          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC THEN NO_TAC)) THEN
  (* --- window: R15'/R14' logged fields -> word(bigdigit Zf pcode/(pcode-1)); WINDOW_FROM_LOGGED.
     The store bridges (word_subword..=word(bigdigit Zf(l-1)), word_ushr..=word(bigdigit Zf l)) and the
     RHS fold 2^(64k)*0+Zf->Zf were already applied by the ASM_REWRITE_TAC above; here we (i) re-derive
     the two grow-guards (l-1)+1=l, (l-1)+2=l+1 [consumed by the line-76 RULE_ASSUM], (ii) MULT/ADD-fold,
     (iii) reorder R14's 5-level field into FINALIZE CONJUNCT2 order via C_LF_REORDER, (iv) apply
     LOGDIGIT_FINALIZE_BRIDGE raw (zpre:=zc, dd:=l-1) with the guards PURE-rewritten to align to l/l+1. *)
  SUBGOAL_THEN `(l - 1) + 1 = l /\ (l - 1) + 2 = l + 1` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [C_LF_REORDER] THEN
  REWRITE_TAC[WORD_VAL] THEN
  MP_TAC(ISPECL [`Zf:num`; `zc:num`; `l - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`]
            LOGDIGIT_FINALIZE_BRIDGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ASSUME `(l - 1) + 2 = l + 1`; ARITH_RULE `1 <= p DIV 64 + 1`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  PURE_REWRITE_TAC[ASSUME `(l - 1) + 1 = l`; ASSUME `(l - 1) + 2 = l + 1`] THEN
  DISCH_THEN(CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THEN
  REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN
  SUBGOAL_THEN `!j. val(word (bigdigit Zf j):int64) = bigdigit Zf j` (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; ALL_TAC] THEN
  REWRITE_TAC[WINDOW_FROM_LOGGED]);;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_BGEN_WIN -- the GENERAL-qhat GROWING regime-B block.
   pc+0x217 -> pc+0x371.  Covers ALL reachable growing-B iterations (index l -> l+1) at 2<=l<k with
   ARBITRARY window/qhat (window!=0 reachable at growing heads for small-top-word moduli).  BGROW pins
   window=0 (=> qh=0); this drops that and carries the full recip-of-d tower + general qhat.

   Port of ARM BIGNUM_MOD_BLOCK_BGEN_304_WIN (block_bgen_304_win.ml).

   = x86 BLOCK_BGROW_WIN skeleton (PREFIX_Z8 ;; TAIL_B two-store grow, GROWING_ZK_FROM_STORES_GEN,
     STORE_IS_BIGDIGIT + C_LF_REORDER + TAIL_LOGIN_TO_ZPRE + LOGDIGIT_FINALIZE_BRIDGE + WINDOW_FROM_LOGGED
     window close) with the qh=0 specialization LIFTED to general qh, using:
   - x86 BLOCK_DDK_WIN's recip-of-t0 setup: RECIP_T0_FROM_D + ROUNDUP_T0_LE (real bracket) -> DDK_QHAT_LT
     (qh<2^64) -> DDK_R_LT_D (R=zv-qh*b<2^(p+2));
   - GROWING_VALUE_CLOSE_GEN (cong + <b*2^64), b<2^(64l) -> <2^(64(l+1)), JJ_STEP (<2^(X17v+61));
   - C_CARRY_IS_Q (carry = qh) for the funnel top word;
   - GROWING_ZK_FROM_STORES_GEN (general-qh two-store assembly, bignum(z,k)' = 2^61*(zv-qh*b)+blk).
   The window entry slot sp+64 holds word hval (=window), not word 0.

   2-segment compose: seg-A PREFIX_Z8[l:=l, h:=hval, Ztin:=0] (0x217->0x2a3) ;; seg-B TAIL_B (general q:=qh)
     (0x2a3->0x371) + value bridges.  ALL deps in the x86 RELOAD chain.  0-hyp, axioms=3.
   ============================================================================ *)

let BIGNUM_MOD_X86_BLOCK_BGEN_WIN = prove
 (`!k z m x n a b pc p ii w d l Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l < k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ b < 2 EXP (64 * l) /\
     p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = l + 1 /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Ztin + zpre /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (l + 1) /\ read R12 s = word (l + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * (l + 1)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* --- setup: Ztin=0 (l<k), then recip-of-t0 real bracket + qhat<2^64 (DDK setup) --- *)
  SUBGOAL_THEN `Ztin = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zpre:num`; `l:num`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * (zpre DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zpre DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* window decomp: h = zpre DIV 2^p (MOD identity since zpre<b*2^64<=2^p*2^64) *)
  SUBGOAL_THEN `(zpre DIV 2 EXP p) MOD 2 EXP 64 = zpre DIV 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]]; ALL_TAC] THEN
  ABBREV_TAC `hval = (zpre DIV 2 EXP p) MOD 2 EXP 64` THEN
  ABBREV_TAC `qh = (w * hval) DIV 2 EXP 64 + hval` THEN
  SUBGOAL_THEN `zpre = hval * 2 EXP p + zpre MOD 2 EXP p /\ zpre MOD 2 EXP p < 2 EXP p` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`zpre:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `p <= 64 * k` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (p-1) < 2 EXP (64*k)` MP_TAC THENL
     [TRANS_TAC LET_TRANS `b:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[LT_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(b = 0)` ASSUME_TAC THENL
   [UNDISCH_TAC `2 EXP (p - 1) <= b` THEN MP_TAC(SPECL [`2`; `p - 1`] EXP_EQ_0) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `hval < 2 EXP 64` ASSUME_TAC THENL
   [EXPAND_TAC "hval" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `zpre - qh * b < 2 EXP (p + 2)` ASSUME_TAC THENL
