  DISCH_THEN(CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THEN
  REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN
  SUBGOAL_THEN `!j. val(word (bigdigit Zf j):int64) = bigdigit Zf j` (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; ALL_TAC] THEN
  REWRITE_TAC[WINDOW_FROM_LOGGED]);;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_FLATGEN_ALL_WIN -- the UNIFIED general-qhat FLAT-regime block.
   pc+0x217 -> pc+0x371.  Covers ALL reachable FLAT iterations (index l STAYS: l->l), 2<=l<=k,
   ARBITRARY window/qhat.  Value Zf' = 2^61*(zv-qh*b)+block FITS l words (witness Zf'<2^(64*l), a hyp).
   Subsumes FLAT_GEN (window=0).

   Port of ARM BIGNUM_MOD_BLOCK_FLATGEN_ALL_304_WIN (block_flatgen_all_304_win.ml).

   = x86 BLOCK_BGEN_WIN setup (IDENTICAL recip-of-d tower + general qh) BUT the FLAT deltas:
   - PRE: l<=k (not l<k), (X17v+124)/64=l (not l+1), b<2^(64*l), + the value-fit witness
     2^61*(zv-qh*b)+blk < 2^(64*l);
   - TAIL = TAIL_FLAT (SINGLE store z[l-1], l unchanged), q:=qh general;
   - value bridge = FLAT_ZK_FROM_STORES_GEN (single store) not GROWING_ZK_FROM_STORES_GEN, with a
     C_TOP_FUNNEL_GEN `word W = word LOW` bridge (FLAT_ZK takes the store in word W form);
   - highdigits zc l = 0 (zv<2^(64l), l stays) via HIGHDIGITS bridge;
   - exit R10=R12=word l (unchanged), bound < 2^(64*l);
   - WINDOW CLOSE: FLAT single-store field shapes (R15'=if dd=pcode then SW else hfv; R14'=4-level
     dd/dd+1) do NOT fit LOGDIGIT_FINALIZE_BRIDGE's 2-store shape; finalize by DIRECT ASM_CASES on
     `l < pcode` (pcode>l => both fields resolve to word(bigdigit Zf .)=word 0 past-top) and
     `pcode < l-1`, mirroring the ARM inline finalize + WINDOW_FROM_LOGGED.
   ALL deps in the x86 RELOAD chain (FLAT_ZK_FROM_STORES_GEN just ported into x86_block_helpers).
   ============================================================================ *)

let BIGNUM_MOD_X86_BLOCK_FLATGEN_ALL_WIN = prove
 (`!k z m x n a b pc p ii w d l Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ b < 2 EXP (64 * l) /\
     p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = l /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * l) /\
     2 EXP 61 * ((2 EXP (64 * k) * Ztin + zpre) -
       ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
        ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b) +
       (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Ztin + zpre /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word l /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word l /\ read R12 s = word l /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * l) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* --- setup: Ztin=0 (l<=k via INV2_TOP_ZERO), recip-of-t0 bracket + qhat<2^64 (DDK setup) --- *)
  SUBGOAL_THEN `Ztin = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zpre:num`; `l:num`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * (zpre DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zpre DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zpre DIV 2 EXP p) MOD 2 EXP 64 = zpre DIV 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]]; ALL_TAC] THEN
  ABBREV_TAC `hval = (zpre DIV 2 EXP p) MOD 2 EXP 64` THEN
  ABBREV_TAC `qh = (w * hval) DIV 2 EXP 64 + hval` THEN
  SUBGOAL_THEN `zpre = hval * 2 EXP p + zpre MOD 2 EXP p /\ zpre MOD 2 EXP p < 2 EXP p` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`zpre:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `p <= 64 * k` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (p-1) < 2 EXP (64*k)` MP_TAC THENL
     [TRANS_TAC LET_TRANS `b:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[LT_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(b = 0)` ASSUME_TAC THENL
   [UNDISCH_TAC `2 EXP (p - 1) <= b` THEN MP_TAC(SPECL [`2`; `p - 1`] EXP_EQ_0) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `hval < 2 EXP 64` ASSUME_TAC THENL
   [EXPAND_TAC "hval" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `zpre - qh * b < 2 EXP (p + 2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`b:num`; `p:num`; `d:num`; `zpre:num`; `hval:num`; `qh:num`; `w:num`;
                  `zpre MOD 2 EXP p`] DDK_R_LT_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(ASM_REWRITE_TAC[] THEN NO_TAC);
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `blk = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  (* Zf' bounds: <b*2^64 + cong (GROWING_VALUE_CLOSE_GEN); <2^(64*l) is a HYP (value-fit); <2^(X17v+61) JJ_STEP *)
  SUBGOAL_THEN `(2 EXP 61 * (zpre - qh * b) + blk == a DIV 2 EXP (61 * ii)) (mod b) /\
                2 EXP 61 * (zpre - qh * b) + blk < b * 2 EXP 64` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zpre:num`; `blk:num`; `qh:num`;
                   `2 EXP 61 * (zpre - qh * b) + blk`] GROWING_VALUE_CLOSE_GEN) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    EXPAND_TAC "blk" THEN REWRITE_TAC[]; ALL_TAC] THEN
  (* NB the value-fit hyp 2^61*(zpre-qh*b)+blk<2^(64*l) is ALREADY present: ABBREV_TAC qh/blk folded the
     incoming un-abbreviated form into it automatically. *)
  SUBGOAL_THEN `2 EXP 61 * (zpre - qh * b) + blk < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [MATCH_MP_TAC JJ_STEP THEN ASM_REWRITE_TAC[] THEN EXPAND_TAC "blk" THEN
    REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== ENSURES_SEQUENCE at 0x2a3; midpoint = PREFIX_Z8[l,h:=hval,Ztin:=0] POST minus {bytes_loaded,RIP}. ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x2a3`
   (let pz8 = ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `l:num`; `zpre:num`; `lfv:num`; `hval:num`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8 in
    let ppost = el 2 (snd(strip_comb(snd(dest_imp(concl pz8))))) in
    let midvar, midbody = dest_abs ppost in
    let keep c = not(is_comb c && (try fst(dest_const(fst(strip_comb c)))="bytes_loaded" with _->false)) &&
                 not(is_eq c && (is_comb(lhs c) && rand(lhs c) = `RIP`)) in
    let body' = list_mk_conj (filter keep (conjuncts midbody)) in
    mk_abs(midvar, body')) THEN
  CONJ_TAC THENL
   [(* ===== seg-A: PREFIX_Z8[l:=l, h:=hval, Ztin:=0] 0x217 -> 0x2a3 ===== *)
    MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `l:num`; `zpre:num`; `lfv:num`; `hval:num`; `X17v:num`; `0`; `stackpointer:int64`] BIGNUM_MOD_X86_PREFIX_Z8)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE
     (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      TRY(REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN AP_TERM_TAC THEN
          FIRST_ASSUM(fun th -> if concl th = `(zpre DIV 2 EXP p) MOD 2 EXP 64 = hval` then MP_TAC th else NO_TAC) THEN
          FIRST_ASSUM(fun th -> if concl th = `hval = zpre DIV 2 EXP p` then SUBST1_TAC th else NO_TAC) THEN
          REWRITE_TAC[])));
    ALL_TAC] THEN
  (* ===== seg-B: TAIL_FLAT (general qh) 0x2a3 -> 0x371 + value bridge ===== *)
  SUBGOAL_THEN `((w * hval) DIV 2 EXP 64 + hval) MOD 2 EXP 64 = qh` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `(w * hval) DIV 2 EXP 64 + hval = qh` then REWRITE_TAC[th] else NO_TAC) THEN
    MATCH_MP_TAC MOD_LT THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  GHOST_INTRO_TAC `hiw:int64` `read R9` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read R11` THEN
  GHOST_INTRO_TAC `lfw:int64` `read R14` THEN
  GHOST_INTRO_TAC `hfw:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
   [`k:num`; `z:int64`; `m:int64`; `pc:num`; `qh:num`; `val(hiw:int64)`; `val(cwinw:int64)`; `0`;
    `b:num`; `zc:num`; `X17v:num`; `p DIV 64 + 1`; `l - 1`; `p:num`; `val(lfw:int64)`; `val(hfw:int64)`;
    `61 * ii`; `stackpointer:int64`] BIGNUM_MOD_X86_TAIL_FLAT)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = l` THEN UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [(* PRE-impl: midpoint P ==> TAIL_FLAT PRE.  leaves word l = word(l-1+1). *)
    GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL] THEN
    AP_TERM_TAC THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC;
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  (* ---- POST-implication: the general-qh FLAT value-bridge chain ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `(l - 1) + 1 = l` ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `(l - 1) + 1 = l`]) THEN
  SUBGOAL_THEN `highdigits zc (l-1) = highdigits zpre (l-1)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th =
       `bignum_from_memory (word_add z (word (8 * (l - 1))),k - (l - 1)) s = highdigits zpre (l - 1)`
     then MP_TAC th else NO_TAC) THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,l-1) s = lowdigits zc (l-1)` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc` then
      REWRITE_TAC[GSYM th] else NO_TAC) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (l-1) = l-1` (fun th -> REWRITE_TAC[th]) THEN
    (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l <= k`] THEN ARITH_TAC); ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit zc (l-1) = bigdigit zpre (l-1)` ASSUME_TAC THENL
   [MP_TAC(AP_TERM `\h. bigdigit h 0` (ASSUME `highdigits zc (l - 1) = highdigits zpre (l - 1)`)) THEN
    REWRITE_TAC[BIGDIGIT_HIGHDIGITS; ADD_CLAUSES]; ALL_TAC] THEN
  SUBGOAL_THEN `lowdigits zc (l-1) < 2 EXP (64 * (l-1))` ASSUME_TAC THENL
   [REWRITE_TAC[LOWDIGITS_BOUND]; ALL_TAC] THEN
  (* highdigits zc l = 0 (=highdigits zpre l, zpre<2^(64l)); FLAT-specific (l stays). *)
  SUBGOAL_THEN `highdigits zpre l = 0` ASSUME_TAC THENL
   [MATCH_MP_TAC HIGHDIGITS_ZERO THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `highdigits zc l = 0` ASSUME_TAC THENL
   [SUBGOAL_THEN `highdigits zc l = highdigits zpre l` SUBST1_TAC THENL
     [SUBGOAL_THEN `l = (l - 1) + 1` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [th] THEN
        GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [th]) THENL
       [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[GSYM HIGHDIGITS_HIGHDIGITS] THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* recast the tail invariant into the state-free 2^61*(qh*..) shape. *)
  SUBGOAL_THEN
   `lowdigits zc (l-1) + 2 EXP (64 * (l-1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * val(hiw:int64)) +
    2 EXP 61 * (qh * lowdigits b (l-1)) =
    blk + 2 EXP 61 * lowdigits zpre (l-1) + 2 EXP 61 * (qh * 2 EXP (64 * (l-1)))` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th =
      `bignum_from_memory (z,l - 1) s +
       2 EXP (64 * (l - 1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * val(hiw:int64)) +
       2 EXP 61 * qh * lowdigits b (l - 1) =
       blk + 2 EXP 61 * lowdigits zpre (l - 1) +
       2 EXP 61 * qh * 2 EXP (64 * (l - 1))`
      then MP_TAC th else NO_TAC) THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,l-1) s = lowdigits zc (l-1)`
      then REWRITE_TAC[th] else NO_TAC) THEN
    REWRITE_TAC[MULT_ASSOC]; ALL_TAC] THEN
  (* C_CARRY_IS_Q at k:=l: the funnel top-word CARRY = qh *)
  SUBGOAL_THEN
   `(bigdigit zpre (l-1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l-1))) DIV 2 EXP 64 = qh`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `val(hiw:int64)`; `qh:num`; `b:num`; `lowdigits zc (l-1)`;
                   `val(cwinw:int64)`; `blk:num`; `zpre - qh * b`; `p:num`; `l:num`] C_CARRY_IS_Q) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
     [EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
      MP_TAC(ISPEC `cwinw:int64` VAL_BOUND_64) THEN ARITH_TAC;
      UNDISCH_TAC `qh * b <= zpre` THEN ARITH_TAC;
      TRANS_TAC LET_TRANS `zpre:num` THEN ASM_REWRITE_TAC[] THEN ARITH_TAC];
    ALL_TAC] THEN
  (* W/LOW funnel split *)
  ABBREV_TAC `W = bigdigit zpre (l-1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l-1))` THEN
  ABBREV_TAC `LOW = W - 2 EXP 64 * qh` THEN
  SUBGOAL_THEN `2 EXP 64 * qh + LOW = W /\ LOW < 2 EXP 64` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`W:num`; `2 EXP 64`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "LOW" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `word W:int64 = word LOW` ASSUME_TAC THENL
   [MATCH_MP_TAC C_TOP_FUNNEL_GEN THEN EXISTS_TAC `qh:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* value: bignum(z,k)s' = Zf' via FLAT_ZK_FROM_STORES_GEN (single store; the store reads word W;
     FLAT_ZK wants word W in the store hyp -- rewrite the tail store-asm (word(bigdigit zc..)) to word W. *)
  SUBGOAL_THEN `bignum_from_memory (z,k) s' = 2 EXP 61 * (zpre - qh * b) + blk` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `zpre:num`; `b:num`; `blk:num`;
                   `val(cwinw:int64)`; `LOW:num`; `val(hiw:int64)`; `qh:num`; `l:num`; `s':x86state`]
       FLAT_ZK_FROM_STORES_GEN) THEN
    (* rewrite the tail's single-store asm (word(bigdigit zc(l-1)+..) form) to word LOW form via the W
       abbrev + `word W = word LOW`.  FLAT_ZK's W-slot := LOW (the funnel bottom part stored). *)
    FIRST_ASSUM(fun th -> let c = concl th in
      if is_eq c && (try rand(lhs c) = `s':x86state` with Failure _ -> false)
         && can (find_term (fun t -> t = `bigdigit zc (l - 1)`)) (rhs c)
         && is_comb(rhs c) && (try fst(dest_const(fst(strip_comb(rhs c)))) = "word_subword" with _ -> false)
      then ASSUME_TAC(REWRITE_RULE
        [ASSUME `bigdigit zc (l - 1) = bigdigit zpre (l - 1)`;
         ASSUME `bigdigit zpre (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1)) = W`;
         ASSUME `word W:int64 = word LOW`] th)
      else NO_TAC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ; VAL_BOUND_64] THEN
      TRY(EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
      FIRST_ASSUM(fun th -> if concl th =
        `lowdigits zc (l-1) + 2 EXP (64 * (l-1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * val(hiw:int64)) +
         2 EXP 61 * (qh * lowdigits b (l-1)) =
         blk + 2 EXP 61 * lowdigits zpre (l-1) + 2 EXP 61 * (qh * 2 EXP (64 * (l-1)))`
        then MP_TAC th else NO_TAC) THEN REWRITE_TAC[MULT_ASSOC];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64) = 0` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[VAL_WORD_0]; ALL_TAC] THEN
  ABBREV_TAC `Zf = 2 EXP 61 * (zpre - qh * b) + blk` THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s' = Zf` ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `Zf < 2 EXP (64 * l)` ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `Zf < 2 EXP (64 * k)` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
    UNDISCH_TAC `l <= k` THEN ARITH_TAC; ALL_TAC] THEN
  (* the single store z[l-1] = word(bigdigit Zf(l-1)) via STORE_IS_BIGDIGIT; bridge to the W-form. *)
  SUBGOAL_THEN
   `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' = word (bigdigit Zf (l - 1))` ASSUME_TAC THENL
   [MATCH_MP_TAC STORE_IS_BIGDIGIT THEN EXISTS_TAC `k:num` THEN
    ASM_REWRITE_TAC[] THEN (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l <= k`] THEN ARITH_TAC); ALL_TAC] THEN
  (* store bridge: the tail store-asm reads word_subword(word_join(word(bigdigit zc(l-1)+..))..) and
     STORE_IS_BIGDIGIT gives =word(bigdigit Zf(l-1)); TRANS them (bigdigit-zc form), then fold to word W
     via the W-abbrev + bigdigit zc(l-1)=bigdigit zpre(l-1).  (Direct ACCEPT of the W-form fails: the two
     read-rhs are in bigdigit-zc form, not W form.) *)
  SUBGOAL_THEN
   `word_subword (word_join (word W:int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
    word (bigdigit Zf (l - 1))` ASSUME_TAC THENL
   [FIRST_ASSUM(fun t2 -> if concl t2 =
      `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' = word (bigdigit Zf (l - 1))`
      then FIRST_ASSUM(fun t1 -> if is_eq(concl t1) &&
             lhs(concl t1) = `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s'` &&
             (try fst(dest_const(fst(strip_comb(rand(concl t1))))) = "word_subword" with _ -> false)
           then ASSUME_TAC(TRANS (SYM t1) t2) else NO_TAC)
      else NO_TAC) THEN
    FIRST_ASSUM(fun th -> if is_eq(concl th) &&
       (try fst(dest_const(fst(strip_comb(lhs(concl th))))) = "word_subword" with _ -> false) &&
       rand(concl th) = `word (bigdigit Zf (l - 1)):int64`
       then MP_TAC th else NO_TAC) THEN
    REWRITE_TAC[ASSUME `bigdigit zpre (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1)) = W`;
                ASSUME `bigdigit zc (l - 1) = bigdigit zpre (l - 1)`]; ALL_TAC] THEN
  (* entry logging -> lfw/hfw = bigdigit zc digits (dd=l-1); TAIL_LOGIN_TO_ZPRE with zc. *)
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `l - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`; `s:x86state`]
                TAIL_LOGIN_TO_ZPRE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN
    (MAP_EVERY UNDISCH_TAC [`2 <= l`; `l <= k`] THEN ARITH_TAC); ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `lowdigits Zf (l - 1) = lowdigits zc (l - 1)` ASSUME_TAC THENL
   [SUBGOAL_THEN `lowdigits Zf (l - 1) = lowdigits (lowdigits Zf l) (l - 1)` SUBST1_TAC THENL
     [REWRITE_TAC[LOWDIGITS_LOWDIGITS] THEN AP_TERM_TAC THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits Zf l = Zf` SUBST1_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = Zf` then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (l - 1) = l - 1` SUBST1_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`2 <= l`; `l <= k`] THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* fold l-1+... for R10'/R12', split POST; the three value conjuncts fold 2^(64k)*0+Zf->Zf. *)
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN TRY(REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN FIRST_ASSUM ACCEPT_TAC) THEN
  (* frame-pulls: sp+16/24/32/40/48, bignum(x,n). *)
  TRY((W(fun (asl,w) ->
        FIRST_X_ASSUM(fun th ->
          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC THEN NO_TAC)) THEN
  (* --- window: FLAT single-store field finalize by DIRECT ASM_CASES `l < pcode`.  R15'/R14' (dd=l-1):
     R15' = if l-1=pcode then SW else hfw;  R14' = if l=pcode then SW else if l<pcode then word 0
       else if l-1<pcode then SW else lfw.  After store-bridge (SW=word(bigdigit Zf(l-1))) + WORD_VAL, they
     resolve to word(bigdigit Zf pcode/(pcode-1)); WINDOW_FROM_LOGGED closes (pcode=p DIV64+1). --- *)
  (* the tail fields are in word LOW form (extr#3 of the funnel bottom); convert to word W via word W=word LOW,
     then apply the store bridge (word_subword(word W..)=word(bigdigit Zf(l-1))) + fold word(val ..)->.. *)
  REWRITE_TAC[GSYM(ASSUME `word W:int64 = word LOW`)] THEN
  REWRITE_TAC[ASSUME
    `word_subword (word_join (word W:int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
     word (bigdigit Zf (l - 1))`] THEN
  REWRITE_TAC[WORD_VAL] THEN
  ASM_CASES_TAC `l < p DIV 64 + 1` THENL
   [(* pcode > l: R15'=hfw=word 0, R14'=word 0 (l<pcode branch); Zf digits >=pcode are 0 (Zf<2^(64l)<=2^p). *)
    SUBGOAL_THEN `hfw:int64 = word 0` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `~(p DIV 64 + 1 < l - 1) ==> hfw:int64 = word 0`
         then MATCH_MP_TAC th else NO_TAC) THEN
      UNDISCH_TAC `l < p DIV 64 + 1` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `~(l - 1 = p DIV 64 + 1) /\ ~(l = p DIV 64 + 1) /\ l < p DIV 64 + 1` STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN (UNDISCH_TAC `l < p DIV 64 + 1` THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC); ALL_TAC] THEN
    ASM_REWRITE_TAC[VAL_WORD_0; DIV_0; MOD_0] THEN
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
    SUBGOAL_THEN `Zf DIV 2 EXP p = 0` SUBST1_TAC THENL
     [MATCH_MP_TAC DIV_LT THEN TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
      SUBGOAL_THEN `l <= p DIV 64` MP_TAC THENL
       [UNDISCH_TAC `l < p DIV 64 + 1` THEN ARITH_TAC; ALL_TAC] THEN
      MP_TAC(SPECL [`p:num`; `64`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[DIV_0; MOD_0];
    (* pcode <= l: R15' = word(bigdigit Zf pcode); R14' = word(bigdigit Zf(pcode-1)); WINDOW_FROM_LOGGED. *)
    SUBGOAL_THEN `p DIV 64 + 1 <= l` ASSUME_TAC THENL
     [UNDISCH_TAC `~(l < p DIV 64 + 1)` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(if l - 1 = p DIV 64 + 1 then word (bigdigit Zf (l - 1)):int64 else hfw) =
                  word (bigdigit Zf (p DIV 64 + 1))` SUBST1_TAC THENL
     [ASM_CASES_TAC `l - 1 = p DIV 64 + 1` THENL
       [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN UNDISCH_TAC `l - 1 = p DIV 64 + 1` THEN ARITH_TAC;
        ASM_REWRITE_TAC[] THEN
        ASM_CASES_TAC `p DIV 64 + 1 < l - 1` THENL
         [FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 < l - 1 ==> hfw:int64 = word (bigdigit (zc:num) (p DIV 64 + 1))`
             then MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
          AP_TERM_TAC THEN MATCH_MP_TAC BIGDIGIT_AGREE_BELOW THEN EXISTS_TAC `l - 1` THEN ASM_REWRITE_TAC[];
          SUBGOAL_THEN `hfw:int64 = word 0` SUBST1_TAC THENL
           [FIRST_X_ASSUM(fun th -> if concl th = `~(p DIV 64 + 1 < l - 1) ==> hfw:int64 = word 0`
               then MATCH_MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN MATCH_MP_TAC BIGDIGIT_ZERO THEN
          TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
          MAP_EVERY UNDISCH_TAC [`~(p DIV 64 + 1 < l - 1)`; `~(l - 1 = p DIV 64 + 1)`; `2 <= l`] THEN ARITH_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(if l = p DIV 64 + 1 then word (bigdigit Zf (l - 1)):int64
                   else if l < p DIV 64 + 1 then word 0
                   else if l - 1 < p DIV 64 + 1 then word (bigdigit Zf (l - 1)) else lfw) =
                  word (bigdigit Zf (p DIV 64))` SUBST1_TAC THENL
     [ASM_CASES_TAC `l:num = p DIV 64 + 1` THENL
       [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN UNDISCH_TAC `l:num = p DIV 64 + 1` THEN ARITH_TAC;
        ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `~(l < p DIV 64 + 1)` (fun th -> REWRITE_TAC[th]) THENL
         [UNDISCH_TAC `p DIV 64 + 1 <= l` THEN ARITH_TAC; ALL_TAC] THEN
        ASM_CASES_TAC `l - 1 < p DIV 64 + 1` THENL
         [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
          MAP_EVERY UNDISCH_TAC [`l - 1 < p DIV 64 + 1`; `p DIV 64 + 1 <= l`; `2 <= l`] THEN ARITH_TAC;
          ASM_REWRITE_TAC[] THEN
          FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 <= l - 1 ==> lfw:int64 = word (bigdigit (zc:num) ((p DIV 64 + 1) - 1))`
             then MP_TAC th else NO_TAC) THEN
          ANTS_TAC THENL
           [MAP_EVERY UNDISCH_TAC [`~(l - 1 < p DIV 64 + 1)`] THEN ARITH_TAC; ALL_TAC] THEN
          DISCH_THEN SUBST1_TAC THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
          REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN
          MATCH_MP_TAC BIGDIGIT_AGREE_BELOW THEN EXISTS_TAC `l - 1` THEN ASM_REWRITE_TAC[] THEN
          MAP_EVERY UNDISCH_TAC [`~(l - 1 < p DIV 64 + 1)`; `p DIV 64 + 1 <= l`; `1 <= p`; `2 <= l`] THEN ARITH_TAC]];
      ALL_TAC] THEN
    (* both fields now word(bigdigit Zf pcode/(pcode-1)); fold val-of-word, then WINDOW_FROM_LOGGED. *)
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
    SUBGOAL_THEN `!j. val(word (bigdigit Zf j):int64) = bigdigit Zf j` (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; ALL_TAC] THEN
    REWRITE_TAC[WINDOW_FROM_LOGGED]]);;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_CGEN_WIN -- the GENERAL-qhat C-position block (l=k, dd=k-1, GROW-to-saturation).
   pc+0x217 -> pc+0x371.  Covers l=k with ARBITRARY window/qhat (window!=0 reachable for small-top-word moduli).
   The DONE x86 C block (x86_block_c_win.ml) pins window=0 (=> qh=0); this drops that and carries general qh.

   Port of ARM BIGNUM_MOD_BLOCK_CGEN_304_WIN (block_cgen_304_win.ml), transliterated to the x86 fused tail
   (ARM's X23 top-word register -> x86 zz-slot rsp+8).

   = x86 BLOCK_C_WIN structure LIFTED to general qh (exactly as BGEN lifted B_GROW):
   - setup: BGEN's recip-of-d tower (RECIP_T0_FROM_D/ROUNDUP_T0_LE -> DDK_QHAT_LT; ABBREV hval,qh; zpre decomp;
     DDK_R_LT_D) instead of WINDOW_ZERO_IMP_LT;
   - PREFIX_Z8[l:=k, h:=hval] ;; TAIL_C[q:=qh];
   - value close = ARM CGEN's decomposition (C_CARRY_IS_Q -> CARRY=qh; W/LOW funnel + C_TOP_FUNNEL_GEN;
     C_ASSEMBLE_GEN for the assembled 2^(64k)*(LOW DIV8)+lowdigits+... = Zf; GROWING_VALUE_CLOSE_GEN cong+bound;
     explicit sp8'/z[k-1] store decomposition via word W=word LOW; CBLK_TOPSPLIT split);
   - window close = C block VERBATIM (C_LF_REORDER + LOGDIGIT_FINALIZE_BRIDGE dd:=k-1 + WINDOW_FROM_LOGGED).
   ALL deps in the x86 RELOAD chain.
   ============================================================================ *)

let BIGNUM_MOD_X86_BLOCK_CGEN_WIN = prove
 (`!k z m x n a b pc p ii w d Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = k + 1 /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * k) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Ztin + zpre /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word k /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (k + 1) /\ read R12 s = word (k + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
