         word (2 EXP 61 * (LOW MOD 2 EXP 3) + val(cwinw:int64) DIV 2 EXP 3):int64`
        then REWRITE_TAC[th] else NO_TAC) THEN
      SUBGOAL_THEN `val(word (2 EXP 61 * (LOW MOD 2 EXP 3) + val(cwinw:int64) DIV 2 EXP 3):int64) =
                    2 EXP 61 * (LOW MOD 2 EXP 3) + val(cwinw:int64) DIV 2 EXP 3` SUBST1_TAC THENL
       [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
        MP_TAC(SPECL [`LOW:num`; `2 EXP 3`] MOD_LT_EQ) THEN MP_TAC(ISPEC `cwinw:int64` VAL_BOUND_64) THEN
        REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th =
      `2 EXP (64 * k) * (LOW DIV 2 EXP 3) +
       (lowdigits zc (k-1) + 2 EXP (64 * (k-1)) * (2 EXP 61 * (LOW MOD 2 EXP 3) + val(cwinw:int64) DIV 8)) = Zf`
      then MP_TAC th else NO_TAC) THEN
    REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`]; ALL_TAC] THEN
  (* split Zf: val(sp8')=bigdigit Zf k, bignum(z,k)s'=lowdigits Zf k (CBLK_TOPSPLIT). *)
  SUBGOAL_THEN `Zf < 2 EXP (64 * (k + 1))` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[ARITH_RULE `64 * (k + 1) = 64 * k + 64`; EXP_ADD] THEN
    MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]; ALL_TAC] THEN
  MP_TAC(ISPECL [`k:num`; `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64)`;
                 `bignum_from_memory (z,k) s'`; `Zf:num`] CBLK_TOPSPLIT) THEN
  ASM_REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND] THEN STRIP_TAC THEN
  (* the tail-entry logging -> lfw/hfw = bigdigit zc digits (dd=k-1). *)
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `k - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`; `s:x86state`]
                TAIL_LOGIN_TO_ZPRE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `lowdigits Zf (k - 1) = lowdigits zc (k - 1)` ASSUME_TAC THENL
   [SUBGOAL_THEN `lowdigits Zf (k - 1) = lowdigits (lowdigits Zf k) (k - 1)` SUBST1_TAC THENL
     [REWRITE_TAC[LOWDIGITS_LOWDIGITS] THEN AP_TERM_TAC THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = lowdigits Zf k`
      then REWRITE_TAC[SYM th] else NO_TAC) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    SUBGOAL_THEN `MIN k (k - 1) = k - 1` SUBST1_TAC THENL
     [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* fold k-1+2=k+1 for R10'/R12'; split POST + close value conjuncts. *)
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  (* frame-pulls: sp+16/24/32/40/48, bignum(x,n). *)
  TRY((W(fun (asl,w) ->
        FIRST_X_ASSUM(fun th ->
          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC THEN NO_TAC)) THEN
  (* window arrives in word LOW form (line-352 ASM_REWRITE folded word W -> word LOW via the
     C_TOP_FUNNEL hyp); flip back to word W so the (word W)-form store bridges below match. *)
  REWRITE_TAC[GSYM(ASSUME `word W:int64 = word LOW`)] THEN
  (* --- window: resolve stores/logged fields to bigdigit Zf, finalize (C block VERBATIM). --- *)
  (* Bridge A: sp8'-store ushr(word W)3 = word(bigdigit Zf k).  val(sp8')=LOW DIV8 (proven above) AND
     val(sp8')=bigdigit Zf k (CBLK); sp8'=word_ushr(word W)3=word_ushr(word LOW)3=word(LOW DIV8). *)
  (* NB: CBLK_TOPSPLIT's `val(sp8')=bigdigit Zf k` was auto-rewritten by the pre-existing
     `val(sp8')=LOW DIV 2 EXP 3` hyp at line-335 ASM_REWRITE into `LOW DIV 2 EXP 3 = bigdigit Zf k`,
     which is exactly the goal after word W->word LOW + GSYM WORD_VAL + VAL_WORD_USHR + AP_TERM. *)
  SUBGOAL_THEN `word_ushr (word W:int64) 3 = word (bigdigit Zf k):int64` ASSUME_TAC THENL
   [REWRITE_TAC[ASSUME `word W:int64 = word LOW`] THEN
    GEN_REWRITE_TAC LAND_CONV [GSYM WORD_VAL] THEN
    REWRITE_TAC[VAL_WORD_USHR] THEN
    SUBGOAL_THEN `val(word LOW:int64) = LOW` SUBST1_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
    AP_TERM_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* Bridge B: z[k-1] store subword(word W..) = word(bigdigit Zf(k-1)) via STORE_IS_BIGDIGIT.
     NB: CBLK_TOPSPLIT stores `bignum(z,k)s' = lowdigits Zf k` (NOT = Zf), so feed lowdigits Zf k
     and collapse bigdigit(lowdigits Zf k)(k-1) -> bigdigit Zf(k-1) via BIGDIGIT_LOWDIGITS. *)
  SUBGOAL_THEN
   `word_subword (word_join (word W:int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
    word (bigdigit Zf (k - 1)):int64` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `k:num`; `s':x86state`; `lowdigits Zf k`; `k - 1`] STORE_IS_BIGDIGIT) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = lowdigits Zf k` then ACCEPT_TAC th else NO_TAC);
        UNDISCH_TAC `2 <= k` THEN ARITH_TAC]; ALL_TAC] THEN
    ASM_SIMP_TAC[BIGDIGIT_LOWDIGITS; ARITH_RULE `2 <= k ==> k - 1 < k`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_ASSUM(fun th -> if concl th =
       `read (memory :> bytes64 (word_add z (word (8 * (k - 1))))) s' =
        word_subword (word_join (word W:int64) (word (val(cwinw:int64)):int64):int128) (3,64)`
      then ACCEPT_TAC(SYM th) else NO_TAC); ALL_TAC] THEN
  (* rewrite the window's stores -> bigdigit Zf; WORD_VAL folds word(val lfw/hfw)->lfw/hfw. *)
  REWRITE_TAC[ASSUME `word_ushr (word W:int64) 3 = word (bigdigit Zf k):int64`;
              ASSUME `word_subword (word_join (word W:int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
                      word (bigdigit Zf (k - 1)):int64`; WORD_VAL] THEN
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [C_LF_REORDER] THEN
  MP_TAC(ISPECL [`Zf:num`; `zc:num`; `k - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`]
            LOGDIGIT_FINALIZE_BRIDGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ASSUME `k - 1 + 2 = k + 1`; ARITH_RULE `1 <= p DIV 64 + 1`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  PURE_REWRITE_TAC[ASSUME `k - 1 + 1 = k`; ASSUME `k - 1 + 2 = k + 1`] THEN
  DISCH_THEN(CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THEN
  REWRITE_TAC[WORD_VAL] THEN
  REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN
  SUBGOAL_THEN `!j. val(word (bigdigit Zf j):int64) = bigdigit Zf j` (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; ALL_TAC] THEN
  REWRITE_TAC[WINDOW_FROM_LOGGED]);;


(* ============================================================================
   x86 L1-family regime BLOCKs 0x217->0x371: the l=1 (dd=0) BASE-CASE.
   l=1 is the FIRST body iteration (ii, jj=61): entry_l=MIN(k+1)1=1.  The x86
   `dec rdi ; jz Lbignum_mod_trivnegadd` (0x264,0x267) at l=1 (dd=l-1=0) has ZF
   set, so the jz is TAKEN, skipping the inner loop entirely -> lands at 0x2a3
   (the tail entry) with the dd=0 empty-accumulation state.

   Distinct from the mainline blocks: PREFIX_Z8 (0x217->0x2a3) assumes 2<=l (jz
   FALLS THROUGH to INNERLOOP @0x265) and composes BLOCKHEAD ;; INNERLOOP_LOG
   (needs 1<=dd).  Both fail at l=1,dd=0.  So we need a NEW prefix sim,
   BIGNUM_MOD_X86_PREFIX_Z8_L1, where the jz is TAKEN.

   Two sub-regimes at exit (dd=0 => dd+1=1):
     k>1  -> B-like (exit_l=2=l+1, grows 1->2 into z): TAIL_B[q:=qh, dd:=0].
     k=1  -> C-like (exit_l=2=k+1, saturated, top spills to sp+8): L1K1 (below).
   GENERAL qhat = (w*h)DIV2^64+h (window h at first iteration arbitrary).

   Deps: BLOCKHEAD scaffold (I0_BOUNDS, BLOCKPOS, QRECON, BH_SHIFT_RW,
   FUNNEL_BLOCK), TAIL_B/TAIL_C, the general-qh value close (C_CARRY_IS_Q etc.),
   PREFIX_Z8_L1 (below).  MUST load AFTER x86_block_bgen_win + x86_block_cgen_win.
   ============================================================================ *)

(* BIGNUM_MOD_X86_PREFIX_Z8_L1 (0x217->0x2a3, l=1 base case): the block-load +
   q-setup body (0x217..0x263, 21 steps -- IDENTICAL to BLOCKHEAD) then the
   `dec rdi ; jz` TAKEN (dd=0 -> ZF set) -> 0x2a3.  POST = dd=0 tail-entry state
   (R10=RDI=word 0, RBP=R9=word qh, R11=word(2^3*block), R12=word 1) + fat
   sp-slots + z/m memory (all frame-preserved; no z write since inner loop empty). *)
let BIGNUM_MOD_X86_PREFIX_Z8_L1 = prove
 (`!k z m x n a b pc p ii w zv lfv h jjv Ztin stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ h < 2 EXP 64 /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word 1 /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x2a3) /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read R10 s = word 0 /\ read RSI s = z /\ read R8 s = m /\
           read RBP s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
           read R9 s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
           read R11 s = word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) /\
           read RDI s = word 0 /\ read R13 s = word (p DIV 64 + 1) /\
           read RSP s = stackpointer /\ read RBX s = word (61 * ii) /\ read R12 s = word 1 /\
           read R14 s = word lfv /\ read R15 s = word 0 /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word jjv /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R14; R15] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `61 * ii + 61 <= 64 * n` ASSUME_TAC THENL
   [MP_TAC(SPEC `n:num` I0_BOUNDS) THEN ANTS_TAC THENL
     [CONJ_TAC THENL [ASM_REWRITE_TAC[]; UNDISCH_TAC `n < 2 EXP 58` THEN ARITH_TAC]; ALL_TAC] THEN
    UNDISCH_TAC `ii < (64 * n + 60) DIV 61 - 1` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `61 * ii < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `61 * ii + 61 <= 64 * n` THEN UNDISCH_TAC `n < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`n:num`; `ii:num`] BLOCKPOS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
  ABBREV_TAC `qw = (61 * ii) DIV 64` THEN ABBREV_TAC `rw = (61 * ii) MOD 64` THEN
  SUBGOAL_THEN `61 * ii = qw * 64 + rw` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["qw"; "rw"] THEN MP_TAC(SPECL [`61 * ii`; `64`] DIVISION) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `rw < 64` ASSUME_TAC THENL
   [EXPAND_TAC "rw" THEN MP_TAC(SPECL [`61 * ii`; `64`] DIVISION) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `qw < 2 EXP 64` ASSUME_TAC THENL
   [TRANS_TAC LET_TRANS `61 * ii` THEN CONJ_TAC THENL
     [EXPAND_TAC "qw" THEN REWRITE_TAC[DIV_LE]; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word qw:int64) = qw` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `qw + 1 < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `qw < n` THEN UNDISCH_TAC `n < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word (qw+1):int64) = qw + 1` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * qw)))) s0 = word (bigdigit a qw)`
   ASSUME_TAC THENL
   [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (x,n) s0 = a`)] THEN
    REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES; BIGDIGIT_BIGNUM_FROM_MEMORY] THEN
    ASM_SIMP_TAC[WORD_VAL]; ALL_TAC] THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th -> is_disj (concl th))) THENL
   [(*** GENERAL qw+1<n : pin x[qw+1] ***)
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--6) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[WORD_RULE
      `word_sub (word (61 * (ii + 1))) (word 61):int64 = word (61 * ii)`]) THEN
    SUBGOAL_THEN `word_ushr (word (61 * ii):int64) 6 = word qw` ASSUME_TAC THENL
     [REWRITE_TAC[word_ushr; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN ONCE_ASM_REWRITE_TAC[ASSUME `61 * ii = qw * 64 + rw`] THEN
      SIMP_TAC[DIV_MULT_ADD; ARITH_EQ] THEN ASM_SIMP_TAC[DIV_LT; ADD_CLAUSES]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word (61 * ii):int64) 6 = word qw`]) THEN
    SUBGOAL_THEN `word_shl (word qw:int64) 3 = word (8 * qw)` ASSUME_TAC THENL
     [REWRITE_TAC[word_shl; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_shl (word qw:int64) 3 = word (8 * qw)`]) THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * qw + 8)))) s6 = word (bigdigit a (qw + 1))`
     ASSUME_TAC THENL
     [SUBGOAL_THEN `word_add x (word (8 * qw + 8)):int64 = word_add x (word (8 * (qw + 1)))` SUBST1_TAC THENL
       [CONV_TAC WORD_RULE; ALL_TAC] THEN
      SUBGOAL_THEN `read (memory :> bytes64 (word_add x (word (8 * (qw + 1))))) s6 =
                    read (memory :> bytes64 (word_add x (word (8 * (qw + 1))))) s0` SUBST1_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s6`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (x,n) s0 = a`)] THEN
      REWRITE_TAC[GSYM BIGNUM_FROM_MEMORY_BYTES; BIGDIGIT_BIGNUM_FROM_MEMORY] THEN
      ASM_SIMP_TAC[WORD_VAL]; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (7--21) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM(ASSUME `61 * ii = qw * 64 + rw`)] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[QRECON];
      ASM_SIMP_TAC[QRECON];
      MP_TAC BH_SHIFT_RW THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ONCE_REWRITE_TAC[GSYM(ASSUME `61 * ii = qw * 64 + rw`)] THEN
      MP_TAC(SPECL [`a:num`; `qw:num`; `rw:num`; `bigdigit a (qw + 1)`; `bigdigit a qw`] FUNNEL_BLOCK) THEN
      ASM_REWRITE_TAC[BIGDIGIT_BOUND];
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (x,n) s0 = a`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zv`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC];
    (*** BOUNDARY rw<=3 : x[qw+1] may be garbage g, masked off ***)
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--6) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[WORD_RULE
      `word_sub (word (61 * (ii + 1))) (word 61):int64 = word (61 * ii)`]) THEN
    SUBGOAL_THEN `word_ushr (word (61 * ii):int64) 6 = word qw` ASSUME_TAC THENL
     [REWRITE_TAC[word_ushr; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN ONCE_ASM_REWRITE_TAC[ASSUME `61 * ii = qw * 64 + rw`] THEN
      SIMP_TAC[DIV_MULT_ADD; ARITH_EQ] THEN ASM_SIMP_TAC[DIV_LT; ADD_CLAUSES]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_ushr (word (61 * ii):int64) 6 = word qw`]) THEN
    SUBGOAL_THEN `word_shl (word qw:int64) 3 = word (8 * qw)` ASSUME_TAC THENL
     [REWRITE_TAC[word_shl; VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN AP_TERM_TAC THEN
      REWRITE_TAC[ARITH_RULE `2 EXP 3 = 8`] THEN ARITH_TAC; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `word_shl (word qw:int64) 3 = word (8 * qw)`]) THEN
    ABBREV_TAC `g:int64 = read (memory :> bytes64 (word_add x (word (8 * qw + 8)))) s6` THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (7--21) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM(ASSUME `61 * ii = qw * 64 + rw`)] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[QRECON];
      ASM_SIMP_TAC[QRECON];
      MP_TAC BH_SHIFT_RW THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ONCE_REWRITE_TAC[GSYM(ASSUME `61 * ii = qw * 64 + rw`)] THEN
      SUBST1_TAC(GSYM(ISPEC `g:int64` WORD_VAL)) THEN
      MP_TAC(SPECL [`a:num`; `qw:num`; `rw:num`; `val(g:int64)`; `bigdigit a qw`] FUNNEL_BLOCK) THEN
      ASM_REWRITE_TAC[BIGDIGIT_BOUND; VAL_BOUND_64];
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (x,n) s0 = a`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zv`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s21`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC]]);;

(* ===== L1 arch-independent value-close helpers (ported from ARM block_l1_304_win.ml) ===== *)

(* L1_ZK_ASSEMBLE: dd=0 two-word assembly (armstate->x86state retyped). *)
let L1_ZK_ASSEMBLE = prove
 (`!z k zpre v0 v1 s.
    1 < k /\ highdigits zpre 2 = 0 /\
    bignum_from_memory (word_add z (word (8 * 2)), k - 2) s = highdigits zpre 2 /\
    read (memory :> bytes64 (word_add z (word (8 * 0)))) s = v0 /\
    read (memory :> bytes64 (word_add z (word (8 * 1)))) s = v1
    ==> bignum_from_memory (z,k) s = val(v0:int64) + 2 EXP 64 * val(v1:int64)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `2 + (k - 2) = k` ASSUME_TAC THENL
   [UNDISCH_TAC `1 < k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s = bignum_from_memory (z,2) s` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `2`; `k - 2`; `s:x86state`] BIGNUM_FROM_MEMORY_SPLIT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`z:int64`; `0`; `s:x86state`] BIGNUM_ASSEMBLE_2) THEN
  REWRITE_TAC[ARITH_RULE `0 + 2 = 2`; ADD_CLAUSES; MULT_CLAUSES; EXP; ARITH_RULE `0 + 1 = 1`] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; ADD_CLAUSES; MULT_CLAUSES] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `8 * 0 = 0`; ARITH_RULE `8 * 1 = 8`]) THEN
  ASM_REWRITE_TAC[]);;

let L1_TAILMUL_DISJ = prove
 (`!p b zv w. 2 EXP (p - 1) <= b /\ b < 2 EXP p /\ zv < 2 EXP 64
   ==> (w * ((zv DIV 2 EXP p) MOD 2 EXP 64)) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64 = 0 \/
       highdigits b 1 = 0`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `p <= 64` THENL
   [DISJ2_TAC THEN REWRITE_TAC[highdigits; EXP; MULT_CLAUSES] THEN
    MATCH_MP_TAC DIV_LT THEN
    TRANS_TAC LTE_TRANS `2 EXP p` THEN ASM_REWRITE_TAC[LE_EXP] THEN ASM_ARITH_TAC;
    DISJ1_TAC THEN
    SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = 0` (fun th -> REWRITE_TAC[th; MULT_CLAUSES; DIV_0; ADD_CLAUSES]) THEN
    SUBGOAL_THEN `zv DIV 2 EXP p = 0` (fun th -> REWRITE_TAC[th]) THENL
     [MATCH_MP_TAC DIV_LT THEN TRANS_TAC LTE_TRANS `2 EXP 64` THEN ASM_REWRITE_TAC[LE_EXP] THEN ASM_ARITH_TAC;
      REWRITE_TAC[MOD_0]]]);;

let L1_B0_MUL_BRIDGE = prove
 (`!q b. (q = 0 \/ highdigits b 1 = 0)
         ==> q * (2 EXP 64 - 1 - bigdigit b 0) = q * (2 EXP 64 - 1 - b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THENL
   [ASM_REWRITE_TAC[MULT_CLAUSES];
    SUBGOAL_THEN `bigdigit b 0 = b` (fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `b < 2 EXP 64` ASSUME_TAC THENL
     [UNDISCH_TAC `highdigits b 1 = 0` THEN
      REWRITE_TAC[highdigits; EXP_1] THEN SIMP_TAC[DIV_EQ_0; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[bigdigit; MULT_CLAUSES; EXP; DIV_1] THEN MATCH_MP_TAC MOD_LT THEN
    ASM_REWRITE_TAC[]]);;

let L1_MODSUB = prove
 (`!zv qhat b. qhat * b <= zv /\ zv < 2 EXP 64 /\ b < 2 EXP 64
   ==> (zv + qhat * (2 EXP 64 - b)) MOD 2 EXP 64 = zv - qhat * b`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `qhat * (2 EXP 64 - b) = qhat * 2 EXP 64 - qhat * b` SUBST1_TAC THENL
   [REWRITE_TAC[LEFT_SUB_DISTRIB]; ALL_TAC] THEN
  SUBGOAL_THEN `zv + (qhat * 2 EXP 64 - qhat * b) = (zv - qhat * b) + qhat * 2 EXP 64` SUBST1_TAC THENL
   [SUBGOAL_THEN `qhat * b <= qhat * 2 EXP 64` MP_TAC THENL
     [MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LE_REFL; LT_IMP_LE]; ALL_TAC] THEN
    UNDISCH_TAC `qhat * b <= zv` THEN ARITH_TAC;
    REWRITE_TAC[MOD_MULT_ADD] THEN MATCH_MP_TAC MOD_LT THEN
    UNDISCH_TAC `qhat * b <= zv` THEN UNDISCH_TAC `zv < 2 EXP 64` THEN ARITH_TAC]);;

(* L1_FUNNEL_TELESCOPE (PROVEN 2026-07-30): the funnel word-telescope.  The assembled 2-word value
   val z0 + 2^64*val z1 where z0=2^61*(A MOD8)+cwin DIV8, z1=(A mod 2^64)DIV8, telescopes:
   2^61*(A MOD8) + 2^64*((A mod 2^64)DIV8) = 2^61*(A mod 2^64).  So bignum(z,k)s' = 2^61*(A mod 2^64) + block
   (with cwin DIV8 = block).  Feeds the value relation via L1_MODSUB (A mod 2^64 = zv - qhat*b). *)
let L1_FUNNEL_TELESCOPE = prove
 (`!A. 2 EXP 61 * (A MOD 8) + 2 EXP 64 * ((A MOD 2 EXP 64) DIV 8) = 2 EXP 61 * (A MOD 2 EXP 64)`,
  GEN_TAC THEN REWRITE_TAC[ARITH_RULE `8 = 2 EXP 3`] THEN
  SUBGOAL_THEN `A MOD 2 EXP 3 = (A MOD 2 EXP 64) MOD 2 EXP 3` SUBST1_TAC THENL
   [REWRITE_TAC[MOD_MOD_EXP_MIN] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  MP_TAC(SPECL [`A MOD 2 EXP 64`; `2 EXP 3`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
  ARITH_TAC);;

(* L1_QHAT_ID (PROVEN 2026-07-30): ((2^64+w)*h)DIV2^64 = (w*h)DIV2^64 + h.  Bridges the QSETUP qhat form
   (w*hwin)DIV2^64+hwin to the KI/BLOCK_VALUE form ((2^64+w)*hwin)DIV2^64 used by KI_LOWER_FROM_RECIPB. *)
let L1_QHAT_ID = prove
 (`!w h. ((2 EXP 64 + w) * h) DIV 2 EXP 64 = (w * h) DIV 2 EXP 64 + h`,
  REPEAT GEN_TAC THEN REWRITE_TAC[RIGHT_ADD_DISTRIB] THEN
  SUBGOAL_THEN `2 EXP 64 * h + w * h = w * h + h * 2 EXP 64` SUBST1_TAC THENL
   [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `w * h + h * 2 EXP 64 = h * 2 EXP 64 + w * h` SUBST1_TAC THENL
   [ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[DIV_MULT_ADD; EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC);;

(* L1_FUNNEL_DECODE (PROVEN 2026-07-30): decodes the two tail stores z0=funnel(A,cwin), z1=ushr(word A)3
   into the 2-word value:  val z0 + 2^64*val z1 = 2^61*(val(word A) MOD8) + val(word cwin)DIV8 +
   2^64*(val(word A)DIV8).  Combined with L1_FUNNEL_TELESCOPE => = 2^61*(A mod 2^64) + (cwin DIV8).
   NB: `extr c,ss,c,#(64-BLOCKSIZE=3)` is the 61-bit SHIFT funnel (bignum_shl_small), NOT a truncation --
   the value spans z0,z1 correctly; VALUE_GROW_STEP (proven) encodes the full funnel algebra. *)
let L1_FUNNEL_DECODE = prove
 (`!A cwin. val(word A:int64) < 2 EXP 64 /\ val(word cwin:int64) < 2 EXP 64
   ==> val(word_subword (word_join (word A:int64) (word cwin:int64):int128) (3,64):int64) +
       2 EXP 64 * val(word_ushr (word A:int64) 3) =
       2 EXP 61 * (val(word A:int64) MOD 8) + val(word cwin:int64) DIV 8 + 2 EXP 64 * (val(word A:int64) DIV 8)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTR_FUNNEL_VAL; VAL_WORD_USHR] THEN ARITH_TAC);;

(* L1_HWIN_BOUND (PROVEN 2026-07-30): hwin*2^p <= zv (hwin=(zv DIV2^p)MOD2^64, zv<2^64).  Feeds KI_LOWER. *)
let L1_HWIN_BOUND = prove
 (`!zv p. zv < 2 EXP 64 ==> ((zv DIV 2 EXP p) MOD 2 EXP 64) * 2 EXP p <= zv`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = zv DIV 2 EXP p` SUBST1_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN TRANS_TAC LET_TRANS `zv:num` THEN ASM_REWRITE_TAC[DIV_LE]; ALL_TAC] THEN
  MP_TAC(SPECL [`zv:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC);;

(* L1_NOUNDERFLOW (PROVEN 2026-07-30): qhat*b<=zv from (RECIP_B) (2^64+w)*b<=2^(p+64) + hwin*2^p<=zv, via
   KI_LOWER_FROM_RECIPB + L1_QHAT_ID.  NB: (RECIP_B) is itself unproven-but-tested (ki_lower.ml) -- so in
   the l=1 BLOCK, the no-underflow qhat*b<=zv is taken as a HYPOTHESIS (threaded from MAINLOOP, Option B),
   EXACTLY as the DDK block takes its no-borrow hyp [21].  This lemma is kept for when RECIP_B is discharged. *)
let L1_NOUNDERFLOW = prove
 (`!w hwin zv b p. (2 EXP 64 + w) * b <= 2 EXP (p + 64) /\ hwin * 2 EXP p <= zv
   ==> ((w * hwin) DIV 2 EXP 64 + hwin) * b <= zv`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`b:num`; `p:num`; `zv:num`; `hwin:num`; `w:num`] KI_LOWER_FROM_RECIPB) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[GSYM L1_QHAT_ID] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* L1_SUBID (PROVEN 2026-07-30): q + q*(2^64-1-b) = q*(2^64-b) given b+1<=2^64.  Nat-subtraction helper
   for the funnel accumulator A = zv + q + q*(2^64-1-b0) = zv + q*(2^64-b0). *)
let L1_SUBID = prove
 (`!q b. b + 1 <= 2 EXP 64 ==> q + q * (2 EXP 64 - 1 - b) = q * (2 EXP 64 - b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `2 EXP 64 - 1 - b = (2 EXP 64 - b) - 1` SUBST1_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `1 <= 2 EXP 64 - b` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `q <= q * (2 EXP 64 - b)` MP_TAC THENL
   [GEN_REWRITE_TAC LAND_CONV [ARITH_RULE `q = q * 1`] THEN
    REWRITE_TAC[LE_MULT_LCANCEL] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[LEFT_SUB_DISTRIB; MULT_CLAUSES] THEN ARITH_TAC);;

(* L1_VALUE_BRIDGE (PROVEN 2026-07-30): the COMPLETE l=1 tail value assembly.  From the two tail stores
   z0 = funnel(word A, word cwin), z1 = ushr(word A)3 where A = zv + q + q*(2^64-1-b) (the word-0 funnel
   accumulator with hi=q), GIVEN no-underflow q*b<=zv, zv<2^64, b<2^64 (p<61 corner; b0=b), val cwin DIV8=block:
     val z0 + 2^64*val z1 = 2^61*(zv - q*b) + block   [= the reduced value Zf'].
   Chain: L1_FUNNEL_DECODE (2-word decode) + L1_FUNNEL_TELESCOPE (regroup to 2^61*(A mod 2^64)) + L1_SUBID
   (A = zv+q*(2^64-b)) + L1_MODSUB (A mod 2^64 = zv - q*b, needs no-underflow).
   Combined with L1_ZK_ASSEMBLE gives bignum(z,k)s' = 2^61*(zv-q*b)+block = Zf'; then Zf'+2^61*q*b=2^61*zv+block
   (nat eqn, q*b<=zv) feeds BLOCK_VALUE_TIGHT for cong + Zf'<b*2^64. *)
let L1_VALUE_BRIDGE = prove
 (`!zv q b block cwin.
    q * b <= zv /\ zv < 2 EXP 64 /\ b < 2 EXP 64 /\ val(word cwin:int64) DIV 8 = block
    ==> val(word_subword (word_join (word (zv + q + q * (2 EXP 64 - 1 - b)):int64) (word cwin:int64):int128) (3,64):int64) +
        2 EXP 64 * val(word_ushr (word (zv + q + q * (2 EXP 64 - 1 - b)):int64) 3) =
        2 EXP 61 * (zv - q * b) + block`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `A = zv + q + q * (2 EXP 64 - 1 - b)` THEN
  MP_TAC(ISPECL [`A:num`; `cwin:num`] L1_FUNNEL_DECODE) THEN
  REWRITE_TAC[VAL_BOUND_64] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `val(word A:int64) = A MOD 2 EXP 64` SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD; DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN
   `2 EXP 61 * ((A MOD 2 EXP 64) MOD 8) + val(word cwin:int64) DIV 8 + 2 EXP 64 * ((A MOD 2 EXP 64) DIV 8) =
    2 EXP 61 * (A MOD 2 EXP 64) + val(word cwin:int64) DIV 8`
   SUBST1_TAC THENL
   [MP_TAC(ISPEC `A MOD 2 EXP 64` L1_FUNNEL_TELESCOPE) THEN
    REWRITE_TAC[MOD_MOD_REFL] THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `A MOD 2 EXP 64 = zv - q * b` SUBST1_TAC THENL
   [EXPAND_TAC "A" THEN
    SUBGOAL_THEN `zv + q + q * (2 EXP 64 - 1 - b) = zv + q * (2 EXP 64 - b)` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`q:num`; `b:num`] L1_SUBID) THEN ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ARITH_TAC;
      MATCH_MP_TAC L1_MODSUB THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REFL_TAC);;

(* L1_VALUE_BRIDGE_GEN (PROVEN 2026-07-30): the tail's ACTUAL store-word form value bridge, valid for
   ALL b (incl b>=2^64).  The tail-B store word is word(bigdigit zv 0 + q + q*(2^64-1-bigdigit b 0));
   this bridges it to 2^61*(zv-q*b)+block, taking the disjunction (q=0 \/ highdigits b 1=0) [from
   L1_TAILMUL_DISJ] instead of b<2^64.
     - q=0 branch: funnel arg = word(bigdigit zv 0)=word zv; L1_FUNNEL_DECODE + telescope give 2^61*zv+block
       = 2^61*(zv-0)+block.  (This is the LARGE-b case: b>=2^64 => highdigits b 1!=0 => q=0.)
     - highdigits b 1=0 branch: b<2^64, bigdigit b 0=b, reduce to L1_VALUE_BRIDGE.
   *** GOTCHA: open with DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC), NOT REPEAT STRIP_TAC --
   STRIP_TAC CASE-SPLITS the disjunctive antecedent conjunct (q=0 \/ ...) into 2 goals, desyncing every
   downstream THENL.  CONJUNCTS_THEN keeps the disjunction as ONE whole hypothesis; then ASM_CASES `q=0`
   splits it deliberately where wanted.  (Same STRIP-splits-a-connective class as L1_VALUE_CLOSE cont50.) *)
let L1_VALUE_BRIDGE_GEN = prove
 (`!zv q b block cwin.
    q * b <= zv /\ zv < 2 EXP 64 /\ (q = 0 \/ highdigits b 1 = 0) /\ val(word cwin:int64) DIV 8 = block
    ==> val(word_subword (word_join (word (bigdigit zv 0 + q + q * (2 EXP 64 - 1 - bigdigit b 0)):int64) (word cwin:int64):int128) (3,64):int64) +
        2 EXP 64 * val(word_ushr (word (bigdigit zv 0 + q + q * (2 EXP 64 - 1 - bigdigit b 0)):int64) 3) =
        2 EXP 61 * (zv - q * b) + block`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `bigdigit zv 0 = zv` SUBST1_TAC THENL
   [REWRITE_TAC[bigdigit; MULT_CLAUSES; EXP; DIV_1] THEN MATCH_MP_TAC MOD_LT THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `q = 0` THENL
   [ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0] THEN
    MP_TAC(ISPECL [`zv:num`; `cwin:num`] L1_FUNNEL_DECODE) THEN
    REWRITE_TAC[VAL_BOUND_64] THEN DISCH_THEN SUBST1_TAC THEN
    SUBGOAL_THEN `val(word zv:int64) = zv` SUBST1_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPEC `zv:num` L1_FUNNEL_TELESCOPE) THEN
    SUBGOAL_THEN `zv MOD 2 EXP 64 = zv` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `8 = 2 EXP 3`] THEN DISCH_THEN(fun th -> MP_TAC th) THEN ARITH_TAC;
    SUBGOAL_THEN `highdigits b 1 = 0` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `q = 0 \/ highdigits b 1 = 0`
                              then MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `b < 2 EXP 64` ASSUME_TAC THENL
     [UNDISCH_TAC `highdigits b 1 = 0` THEN
      REWRITE_TAC[highdigits; ARITH_RULE `64 * 1 = 64`; EXP_1] THEN
      SIMP_TAC[DIV_EQ_0; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN `bigdigit b 0 = b` SUBST1_TAC THENL
     [REWRITE_TAC[bigdigit; MULT_CLAUSES; EXP; DIV_1] THEN MATCH_MP_TAC MOD_LT THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`zv:num`; `q:num`; `b:num`; `block:num`; `cwin:num`] L1_VALUE_BRIDGE) THEN
    ASM_REWRITE_TAC[]]);;

(* L1_RELQ (PROVEN 2026-07-30): the reduced-value relation.  From no-underflow q*b<=zv and the reduced
   value Zfp = 2^61*(zv-q*b)+block, recover Zfp + 2^61*q*b = 2^61*zv+block (feeds CONG_HALF).  Nat
   subtraction is distributed via LEFT_SUB_DISTRIB after SUBST'ing 2^61*(q*b), then closed by ARITH_TAC
   under the 2^61*(q*b) <= 2^61*zv guard. *)
let L1_RELQ = prove
 (`!zv q b block Zfp.
    q * b <= zv /\ Zfp = 2 EXP 61 * (zv - q * b) + block
    ==> Zfp + 2 EXP 61 * q * b = 2 EXP 61 * zv + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if concl th = `Zfp = 2 EXP 61 * (zv - q * b) + block`
                          then SUBST1_TAC th else NO_TAC) THEN
  SUBGOAL_THEN `2 EXP 61 * q * b = 2 EXP 61 * (q * b)` SUBST1_TAC THENL
   [REWRITE_TAC[MULT_ASSOC]; ALL_TAC] THEN
  SUBGOAL_THEN `2 EXP 61 * (zv - q * b) = 2 EXP 61 * zv - 2 EXP 61 * (q * b)` SUBST1_TAC THENL
   [REWRITE_TAC[LEFT_SUB_DISTRIB]; ALL_TAC] THEN
  SUBGOAL_THEN `2 EXP 61 * (q * b) <= 2 EXP 61 * zv` MP_TAC THENL
   [ASM_REWRITE_TAC[LE_MULT_LCANCEL]; ALL_TAC] THEN
  ARITH_TAC);;

(* L1_VALUE_CLOSE (PROVEN 2026-07-30): the COMPLETE l=1 value close.  From the DDK-style recip-bracket
   cluster + no-underflow (q*b<=zv) + Zfp = 2^61*(zv-q*b)+block (the reduced value), derives
   cong (CONG_HALF via the relation Zfp+2^61*q*b=2^61*zv+block) + tight bound Zfp<b*2^64 (BLOCK_VALUE_TIGHT,
   its relation ANTS = Zfp+2^61*((2^64+w)*hwin)DIV2^64*b=2^61*zv+block via L1_QHAT_ID) + INV2 Zfp<2^128
   (from Zfp<b*2^64 & b<2^64).  The 2^(64k)*0 terms are the X23'=0 (growing) framing.
   *** no-underflow q*b<=zv is a HYPOTHESIS (threaded from MAINLOOP, like DDK block's [21]; (RECIP_B) open). *)
let L1_VALUE_CLOSE = prove
 (`!a b ii p w hwin zv q block Zfp t0 s zr k.
    (zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
    block = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 /\ block < 2 EXP 61 /\
    b < 2 EXP p /\ zv < 2 EXP 64 /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
    t0 < 2 EXP 64 /\ 0 < t0 /\ hwin < 2 EXP 64 /\
    b * 2 EXP 64 = t0 * 2 EXP p + s /\ zv = hwin * 2 EXP p + zr /\ zr < 2 EXP p /\
    &2 pow 128 <= (&2 pow 64 + &w + &1) * &t0 /\ (&2 pow 64 + &w) * &t0 <= &2 pow 128 /\
    q = (w * hwin) DIV 2 EXP 64 + hwin /\ q * b <= zv /\
    Zfp = 2 EXP 61 * (zv - q * b) + block
    ==> (2 EXP (64 * k) * 0 + Zfp == a DIV 2 EXP (61 * ii)) (mod b) /\
        2 EXP (64 * k) * 0 + Zfp < b * 2 EXP 64 /\
        2 EXP (64 * k) * 0 + Zfp < 2 EXP (64 * 2)`,
  (* *** single STRIP_TAC (REPEAT GEN_TAC THEN STRIP_TAC): do NOT let REPEAT STRIP_TAC split the
     conclusion A/\B/\C into 3 goals -- that desyncs the closing REPEAT CONJ_TAC THENL count.
     Establish RELq (L1_RELQ), the QH-form relation (L1_QHAT_ID), cong (CONG_HALF) and Zfp<b*2^64
     (BLOCK_VALUE_TIGHT) as separate ASSUME_TAC subgoals, THEN split the intact conclusion 3-way.
     *** INV2 (Zfp<2^128) derived from zv<2^64 (ALWAYS true at l=1: zv is a 61-bit block), NOT from
     b<2^64 -- so this close is valid for LARGE b>=2^64 too (then p>=65 => hwin=0 => q=0). *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
  SUBGOAL_THEN `Zfp + 2 EXP 61 * q * b = 2 EXP 61 * zv + block` ASSUME_TAC THENL
   [MATCH_MP_TAC L1_RELQ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `Zfp + 2 EXP 61 * ((2 EXP 64 + w) * hwin) DIV 2 EXP 64 * b = 2 EXP 61 * zv + block`
   ASSUME_TAC THENL
   [REWRITE_TAC[L1_QHAT_ID] THEN
    FIRST_X_ASSUM(fun th -> if concl th = `q = (w * hwin) DIV 2 EXP 64 + hwin`
                            then SUBST1_TAC(SYM th) else NO_TAC) THEN
    FIRST_X_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(Zfp == a DIV 2 EXP (61 * ii)) (mod b)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `zv:num`; `Zfp:num`; `q:num`; `block:num`]
                  CONG_HALF) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `Zfp < b * 2 EXP 64` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `t0:num`; `zv:num`; `Zfp:num`;
                   `w:num`; `block:num`; `s:num`; `zr:num`; `hwin:num`; `0`]
                  BLOCK_VALUE_TIGHT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `0 < 2 EXP 64`]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `64 * 2 = 128`] THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_X_ASSUM(fun th -> if concl th = `Zfp = 2 EXP 61 * (zv - q * b) + block`
                            then SUBST1_TAC th else NO_TAC) THEN
    TRANS_TAC LET_TRANS `2 EXP 61 * zv + block` THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ARITH_RULE `a <= b ==> 2 EXP 61 * a + c <= 2 EXP 61 * b + c`) THEN ARITH_TAC;
      MAP_EVERY UNDISCH_TAC [`zv < 2 EXP 64`; `block < 2 EXP 61`] THEN ARITH_TAC]]);;


(* L1B_VALUE_ASM: the dd=0 two-word value assembly, packaged as a standalone lemma so its proof runs in a
   CLEAN context (the in-block ASM_REWRITE over ~40 hyps was leaking a stray subgoal -> seqapply).  Combines
   L1_ZK_ASSEMBLE (two-word bignum) + L1_VALUE_BRIDGE_GEN (funnel decode).  cwin folds to 2^3*blk. *)
let L1B_VALUE_ASM = prove
 (`!z k zpre hiw cwinw qh b blk s'.
    val(hiw:int64) = qh /\
    cwinw = word (2 EXP 3 * blk):int64 /\
    val(word (2 EXP 3 * blk):int64) = 2 EXP 3 * blk /\
    highdigits zpre 2 = 0 /\
    (qh = 0 \/ highdigits b 1 = 0) /\
    qh * b <= zpre /\ zpre < 2 EXP 64 /\ 1 < k /\
    bignum_from_memory (word_add z (word (8 * 2)),k - 2) s' = highdigits zpre 2 /\
    read (memory :> bytes64 (word_add z (word (8 * 0)))) s' =
      word_subword (word_join (word (bigdigit zpre 0 + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b 0)):int64) (word (val(cwinw:int64)):int64):int128) (3,64) /\
    read (memory :> bytes64 (word_add z (word (8 * 1)))) s' =
      word_ushr (word (bigdigit zpre 0 + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b 0)):int64) 3
    ==> bignum_from_memory (z,k) s' = 2 EXP 61 * (zpre - qh * b) + blk`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zpre:num`;
     `word_subword (word_join (word (bigdigit zpre 0 + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b 0)):int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64`;
     `word_ushr (word (bigdigit zpre 0 + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b 0)):int64) 3`;
     `s':x86state`] L1_ZK_ASSEMBLE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`zpre:num`; `qh:num`; `b:num`; `blk:num`; `2 EXP 3 * blk`] L1_VALUE_BRIDGE_GEN) THEN
  ASM_REWRITE_TAC[ARITH_RULE `(2 EXP 3 * blk) DIV 8 = blk`]);;


(* L1_LF_REORDER: dd=0 specialization of C_LF_REORDER with LITERAL guards (2,1,0 not (l-1)+1 etc).
   The R14 5-level field at dd=0 has literal `2 = c`/`2 < c`, which C_LF_REORDER (needs r+1=c syntactic
   form) will NOT match.  This reorders it into LOGDIGIT_FINALIZE_BRIDGE CONJUNCT2's dd=0 shape
   (if 2=c then W else if c<=2 then (if 1<c then W else if 0<c then X else L) else word 0). *)
let L1_LF_REORDER = prove
 (`!c W X L:int64.
    (if 2 = c then W else if 2 < c then word 0 else if 1 < c then W else if 0 < c then X else L) =
    (if 2 = c then W else if c <= 2 then (if 1 < c then W else if 0 < c then X else L) else word 0)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `2 = c` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `2 < c` THEN ASM_REWRITE_TAC[] THENL
   [SUBGOAL_THEN `~(c <= 2)` (fun th -> REWRITE_TAC[th]) THEN ASM_ARITH_TAC;
    SUBGOAL_THEN `c <= 2` (fun th -> REWRITE_TAC[th]) THEN ASM_ARITH_TAC]);;


(* ============================================================================
   BIGNUM_MOD_X86_BLOCK_L1_WIN (0x217->0x371, l=1 base case, k>1 => B-like grow 1->2).
   Composes PREFIX_Z8_L1 (0x217->0x2a3, jz-taken) ;; TAIL_B[dd:=0] ;; L1 value-close.
   Setup (Ztin=0 l:=1, recip bracket, DDK_QHAT_LT, hval/qh/blk abbrev deferred to seg-B).
   seg-A discharge = PREFIX_Z8_L1 with UNFOLDED midpoint (RBP/R9=word(((w*(zpre DIV2^p))DIV2^64+
   zpre DIV2^p)MOD2^64), R11=word(2^3*(a DIV2^(61 ii))MOD2^61)) => reflexive POST-weaken.
   seg-B = TAIL_B[dd:=0] + value assembly (L1_ZK_ASSEMBLE + L1_VALUE_BRIDGE_GEN + L1_TAILMUL_DISJ)
   + bounds (L1_VALUE_CLOSE for cong+<b*2^64; direct ARITH for <2^(X17v+61)) + window fieldsel
   (LOGDIGIT_FINALIZE_BRIDGE) + stores (STORE_IS_BIGDIGIT).  Mirror of ARM BIGNUM_MOD_L1_SEGB. *)
let BIGNUM_MOD_X86_BLOCK_L1_WIN = prove
 (`!k z m x n a b pc p ii w d Ztin zpre X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 < k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\
     p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = 2 /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP (64 * 1) /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Ztin + zpre /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word 1 /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztin /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (1 + 1) /\ read R12 s = word (1 + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * (1 + 1)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `Ztin = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zpre:num`; `1`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `1 < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w * (zpre DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zpre DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zpre:num`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zpre DIV 2 EXP p) MOD 2 EXP 64 = zpre DIV 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]]; ALL_TAC] THEN
  SUBGOAL_THEN `zpre DIV 2 EXP p < 2 EXP 64` ASSUME_TAC THENL
   [TRANS_TAC LET_TRANS `zpre:num` THEN ASM_REWRITE_TAC[DIV_LE]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2a3`
   `\s. read RIP s = word (pc + 0x2a3) /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read R10 s = word 0 /\ read RSI s = z /\ read R8 s = m /\
        read RBP s = word (((w * zpre DIV 2 EXP p) DIV 2 EXP 64 + zpre DIV 2 EXP p) MOD 2 EXP 64) /\
        read R9 s = word (((w * zpre DIV 2 EXP p) DIV 2 EXP 64 + zpre DIV 2 EXP p) MOD 2 EXP 64) /\
        read R11 s = word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) /\
        read RDI s = word 0 /\ read R13 s = word (p DIV 64 + 1) /\
        read RSP s = stackpointer /\ read RBX s = word (61 * ii) /\ read R12 s = word 1 /\
        read R14 s = word lfv /\ read R15 s = word 0 /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s = word (zpre DIV 2 EXP p) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = zpre` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
      [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
       `zpre:num`; `lfv:num`; `zpre DIV 2 EXP p`; `X17v:num`; `0`; `stackpointer:int64`]
       BIGNUM_MOD_X86_PREFIX_Z8_L1)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `1 < k` THEN ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
     [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES];
      SUBSUMED_MAYCHANGE_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ===== seg-B: abbrev qh/blk locally, fold midpoint RBP/R9 -> word qh, then TAIL_B[dd:=0] + value close ===== *)
  ABBREV_TAC `qh = (w * (zpre DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zpre DIV 2 EXP p) MOD 2 EXP 64` THEN
  ABBREV_TAC `blk = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  (* NB: ABBREV_TAC qh auto-folds the qhat-noovershoot hyp -> qh<2^64 and qh*b<=zpre already present. *)
  SUBGOAL_THEN `((w * zpre DIV 2 EXP p) DIV 2 EXP 64 + zpre DIV 2 EXP p) MOD 2 EXP 64 = qh` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[GSYM(ASSUME `(zpre DIV 2 EXP p) MOD 2 EXP 64 = zpre DIV 2 EXP p`)] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `((w * zpre DIV 2 EXP p) DIV 2 EXP 64 + zpre DIV 2 EXP p) MOD 2 EXP 64 = qh`]) THEN
  REWRITE_TAC[ASSUME `((w * zpre DIV 2 EXP p) DIV 2 EXP 64 + zpre DIV 2 EXP p) MOD 2 EXP 64 = qh`] THEN
  GHOST_INTRO_TAC `hiw:int64` `read R9` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read R11` THEN
  GHOST_INTRO_TAC `lfw:int64` `read R14` THEN
  GHOST_INTRO_TAC `hfw:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
   [`k:num`; `z:int64`; `m:int64`; `pc:num`; `qh:num`; `val(hiw:int64)`; `val(cwinw:int64)`; `0`;
    `b:num`; `zc:num`; `X17v:num`; `p DIV 64 + 1`; `0`; `p:num`; `val(lfw:int64)`; `val(hfw:int64)`;
    `61 * ii`; `stackpointer:int64`] BIGNUM_MOD_X86_TAIL_B)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ADD_CLAUSES] THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (UNDISCH_TAC `1 < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN UNDISCH_TAC `(X17v + 124) DIV 64 = 2` THEN
     UNDISCH_TAC `p < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL; ADD_CLAUSES];
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC(REWRITE_RULE[ADD_CLAUSES]) THEN
  (* NB: type annotation `zc:num` is REQUIRED -- bare `zc = zpre` parses polymorphically and SUBST_ALL_TAC
     silently no-ops, leaving zc in the tail store forms (which then mismatch the zpre-form window). *)
  SUBST_ALL_TAC(ASSUME `zc:num = zpre`) THEN
  SUBGOAL_THEN `val(hiw:int64) = qh` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN `highdigits zpre 2 = 0` ASSUME_TAC THENL
   [REWRITE_TAC[highdigits] THEN MATCH_MP_TAC DIV_LT THEN
    TRANS_TAC LTE_TRANS `2 EXP 64` THEN ASM_REWRITE_TAC[LE_EXP] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `qh = 0 \/ highdigits b 1 = 0` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `(w * (zpre DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zpre DIV 2 EXP p) MOD 2 EXP 64 = qh`
      then REWRITE_TAC[SYM th] else NO_TAC) THEN
    MATCH_MP_TAC L1_TAILMUL_DISJ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pre-fold cwinw = word(2^3*blk) and val hiw = qh so the L1_ZK conclusion + bridge match cleanly. *)
  SUBGOAL_THEN `val(word (2 EXP 3 * blk):int64) = 2 EXP 3 * blk` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    SUBGOAL_THEN `blk < 2 EXP 61` MP_TAC THENL
     [EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ARITH_TAC]; ALL_TAC] THEN
  (* value assembly: bignum(z,k)s' = 2^61*(zpre-qh*b)+blk.  L1_ZK gives val v0 + 2^64*val v1;
     substitute cwinw=word(2^3*blk), val hiw=qh so the funnel words become L1_VALUE_BRIDGE_GEN's exact
     shape with cwin := 2^3*blk (val(word cwin)DIV8 = (2^3*blk)DIV8 = blk). *)
  SUBGOAL_THEN `bignum_from_memory (z,k) s' = 2 EXP 61 * (zpre - qh * b) + blk` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`z:int64`; `k:num`; `zpre:num`; `hiw:int64`; `cwinw:int64`; `qh:num`; `b:num`;
       `blk:num`; `s':x86state`] L1B_VALUE_ASM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Zfp < 2^(X17v+61) via JJ_STEP (zpre-qh*b <= zpre < 2^X17v, blk < 2^61); raw ARITH fails on 2^X17v*2^61. *)
  SUBGOAL_THEN `2 EXP 61 * (zpre - qh * b) + blk < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [MATCH_MP_TAC JJ_STEP THEN ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  (* cong + <b*2^64 + <2^128 via L1_VALUE_CLOSE_D (roundup-d brackets, matching this block's hyps).
     hwin := zpre DIV 2^p (= (zpre DIV 2^p)MOD 2^64 via the MOD-identity hyp); zr := zpre MOD 2^p. *)
  SUBGOAL_THEN `~(b = 0)` ASSUME_TAC THENL
   [UNDISCH_TAC `2 EXP (p - 1) <= b` THEN MP_TAC(SPECL [`2`; `p - 1`] EXP_EQ_0) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `blk < 2 EXP 61` ASSUME_TAC THENL
   [EXPAND_TAC "blk" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `zpre = zpre DIV 2 EXP p * 2 EXP p + zpre MOD 2 EXP p` ASSUME_TAC THENL
   [MP_TAC(SPECL [`zpre:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(2 EXP (64 * k) * 0 + (2 EXP 61 * (zpre - qh * b) + blk) == a DIV 2 EXP (61 * ii)) (mod b) /\
    2 EXP (64 * k) * 0 + (2 EXP 61 * (zpre - qh * b) + blk) < b * 2 EXP 64 /\
    2 EXP (64 * k) * 0 + (2 EXP 61 * (zpre - qh * b) + blk) < 2 EXP (64 * 2)`
   STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `w:num`; `d:num`; `zpre DIV 2 EXP p`; `zpre:num`;
      `qh:num`; `blk:num`; `2 EXP 61 * (zpre - qh * b) + blk`; `zpre MOD 2 EXP p`; `k:num`] L1_VALUE_CLOSE_D) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
    (* remaining conjunct: qh = (w*zpre DIV2^p)DIV2^64 + zpre DIV2^p (q-def, MOD-form via MOD-identity) *)
    (FIRST_ASSUM(fun th -> if concl th = `(w * (zpre DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zpre DIV 2 EXP p) MOD 2 EXP 64 = qh`
       then MP_TAC(REWRITE_RULE[ASSUME `(zpre DIV 2 EXP p) MOD 2 EXP 64 = zpre DIV 2 EXP p`] th) else NO_TAC) THEN
     DISCH_THEN(fun th -> REWRITE_TAC[SYM th]));
    ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  (* fold sp+8 s' = word 0 (val 0), and the assembled value into POST *)
  SUBGOAL_THEN `val(read (memory :> bytes64 (word_add stackpointer (word 8))) s':int64) = 0` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[VAL_WORD_0]; ALL_TAC] THEN
  ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
  (* z[0]/z[1] stores = word(bigdigit Zfp 0/1) via STORE_IS_BIGDIGIT *)
  ABBREV_TAC `Zfp = 2 EXP 61 * (zpre - qh * b) + blk` THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * 0)))) s' = word (bigdigit Zfp 0)` ASSUME_TAC THENL
   [MATCH_MP_TAC STORE_IS_BIGDIGIT THEN EXISTS_TAC `k:num` THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; UNDISCH_TAC `1 < k` THEN ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * 1)))) s' = word (bigdigit Zfp 1)` ASSUME_TAC THENL
   [MATCH_MP_TAC STORE_IS_BIGDIGIT THEN EXISTS_TAC `k:num` THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; UNDISCH_TAC `1 < k` THEN ARITH_TAC]; ALL_TAC] THEN
  (* store-chain: funnel-store = word(bigdigit Zfp 0/1).  The line-779 RULE_ASSUM MULT/ADD-reduced the
     funnel-store hyps to word_add z (word 0)/(word 8); reduce the STORE_IS_BIGDIGIT results to match, then
     TRANS the funnel-store form to word(bigdigit Zfp .) so ASM_REWRITE folds them into the window selectors. *)
  RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `8 * 0 = 0`; ARITH_RULE `8 * 1 = 8`]) THEN
  (fun (asl,w) ->
     let z0read = `read (memory :> bytes64 (word_add z (word 0))) s'` in
     let z1read = `read (memory :> bytes64 (word_add z (word 8))) s'` in
     let thms = map snd asl in
     let iseqL t = is_eq(concl t) in
     let isword t = is_comb t && (try fst(strip_comb t) = `word:num->int64` with _ -> false) in
     let sw = find (fun th -> iseqL th && lhs(concl th)=z0read && not(isword(rand(concl th)))) thms in
     let bd0 = find (fun th -> iseqL th && lhs(concl th)=z0read && isword(rand(concl th))) thms in
     let uh = find (fun th -> iseqL th && lhs(concl th)=z1read && not(isword(rand(concl th)))) thms in
     let bd1 = find (fun th -> iseqL th && lhs(concl th)=z1read && isword(rand(concl th))) thms in
     (ASSUME_TAC(TRANS (SYM sw) bd0) THEN ASSUME_TAC(TRANS (SYM uh) bd1)) (asl,w)) THEN
  ASM_REWRITE_TAC[] THEN
  (* window close (dd=0): fold val hiw->qh, cwinw->word(2^3*blk), val(word(2^3*blk))->2^3*blk into the store
     bridges (so they match the qh/2^3*blk-form window selectors), reorder R14's 5-level field via
     L1_LF_REORDER (literal-2 guards; C_LF_REORDER's r+1=c form won't match dd=0), then FINALIZE + WINDOW.
     NB: plain REWRITE_TAC[L1_LF_REORDER] not GEN_REWRITE ONCE_DEPTH -- the latter can miss the R14 field. *)
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(hiw:int64) = qh`; ASSUME `cwinw = word (2 EXP 3 * blk):int64`;
    ASSUME `val(word (2 EXP 3 * blk):int64) = 2 EXP 3 * blk`]) THEN
  ASM_REWRITE_TAC[] THEN
  (* 1+1->2 (R10'/R12' block-count POST); WORD_VAL collapses word(val(word 0))->word 0, word(val(word lfv))->
     word lfv in the R15/R14 else-branches so they match LOGDIGIT_FINALIZE's hfw/lfw; L1_LF_REORDER puts the
     R14 5-level ladder into FINALIZE CONJUNCT2's dd=0 shape (literal-2 guards; C_LF_REORDER won't match). *)
  REWRITE_TAC[ARITH_RULE `1 + 1 = 2`; WORD_VAL] THEN
  REWRITE_TAC[L1_LF_REORDER] THEN
  MP_TAC(ISPECL [`Zfp:num`; `zpre:num`; `0`; `p DIV 64 + 1`; `word lfv:int64`; `word 0:int64`]
            LOGDIGIT_FINALIZE_BRIDGE) THEN
  REWRITE_TAC[ADD_CLAUSES; ARITH_RULE `1 <= p DIV 64 + 1`] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[LOWDIGITS_0; ARITH_RULE `~(p DIV 64 + 1 <= 0)`; ARITH_RULE `~(p DIV 64 + 1 < 0)`];
    ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THEN
  REWRITE_TAC[ARITH_RULE `(p DIV 64 + 1) - 1 = p DIV 64`] THEN
  SUBGOAL_THEN `!j. val(word (bigdigit Zfp j):int64) = bigdigit Zfp j` (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; ALL_TAC] THEN
  REWRITE_TAC[WINDOW_FROM_LOGGED] THEN
  (* frame close: pull sp+16/24/32/40/48 + bignum(x,n) from s to s'; the width bound
     V' < 2^(64*2) [l'=2] is an inequality (not a state-eq) -- discharge it in the same REPEAT CONJ_TAC
     sweep via the ASM (val(sp8')=0, bignum(z,k)s'=Zfp fold + banked Zfp<2^(64*2)). *)
  REPEAT CONJ_TAC THEN
  TRY(ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN FIRST_ASSUM ACCEPT_TAC THEN NO_TAC) THEN
  (W(fun (asl,w) ->
        FIRST_X_ASSUM(fun th ->
          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC));;


(* ============================================================================
   x86 BIGNUM_MOD_X86_BLOCK_L1K1_WIN -- the k=1 saturated l=1 variant regime block, 0x217->0x371.
   The l=1 base case (first iteration, dd=0, GENERAL window/qhat) at k=1, where l = min(k+1,(j+63)/64)
   SATURATES to 2=k+1 on the very first iteration: the single new word cannot grow into z[1] (out of
   bounds at k=1), so its top spills into the zz-slot (sp+8) -- a C-family tail (top->sp+8, low->z[0]).
   Distinct from:
     - L1 (x86_block_l1_win.ml): 1<k, grows 1->2 into z (sp+8 stays word 0);
     - CGEN (x86_block_cgen_win.ml): l=k->k+1 general-qhat but 2<=k (uses C_ASSEMBLE_GEN which needs 2<=k).
   Port of ARM BIGNUM_MOD_BLOCK_L1K1_304_WIN (block_l1k1_304_win.ml), ARM X23 top-word -> x86 sp+8 zz-slot.

   Structure = PREFIX_Z8_L1 (k:=1, 0x217->0x2a3, jz-taken) ;; TAIL_C (dd:=0, k:=1, 0x2a3->0x371) ;; value
   close.  The value close mirrors L1 (L1B-style) BUT the assembled value is the C-SPILL split
   2^64*val(sp8') + bignum(z,1) = Zf (via L1K1_ZK, the k=1 single-word assembly built from
   L1_VALUE_BRIDGE_GEN), NOT L1's grow-into-z[1].  CGEN's C_ASSEMBLE_GEN needs 2<=k so is NOT reused;
   L1K1_ZK is the dedicated k=1 assembly (from ARM block_l1k1_304_win.ml).

   Deps (all in x86 RELOAD chain): BIGNUM_MOD_X86_PREFIX_Z8_L1, L1_VALUE_BRIDGE_GEN, L1_TAILMUL_DISJ,
   L1_VALUE_CLOSE_D, L1_LF_REORDER (x86_block_l1_win.ml); BIGNUM_MOD_X86_TAIL_C (x86_tail_c_candidate.ml);
   RECIP_T0_FROM_D/ROUNDUP_T0_LE/DDK_QHAT_LT/DDK_R_LT_D/JJ_STEP/GROWING_VALUE_CLOSE_GEN (scaffold);
   CBLK_TOPSPLIT/STORE_IS_BIGDIGIT (x86_block_helpers); LOGDIGIT_FINALIZE_BRIDGE/WINDOW_FROM_LOGGED/
   BIGNUM_FROM_MEMORY_SING.  MUST load AFTER x86_block_l1_win.ml + x86_tail_c_candidate.ml.
   ============================================================================ *)

(* L1K1_ZK (x86): k=1 value assembly (general qhat q; top spills to sp+8 zz-slot, low word into z[0]).
   Re-partitions the SAME two funnel terms L1_VALUE_BRIDGE_GEN produces as (2^64*val(sp8'), bignum(z,1)).
   Arch-independent modulo the x86state retype. *)
let L1K1_ZK = prove
 (`!z zv q b block cwin s.
    q * b <= zv /\ zv < 2 EXP 64 /\ (q = 0 \/ highdigits b 1 = 0) /\
    val(word cwin:int64) DIV 8 = block /\
    read (memory :> bytes64 (word_add z (word (8 * 0)))) s =
      word_subword (word_join (word (bigdigit zv 0 + q + q * (2 EXP 64 - 1 - bigdigit b 0)):int64) (word cwin:int64):int128) (3,64)
    ==> 2 EXP 64 * val(word_ushr (word (bigdigit zv 0 + q + q * (2 EXP 64 - 1 - bigdigit b 0)):int64) 3) +
        bignum_from_memory (z,1) s = 2 EXP 61 * (zv - q * b) + block`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MP_TAC(ISPECL [`zv:num`; `q:num`; `b:num`; `block:num`; `cwin:num`] L1_VALUE_BRIDGE_GEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `8 * 0 = 0`; WORD_ADD_0]) THEN
  REWRITE_TAC[BIGNUM_FROM_MEMORY_SING] THEN ASM_REWRITE_TAC[] THEN ARITH_TAC);;


(* ============================================================================
   BIGNUM_MOD_X86_BLOCK_L1K1_WIN (0x217->0x371, k=1 saturated l=1).
   Composes PREFIX_Z8_L1 (k:=1, 0x217->0x2a3, jz-taken) ;; TAIL_C (dd:=0, k:=1, C-spill) ;; value close
   (L1K1_ZK for the two-word split + CBLK_UNIQ/CBLK_SPLIT k=1; GROWING_VALUE_CLOSE_GEN cong+bound; JJ_STEP).
   The k=1 edge: CGEN's C_ASSEMBLE_GEN needs 2<=k, so we use the k=1-specific L1K1_ZK (from L1_VALUE_BRIDGE_GEN).
   Window close = WORD_VAL + L1_LF_REORDER (after reducing 1+1->2 in the R14 field) + LOGDIGIT_FINALIZE_BRIDGE
   (dd=0) + WINDOW_FROM_LOGGED, then frame-pull.  LESSONS: (a) DDK_QHAT_LT ANTS `zv<b*2^64` supplied from
   zv<2^64<=b*2^64 (1<=b); (b) `SUBST_ALL_TAC(ASSUME zc:num=zv)` needs the type annotation; (c) at k=1 the
   R14 field guard is literal `1+1` (not reduced to `2`) so REWRITE[1+1=2] BEFORE L1_LF_REORDER, and the
   WINDOW rewrite folds field-1 first then field-2 needs a SECOND finalize pass. *)
let BIGNUM_MOD_X86_BLOCK_L1K1_WIN = prove
 (`!z m x n a b pc p ii w d zv X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\
     b < 2 EXP (64 * 1) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = 2 /\ zv < 2 EXP 64 /\ zv < 2 EXP X17v /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b <= zv /\
     nonoverlapping (word pc,0x4da) (z,8 * 1) /\ nonoverlapping (word pc,0x4da) (m,8 * 1) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * 1) (m,8 * 1) /\ nonoverlapping (z,8 * 1) (x,8 * n) /\
     nonoverlapping (z,8 * 1) (stackpointer,72) /\ nonoverlapping (m,8 * 1) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\ read R12 s = word 1 /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\
           read (memory :> bytes64 stackpointer) s = word 1 /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word ((zv DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
           bignum_from_memory (z,1) s = zv)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (1 + 1) /\ read R12 s = word (1 + 1) /\ read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word 1 /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
           (2 EXP (64 * 1) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,1) s == a DIV 2 EXP (61 * ii)) (mod b) /\
