            bignum_from_memory (z,1) s < b * 2 EXP 64 /\
           2 EXP (64 * 1) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,1) s < 2 EXP (64 * (1 + 1)) /\
           2 EXP (64 * 1) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,1) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
