  SUBGOAL_THEN `1 <= b` ASSUME_TAC THENL
   [UNDISCH_TAC `~(b = 0)` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `zv < b * 2 EXP 64` ASSUME_TAC THENL
