        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s = word (zv DIV 2 EXP p) /\
