          if is_eq(concl th) && rand(concl th) = rand w &&
             (try rand(lhs(concl th)) = `s:x86state` with Failure _ -> false)
          then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC)) THEN
      (REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] ORELSE ALL_TAC) THEN
      FIRST_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s s'`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[bignum] THEN READ_OVER_WRITE_ORTHOGONAL_TAC));;


(* ============================================================================
   BIGNUM_MOD_X86_BODY_DISPATCH -- the FULL regime dispatch for ONE main-loop iteration
   (x86 0x217 -> 0x371), keyed on l = MIN(k+1)((X17v+63)DIV64), covering ALL regimes incl FLAT.
   Port of ARM BIGNUM_MOD_BODY_DISPATCH (block_dispatch.ml).
   ----------------------------------------------------------------------------
   Pure 9-leaf decision tree, ZERO instruction-stepping: each leaf MPs a per-regime
   BIGNUM_MOD_X86_BLOCK_<R>_WIN.  Tree (raw = (X17v+63)DIV64):
     k+1<=raw                          -> DDK  (l=k+1, saturated, raw2=raw)
     l=raw<k+1, RAW2_STEP raw2=raw+1 (GROW):  l=1,k=1->L1K1 ; l=1,1<k->L1 ;
                                              2<=l=k [win=0->C ; win!=0->CGEN] ;
                                              2<=l<k [win=0->B_GROW ; win!=0->BGEN]
     l=raw<k+1, RAW2_STEP raw2=raw   (FLAT):  l<pcode -> FLAT_GEN ; pcode<=l -> FLATGEN_ALL.
   x86<->ARM: X16->RBX (counter word(61*ii)); X23->sp+8 (top word); X15->sp+64 (window);
     X19->R12=R10 (exit l'); X17->sp+56 (jj); X0->sp+0 (word k); loader BUTLAST bignum_mod_tmc;
     offsets 0x1a4->0x217, 0x304->0x371; width 0x438->0x4da.
   x86 DIVERGENCE from ARM (handled per-leaf): the x86 blocks are NOT PRE-uniform in R15 --
     DDK/C/L1/L1K1 omit `read R15 s = word hfv` (their hfv is a dead binder), while
     CGEN/FLAT_GEN/FLATGEN_ALL/B_GROW/BGEN require it.  The dispatch PRE carries R15 (feeds
     the latter 5); the 4 no-R15 leaves are weaker in PRE, so plain DISCH_THEN ACCEPT_TAC
     works for them too (the block PRE is IMPLIED by the dispatch PRE -- MATCH_MP just drops
     the unused R15 read).  [If a leaf mismatches, wrap it in ENSURES_PRECONDITION_THM.]
   Deps: all 9 BIGNUM_MOD_X86_BLOCK_*_WIN + JJ_STEP/FLAT_JJ_FIT/INV2_TOP_ZERO/RAW2_STEP/
     WINDOW_NZ_IMP_B_LT (scaffold).  Load LAST (after all 9 blocks).
   ============================================================================ *)

(* Universal leaf closer: MP the block ens (goal is now `block-ens ==> dispatch-ens`), then
   weaken dispatch-PRE to block-PRE via ENSURES_PRECONDITION_THM.  POST+FRAME are alpha-equal
   (all blocks share the DDK POST/frame shape), and dispatch-PRE IMPLIES block-PRE (dispatch
   carries R15=word hfv which DDK/C/L1/L1K1 blocks drop; the R15-reading blocks match exactly,
   for which the implication is reflexive).  Uniform across all 9 leaves. *)
let DISPATCH_LEAF_TAC =
  DISCH_THEN(fun bth0 ->
    (* L1/L1K1 blocks deliver POST exit-count word(1+1); the dispatch l=1 branch normalizes it to
       word 2, so fold 1+1->2 in the block ens first (no-op for the other 7 leaves). *)
    let bth = REWRITE_RULE[ARITH_RULE `1 + 1 = 2`] bth0 in
    let pblock = rand(rator(rator(concl bth))) in
    MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN EXISTS_TAC pblock THEN CONJ_TAC THENL
     [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
      ACCEPT_TAC bth]);;

let BIGNUM_MOD_X86_BODY_DISPATCH = prove
 (`!k z m x n a b pc p ii w d Zt zv X17v lfv hfv stackpointer.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ 61 <= X17v /\ 1 <= (X17v + 63) DIV 64 /\
     zv < 2 EXP (64 * k) /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * MIN (k + 1) ((X17v + 63) DIV 64)) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Zt + zv /\
     nonoverlapping (word pc,0x4da) (z,8 * k) /\ nonoverlapping (word pc,0x4da) (m,8 * k) /\
     nonoverlapping (word pc,0x4da) (x,8 * n) /\ nonoverlapping (word pc,0x4da) (stackpointer,72) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
     nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
     nonoverlapping (x,8 * n) (stackpointer,72)
     ==> ensures x86
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x217) /\
           read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
           read RBX s = word (61 * (ii + 1)) /\
           read R12 s = word (MIN (k + 1) ((X17v + 63) DIV 64)) /\
           read R13 s = word (p DIV 64 + 1) /\ read R14 s = word lfv /\ read R15 s = word hfv /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Zt /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word X17v /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x371) /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read R10 s = word (MIN (k + 1) ((X17v + 124) DIV 64)) /\
           read R12 s = word (MIN (k + 1) ((X17v + 124) DIV 64)) /\
           read RBX s = word (61 * ii) /\
           read RSP s = stackpointer /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (X17v + 61) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (64 * MIN (k + 1) ((X17v + 124) DIV 64)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
            bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
       MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
       MAYCHANGE [memory :> bignum(z,k)] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ABBREV_TAC `l = MIN (k + 1) ((X17v + 63) DIV 64)` THEN
  SUBGOAL_THEN `1 <= l` ASSUME_TAC THENL
   [EXPAND_TAC "l" THEN UNDISCH_TAC `1 <= (X17v + 63) DIV 64` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `k + 1 <= (X17v + 63) DIV 64` THENL
   [(* ===== DDK: l=k+1, raw2=raw=k+1 (saturated stays) ===== *)
    SUBGOAL_THEN `l = k + 1` SUBST_ALL_TAC THENL
     [EXPAND_TAC "l" THEN UNDISCH_TAC `k + 1 <= (X17v + 63) DIV 64` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `MIN (k + 1) ((X17v + 124) DIV 64) = k + 1` SUBST1_TAC THENL
     [MP_TAC(SPEC `X17v:num` RAW2_STEP) THEN
      UNDISCH_TAC `k + 1 <= (X17v + 63) DIV 64` THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                   `p:num`;`ii:num`;`w:num`;`d:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                   `stackpointer:int64`]
                  BIGNUM_MOD_X86_BLOCK_DDK_WIN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISPATCH_LEAF_TAC];
    (* ===== growing: l = raw < k+1 ===== *)
    ALL_TAC] THEN
  SUBGOAL_THEN `l < k + 1 /\ l = (X17v + 63) DIV 64` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN EXPAND_TAC "l" THEN UNDISCH_TAC `~(k + 1 <= (X17v + 63) DIV 64)` THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `l <= k` ASSUME_TAC THENL
   [UNDISCH_TAC `l < k + 1` THEN ARITH_TAC; ALL_TAC] THEN
  DISJ_CASES_TAC(SPEC `X17v:num` RAW2_STEP) THENL
   [(* ===== FLAT: raw2 = raw = l, exit l unchanged ===== *)
    SUBGOAL_THEN `MIN (k + 1) ((X17v + 124) DIV 64) = l` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k + 1` THEN UNDISCH_TAC `l = (X17v + 63) DIV 64` THEN
      ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `2 <= l` ASSUME_TAC THENL
     [SUBGOAL_THEN `~(l = 1)` MP_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(SPECL [`X17v + 63`; `64`] DIVISION) THEN
        MP_TAC(SPECL [`X17v + 124`; `64`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN
        UNDISCH_TAC `(X17v + 124) DIV 64 = (X17v + 63) DIV 64` THEN
        UNDISCH_TAC `l = (X17v + 63) DIV 64` THEN UNDISCH_TAC `l = 1` THEN
        UNDISCH_TAC `61 <= X17v` THEN ARITH_TAC;
        UNDISCH_TAC `1 <= l` THEN ARITH_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `(X17v + 124) DIV 64 = l` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `X17v + 61 <= 64 * l` ASSUME_TAC THENL
     [MP_TAC(SPEC `X17v:num` FLAT_JJ_FIT) THEN
      ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
       [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`;`zv:num`;`l:num`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
    SUBGOAL_THEN
     `2 EXP 61 * (zv -
        ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
         (zv DIV 2 EXP p) MOD 2 EXP 64) * b) +
      (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)`
     ASSUME_TAC THENL
     [MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP (X17v + 61)` THEN CONJ_TAC THENL
       [MATCH_MP_TAC JJ_STEP THEN ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
        ASM_REWRITE_TAC[LE_EXP; ARITH_EQ]]; ALL_TAC] THEN
    ASM_CASES_TAC `l < p DIV 64 + 1` THENL
     [(* l < pcode: window=0 -> FLAT_GEN (Zt:=0). *)
      SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = 0` ASSUME_TAC THENL
       [SUBGOAL_THEN `zv DIV 2 EXP p = 0` (fun th -> REWRITE_TAC[th; MOD_0]) THEN
        MATCH_MP_TAC DIV_LT THEN
        TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
          UNDISCH_TAC `l < p DIV 64 + 1` THEN
          MP_TAC(SPECL [`p:num`; `64`] DIVISION) THEN ARITH_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)` ASSUME_TAC THENL
       [UNDISCH_TAC `2 EXP 61 * (zv -
           ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
            (zv DIV 2 EXP p) MOD 2 EXP 64) * b) +
         (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)` THEN
        ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; DIV_0; SUB_0]; ALL_TAC] THEN
      MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                     `p:num`;`ii:num`;`w:num`;`l:num`;`0`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                     `stackpointer:int64`]
                    BIGNUM_MOD_X86_BLOCK_FLATGEN_WIN) THEN
      REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        REWRITE_TAC[ASSUME `(zv DIV 2 EXP p) MOD 2 EXP 64 = 0`] THEN DISPATCH_LEAF_TAC];
      (* pcode <= l: b<2^(64*l); FLATGEN_ALL (Zt:=0). *)
      SUBGOAL_THEN `b < 2 EXP (64 * l)` ASSUME_TAC THENL
       [TRANS_TAC LTE_TRANS `2 EXP p` THEN CONJ_TAC THENL
         [ASM_REWRITE_TAC[LT_IMP_LE];
          REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
          UNDISCH_TAC `~(l < p DIV 64 + 1)` THEN
          MP_TAC(SPECL [`p:num`; `64`] DIVISION) THEN ARITH_TAC]; ALL_TAC] THEN
      MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                     `p:num`;`ii:num`;`w:num`;`d:num`;`l:num`;`0`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                     `stackpointer:int64`]
                    BIGNUM_MOD_X86_BLOCK_FLATGEN_ALL_WIN) THEN
      REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISPATCH_LEAF_TAC]];
    (* ===== GROW: raw2 = raw + 1, exit l+1 ===== *)
    SUBGOAL_THEN `MIN (k + 1) ((X17v + 124) DIV 64) = l + 1` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k + 1` THEN UNDISCH_TAC `l = (X17v + 63) DIV 64` THEN
      ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(X17v + 124) DIV 64 = l + 1` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `l = 1` THENL
     [(* ===== l=1 ===== *)
      FIRST_X_ASSUM(fun th -> if concl th = `l = 1` then SUBST_ALL_TAC th else NO_TAC) THEN
      REWRITE_TAC[ARITH_RULE `1 + 1 = 2`] THEN
      SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
       [SUBGOAL_THEN `2 EXP (64 * k) * Zt < 2 EXP (64 * k) * 1` MP_TAC THENL
         [REWRITE_TAC[MULT_CLAUSES] THEN
          TRANS_TAC LET_TRANS `2 EXP (64 * k) * Zt + zv` THEN CONJ_TAC THENL
           [ARITH_TAC; ALL_TAC] THEN
          TRANS_TAC LTE_TRANS `2 EXP (64 * 1)` THEN CONJ_TAC THENL
           [FIRST_X_ASSUM(fun th -> if concl th = `2 EXP (64 * k) * Zt + zv < 2 EXP (64 * 1)`
               then ACCEPT_TAC th else NO_TAC);
            REWRITE_TAC[LE_EXP] THEN UNDISCH_TAC `1 <= k` THEN ARITH_TAC];
          REWRITE_TAC[LT_MULT_LCANCEL; EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC];
        ALL_TAC] THEN
      REWRITE_TAC[ARITH_RULE `2 EXP (64 * k) * 0 + zv = zv`] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `2 EXP (64 * k) * 0 + zv = zv`]) THEN
      SUBGOAL_THEN `zv < 2 EXP 64` ASSUME_TAC THENL
       [TRANS_TAC LTE_TRANS `2 EXP (64 * 1)` THEN CONJ_TAC THENL
         [FIRST_X_ASSUM(fun th -> if concl th = `zv < 2 EXP (64 * 1)` then ACCEPT_TAC th else NO_TAC);
          REWRITE_TAC[MULT_CLAUSES; LE_REFL]];
        ALL_TAC] THEN
      ASM_CASES_TAC `k = 1` THENL
       [(* L1K1: k=1.  Pre-establish (X17v+124)DIV64=2 (tiny context) so ANTS is pure ACCEPT
           (ARITH_TAC over the leaf context HANGS). *)
        FIRST_X_ASSUM(fun th -> if concl th = `k = 1` then SUBST_ALL_TAC th else NO_TAC) THEN
        SUBGOAL_THEN `(X17v + 124) DIV 64 = 2` ASSUME_TAC THENL
         [UNDISCH_TAC `(X17v + 124) DIV 64 = 1 + 1` THEN ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPECL [`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                       `p:num`;`ii:num`;`w:num`;`d:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                       `stackpointer:int64`]
                      BIGNUM_MOD_X86_BLOCK_L1K1_WIN) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          (ASM_REWRITE_TAC[MULT_CLAUSES]);
          DISPATCH_LEAF_TAC];
        (* L1: 1<k.  Pre-establish the 2 non-ASM ANTS facts (1<k, (X17v+124)DIV64=2) with TINY
           contexts, so the ANTS discharge is pure FIRST_ASSUM ACCEPT_TAC (ARITH_TAC over the ~46-asm
           leaf context HANGS). *)
        SUBGOAL_THEN `1 < k` ASSUME_TAC THENL
         [UNDISCH_TAC `~(k = 1)` THEN UNDISCH_TAC `1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
        SUBGOAL_THEN `(X17v + 124) DIV 64 = 2` ASSUME_TAC THENL
         [UNDISCH_TAC `(X17v + 124) DIV 64 = 1 + 1` THEN ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                       `p:num`;`ii:num`;`w:num`;`d:num`;`0`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                       `stackpointer:int64`]
                      BIGNUM_MOD_X86_BLOCK_L1_WIN) THEN
        REWRITE_TAC[ARITH_RULE `2 EXP (64 * k) * 0 + zv = zv`; MULT_CLAUSES; ADD_CLAUSES] THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISPATCH_LEAF_TAC]];
      (* ===== 2<=l ===== *)
      SUBGOAL_THEN `2 <= l` ASSUME_TAC THENL
       [UNDISCH_TAC `~(l = 1)` THEN UNDISCH_TAC `1 <= l` THEN ARITH_TAC; ALL_TAC] THEN
      ASM_CASES_TAC `l:num = k` THENL
       [(* l=k: C / CGEN *)
        FIRST_X_ASSUM(fun th -> if concl th = `l:num = k` then SUBST_ALL_TAC th else NO_TAC) THEN
        ASM_CASES_TAC `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0` THENL
         [FIRST_ASSUM(fun th -> if concl th = `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0`
             then GEN_REWRITE_TAC (RATOR_CONV o LAND_CONV o ONCE_DEPTH_CONV) [th] else NO_TAC) THEN
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;
                         `stackpointer:int64`]
                        BIGNUM_MOD_X86_BLOCK_C_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISPATCH_LEAF_TAC];
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`d:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                         `stackpointer:int64`]
                        BIGNUM_MOD_X86_BLOCK_CGEN_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISPATCH_LEAF_TAC]];
        (* l<k: B_GROW / BGEN *)
        SUBGOAL_THEN `l < k` ASSUME_TAC THENL
         [UNDISCH_TAC `l < k + 1` THEN UNDISCH_TAC `~(l:num = k)` THEN ARITH_TAC; ALL_TAC] THEN
        ASM_CASES_TAC `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0` THENL
         [FIRST_ASSUM(fun th -> if concl th = `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0`
             then GEN_REWRITE_TAC (RATOR_CONV o LAND_CONV o ONCE_DEPTH_CONV) [th] else NO_TAC) THEN
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`l:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                         `stackpointer:int64`]
                        BIGNUM_MOD_X86_BLOCK_BGROW_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISPATCH_LEAF_TAC];
          SUBGOAL_THEN `b < 2 EXP (64 * l)` ASSUME_TAC THENL
           [MATCH_MP_TAC WINDOW_NZ_IMP_B_LT THEN
            MAP_EVERY EXISTS_TAC [`2 EXP (64 * k) * Zt + zv`; `p:num`] THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`d:num`;`l:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`;
                         `stackpointer:int64`]
                        BIGNUM_MOD_X86_BLOCK_BGEN_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISPATCH_LEAF_TAC]]]]]);;


(* ============================================================================
   BIGNUM_MOD_X86_MAINLOOP -- the full main division loop (x86 pc+0x217 -> pc+0x37a),
   wrapping BIGNUM_MOD_X86_BODY_DISPATCH over the 61-bit-block countdown via ENSURES_WHILE_PDOWN_TAC.
   Port of ARM BIGNUM_MOD_MAINLOOP (mainloop_wrap.ml).
   ----------------------------------------------------------------------------
   x86 backedge (decoded from tmc @0x371): `test rbx,rbx`(48 85 db)@0x371 ; `jnz 0x217`(0f 85 rel32)@0x374 ;
   fall-through EXIT @0x37a.  So the loop counter lives in RBX (x86) where ARM used X16; the dispatch POST
   (built cont124) pins RBX=word(61*ii) for exactly this test.  ENSURES_WHILE_PDOWN_TAC body-head=0x217,
   backedge-test=0x371.
   x86<->ARM register/slot map for the invariant (i = NB..0, NB=(64n+60)DIV61-1):
     ARM X16=word(61*i)          -> x86 RBX=word(61*i)          [loop counter, test rbx,rbx]
     ARM X17=word(61+61*(NB-i))  -> x86 sp+56 = word(61+61*(NB-i))   [jj bit-counter, in memory]
     ARM X19=word(MIN(k+1)(...)) -> x86 R12 = word(MIN(k+1)((61+61*(NB-i)+63)DIV64))  [word count l]
     ARM X12=word(pDIV64+1)      -> x86 R13 = word(p DIV 64 + 1)     [pcode]
     ARM X23=top word            -> x86 sp+8 = word Zt               [top word in zz-slot]
     ARM X15=window              -> x86 sp+64 = word(((V) DIV 2^p) MOD 2^64)  [window]
     ARM X0/X1/X2/X3/X4=k/z/n/x/m; x86: sp+0=word k, RSI=z, sp+16=word n, sp+24=x, RSI... m=R8,
       sp+32=m, sp+40=word w, sp+48=word p.  V := 2^(64k)*val(sp+8) + bignum(z,k).
   Precond n < 2^58 - 1 (block-counter no-wrap, as ARM); k < 2^58.
   Body maps INV(i+1)@0x217 -> INV(i)@0x371 via BODY_DISPATCH (X17v:=61+61*(NB-(i+1)), ii:=i, w:=val w,
   Zt/zv/lfv/hfv GHOST_INTRO'd); qh-bound via RED_LEMMA_D; POST->PRE via ENSURES_POST/PRECONDITION_THM.
   Deps: BIGNUM_MOD_X86_BODY_DISPATCH + BIGNUM_MOD_EXEC + RED_LEMMA_D/QHAT_ID (scaffold).
   ============================================================================ *)

let BIGNUM_MOD_X86_MAINLOOP = prove
 (`!k z n x m a b w d p pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\
      a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\
      ~(b = 0) /\
      w < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
      0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
      (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
      d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + w) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (x,8 * n) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\ nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (x,8 * n) (stackpointer,72)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x217) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read RBX s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read R12 s = word 1 /\ read R13 s = word (p DIV 64 + 1) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 56))) s = word 61 /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s = a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\
            read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
             bignum_from_memory (z,k) s == a) (mod b) /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
             bignum_from_memory (z,k) s < b * 2 EXP 64 /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                      bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `61 * ((64 * n + 60) DIV 61 - 1) + 124 < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `n < 2 EXP 58 - 1` THEN ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `NB = (64 * n + 60) DIV 61 - 1` THEN
  ENSURES_WHILE_PDOWN_TAC `NB:num` `pc + 0x217` `pc + 0x371`
   `\(i:num) s. (read RSP s = stackpointer /\
           read RSI s = z /\ read R8 s = m /\ read R13 s = word (p DIV 64 + 1) /\
           read RBX s = word (61 * i) /\
           read R12 s = word (MIN (k + 1) ((61 + 61 * (NB - i) + 63) DIV 64)) /\
           read (memory :> bytes64 stackpointer) s = word k /\
           read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
           read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
           read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
           read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
           read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
           read (memory :> bytes64 (word_add stackpointer (word 56))) s = word (61 + 61 * (NB - i)) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s == a DIV 2 EXP (61 * i)) (mod b) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s
              < 2 EXP (64 * MIN (k + 1) ((61 + 61 * (NB - i) + 63) DIV 64)) /\
           2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s < 2 EXP (61 + 61 * (NB - i)) /\
           bignum_from_memory (z,k) s < 2 EXP (64 * k) /\
           read (memory :> bytes64 (word_add stackpointer (word 64))) s =
             word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                     bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64)) /\
          T` THEN
  ASM_REWRITE_TAC[] THEN
  (* ---- NB <> 0 ---- *)
  CONJ_TAC THENL
   [EXPAND_TAC "NB" THEN
    MP_TAC(SPECL [`64 * n`; `61`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN
    UNDISCH_TAC `1 <= n` THEN ARITH_TAC;
    ALL_TAC] THEN
  (* ---- entry jj-base: a DIV 2^(61 NB) < 2^61 ---- *)
  SUBGOAL_THEN `64 * n <= 61 + 61 * NB` ASSUME_TAC THENL
   [EXPAND_TAC "NB" THEN MP_TAC(SPECL [`64 * n`; `61`] DIVISION) THEN
    REWRITE_TAC[ARITH_EQ] THEN UNDISCH_TAC `1 <= n` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `a DIV 2 EXP (61 * NB) < 2 EXP 61` ASSUME_TAC THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
    REWRITE_TAC[GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `2 EXP (64 * n)` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
      UNDISCH_TAC `64 * n <= 61 + 61 * NB` THEN ARITH_TAC]; ALL_TAC] THEN
  (* ---- ENTRY (i = NB) ---- *)
  CONJ_TAC THENL
   [ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN
    (* fold NB-NB=0, MIN(k+1)((61+63)DIV64)=1, val(word 0)=0 so V = bignum(z,k) at entry; then the
       V-equation hyp `2^(64k)*val(sp+8)+bignum(z,k) = a DIV2^(61 NB)` (=bignum(z,k) after val(word 0)=0)
       makes cong CONG_REFL and window/bounds refer to a DIV2^(61 NB) (<2^61 banked). *)
    REWRITE_TAC[SUB_REFL; MULT_CLAUSES; ADD_CLAUSES; VAL_WORD_0;
                ARITH_RULE `(61 + 63) DIV 64 = 1`; ARITH_RULE `MIN (k + 1) 1 = 1`] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CONG_REFL] THEN
    REWRITE_TAC[ARITH_RULE `64 * 1 = 64`] THEN
    (* residual value-bounds at i=NB (V = a DIV2^(61 NB) < 2^61 banked): V<b*2^64, V<2^64 [width, l'=1],
       V<2^61 [jj], bignum(z,k)<2^(64k).  First bank V<b*2^64 and V<2^64 as facts, then all conjuncts
       close by FIRST_ASSUM ACCEPT / BIGNUM bound. *)
    SUBGOAL_THEN `a DIV 2 EXP (61 * NB) < 2 EXP 64` ASSUME_TAC THENL
     [MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP 61` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; REWRITE_TAC[LE_EXP] THEN ARITH_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `a DIV 2 EXP (61 * NB) < b * 2 EXP 64` ASSUME_TAC THENL
     [MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP 64` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        GEN_REWRITE_TAC LAND_CONV [ARITH_RULE `2 EXP 64 = 1 * 2 EXP 64`] THEN
        REWRITE_TAC[LE_MULT_RCANCEL] THEN DISJ1_TAC THEN UNDISCH_TAC `~(b = 0)` THEN ARITH_TAC]; ALL_TAC] THEN
    REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND];
    ALL_TAC] THEN
  (* ---- BODY (INV(i+1)@0x217 -> INV(i)@0x371 via BODY_DISPATCH) ---- *)
  CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN STRIP_TAC THEN
    GHOST_INTRO_TAC `Ztv:num` `\s. val(read (memory :> bytes64 (word_add stackpointer (word 8))) s)` THEN
    GHOST_INTRO_TAC `zprev:num` `bignum_from_memory (z,k)` THEN
    GHOST_INTRO_TAC `lfvv:int64` `read R14` THEN
    GHOST_INTRO_TAC `hfvv:int64` `read R15` THEN
    GLOBALIZE_PRECONDITION_TAC THEN
    SUBGOAL_THEN `(61 + 61 * (NB - (i + 1))) + 61 = 61 + 61 * (NB - i) /\
                  (61 + 61 * (NB - (i + 1))) + 124 = 61 + 61 * (NB - i) + 63`
      STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `i < NB` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p < 2 EXP 64` ASSUME_TAC THENL
     [MP_TAC(SPECL [`2 EXP p`; `2 EXP (64 * k) * Ztv + zprev`; `2 EXP 64`] RDIV_LT_EQ) THEN
      REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN DISCH_THEN SUBST1_TAC THEN
      (* V < 2^64 * 2^p from V < b*2^64 <= 2^p*2^64 (b<2^p); avoid MULT_SYM ordering pitfalls. *)
      MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `b * 2 EXP 64` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        REWRITE_TAC[ARITH_RULE `2 EXP 64 * 2 EXP p = 2 EXP p * 2 EXP 64`] THEN
        REWRITE_TAC[LE_MULT_RCANCEL] THEN DISJ1_TAC THEN ASM_SIMP_TAC[LT_IMP_LE]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `2 EXP (64 * k) * Ztv + zprev =
      ((2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p) MOD 2 EXP 64 * 2 EXP p +
      (2 EXP (64 * k) * Ztv + zprev) MOD 2 EXP p` ASSUME_TAC THENL
     [SUBGOAL_THEN `((2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p) MOD 2 EXP 64 =
                    (2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p` SUBST1_TAC THENL
       [ASM_SIMP_TAC[MOD_LT]; ALL_TAC] THEN
      MP_TAC(SPECL [`2 EXP (64 * k) * Ztv + zprev`; `2 EXP p`] DIVISION) THEN
      REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`b:num`;`p:num`;`w:num`;`d:num`;
                   `((2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p) MOD 2 EXP 64`;
                   `(2 EXP (64 * k) * Ztv + zprev) MOD 2 EXP p`;
                   `2 EXP (64 * k) * Ztv + zprev`] RED_LEMMA_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN
      REWRITE_TAC[GSYM QHAT_ID] THEN DISCH_TAC] THEN
    MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                   `p:num`;`i:num`;`w:num`;`d:num`;`Ztv:num`;`zprev:num`;
                   `61 + 61 * (NB - (i + 1))`;`val(lfvv:int64)`;`val(hfvv:int64)`;`stackpointer:int64`]
                  BIGNUM_MOD_X86_BODY_DISPATCH) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[GSYM ADD_ASSOC]) THEN
      REWRITE_TAC[GSYM ADD_ASSOC] THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `n < 2 EXP 58 - 1` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `i < NB` THEN UNDISCH_TAC `(64 * n + 60) DIV 61 - 1 = NB` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `61 * NB + 124 < 2 EXP 64` THEN UNDISCH_TAC `i < NB` THEN
          UNDISCH_TAC `(64 * n + 60) DIV 61 - 1 = NB` THEN ARITH_TAC) THEN
      TRY(MP_TAC(SPECL [`61 + 61 * (NB - (i + 1))`; `64`] DIVISION) THEN ARITH_TAC) THEN
      ARITH_TAC;
      REWRITE_TAC[ASSUME `(61 + 61 * (NB - (i + 1))) + 61 = 61 + 61 * (NB - i)`;
                  ASSUME `(61 + 61 * (NB - (i + 1))) + 124 = 61 + 61 * (NB - i) + 63`;
                  WORD_VAL; SOME_FLAGS] THEN
      DISCH_THEN(fun dth ->
        let ens = concl dth in
        let qd = rand(rator ens) and pd = rand(rator(rator ens)) in
        MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN EXISTS_TAC qd THEN CONJ_TAC THENL
         [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND];
          MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN EXISTS_TAC pd THEN CONJ_TAC THENL
           [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN
            REPEAT CONJ_TAC THEN
            TRY(FIRST_ASSUM ACCEPT_TAC) THEN
            TRY(ASM_REWRITE_TAC[ADD_ASSOC] THEN NO_TAC) THEN
            (* dispatch-PRE `read sp+8 = word Ztv` from the ghost `val(read sp+8) = Ztv`:
               word(val x)=x (WORD_VAL) after substituting the ghost eqn.  Guarded (TRY) so it is a
               no-op on the other PRE conjuncts already closed above. *)
            TRY(FIRST_ASSUM(fun th -> if is_eq(concl th) &&
                (try rand(concl th) = `Ztv:num` with Failure _ -> false)
              then GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [SYM th] else NO_TAC) THEN
             REWRITE_TAC[WORD_VAL]);
            ACCEPT_TAC dth]])];
    ALL_TAC] THEN
  (* ---- BACK-EDGE (test rbx,rbx ; jnz taken, i>0) ---- *)
  CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
    SUBGOAL_THEN `val(word (61 * i):int64) = 61 * i` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      TRANS_TAC LET_TRANS `61 * NB` THEN CONJ_TAC THENL
       [MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LE_REFL; LT_IMP_LE];
        UNDISCH_TAC `61 * NB + 124 < 2 EXP 64` THEN ARITH_TAC];
      ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    ASM_SIMP_TAC[VAL_EQ_0; WORD_EQ_0; DIMINDEX_64; ARITH_RULE `0 < i ==> ~(61 * i = 0)`];
    (* ---- EXIT (i = 0, test rbx,rbx ; jnz NOT taken -> fall through to 0x37a) ---- *)
    REWRITE_TAC[SOME_FLAGS] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; DIV_1; SUB_0] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2)]);;


(* ============================================================================
   x86_negadd1.ml -- the FIRST correction pass (negaddloop1) ported ARM->x86.
   Port of ARM negadd1_{loop,tail}.ml + negadd1.ml (BIGNUM_MOD_NEGADD1).
   x86 span 0x37a -> 0x432 (ground-truth objdump of bignum_mod_tmc):
     PREFIX 0x37a->0x3b6  quotient setup q1=(w*h)DIV2^64+h into RBP/R9=hh, ii=R10=0,
                          pcode=R13=(p+3)DIV64, lf=R14=0, hf=R15=0, p+=3 stored sp+48.
     LOOP   0x3b6->0x3e7  per-word z := z - q*m = z + q*~m + q, carry R9=hh, lf/hf log.
     TAIL   0x3ed->...    top-word fold zt'=Ztv+(hh-q) into sp+8, + field-select h into sp+64.
   Value pin: V1 = 2^(64k)*val(sp+8) + bignum(z,k) = V - q1*b, V = 2^(64k)*Ztv + zk.
   x86 slot/reg map (vs ARM): hh=R9(X5), q1=RBP(X15), pcode=R13(X12), lf=R14(X13), hf=R15(X14),
     z=RSI(X1), m=R8(X4), zt=sp+8(X23), ww=sp+40(X21), pp=sp+48(X20), hs=sp+64(X15win), kk=sp+0(X0).
   Value helpers NEGADD1_ADVANCE/NEGADD_STEP/NEGADD1_TOPFOLD/CONG_BOUND_PIN/TWOPART_BOUND +
   LF_STEP/HF_STEP_G_POS/HF_STEP_G_NEG (all arch-indep, in scaffold Section B).
   Deps: BIGNUM_MOD_EXEC, scaffold Section B.  Load in RELOAD_X86 after the mainloop wrap.
   ============================================================================ *)

(* ===== PREFIX 0x37a -> 0x3b6 (quotient setup) =====
   mul [rsp+0x40](h) by rax=[rsp+0x28]=ww=w -> word(w*h):int128; rbp=hi+h=q1; r9=q1; r10=0;
   r11=pp+3 stored back to sp+48; r13=(p+3)>>6=pcode; r14=r15=0; rdi=kk; test/je NOT taken.
   The mul-high reconciliation: word_zx(word_ushr(word(w*h):int128) 64) = word((w*h)DIV2^64)
   (VAL_WORD_ZX_GEN;VAL_WORD_USHR;VAL_WORD @128;MOD_LT with w*h<2^128,(w*h)DIV2^64<2^64). *)

let BIGNUM_MOD_X86_NEGADD1_PREFIX = prove
 (`!k z m w h p zk b Ztv pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ p + 3 < 2 EXP 64 /\
      w < 2 EXP 64 /\ h < 2 EXP 64 /\ (w * h) DIV 2 EXP 64 + h < 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x3b6) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read R10 s = word 0 /\
            read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
            read R9 s = word ((w * h) DIV 2 EXP 64 + h) /\
            read R13 s = word ((p + 3) DIV 64) /\
            read R14 s = word 0 /\ read R15 s = word 0 /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word w:int64) = w` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `w < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word h:int64) = h` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `h < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--16) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `w * h < 2 EXP 128` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `2 EXP 64 * 2 EXP 64` THEN CONJ_TAC THENL
     [MATCH_MP_TAC LT_MULT2 THEN ASM_REWRITE_TAC[]; REWRITE_TAC[GSYM EXP_ADD] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `word_zx (word_ushr (word (w * h):int128) 64):int64 = word((w*h) DIV 2 EXP 64)`
    SUBST_ALL_TAC THENL
   [REWRITE_TAC[GSYM VAL_EQ] THEN
    REWRITE_TAC[VAL_WORD_ZX_GEN; DIMINDEX_64; VAL_WORD_USHR; VAL_WORD; DIMINDEX_128] THEN
    ASM_SIMP_TAC[MOD_LT] THEN
    SUBGOAL_THEN `(w * h) DIV 2 EXP 64 < 2 EXP 64` (fun th -> SIMP_TAC[th; MOD_LT]) THEN
    SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[WORD_ADD] THEN
  SUBGOAL_THEN `word_add (word p:int64) (word 3) = word (p + 3)` SUBST_ALL_TAC THENL
   [CONV_TAC WORD_RULE; ALL_TAC] THEN
  SUBGOAL_THEN `word_ushr (word (p + 3):int64) 6 = word ((p + 3) DIV 64)` SUBST1_TAC THENL
   [REWRITE_TAC[word_ushr] THEN AP_TERM_TAC THEN
    REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT] THEN
    REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`]; ALL_TAC] THEN
  REWRITE_TAC[] THEN
  CONJ_TAC THEN
  (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zk` ||
                              concl th = `bignum_from_memory (m,k) s0 = b`
     then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
   REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
   FIRST_X_ASSUM(MP_TAC o check (can
     (term_match [] `(f:x86state->x86state->bool) s0 s16`) o concl)) THEN
   REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
   REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
   REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC));;


(* ===== LOOP 0x3b6 -> 0x3ed (negaddloop1 core + lf/hf logging) =====
   ENSURES_WHILE_AUP `0` `k` head=0x3b6 backedge-test=0x3e7.  Per-word z:=z-q*m = z+q*~m+q, carry R9=hh.
   Body 14 instrs (ACCSTEPS [3;5;7;8;9] = mul;add;adc;add;adc); plain rcx store (no funnel).  lf=R14,
   hf=R15 logging via LF_STEP/HF_STEP_G_POS/HF_STEP_G_NEG.  Value eqn at exit:
     bignum(z,k) + 2^(64k)*val(R9) + q*b = zorig + q*2^(64k).
   x86 backedge = `cmp r10,[rsp]`@0x3e7 + `jne 0x3b6`@0x3eb (X86_SIM 1--2); EXIT falls through to 0x3ed
   (NOT 0x3e7 -- the +2-instr fall-through addr).  Port of ARM BIGNUM_MOD_NEGADD1_LOOP_LOG. *)

let BIGNUM_MOD_X86_NEGADD1_LOOP = prove
 (`!k z m q zorig b pcode r12v rbxv zt8 pp48 ww40 pc stackpointer.
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      1 <= k /\ k < 2 EXP 58 /\ q < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zorig < 2 EXP (64 * k) /\ 1 <= pcode /\ pcode < 2 EXP 64
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x3b6) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww40 /\
            read R10 s = word 0 /\ read RBP s = word q /\ read R9 s = word q /\
            read R13 s = word pcode /\ read R14 s = word 0 /\ read R15 s = word 0 /\
            read RBX s = rbxv /\ read R12 s = r12v /\
            bignum_from_memory (z,k) s = zorig /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x3ed) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww40 /\
            read R10 s = word k /\ read RBP s = word q /\ read R13 s = word pcode /\
            read RBX s = rbxv /\ read R12 s = r12v /\
            (1 <= k ==> read R14 s =
                read (memory :> bytes64 (word_add z (word (8 * (MIN k pcode - 1))))) s) /\
            (pcode < k ==> read R15 s =
                read (memory :> bytes64 (word_add z (word (8 * pcode)))) s) /\
            (~(pcode < k) ==> read R15 s = word 0) /\
            bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read R9 s) + q * b =
              zorig + q * 2 EXP (64 * k))
       (MAYCHANGE [RIP; RAX; RCX; RDX; R9; R10; R14; R15] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_WHILE_AUP_TAC `0` `k:num` `pc + 0x3b6` `pc + 0x3e7`
   `\i s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
          read RBP s = word q /\ read R13 s = word pcode /\
          read (memory :> bytes64 stackpointer) s = word k /\
          read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
          read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
          read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww40 /\
          read R10 s = word i /\ read RBX s = rbxv /\ read R12 s = r12v /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (word_add z (word (8 * i)), k - i) s = highdigits zorig i /\
          (1 <= i ==> read R14 s =
             read (memory :> bytes64 (word_add z (word (8 * (MIN i pcode - 1))))) s) /\
          (pcode < i ==> read R15 s =
             read (memory :> bytes64 (word_add z (word (8 * pcode)))) s) /\
          (~(pcode < i) ==> read R15 s = word 0) /\
          bignum_from_memory (z,i) s + 2 EXP (64 * i) * val(read R9 s) +
            q * lowdigits b i = lowdigits zorig i + q * 2 EXP (64 * i)` THEN
  CONJ_TAC THENL [UNDISCH_TAC `1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0; WORD_ADD_0; ARITH_RULE `8 * 0 = 0`;
               ARITH_RULE `(1 <= 0) <=> F`; ARITH_RULE `(pcode < 0) <=> F`] THEN
    ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; HIGHDIGITS_0; LOWDIGITS_0] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; ADD_CLAUSES; DIV_1] THEN
    MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN VAL_INT64_TAC `pcode:num` THEN
    GHOST_INTRO_TAC `hhin:int64` `read R9` THEN
    GHOST_INTRO_TAC `lfval:int64` `read R14` THEN
    GHOST_INTRO_TAC `hfval:int64` `read R15` THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
    ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
    REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i + 1)`; BIGNUM_FROM_MEMORY_STEP] THEN
    ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * i)))) s0 = word (bigdigit b i)`
      ASSUME_TAC THENL
     [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
      ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * i)))) s0 = word (bigdigit zorig i)`
      ASSUME_TAC THENL
     [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
      GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [3;5;7;8;9] (1--14) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `i < 2 EXP 64` ASSUME_TAC THENL
     [UNDISCH_TAC `i:num < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(val(word_sub (word i:int64) (word pcode)) = 0) <=> i = pcode` ASSUME_TAC THENL
     [MATCH_MP_TAC test_bridge THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [CONV_TAC WORD_RULE;
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s14`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      REWRITE_TAC[ARITH_RULE `k <= i + 1 <=> k - (i + 1) = 0`;
                  ARITH_RULE `k - ((i + 1) + 1) = k - (i + 1) - 1`] THEN
      GEN_REWRITE_TAC I [GSYM BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0 = highdigits zorig (i+1)` MP_TAC THENL
       [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
        GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
        ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
        REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i+1)`] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s14 =
        bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0`
       (fun th -> ASM_REWRITE_TAC[th]) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s14`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      MATCH_MP_TAC(BETA_RULE(ISPECL
        [`\j. read (memory :> bytes64 (word_add z (word (8 * j)))) s14`;
         `sum_s8:int64`; `lfval:int64`; `i:num`; `pcode:num`] LF_STEP)) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(BETA_RULE(ISPECL
        [`\j. read (memory :> bytes64 (word_add z (word (8 * j)))) s14`;
         `sum_s8:int64`; `hfval:int64`; `i:num`; `pcode:num`] HF_STEP_G_POS)) THEN
      ASM_REWRITE_TAC[NOT_LT];
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(BETA_RULE(ISPECL
        [`\j. read (memory :> bytes64 (word_add z (word (8 * j)))) s14`;
         `sum_s8:int64`; `hfval:int64`; `i:num`; `pcode:num`] HF_STEP_G_NEG)) THEN
      ASM_REWRITE_TAC[NOT_LT];
      SUBGOAL_THEN `bignum_from_memory (z,i) s14 = bignum_from_memory (z,i) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s14`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `val(word_not(word(bigdigit b i)):int64) = 2 EXP 64 - 1 - bigdigit b i` ASSUME_TAC THENL
       [REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN
        SUBGOAL_THEN `val(word(bigdigit b i):int64) = bigdigit b i` SUBST1_TAC THENL
         [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; REFL_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `val(word q:int64) = q /\ val(word (bigdigit zorig i):int64) = bigdigit zorig i`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND] THEN
        UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `2 EXP 64 * (bitval carry_s7 + bitval carry_s9) + val(sum_s9:int64) =
        bitval carry_s5 + val(mulhi_s3:int64) + bitval carry_s8` ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun h26 -> FIRST_X_ASSUM(fun h24 ->
          if free_in `sum_s7:int64` (concl h24) && free_in `sum_s9:int64` (concl h26) &&
             free_in `carry_s9:bool` (concl h26)
          then MP_TAC h24 THEN MP_TAC h26 else failwith "nope")) THEN
        REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `bitval carry_s7 + bitval carry_s9 <= 1` ASSUME_TAC THENL
       [MP_TAC(SPEC `i:num`(SPEC `b:num` BIGDIGIT_BOUND)) THEN
        MP_TAC(ISPEC `mulhi_s3:int64` VAL_BOUND_64) THEN REWRITE_TAC[DIMINDEX_64] THEN
        UNDISCH_TAC `2 EXP 64 * (bitval carry_s7 + bitval carry_s9) + val(sum_s9:int64) =
          bitval carry_s5 + val(mulhi_s3:int64) + bitval carry_s8` THEN
        MP_TAC(ISPEC `carry_s5:bool` BITVAL_BOUND) THEN MP_TAC(ISPEC `carry_s8:bool` BITVAL_BOUND) THEN
        ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `2 EXP 64 * val(sum_s9:int64) + val(sum_s8:int64) =
        bigdigit zorig i + val(hhin:int64) + q * (2 EXP 64 - 1 - bigdigit b i)` ASSUME_TAC THENL
       [MP_TAC(ISPECL
         [`bigdigit zorig i`; `val(hhin:int64)`; `q:num`; `2 EXP 64 - 1 - bigdigit b i`;
          `val(sum_s5:int64)`; `val(sum_s8:int64)`; `val(sum_s9:int64)`;
          `val(mullo_s3:int64)`; `val(mulhi_s3:int64)`;
          `bitval carry_s5`; `bitval carry_s8`; `bitval carry_s7 + bitval carry_s9`] NEGADD_STEP) THEN
        ASM_REWRITE_TAC[BITVAL_BOUND; VAL_BOUND_64; BIGDIGIT_BOUND;
                        ARITH_RULE `2 EXP 64 - 1 - x < 2 EXP 64`] THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
          ASM_REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN
          FIRST_X_ASSUM(fun th -> MP_TAC th THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
            CONV_TAC REAL_RING) ORELSE ALL_TAC;
          DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
      MP_TAC(ISPECL
        [`q:num`; `bignum_from_memory (z,i) s0`; `lowdigits zorig i`; `lowdigits b i`;
         `val(hhin:int64)`; `val(sum_s9:int64)`; `val(sum_s8:int64)`;
         `bigdigit zorig i`; `bigdigit b i`; `i:num`] NEGADD1_ADVANCE) THEN
      ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN
      REWRITE_TAC[LOWDIGITS_CLAUSES] THEN CONV_TAC NUM_RING]; ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** BACKEDGE (cmp r10,[rsp] ; jne taken, i<k) ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    ASM_SIMP_TAC[ARITH_RULE `i < k ==> ~(i = k)`] THEN
    DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    UNDISCH_TAC `i <= pcode` THEN ARITH_TAC;
    (*** EXIT (i=k, jne not taken -> fall through to 0x3ed) ***)
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    SUBGOAL_THEN `lowdigits b k = b` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits zorig k = zorig` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `1 <= k ==> read R14 s2 =
         read (memory :> bytes64 (word_add z (word (8 * (MIN k pcode - 1))))) s2`
       then MATCH_MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      UNDISCH_TAC `k <= pcode` THEN ARITH_TAC]]);;


(* ANDMASK63 -- x86 `and rcx,0x3f` mask fold: word_and (word v)(word 63) = word(v MOD 64). *)
let ANDMASK63 = prove
 (`!v. word_and (word v:int64) (word 63) = word (v MOD 64)`,
  GEN_TAC THEN
  SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
  AP_TERM_TAC THEN REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN
  ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD]);;


(* ===== TAIL 0x3ed -> 0x432 (negaddtail1 top-word fold + field-select) =====
   17 straight-line instrs: sub r9,rbp[hh-=q]; mov rcx,zt(sp8); add rcx,r9; mov zt,rcx[zt'=Ztv+(hh-q)];
   cmp r10,r13; cmovb r14,rcx; cmove r15,rcx [ii=k top-word log]; then field-select
   mov rcx,pp(sp48); and rcx,63; mov r11,rcx; mov rax,r14(lf); shr rax,cl; mov rdx,r15(hf); neg rcx;
   shl rdx,cl; or rdx,rax; test r11,r11; cmove rdx,rax; mov hs(sp64),rdx[field-h into sp+64].
   Ends at 0x432 (before NEGADD2 q-recompute).  Field-select closed via ANDMASK63 (mask fold p+3) +
   DDK_HS_CLOSE[p:=p+3] (the x86 funnel = word((2^64*val hi + val lo) DIV 2^((p+3)MOD64) MOD 2^64)) +
   ZF-bridge k=(p+3)DIV64.  Port of ARM BIGNUM_MOD_NEGADD1_TAIL.  Deps: DDK_HS_CLOSE (x86_tail_ddk). *)

let BIGNUM_MOD_X86_NEGADD1_TAIL = prove
 (`!k z m p q hh Ztv lf hf ww zk b pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ p + 3 < 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x3ed) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww /\
            read RBP s = word q /\ read R9 s = hh /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = Ztv /\
            read R10 s = word k /\ read R13 s = word ((p + 3) DIV 64) /\
            read R14 s = lf /\ read R15 s = hf /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x432) /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s =
              word_add Ztv (word_sub hh (word q)) /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((2 EXP 64 *
                     val(if k = (p + 3) DIV 64
                         then word_add Ztv (word_sub hh (word q)) else hf) +
                     val(if k < (p + 3) DIV 64
                         then word_add Ztv (word_sub hh (word q)) else lf))
                    DIV 2 EXP ((p + 3) MOD 64) MOD 2 EXP 64) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; R9; R11; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `val(word ((p + 3) DIV 64):int64) = (p + 3) DIV 64` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `p + 3 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--19) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (* WORD_SUB: robust close via WORD_EQ_IMP (the old ASM_SIMP[WORD_EQ;CONG;MOD_LT] leaves a
     `k MOD 2^64 = ...` residual on this checkpoint since MOD_LT can't derive k<2^64 from k<2^58). *)
  SUBGOAL_THEN `(val(word_sub (word k:int64) (word ((p + 3) DIV 64))) = 0) <=> k = (p + 3) DIV 64`
    ASSUME_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN
    MATCH_MP_TAC WORD_EQ_IMP THEN REWRITE_TAC[DIMINDEX_64] THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC;
      TRANS_TAC LET_TRANS `p + 3` THEN REWRITE_TAC[DIV_LE] THEN
      UNDISCH_TAC `p + 3 < 2 EXP 64` THEN ARITH_TAC]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ANDMASK63] THEN
  (* DDK_HS_CLOSE is now UNCONDITIONAL (forall H L p. funnel = word(...)); fold the funnel to
     word(...) directly (the old MP_TAC..ANTS_TAC..DISCH structure assumed a conditional DDK). *)
  REWRITE_TAC[DDK_HS_CLOSE] THEN
  CONJ_TAC THEN
  (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zk` ||
                              concl th = `bignum_from_memory (m,k) s0 = b`
     then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
   REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
   FIRST_X_ASSUM(MP_TAC o check (can
     (term_match [] `(f:x86state->x86state->bool) s0 s19`) o concl)) THEN
   REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
   REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
   REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC));;


(* ===== COMPOSE: BIGNUM_MOD_X86_NEGADD1 (0x37a -> 0x432, VALUE-LEVEL) =====
   PREFIX(0x37a->0x3b6) ;; LOOP(0x3b6->0x3ed) ;; TAIL(0x3ed->0x432), value pin
   V1 := 2^(64k)*val(sp+8) + bignum(z,k) = V - q1*b, V = 2^(64k)*Ztv + zk, q1=(w*h)DIV2^64+h.
   Pinned exact via NEGADD1_TOPFOLD + CONG_BOUND_PIN + TWOPART_BOUND (field-h in POST DEFERRED, like ARM).
   Each leg via ENSURES_SEQUENCE + MP_TAC(REWRITE_RULE[SOME_FLAGS] sublemma) THEN ANTS_TAC[..;ALL_TAC] THEN
   MATCH_MP_TAC ENSURES_SUBLEMMA_THM (the ANTS-then-MATCH order is essential -- ASM_REWRITE'ing the
   sublemma antecedent to nothing breaks the `ens'==>ens` shape MATCH_MP_TAC needs). RBX/R12 dead here so
   GHOST_INTRO'd (rbxv/r12v); sp+48 threaded through LOOP via its pp48 spectator.  q1 EXPLICIT (no ABBREV).
   Deps: BIGNUM_MOD_X86_NEGADD1_{PREFIX,LOOP,TAIL}, NEGADD1_TOPFOLD, CONG_BOUND_PIN, TWOPART_BOUND,
         ENSURES_SEQUENCE_TAC/ENSURES_SUBLEMMA_THM (base). *)

let BIGNUM_MOD_X86_NEGADD1 = prove
 (`!k z m w h p b Ztv zk pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 61 <= p /\ p + 3 < 2 EXP 64 /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\
      w < 2 EXP 64 /\ h < 2 EXP 64 /\ (w * h) DIV 2 EXP 64 + h < 2 EXP 64 /\
      ((w * h) DIV 2 EXP 64 + h) * b <= 2 EXP (64 * k) * Ztv + zk /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. read RIP s = word (pc + 0x432) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s =
              (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x3b6`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read R10 s = word 0 /\
        read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R9 s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R13 s = word ((p + 3) DIV 64) /\
        read R14 s = word 0 /\ read R15 s = word 0 /\
        bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL [`k:num`; `z:int64`; `m:int64`; `w:num`; `h:num`; `p:num`; `zk:num`;
                  `b:num`; `Ztv:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_PREFIX)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  GHOST_INTRO_TAC `rbxv:int64` `read RBX` THEN
  GHOST_INTRO_TAC `r12v:int64` `read R12` THEN
  ENSURES_SEQUENCE_TAC `pc + 0x3ed`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
        read R10 s = word k /\ read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R13 s = word ((p + 3) DIV 64) /\ read RBX s = rbxv /\ read R12 s = r12v /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        (1 <= k ==> read R14 s =
            read (memory :> bytes64 (word_add z (word (8 * (MIN k ((p + 3) DIV 64) - 1))))) s) /\
        (((p + 3) DIV 64) < k ==> read R15 s =
            read (memory :> bytes64 (word_add z (word (8 * ((p + 3) DIV 64))))) s) /\
        (~(((p + 3) DIV 64) < k) ==> read R15 s = word 0) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read R9 s) +
          ((w * h) DIV 2 EXP 64 + h) * b = zk + ((w * h) DIV 2 EXP 64 + h) * 2 EXP (64 * k)` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `(w * h) DIV 2 EXP 64 + h`; `zk:num`; `b:num`;
       `(p + 3) DIV 64`; `r12v:int64`; `rbxv:int64`; `word Ztv:int64`; `word (p + 3):int64`;
       `word w:int64`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_LOOP)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `1 <= (p + 3) DIV 64` ASSUME_TAC THENL
       [SIMP_TAC[LE_RDIV_EQ; ARITH_EQ] THEN UNDISCH_TAC `61 <= p` THEN ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `(p + 3) DIV 64 < 2 EXP 64` ASSUME_TAC THENL
       [TRANS_TAC LET_TRANS `p + 3` THEN ASM_REWRITE_TAC[] THEN
        MP_TAC(SPECL [`p + 3`; `64`] DIV_LE) THEN ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  GHOST_INTRO_TAC `hh:int64` `read R9` THEN
  GHOST_INTRO_TAC `lf:int64` `read R14` THEN
  GHOST_INTRO_TAC `hf:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
    [`k:num`; `z:int64`; `m:int64`; `p:num`; `(w * h) DIV 2 EXP 64 + h`; `hh:int64`;
     `word Ztv:int64`; `lf:int64`; `hf:int64`; `word w:int64`; `zc:num`; `b:num`; `pc:num`; `stackpointer:int64`]
    BIGNUM_MOD_X86_NEGADD1_TAIL)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  (* value pin: V1 = V - q1*b via NEGADD1_TOPFOLD + CONG_BOUND_PIN + TWOPART_BOUND *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc`
      then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word Ztv:int64) = Ztv` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  MP_TAC(SPECL [`word Ztv:int64`; `hh:int64`; `(w * h) DIV 2 EXP 64 + h`;
                `zc:num`; `zk:num`; `b:num`; `k:num`] NEGADD1_TOPFOLD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC CONG_BOUND_PIN THEN
  EXISTS_TAC `2 EXP (64 * (k + 1))` THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[VAL_BOUND_64];
    MATCH_MP_TAC(ARITH_RULE `V < K ==> V - qb < K`) THEN
    MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[]]);;


(* ===== BIGNUM_MOD_X86_NEGADD1_LOG (0x37a -> 0x432, value + FIELD-H) =====
   Same as BIGNUM_MOD_X86_NEGADD1 but the POST additionally exposes the negaddtail1 field-select
   output in sp+64:  read sp+64 = word((V1 DIV 2^(p-61)) MOD 2^64)  [V1 = V - q1*b, V = 2^(64k)*Ztv+zk].
   This h2 is the SECOND-PASS quotient-digit window that NEGADD2 consumes.  Port of ARM
   BIGNUM_MOD_NEGADD1_LOG.  Same PREFIX;;LOOP;;TAIL compose; the TAIL leg's POST-derive now has TWO
   conjuncts (field-h /\ value); value closes by the V1 pin (NEGADD1_TOPFOLD/CONG_BOUND_PIN/
   TWOPART_BOUND), field-h by LOGGED_FIELD_RECONCILE (scaffold) after substituting the V1 pin into the
   window RHS.  The LOOP's logged lf/hf (R14/R15 = z[pcode-1]/z[pcode]) feed RECONCILE's
   val hf=bigdigit zc pcode / val lf=bigdigit zc (pcode-1) side conditions (via BIGDIGIT_BIGNUM_FROM_MEMORY
   + VAL_WORD_BIGDIGIT).  Extra precond over NEGADD1: p <= 64*k (=> pcode=(p+3)DIV64 <= k, field windows
   in range; at the CORRECT splice p=bitsize b <= 64k).  Deps: BIGNUM_MOD_X86_NEGADD1_{PREFIX,LOOP,TAIL},
   NEGADD1_TOPFOLD/CONG_BOUND_PIN/TWOPART_BOUND, LOGGED_FIELD_RECONCILE (scaffold), BIGDIGIT_BIGNUM_FROM_MEMORY,
   VAL_WORD_BIGDIGIT, LE_LDIV_EQ.  KEY: `lhs` is shadowed in the session -> use `lhand(concl th)` in the
   find-based V-q1*b subterm rewrite. *)

let BIGNUM_MOD_X86_NEGADD1_LOG = prove
 (`!k z m w h p b Ztv zk pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 61 <= p /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\
      w < 2 EXP 64 /\ h < 2 EXP 64 /\ (w * h) DIV 2 EXP 64 + h < 2 EXP 64 /\
      ((w * h) DIV 2 EXP 64 + h) * b <= 2 EXP (64 * k) * Ztv + zk /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x432) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((((2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b)
                     DIV 2 EXP (p - 61)) MOD 2 EXP 64) /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s =
              (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x3b6`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read R10 s = word 0 /\
        read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R9 s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R13 s = word ((p + 3) DIV 64) /\
        read R14 s = word 0 /\ read R15 s = word 0 /\
        bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL [`k:num`; `z:int64`; `m:int64`; `w:num`; `h:num`; `p:num`; `zk:num`;
                  `b:num`; `Ztv:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_PREFIX)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  GHOST_INTRO_TAC `rbxv:int64` `read RBX` THEN
  GHOST_INTRO_TAC `r12v:int64` `read R12` THEN
  ENSURES_SEQUENCE_TAC `pc + 0x3ed`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
        read R10 s = word k /\ read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R13 s = word ((p + 3) DIV 64) /\ read RBX s = rbxv /\ read R12 s = r12v /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        (1 <= k ==> read R14 s =
            read (memory :> bytes64 (word_add z (word (8 * (MIN k ((p + 3) DIV 64) - 1))))) s) /\
        (((p + 3) DIV 64) < k ==> read R15 s =
            read (memory :> bytes64 (word_add z (word (8 * ((p + 3) DIV 64))))) s) /\
        (~(((p + 3) DIV 64) < k) ==> read R15 s = word 0) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read R9 s) +
          ((w * h) DIV 2 EXP 64 + h) * b = zk + ((w * h) DIV 2 EXP 64 + h) * 2 EXP (64 * k)` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `(w * h) DIV 2 EXP 64 + h`; `zk:num`; `b:num`;
       `(p + 3) DIV 64`; `r12v:int64`; `rbxv:int64`; `word Ztv:int64`; `word (p + 3):int64`;
       `word w:int64`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_LOOP)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `1 <= (p + 3) DIV 64` ASSUME_TAC THENL
       [SIMP_TAC[LE_RDIV_EQ; ARITH_EQ] THEN UNDISCH_TAC `61 <= p` THEN ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `(p + 3) DIV 64 < 2 EXP 64` ASSUME_TAC THENL
       [TRANS_TAC LET_TRANS `p + 3` THEN ASM_REWRITE_TAC[] THEN
        MP_TAC(SPECL [`p + 3`; `64`] DIV_LE) THEN ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  GHOST_INTRO_TAC `hh:int64` `read R9` THEN
  GHOST_INTRO_TAC `lf:int64` `read R14` THEN
  GHOST_INTRO_TAC `hf:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
    [`k:num`; `z:int64`; `m:int64`; `p:num`; `(w * h) DIV 2 EXP 64 + h`; `hh:int64`;
     `word Ztv:int64`; `lf:int64`; `hf:int64`; `word w:int64`; `zc:num`; `b:num`; `pc:num`; `stackpointer:int64`]
    BIGNUM_MOD_X86_NEGADD1_TAIL)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc`
      then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word Ztv:int64) = Ztv` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN
   `2 EXP (64 * k) *
      val(word_add (word Ztv) (word_sub hh (word ((w * h) DIV 2 EXP 64 + h))):int64) + zc =
    (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b`
   ASSUME_TAC THENL
   [MP_TAC(SPECL [`word Ztv:int64`; `hh:int64`; `(w * h) DIV 2 EXP 64 + h`;
                  `zc:num`; `zk:num`; `b:num`; `k:num`] NEGADD1_TOPFOLD) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC CONG_BOUND_PIN THEN EXISTS_TAC `2 EXP (64 * (k + 1))` THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[VAL_BOUND_64];
      MATCH_MP_TAC(ARITH_RULE `V < K ==> V - qb < K`) THEN
      MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC] THEN
  (* field-h = window of V1: strip word, substitute V1 pin into RHS, apply LOGGED_FIELD_RECONCILE *)
  AP_TERM_TAC THEN
  FIRST_X_ASSUM(fun th ->
    if is_eq(concl th) &&
       (let l = lhand(concl th) in
        is_comb l && (try fst(dest_const(fst(strip_comb l))) = "+" with _ -> false))
    then GEN_REWRITE_TAC (RAND_CONV o LAND_CONV o LAND_CONV) [SYM th]
    else NO_TAC) THEN
  GEN_REWRITE_TAC (RAND_CONV o LAND_CONV o LAND_CONV) [ADD_SYM] THEN
  MATCH_MP_TAC LOGGED_FIELD_RECONCILE THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[VAL_BOUND_64];
    UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC;
    DISCH_TAC THEN
    FIRST_X_ASSUM(fun th -> if concl th =
       `(p + 3) DIV 64 < k
        ==> hf = read (memory :> bytes64 (word_add z (word (8 * (p + 3) DIV 64)))) s`
       then MP_TAC th else NO_TAC) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL [`k:num`; `z:int64`; `s:x86state`; `(p + 3) DIV 64`]
      BIGDIGIT_BIGNUM_FROM_MEMORY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[VAL_WORD_BIGDIGIT];
    SUBGOAL_THEN `(p + 3) DIV 64 <= k` ASSUME_TAC THENL
     [SIMP_TAC[LE_LDIV_EQ; ARITH_EQ] THEN UNDISCH_TAC `p <= 64 * k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM(fun th -> if concl th =
       `1 <= k ==> lf = read (memory :> bytes64 (word_add z (word (8 * (MIN k ((p + 3) DIV 64) - 1))))) s`
       then MP_TAC th else NO_TAC) THEN
    ANTS_TAC THENL [UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `MIN k ((p + 3) DIV 64) = (p + 3) DIV 64` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `MIN k n = n <=> n <= k`]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL [`k:num`; `z:int64`; `s:x86state`; `(p + 3) DIV 64 - 1`]
      BIGDIGIT_BIGNUM_FROM_MEMORY) THEN
    SUBGOAL_THEN `(p + 3) DIV 64 - 1 < k` ASSUME_TAC THENL
     [UNDISCH_TAC `(p + 3) DIV 64 <= k` THEN UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[VAL_WORD_BIGDIGIT]]);;


(* ============================================================================
   x86_negadd1_loop_small.ml -- BIGNUM_MOD_X86_NEGADD1_LOOP_LOG_SMALL.
   The pcode=0 (p<61 single-word modulus) variant of BIGNUM_MOD_X86_NEGADD1_LOOP.
   x86 analog of ARM BIGNUM_MOD_NEGADD1_LOOP_LOG_SMALL (negadd1_loop_small.ml).

   For p<61, pcode = (p+3) DIV 64 = 0, so the negaddloop1 field logging degenerates:
     lf (R14): cmovb r14,rcx logs when i<pcode=0 -> NEVER -> R14 stays word 0.
     hf (R15): cmove r15,rcx logs when i=pcode=0 -> at i=0 -> R15 := z'[0] (stored low word).
   POST: R14 = word 0, R15 = read(mem z[0]) (= final low word of z).  Value equation identical
   to the plain loop.  Feeds the p-general NEGADD1_TAIL field-select, which at pcode=0 computes
   (2^64*hf + lf) DIV 2^((p+3)MOD64) MOD 2^64 = z[0]*2^(61-p) MOD 2^64 (FUNNEL_SMALL) = the p<61
   second-pass window.

   Same code + ACCSTEPS as BIGNUM_MOD_X86_NEGADD1_LOOP (x86_negadd1.ml:113): ENSURES_WHILE_AUP
   0x3b6->0x3e7, X86_ACCSTEPS [3;5;7;8;9] (1--14), NEGADD_STEP + NEGADD1_ADVANCE per word.  The
   invariant carries the degenerate logging clauses (R14=word 0 always; R15=z[0] for i>=1, word 0
   for i=0) instead of the general MIN/pcode clauses.
   Deps: NEGADD_STEP + NEGADD1_ADVANCE (scaffold), test_bridge (x86_innerloop_log_candidate).
   ============================================================================ *)

let BIGNUM_MOD_X86_NEGADD1_LOOP_LOG_SMALL = prove
 (`!k z m q zorig b r12v rbxv zt8 pp48 ww40 pc stackpointer.
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      1 <= k /\ k < 2 EXP 58 /\ q < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zorig < 2 EXP (64 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x3b6) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww40 /\
            read R10 s = word 0 /\ read RBP s = word q /\ read R9 s = word q /\
            read R13 s = word 0 /\ read R14 s = word 0 /\ read R15 s = word 0 /\
            read RBX s = rbxv /\ read R12 s = r12v /\
            bignum_from_memory (z,k) s = zorig /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x3ed) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww40 /\
            read R10 s = word k /\ read RBP s = word q /\ read R13 s = word 0 /\
            read RBX s = rbxv /\ read R12 s = r12v /\
            read R14 s = word 0 /\
            read R15 s = read (memory :> bytes64 (word_add z (word 0))) s /\
            bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read R9 s) + q * b =
              zorig + q * 2 EXP (64 * k))
       (MAYCHANGE [RIP; RAX; RCX; RDX; R9; R10; R14; R15] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_WHILE_AUP_TAC `0` `k:num` `pc + 0x3b6` `pc + 0x3e7`
   `\i s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
          read RBP s = word q /\ read R13 s = word 0 /\
          read (memory :> bytes64 stackpointer) s = word k /\
          read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
          read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
          read (memory :> bytes64 (word_add stackpointer (word 40))) s = ww40 /\
          read R10 s = word i /\ read RBX s = rbxv /\ read R12 s = r12v /\
          read R14 s = word 0 /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (word_add z (word (8 * i)), k - i) s = highdigits zorig i /\
          (1 <= i ==> read R15 s = read (memory :> bytes64 (word_add z (word 0))) s) /\
          (i = 0 ==> read R15 s = word 0) /\
          bignum_from_memory (z,i) s + 2 EXP (64 * i) * val(read R9 s) +
            q * lowdigits b i = lowdigits zorig i + q * 2 EXP (64 * i)` THEN
  REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `1 <= k` THEN ARITH_TAC;
    (* ===== ENTRY (i=0) ===== *)
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0; WORD_ADD_0;
                ARITH_RULE `(1 <= 0) <=> F`] THEN
    ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; HIGHDIGITS_0; LOWDIGITS_0] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; ADD_CLAUSES; DIV_1] THEN
    MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC;
    (* ===== BODY (i -> i+1) ===== *)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    GHOST_INTRO_TAC `hhin:int64` `read R9` THEN
    GHOST_INTRO_TAC `hfval:int64` `read R15` THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
    ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
    REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i + 1)`; BIGNUM_FROM_MEMORY_STEP] THEN
    ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * i)))) s0 = word (bigdigit b i)`
      ASSUME_TAC THENL
     [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
      ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * i)))) s0 = word (bigdigit zorig i)`
      ASSUME_TAC THENL
     [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
      GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [3;5;7;8;9] (1--14) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `i < 2 EXP 64` ASSUME_TAC THENL
     [UNDISCH_TAC `i:num < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    (* the i=pcode=0 comparison: val(word_sub (word i)(word 0))=0 <=> i=0 *)
    SUBGOAL_THEN `(val(word_sub (word i:int64) (word 0)) = 0) <=> i = 0` ASSUME_TAC THENL
     [MATCH_MP_TAC test_bridge THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    (* R14 clause: read R14 = (if i<0 then .. else word 0); i<0 is F for num, so it collapses to
       word 0 = word 0 and the conjunct disappears (leaving 6 conjuncts, matching the branches below). *)
    REWRITE_TAC[ARITH_RULE `~(i < 0)`] THEN
    REWRITE_TAC[LOWDIGITS_CLAUSES] THEN REPEAT CONJ_TAC THENL
     [(* R10 = word(i+1) *) CONV_TAC WORD_RULE;
      (* m preserved *)
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s14`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* z suffix -> highdigits (i+1) *)
      REWRITE_TAC[ARITH_RULE `k <= i + 1 <=> k - (i + 1) = 0`;
                  ARITH_RULE `k - ((i + 1) + 1) = k - (i + 1) - 1`] THEN
      GEN_REWRITE_TAC I [GSYM BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0 = highdigits zorig (i+1)` MP_TAC THENL
       [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
        GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
        ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
        REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i+1)`] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s14 =
        bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0`
       (fun th -> ASM_REWRITE_TAC[th]) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s14`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* R15 clause (1<=i+1 ==> (if i=0 then sum_s8 else hfval) = read(mem z) s14): case i=0 (cmove
         fires, R15=sum_s8=z'[0]) vs i>=1 (cmove i=0 false, R15=hfval; IH gives hfval=read(mem z[0]) s14
         with s14 the SAME state, so WORD_ADD_0 fold `word_add z (word 0)=z` closes -- no s14->s0). *)
      DISCH_THEN(K ALL_TAC) THEN
      ASM_CASES_TAC `i = 0` THENL
       [ASM_REWRITE_TAC[MULT_CLAUSES; WORD_ADD_0] THEN
        UNDISCH_TAC `read (memory :> bytes64 (word_add z (word (8 * i)))) s14 = sum_s8` THEN
        ASM_REWRITE_TAC[MULT_CLAUSES; WORD_ADD_0] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC;
        ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `~(i < 1)` ASSUME_TAC THENL [UNDISCH_TAC `~(i = 0)` THEN ARITH_TAC; ALL_TAC] THEN
        FIRST_X_ASSUM(fun th -> if is_imp(concl th) && fst(dest_imp(concl th)) = `~(i < 1)`
          then MP_TAC(MP th (ASSUME `~(i < 1)`)) else NO_TAC) THEN
        REWRITE_TAC[WORD_ADD_0]];
      (* vacuous i+1=0 clause *)
      ASM_REWRITE_TAC[ARITH_RULE `~(i + 1 = 0)`];
      (* value equation *)
      SUBGOAL_THEN `bignum_from_memory (z,i) s14 = bignum_from_memory (z,i) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s14`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `val(word_not(word(bigdigit b i)):int64) = 2 EXP 64 - 1 - bigdigit b i` ASSUME_TAC THENL
       [REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN
        SUBGOAL_THEN `val(word(bigdigit b i):int64) = bigdigit b i` SUBST1_TAC THENL
         [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND]; REFL_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `val(word q:int64) = q /\ val(word (bigdigit zorig i):int64) = bigdigit zorig i`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND] THEN
        UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `2 EXP 64 * (bitval carry_s7 + bitval carry_s9) + val(sum_s9:int64) =
        bitval carry_s5 + val(mulhi_s3:int64) + bitval carry_s8` ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun h26 -> FIRST_X_ASSUM(fun h24 ->
          if free_in `sum_s7:int64` (concl h24) && free_in `sum_s9:int64` (concl h26) &&
             free_in `carry_s9:bool` (concl h26)
          then MP_TAC h24 THEN MP_TAC h26 else failwith "nope")) THEN
        REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `bitval carry_s7 + bitval carry_s9 <= 1` ASSUME_TAC THENL
       [MP_TAC(SPEC `i:num`(SPEC `b:num` BIGDIGIT_BOUND)) THEN
        MP_TAC(ISPEC `mulhi_s3:int64` VAL_BOUND_64) THEN REWRITE_TAC[DIMINDEX_64] THEN
        UNDISCH_TAC `2 EXP 64 * (bitval carry_s7 + bitval carry_s9) + val(sum_s9:int64) =
          bitval carry_s5 + val(mulhi_s3:int64) + bitval carry_s8` THEN
        MP_TAC(ISPEC `carry_s5:bool` BITVAL_BOUND) THEN MP_TAC(ISPEC `carry_s8:bool` BITVAL_BOUND) THEN
        ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `2 EXP 64 * val(sum_s9:int64) + val(sum_s8:int64) =
        bigdigit zorig i + val(hhin:int64) + q * (2 EXP 64 - 1 - bigdigit b i)` ASSUME_TAC THENL
       [MP_TAC(ISPECL
         [`bigdigit zorig i`; `val(hhin:int64)`; `q:num`; `2 EXP 64 - 1 - bigdigit b i`;
          `val(sum_s5:int64)`; `val(sum_s8:int64)`; `val(sum_s9:int64)`;
          `val(mullo_s3:int64)`; `val(mulhi_s3:int64)`;
          `bitval carry_s5`; `bitval carry_s8`; `bitval carry_s7 + bitval carry_s9`] NEGADD_STEP) THEN
        ASM_REWRITE_TAC[BITVAL_BOUND; VAL_BOUND_64; BIGDIGIT_BOUND;
                        ARITH_RULE `2 EXP 64 - 1 - x < 2 EXP 64`] THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
          ASM_REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN
          FIRST_X_ASSUM(fun th -> MP_TAC th THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
            CONV_TAC REAL_RING) ORELSE ALL_TAC;
          DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
      MP_TAC(ISPECL
        [`q:num`; `bignum_from_memory (z,i) s0`; `lowdigits zorig i`; `lowdigits b i`;
         `val(hhin:int64)`; `val(sum_s9:int64)`; `val(sum_s8:int64)`;
         `bigdigit zorig i`; `bigdigit b i`; `i:num`] NEGADD1_ADVANCE) THEN
      ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN
      REWRITE_TAC[LOWDIGITS_CLAUSES] THEN CONV_TAC NUM_RING];
    (* ===== BACKEDGE (cmp r10,[rsp] ; jne taken, i<k) ===== *)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    ASM_SIMP_TAC[ARITH_RULE `i < k ==> ~(i = k)`] THEN
    (* residual R15 invariant clause `1<=i ==> R15 = read(mem z)`: from IH (word_add z (word 0) form). *)
    DISCH_TAC THEN
    FIRST_X_ASSUM(fun th -> if is_imp(concl th) && fst(dest_imp(concl th)) = `1 <= i`
      then MP_TAC(MP th (ASSUME `1 <= i`)) else NO_TAC) THEN
    REWRITE_TAC[WORD_ADD_0];
    (* ===== EXIT (i=k, jne not taken -> fall through to 0x3ed) ===== *)
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    SUBGOAL_THEN `lowdigits b k = b` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits zorig k = zorig` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    (* POST R15 clause: read R15 s2 = read(mem z) s2, from IH `1<=k ==> R15 = read(mem word_add z(word 0))`
       + 1<=k asm + WORD_ADD_0 (word_add z (word 0)=z). *)
    FIRST_X_ASSUM(fun th -> if is_imp(concl th) && fst(dest_imp(concl th)) = `1 <= k`
      then MP_TAC(MP th (ASSUME `1 <= k`)) else NO_TAC) THEN
    REWRITE_TAC[WORD_ADD_0]]);;


(* ============================================================================
   x86_negadd1_log_small.ml -- BIGNUM_MOD_X86_NEGADD1_LOG_SMALL.
   The p<61 (pcode=0) variant of BIGNUM_MOD_X86_NEGADD1_LOG (x86_negadd1.ml:584).
   x86 analog of ARM BIGNUM_MOD_NEGADD1_LOG_SMALL (negadd1_log_small.ml).

   0x37a -> 0x432 first correction pass, value-level V1 = V - q1*b, q1=(w*h)DIV2^64+h,
   V = 2^(64k)*Ztv + zk.  Same three legs as LARGE:
     PREFIX (0x37a->0x3b6, p-general)  -- BIGNUM_MOD_X86_NEGADD1_PREFIX
     LOOP   (0x3b6->0x3ed, pcode=0)    -- BIGNUM_MOD_X86_NEGADD1_LOOP_LOG_SMALL  (<- the SMALL swap)
     TAIL   (0x3ed->0x432, p-general)  -- BIGNUM_MOD_X86_NEGADD1_TAIL
   value pin V1EQ via NEGADD1_TOPFOLD + CONG_BOUND_PIN + TWOPART_BOUND (p-free, verbatim from LARGE).
   POST sp+64 = word((V1 * 2^(61-p)) MOD 2^64) [LEFT-shift window] instead of the LARGE
   word((V1 DIV 2^(p-61)) MOD 2^64) [right-shift].  Field close: the p-general TAIL POST funnel
   (DIV 2^((p+3)MOD64) with k=(p+3)DIV64 / k<(p+3)DIV64 csel) reconciles to V1*2^(61-p) MOD 2^64 via
   LOGGED_FIELD_WINDOW_SMALL (pcode=0: csel branches false since k>=1; lf=word 0, hf=z[0]=bigdigit V1 0).

   PRE: 1 <= p /\ p < 61 (was 61 <= p) + V1<2^(p+2) [SMALL 2nd-window no-wrap, extra hyp].
   Deps: NEGADD1_PREFIX, NEGADD1_LOOP_LOG_SMALL, NEGADD1_TAIL, NEGADD1_TOPFOLD, CONG_BOUND_PIN,
     TWOPART_BOUND, LOGGED_FIELD_WINDOW_SMALL (all scaffold/x86_negadd1/x86_negadd1_loop_small).
   Load AFTER x86_negadd1 + x86_negadd1_loop_small.
   ============================================================================ *)

let BIGNUM_MOD_X86_NEGADD1_LOG_SMALL = prove
 (`!k z m w h p b Ztv zk pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 1 <= p /\ p < 61 /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\
      w < 2 EXP 64 /\ h < 2 EXP 64 /\ (w * h) DIV 2 EXP 64 + h < 2 EXP 64 /\
      ((w * h) DIV 2 EXP 64 + h) * b <= 2 EXP (64 * k) * Ztv + zk /\
      (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b < 2 EXP (p + 2) /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x432) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((((2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b)
                     * 2 EXP (61 - p)) MOD 2 EXP 64) /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s =
              (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== PREFIX 0x37a -> 0x3b6 (p-general, verbatim from LARGE) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x3b6`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read R10 s = word 0 /\
        read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R9 s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R13 s = word ((p + 3) DIV 64) /\
        read R14 s = word 0 /\ read R15 s = word 0 /\
        bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL [`k:num`; `z:int64`; `m:int64`; `w:num`; `h:num`; `p:num`; `zk:num`;
                  `b:num`; `Ztv:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_PREFIX)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* pcode = (p+3) DIV 64 = 0 for p < 61 *)
  SUBGOAL_THEN `(p + 3) DIV 64 = 0` ASSUME_TAC THENL
   [REWRITE_TAC[DIV_EQ_0; ARITH_EQ] THEN UNDISCH_TAC `p < 61` THEN ARITH_TAC; ALL_TAC] THEN
  GHOST_INTRO_TAC `rbxv:int64` `read RBX` THEN
  GHOST_INTRO_TAC `r12v:int64` `read R12` THEN
  (* ===== LOOP_LOG_SMALL 0x3b6 -> 0x3ed (pcode=0: R14=word 0, R15=z[0]) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x3ed`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
        read R10 s = word k /\ read RBP s = word ((w * h) DIV 2 EXP 64 + h) /\
        read R13 s = word 0 /\ read RBX s = rbxv /\ read R12 s = r12v /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read R14 s = word 0 /\
        read R15 s = read (memory :> bytes64 (word_add z (word 0))) s /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read R9 s) +
          ((w * h) DIV 2 EXP 64 + h) * b = zk + ((w * h) DIV 2 EXP 64 + h) * 2 EXP (64 * k)` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `(w * h) DIV 2 EXP 64 + h`; `zk:num`; `b:num`;
       `r12v:int64`; `rbxv:int64`; `word Ztv:int64`; `word (p + 3):int64`;
       `word w:int64`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_LOOP_LOG_SMALL)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== TAIL 0x3ed -> 0x432 (p-general) + value pin + SMALL field-select close ===== *)
  GHOST_INTRO_TAC `hh:int64` `read R9` THEN
  GHOST_INTRO_TAC `lf:int64` `read R14` THEN
  GHOST_INTRO_TAC `hf:int64` `read R15` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
    [`k:num`; `z:int64`; `m:int64`; `p:num`; `(w * h) DIV 2 EXP 64 + h`; `hh:int64`;
     `word Ztv:int64`; `lf:int64`; `hf:int64`; `word w:int64`; `zc:num`; `b:num`; `pc:num`; `stackpointer:int64`]
    BIGNUM_MOD_X86_NEGADD1_TAIL)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  (* NB: NO trailing ASM_REWRITE here (unlike LARGE) -- with the SMALL asm `hf=read(mem z[0])` an ASM_REWRITE
     would rewrite hf in the POST field term and split the `field /\ value` conjunction prematurely, breaking
     the CONJ_TAC below.  Keep the POST as one conjunction; the field branch does its own ASM_REWRITE. *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc`
      then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  SUBGOAL_THEN `val(word Ztv:int64) = Ztv` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  (* value pin V1 = V - q1*b (p-free, verbatim from LARGE) *)
  SUBGOAL_THEN
   `2 EXP (64 * k) *
      val(word_add (word Ztv) (word_sub hh (word ((w * h) DIV 2 EXP 64 + h))):int64) + zc =
    (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b`
   ASSUME_TAC THENL
   [MP_TAC(SPECL [`word Ztv:int64`; `hh:int64`; `(w * h) DIV 2 EXP 64 + h`;
                  `zc:num`; `zk:num`; `b:num`; `k:num`] NEGADD1_TOPFOLD) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC CONG_BOUND_PIN THEN EXISTS_TAC `2 EXP (64 * (k + 1))` THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[VAL_BOUND_64];
      MATCH_MP_TAC(ARITH_RULE `V < K ==> V - qb < K`) THEN
      MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* NOW ASM_REWRITE the POST: with V1EQ banked, the value-eq conjunct closes; the many read-conjuncts
     close by their asms; only the field-h equation survives (whether or not the conjunction got split by
     the `hf` rewrite -- ASM_REWRITE leaves exactly the field-h goal). *)
  ASM_REWRITE_TAC[] THEN
  (* SMALL field close (mirror ARM negadd1_log_small.ml:169-197): pcode=0 -> csel k=0 & k<0 false (k>=1);
     lf=word 0, hf=z[0].  (p+3)MOD64=p+3; strip val(word 0)=0; z[0]=bigdigit zc 0 -> bigdigit V1 0;
     then LOGGED_FIELD_WINDOW_SMALL gives V1*2^(61-p) MOD 2^64. *)
  REWRITE_TAC[ARITH_RULE `~(k < 0)`] THEN
  SUBGOAL_THEN `(p + 3) MOD 64 = p + 3` SUBST1_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN UNDISCH_TAC `p < 61` THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_0; ADD_CLAUSES] THEN
  (* fold read(mem z[0]) s -> word(bigdigit zc 0) INLINE (SUBST1_TAC); the reverse z[0] obligation is
     `read(mem z) s = word(bigdigit zc 0)`, proved by BIGDIGIT_BIGNUM_FROM_MEMORY (0<k) + DISCH SUBST1 +
     WORD_VAL (NOT SUBST1 o SYM -- that folds the wrong direction, leaving val(read) unclosed). *)
  SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word 0))) s = word (bigdigit zc 0)` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`k:num`; `z:int64`; `s:x86state`; `0`] BIGDIGIT_BIGNUM_FROM_MEMORY) THEN
    ASM_REWRITE_TAC[MULT_CLAUSES; WORD_ADD_0; ARITH_RULE `0 < k <=> ~(k = 0)`] THEN
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[WORD_VAL]; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_BIGDIGIT] THEN
  (* pin V1 := V - q1*b; fold bigdigit zc 0 = bigdigit V1 0 via the value eqn. *)
  ABBREV_TAC `V1 = (2 EXP (64 * k) * Ztv + zk) - ((w * h) DIV 2 EXP 64 + h) * b` THEN
  SUBGOAL_THEN `bigdigit zc 0 = bigdigit V1 0` SUBST1_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && rand(concl th) = `V1:num` &&
       (try fst(dest_const(fst(strip_comb(lhand(concl th))))) = "+" with _ -> false)
       then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[bigdigit; MULT_CLAUSES; EXP; DIV_1] THEN
    CONV_TAC SYM_CONV THEN
    SUBGOAL_THEN `2 EXP (64 * k) = 2 EXP 64 * 2 EXP (64 * (k - 1))` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM EXP_ADD] THEN AP_TERM_TAC THEN
      UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[GSYM MULT_ASSOC] THEN ONCE_REWRITE_TAC[ADD_SYM] THEN SIMP_TAC[MOD_MULT_ADD];
    ALL_TAC] THEN
  (* field window = V1 * 2^(61-p) MOD 2^64 via LOGGED_FIELD_WINDOW_SMALL *)
  AP_TERM_TAC THEN
  MP_TAC(REWRITE_RULE[ADD_0] (SPECL [`V1:num`; `p:num`] LOGGED_FIELD_WINDOW_SMALL)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ACCEPT_TAC th));;


(* ============================================================================
   x86_negadd2.ml -- the SECOND correction pass (negaddloop2) ported ARM->x86.
   Port of ARM negadd2_{prefix,loop,tail}.ml + negadd2.ml (BIGNUM_MOD_NEGADD2).
   x86 span 0x432 -> 0x496 (ground-truth objdump of bignum_mod_tmc):
     PREFIX2 0x432->0x45d  q2 setup: q2=(((w*h2)DIV2^64+h2)>>61)+1 into RBP/R9=hh, ii=R10=0,
                           cy-mask RDI=0, CF=0, reads kk; test/jz NOT taken (k!=0).
     LOOP2   0x45d->0x485  per-word z := z - q2*m, 2-carry-chain (hh in R9 + low-add carry in RDI mask,
                           re-injected via neg rdi / captured via sbb rdi,rdi).  ARM adcs/adc 2-chain.
     TAIL2   0x48b->0x496  neg rdi[cy->CF]; rcx=zt(sp8); adc rcx,r9[T=zt1w+hh+cy]; cmp rcx,rbp[T vs q2];
                           sbb rax,rax[mask t=(T<q2)?-1:0].  T in rcx (NOT stored); mask rax->r9 for optadd.
   POST (existential over hh,cf, register-faithful, like ARM negadd2.ml):
     bignum(z,k)+2^(64k)*(hh+bitval cf)+q2*b = zk+q2*2^(64k), T=(zt1w+hh+cf)MOD2^64, mask=(T<q2)?2^64-1:0.
   x86 slot/reg map (vs ARM negadd2): hh=R9(X5), q2=RBP(X15), cy-mask=RDI(the 2-chain carry, ARM used CF),
     z=RSI(X1), m=R8(X4), zt=sp+8(X23), ww=sp+40(X21), hs=sp+64(X15win=h2), kk=sp+0(X0).
   Value helpers NEGADD2_STEP (2-chain identity, in scaffold) + NEGADD1_ADVANCE (combined carry).
   Deps: BIGNUM_MOD_EXEC, scaffold Section B (NEGADD2_STEP, NEGADD1_ADVANCE).  Load after x86_negadd1.
   ============================================================================ *)

(* ===== PREFIX2 0x432 -> 0x45d (q2 quotient setup) =====
   12 instrs straight-line (last is jz@0x45b, NOT taken since k!=0, falls to 0x45d).
   mul [rsp+0x40](h2) by rax=ww=w -> word(w*h2):int128; rbp=hi+h2; shr rbp,0x3d[>>61]; add rbp,1[q2];
   r9=rbp[hh]; xor r10,r10[ii]; xor edi,edi[cy mask=0]; mov rax,[rsp][k]; test; jz.  No memory writes.
   mul-high bridge word_zx(word_ushr(word(w*h2):int128)64)=word((w*h2)DIV2^64) as in NEGADD1 PREFIX. *)

let BIGNUM_MOD_X86_NEGADD2_PREFIX = prove
 (`!k z m w h2 zt8 p zk b pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ w < 2 EXP 64 /\ h2 < 2 EXP 64 /\
      (w * h2) DIV 2 EXP 64 + h2 < 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x432) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h2 /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = (zt8:int64) /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x45d) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read R10 s = word 0 /\ read RDI s = word 0 /\ read CF s = F /\
            read R9 s = word ((((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61) + 1) /\
            read RBP s = word ((((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61) + 1) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word w:int64) = w` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `w < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word h2:int64) = h2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `h2 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--12) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `w * h2 < 2 EXP 128` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `2 EXP 64 * 2 EXP 64` THEN CONJ_TAC THENL
     [MATCH_MP_TAC LT_MULT2 THEN ASM_REWRITE_TAC[]; REWRITE_TAC[GSYM EXP_ADD] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `word_zx (word_ushr (word (w * h2):int128) 64):int64 = word((w*h2) DIV 2 EXP 64)`
    SUBST_ALL_TAC THENL
   [REWRITE_TAC[GSYM VAL_EQ] THEN
    REWRITE_TAC[VAL_WORD_ZX_GEN; DIMINDEX_64; VAL_WORD_USHR; VAL_WORD; DIMINDEX_128] THEN
    ASM_SIMP_TAC[MOD_LT] THEN
    SUBGOAL_THEN `(w * h2) DIV 2 EXP 64 < 2 EXP 64` (fun th -> SIMP_TAC[th; MOD_LT]) THEN
    SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM WORD_ADD] THEN
  SUBGOAL_THEN `word_add (word ((w * h2) DIV 2 EXP 64)) (word h2):int64 = word((w*h2) DIV 2 EXP 64 + h2)`
    SUBST1_TAC THENL [REWRITE_TAC[WORD_ADD]; ALL_TAC] THEN
  SUBGOAL_THEN `word_ushr (word ((w * h2) DIV 2 EXP 64 + h2):int64) 61 =
                word (((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61)` SUBST1_TAC THENL
   [REWRITE_TAC[word_ushr] THEN AP_TERM_TAC THEN
    REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN ASM_SIMP_TAC[MOD_LT]; ALL_TAC] THEN
  REWRITE_TAC[WORD_ADD] THEN
  CONJ_TAC THEN
  (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zk` ||
                              concl th = `bignum_from_memory (m,k) s0 = b`
     then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
   REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
   FIRST_X_ASSUM(MP_TAC o check (can
     (term_match [] `(f:x86state->x86state->bool) s0 s12`) o concl)) THEN
   REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
   REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
   REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC));;


(* ===== Carry-mask helpers (x86-specific: the 2-carry-chain holds the low-add carry in RDI as a
   0/-1 mask cy, re-injected each iter by `neg rdi` and re-captured by `sbb rdi,rdi`).  These bridge
   the RDI mask (word_sub(word 0)(word(bitval c)) or word_neg(word(bitval c))) to the carry bit c. *)

let CARRY_MASK_DISJ = prove
 (`!c. (word_sub (word 0) (word (bitval c)):int64 = word 0 \/
        word_sub (word 0) (word (bitval c)):int64 = word (2 EXP 64 - 1)) /\
       (word_neg (word (bitval c)):int64 = word 0 \/
        word_neg (word (bitval c)):int64 = word (2 EXP 64 - 1))`,
  GEN_TAC THEN BOOL_CASES_TAC `c:bool` THEN
  REWRITE_TAC[BITVAL_CLAUSES] THEN
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_SUB; VAL_WORD_NEG_CASES; VAL_WORD_0; VAL_WORD_1;
              VAL_WORD; DIMINDEX_64] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let MASK_IS_ZERO_IFF = prove
 (`!c. (word_sub (word 0) (word (bitval c)):int64 = word 0 <=> ~c) /\
       (word_neg (word (bitval c)):int64 = word 0 <=> ~c)`,
  GEN_TAC THEN BOOL_CASES_TAC `c:bool` THEN
  REWRITE_TAC[BITVAL_CLAUSES] THEN CONV_TAC WORD_REDUCE_CONV);;


(* ===== LOOP2 0x45d -> 0x48b (negaddloop2 core, 2-carry-chain) =====
   ENSURES_WHILE_AUP 0..k, head=0x45d, backedge-test=0x485, exit-fallthrough=0x48b.
   Invariant tracks the low-add carry in RDI as a 0/-1 mask (disjunct read RDI = word 0 \/ word(2^64-1))
   + combined carry (val R9 + (if read RDI = word 0 then 0 else 1)) in the value eqn.  Body 12 instrs
   (ACCSTEPS [3;6;8;9]); DISJ_CASES on the RDI mask; NEGADD2_STEP (2-chain identity) + NEGADD1_ADVANCE
   (combined carry).  Port of ARM BIGNUM_MOD_NEGADD2_LOOP.  Deps: NEGADD2_STEP, NEGADD1_ADVANCE (scaffold),
   CARRY_MASK_DISJ, MASK_IS_ZERO_IFF (above). *)

let MASK_NEQ_ZERO = prove
 (`~(word (2 EXP 64 - 1):int64 = word 0)`,
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_0; VAL_WORD; DIMINDEX_64] THEN CONV_TAC NUM_REDUCE_CONV);;

let BIGNUM_MOD_X86_NEGADD2_LOOP = prove
 (`!k z m q2 zorig b r12v rbxv zt8 pp48 pc stackpointer.
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      1 <= k /\ k < 2 EXP 58 /\ q2 < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zorig < 2 EXP (64 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x45d) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
            read R10 s = word 0 /\ read RBP s = word q2 /\ read R9 s = word q2 /\
            read RDI s = word 0 /\ read CF s = F /\
            read RBX s = rbxv /\ read R12 s = r12v /\
            bignum_from_memory (z,k) s = zorig /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x48b) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
            read R10 s = word k /\ read RBP s = word q2 /\
            read RBX s = rbxv /\ read R12 s = r12v /\
            (read RDI s = word 0 \/ read RDI s = word (2 EXP 64 - 1)) /\
            bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s +
              2 EXP (64 * k) * (val(read R9 s) +
                (if read RDI s = word 0 then 0 else 1)) + q2 * b =
              zorig + q2 * 2 EXP (64 * k))
       (MAYCHANGE [RIP; RAX; RCX; RDX; RDI; R9; R10] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_WHILE_AUP_TAC `0` `k:num` `pc + 0x45d` `pc + 0x485`
   `\i s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
          read RBP s = word q2 /\
          read (memory :> bytes64 stackpointer) s = word k /\
          read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
          read (memory :> bytes64 (word_add stackpointer (word 48))) s = pp48 /\
          read R10 s = word i /\ read RBX s = rbxv /\ read R12 s = r12v /\
          (read RDI s = word 0 \/ read RDI s = word (2 EXP 64 - 1)) /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (word_add z (word (8 * i)), k - i) s = highdigits zorig i /\
          bignum_from_memory (z,i) s +
            2 EXP (64 * i) * (val(read R9 s) + (if read RDI s = word 0 then 0 else 1)) +
            q2 * lowdigits b i = lowdigits zorig i + q2 * 2 EXP (64 * i)` THEN
  CONJ_TAC THENL [UNDISCH_TAC `1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** ENTRY i=0 ***)
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0; WORD_ADD_0; ARITH_RULE `8 * 0 = 0`] THEN
    ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; HIGHDIGITS_0; LOWDIGITS_0] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; ADD_CLAUSES; DIV_1] THEN
    MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `q2 < 2 EXP 64` THEN ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** BODY i -> i+1 ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    GHOST_INTRO_TAC `hhin:int64` `read R9` THEN
    GHOST_INTRO_TAC `dimask:int64` `read RDI` THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
    ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
    REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i + 1)`; BIGNUM_FROM_MEMORY_STEP] THEN
    ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * i)))) s0 = word (bigdigit b i)`
      ASSUME_TAC THENL
     [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
      ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * i)))) s0 = word (bigdigit zorig i)`
      ASSUME_TAC THENL
     [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
      GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN SUBST_ALL_TAC o check (fun th -> is_disj(concl th))) THEN
    REWRITE_TAC[MASK_NEQ_ZERO] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[MASK_NEQ_ZERO]) THEN
    X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [3;6;8;9] (1--12) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CARRY_MASK_DISJ; MASK_IS_ZERO_IFF] THEN
    REWRITE_TAC[COND_CLAUSES; ADD_CLAUSES] THEN
    (REPEAT CONJ_TAC THENL
     [(* word(i+1) *) CONV_TAC WORD_RULE;
      (* m-frame *)
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s12`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* z-tail split *)
      REWRITE_TAC[ARITH_RULE `k <= i + 1 <=> k - (i + 1) = 0`;
                  ARITH_RULE `k - ((i + 1) + 1) = k - (i + 1) - 1`] THEN
      GEN_REWRITE_TAC I [GSYM BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0 = highdigits zorig (i+1)` MP_TAC THENL
       [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
        GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
        ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
        REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i+1)`] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s12 =
        bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0`
       (fun th -> ASM_REWRITE_TAC[th]) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s12`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* VALUE via NEGADD2_STEP + NEGADD1_ADVANCE.  cfin = the carry-into-this-word in the invariant
         value hyp (0 for dimask=0 branch, 1 for dimask=-1 branch); read it off that hypothesis. *)
      SUBGOAL_THEN `(if ~carry_s9 then 0 else 1) = bitval carry_s9` SUBST1_TAC THENL
       [REWRITE_TAC[bitval] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `bignum_from_memory (z,i) s12 = bignum_from_memory (z,i) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s12`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `val(word q2:int64) = q2 /\ val(word (bigdigit zorig i):int64) = bigdigit zorig i /\
                    val(word_not(word(bigdigit b i)):int64) = 2 EXP 64 - 1 - bigdigit b i`
        STRIP_ASSUME_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
          UNDISCH_TAC `q2 < 2 EXP 64` THEN ARITH_TAC;
          MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND];
          REWRITE_TAC[VAL_WORD_NOT; DIMINDEX_64] THEN
          SIMP_TAC[VAL_WORD_EQ; DIMINDEX_64; BIGDIGIT_BOUND]]; ALL_TAC] THEN
      SUBGOAL_THEN `2 EXP 64 * val(mulhi_s3:int64) + val(mullo_s3:int64) =
                    (2 EXP 64 - 1 - bigdigit b i) * q2` ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun th -> if free_in `mulhi_s3:int64` (concl th) && is_eq(concl th) &&
            (try rand(rand(concl th)) = `&(val(word q2:int64))` with _ -> false)
          then MP_TAC th else NO_TAC) THEN
        ASM_REWRITE_TAC[] THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `val(mulhi_s3:int64) + bitval carry_s6 < 2 EXP 64` ASSUME_TAC THENL
       [SUBGOAL_THEN `(2 EXP 64 - 1 - bigdigit b i) * q2 <= (2 EXP 64 - 1) * (2 EXP 64 - 1)` ASSUME_TAC THENL
         [MATCH_MP_TAC LE_MULT2 THEN
          MP_TAC(SPEC `i:num`(SPEC `b:num` BIGDIGIT_BOUND)) THEN
          UNDISCH_TAC `q2 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPEC `carry_s6:bool` BITVAL_BOUND) THEN
        MP_TAC(ISPEC `mullo_s3:int64` VAL_BOUND_64) THEN
        UNDISCH_TAC `2 EXP 64 * val(mulhi_s3:int64) + val(mullo_s3:int64) =
                     (2 EXP 64 - 1 - bigdigit b i) * q2` THEN
        UNDISCH_TAC `(2 EXP 64 - 1 - bigdigit b i) * q2 <= (2 EXP 64 - 1) * (2 EXP 64 - 1)` THEN
        ARITH_TAC; ALL_TAC] THEN
      (fun (asl,w) ->
        (* cfin = the num added to `val hhin` in the invariant value hypothesis. *)
        let ivhyp = concl (find (fun th -> free_in `val(hhin:int64)` (concl th) &&
                                           free_in `lowdigits b i` (concl th)) (map snd asl)) in
        let cfin = rand(rand(lhand(rand(lhand ivhyp)))) in
        (SUBGOAL_THEN
          (subst [cfin,`CFIN:num`]
           `2 EXP 64 * (val(sum_s8:int64) + bitval carry_s9) + val(sum_s9:int64) =
            bigdigit zorig i + (val(hhin:int64) + CFIN) + q2 * (2 EXP 64 - 1 - bigdigit b i)`)
          ASSUME_TAC THENL
          [MP_TAC(ISPECL
             [`bigdigit zorig i`; `val(hhin:int64)`; cfin; `q2:num`; `2 EXP 64 - 1 - bigdigit b i`;
              `val(sum_s6:int64)`; `val(sum_s9:int64)`; `val(sum_s8:int64)`;
              `bitval carry_s6`; `bitval carry_s8`; `bitval carry_s9`;
              `val(mullo_s3:int64)`; `val(mulhi_s3:int64)`] NEGADD2_STEP) THEN
           ASM_REWRITE_TAC[ADD_CLAUSES] THEN DISCH_THEN MATCH_MP_TAC THEN
           REPEAT CONJ_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN
           ASM_REWRITE_TAC[REAL_OF_NUM_CLAUSES] THEN
           REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN CONV_TAC REAL_RING; ALL_TAC] THEN
         REWRITE_TAC[LOWDIGITS_CLAUSES] THEN
         MP_TAC(ISPECL
           [`q2:num`; `bignum_from_memory (z,i) s0`; `lowdigits zorig i`; `lowdigits b i`;
            mk_comb(mk_comb(`(+):num->num->num`,`val(hhin:int64)`),cfin);
            `val(sum_s8:int64) + bitval carry_s9`; `val(sum_s9:int64)`;
            `bigdigit zorig i`; `bigdigit b i`; `i:num`] NEGADD1_ADVANCE) THEN
         ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN REWRITE_TAC[LOWDIGITS_CLAUSES] THEN CONV_TAC NUM_RING)
        (asl,w))]);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** BACKEDGE 0x485 ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    ASM_SIMP_TAC[ARITH_RULE `i < k ==> ~(i = k)`];
    (*** EXIT 0x48b ***)
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    SUBGOAL_THEN `lowdigits b k = b` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits zorig k = zorig` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;


(* ===== TAIL2 0x48b -> 0x49c (negaddtail2 top-word fold + sign mask) =====
   5 straight-line instrs: neg rdi[CF:=cy bit]; mov rcx,zt(sp8); adc rcx,r9[T=zt8+hh+cy]; cmp rcx,rbp[q2];
   sbb r9,r9[mask into R9 -- NB the .o writes R9, NOT rax as the annotated intel.S suggests; OPTADD reads
   the mask from R9 directly, dropping the `mov r9,rax`].  T := (val zt8 + val hh + bitval cf) MOD 2^64
   (the signed top word of V1 - q2*b); mask R9 = (T < q2)?2^64-1:0 = sign(V1-q2*b).  Entry cy passed as
   RDI = word_neg(word(bitval cf)) (the LOOP2 exit mask disjunct, cf the low-add carry bit).
   POST: RCX = word T, R9 = mask, sp+8/RBP=q2/z-mem/m-mem preserved.  Purely register/state; the signed
   V1-q2*b = zc2 + 2^(64k)*(T-q2) interpretation is done at Stage 4d (OPTADD add-back).
   Mask close: WORD_REDUCE leaves `word 18446744073709551615 = word(2 EXP 64 - 1)` -> AP_TERM_TAC +
   NUM_REDUCE_CONV (WORD_REDUCE won't reduce the non-literal 2 EXP 64 - 1).  z/m-mem: ONE MAYCHANGE
   shared by both frames -> FIRST_ASSUM (non-consuming), NOT FIRST_X_ASSUM (2nd frame would fail tryfind).
   Deps: BIGNUM_MOD_EXEC, MASK_IS_ZERO_IFF (above). *)

let BIGNUM_MOD_X86_NEGADD2_TAIL = prove
 (`!k z m q2 hh zt8 cf zk b pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ q2 < 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x48b) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = (zt8:int64) /\
            read R10 s = word k /\ read RBP s = word q2 /\ read R9 s = (hh:int64) /\
            read RDI s = word_neg(word(bitval cf)) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x49c) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read RBP s = word q2 /\
            read RCX s = word ((val(zt8:int64) + val(hh:int64) + bitval cf) MOD 2 EXP 64) /\
            read R9 s = word (if (val(zt8:int64) + val(hh:int64) + bitval cf) MOD 2 EXP 64 < q2
                              then 2 EXP 64 - 1 else 0) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RDI; R9; R10] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `val(word q2:int64) = q2` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `q2 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  X86_STEPS_TAC BIGNUM_MOD_EXEC (1--5) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[MASK_IS_ZERO_IFF] THEN
  SUBGOAL_THEN `bitval (~(word_neg (word (bitval cf)):int64 = word 0)) = bitval cf` SUBST_ALL_TAC THENL
   [REWRITE_TAC[MASK_IS_ZERO_IFF; bitval] THEN CONV_TAC TAUT; ALL_TAC] THEN
  SUBGOAL_THEN
   `word_add (word_add (zt8:int64) hh) (word (bitval cf)) =
    word ((val(zt8:int64) + val(hh:int64) + bitval cf) MOD 2 EXP 64)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_ADD; VAL_WORD_BITVAL; VAL_WORD; DIMINDEX_64] THEN
    CONV_TAC MOD_DOWN_CONV THEN REWRITE_TAC[ADD_ASSOC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `val(word_add (word_add (zt8:int64) hh) (word (bitval cf))) =
    (val(zt8:int64) + val(hh:int64) + bitval cf) MOD 2 EXP 64` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MP_TAC(SPECL [`val(zt8:int64) + val(hh:int64) + bitval cf`; `2 EXP 64`] MOD_LT_EQ) THEN
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [(* R9 mask: word_neg(word(bitval(T<q2))) = word(if T<q2 then 2^64-1 else 0) *)
    BOOL_CASES_TAC `(val(zt8:int64) + val(hh:int64) + bitval cf) MOD 2 EXP 64 < q2` THEN
    REWRITE_TAC[BITVAL_CLAUSES] THEN CONV_TAC WORD_REDUCE_CONV THEN
    AP_TERM_TAC THEN CONV_TAC NUM_REDUCE_CONV;
    (* z-mem /\ m-mem via the SINGLE MAYCHANGE (FIRST_ASSUM non-consuming so both frames see it) *)
    CONJ_TAC THEN
    (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zk` ||
                                concl th = `bignum_from_memory (m,k) s0 = b`
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
     REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
     FIRST_ASSUM(MP_TAC o check (can
       (term_match [] `(f:x86state->x86state->bool) s0 s5`) o concl)) THEN
     REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
     REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
     REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC)]);;


(* ===== MASK_TO_NEG_BITVAL: bridge the LOOP2-exit RDI disjunct to the TAIL2-input neg-bitval form.
   From (d = word 0 \/ d = word(2^64-1)), d = word_neg(word(bitval(~(d = word 0)))).  Lets the compose
   feed TAIL2 with cf := ~(dimask=word 0) UNIFORMLY (no case-split) -- the disjunct sits in the ensures
   PRE (not an assumption), so a bare STRIP_TAC would case-split it into 2 residuals; MATCH_MP_TAC of
   this lemma dodges that. *)

let MASK_TO_NEG_BITVAL = prove
 (`!d:int64. (d = word 0 \/ d = word (2 EXP 64 - 1))
     ==> d = word_neg (word (bitval (~(d = word 0))))`,
  GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_0; VAL_WORD; DIMINDEX_64] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[BITVAL_CLAUSES; WORD_NEG_0; COND_CLAUSES] THEN
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_NEG_CASES; VAL_WORD_1; VAL_WORD_0; VAL_WORD; DIMINDEX_64] THEN
  CONV_TAC NUM_REDUCE_CONV);;


(* ===== COMPOSE: BIGNUM_MOD_X86_NEGADD2 (0x432 -> 0x49c, value-level, EXISTENTIAL POST) =====
   PREFIX2(0x432->0x45d) ;; LOOP2(0x45d->0x48b) ;; TAIL2(0x48b->0x49c).  Port of ARM negadd2.ml.
   POST carries (EXISTENTIAL over the loop's final accumulator word hh=val(R9) and combined carry
   cf=~(RDI=word 0)):  bignum(z,k) + 2^(64k)*(hh+bitval cf) + q2*b = zk + q2*2^(64k), and the signed
   top word T=(zt8+hh+bitval cf)MOD2^64 in RCX + sign-mask R9=(T<q2)?2^64-1:0.  q2 abstract =
   (((w*h2)DIV2^64+h2)DIV2^61)+1.  sp+48 (word p, the pcode slot) is threaded through PRE (LOOP2 needs
   pp48) but dropped from POST (not needed downstream; avoids a SLOT_PRESERVED frame discharge).
   Key steps: (a) q2<2^64 from the DIV/8 bound; (b) PREFIX2 leg folds the big DIV term to q2 via GSYM;
   (c) LOOP2 leg (rbxv/r12v GHOST'd, pp48:=word p); (d) TAIL2 leg feeds cf:=~(dimask=word 0) via
   MASK_TO_NEG_BITVAL (dodges the PRE-disjunct case-split), value close = bitval(~(dimask=0))=(if
   dimask=word 0 then 0 else 1) + GSYM q2 fold + ACCEPT the LOOP2 value eqn.
   Deps: BIGNUM_MOD_X86_NEGADD2_{PREFIX,LOOP,TAIL}, MASK_TO_NEG_BITVAL, ENSURES_SEQUENCE/SUBLEMMA. *)

let BIGNUM_MOD_X86_NEGADD2 = prove
 (`!k z m w h2 q2 zt8 p zk b pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ h2 < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zk < 2 EXP (64 * k) /\
      (w * h2) DIV 2 EXP 64 + h2 < 2 EXP 64 /\
      q2 = (((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61) + 1 /\
      w < 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x432) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h2 /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = (zt8:int64) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x49c) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
            read RBP s = word q2 /\
            bignum_from_memory (m,k) s = b /\
            ?hh cf. bignum_from_memory (z,k) s +
                    2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
                    zk + q2 * 2 EXP (64 * k) /\
                    hh < 2 EXP 64 /\
                    read RCX s = word ((val(zt8:int64) + hh + bitval cf) MOD 2 EXP 64) /\
                    read R9 s = word (if (val(zt8:int64) + hh + bitval cf) MOD 2 EXP 64 < q2
                                      then 2 EXP 64 - 1 else 0))
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `q2 < 2 EXP 64` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ARITH_RULE `x < 8 ==> x + 1 < 2 EXP 64`) THEN
    MATCH_MP_TAC(ARITH_RULE `y < 2 EXP 64 ==> y DIV 2 EXP 61 < 8`) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== PREFIX2 0x432 -> 0x45d ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x45d`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        read R10 s = word 0 /\ read RDI s = word 0 /\ read CF s = F /\
        read R9 s = word q2 /\ read RBP s = word q2 /\
        bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `w:num`; `h2:num`; `zt8:int64`; `p:num`; `zk:num`; `b:num`;
       `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD2_PREFIX)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)
      [SYM(ASSUME `q2 = ((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61 + 1`)] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== LOOP2 0x45d -> 0x48b ===== *)
  GHOST_INTRO_TAC `rbxv:int64` `read RBX` THEN
  GHOST_INTRO_TAC `r12v:int64` `read R12` THEN
  ENSURES_SEQUENCE_TAC `pc + 0x48b`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = zt8 /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        read R10 s = word k /\ read RBP s = word q2 /\
        read RBX s = rbxv /\ read R12 s = r12v /\
        (read RDI s = word 0 \/ read RDI s = word (2 EXP 64 - 1)) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s +
          2 EXP (64 * k) * (val(read R9 s) + (if read RDI s = word 0 then 0 else 1)) +
          q2 * b = zk + q2 * 2 EXP (64 * k)` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `q2:num`; `zk:num`; `b:num`;
       `r12v:int64`; `rbxv:int64`; `zt8:int64`; `word p:int64`; `pc:num`;
       `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD2_LOOP)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THEN
    (SUBSUMED_MAYCHANGE_TAC ORELSE (REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]));
    ALL_TAC] THEN
  (* ===== TAIL2 0x48b -> 0x49c ===== *)
  GHOST_INTRO_TAC `hh:int64` `read R9` THEN
  GHOST_INTRO_TAC `dimask:int64` `read RDI` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
    [`k:num`; `z:int64`; `m:int64`; `q2:num`; `hh:int64`; `zt8:int64`; `~(dimask:int64 = word 0)`;
     `zc:num`; `b:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD2_TAIL)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN
  REPEAT CONJ_TAC THENL
   [(* PRE-strengthen: RDI = word_neg(word(bitval(~(dimask=0)))) via MASK_TO_NEG_BITVAL (disjunct in PRE
       kept whole by CONJUNCTS_THEN -- a bare STRIP would case-split it). *)
    GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MASK_TO_NEG_BITVAL THEN ASM_REWRITE_TAC[];
    SUBSUMED_MAYCHANGE_TAC;
    (* POST-derive: witness hh:=val hh, cf:=~(dimask=0); value close via bitval-fold + GSYM q2 + ACCEPT. *)
    REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `val(hh:int64)` THEN EXISTS_TAC `~(dimask:int64 = word 0)` THEN
    ASM_REWRITE_TAC[VAL_BOUND_64] THEN
    SUBGOAL_THEN `bitval (~(dimask:int64 = word 0)) = (if dimask:int64 = word 0 then 0 else 1)`
      SUBST_ALL_TAC THENL
     [REWRITE_TAC[bitval] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[GSYM(ASSUME `q2 = ((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61 + 1`)] THEN
    FIRST_X_ASSUM(fun th -> if free_in `zc:num` (concl th) && free_in `zk:num` (concl th) &&
        is_eq(concl th) then ACCEPT_TAC th else NO_TAC)]);;


(* ============================================================================
   x86_optadd.ml -- the conditional add-back (optaddloop) ported ARM->x86.
   Port of ARM optadd.ml (BIGNUM_MOD_OPTADD).  Stage 4c: z := z + (mask AND m), i.e.
   z := z + bitval msk * b, where the sign-mask R9 = (if msk then 2^64-1 else 0) came from
   NEGADD2's TAIL2 (msk = the sign of V1 - q2*b).  x86 span 0x49c -> 0x4cb.
     prefix 0x49c->0x4aa : xor r10,r10[ii=0]; xor edi,edi[cy mask=0]; mov rax,[rsp][k]; test; jz
                           (NB the .o keeps the mask in R9 -- the annotated intel.S `mov r9,rax` is
                            ABSENT; R9 already holds the mask from TAIL2's `sbb r9,r9`).
     loop   0x4aa->0x4c5 : mov rcx,[z]; mov rax,[m]; and rax,r9[m&mask]; neg rdi[CF=cy]; adc rcx,rax;
                           sbb rdi,rdi[cy=-CF]; mov [z],rcx; inc r10 (backedge cmp r10,[rsp] @0x4c5)
     exit   0x4c5->0x4cb : cmp r10,kk; jne -> fall-through.
   POST: bignum(z,k) = lowdigits (zorig + bitval msk * b) k  (top carry into the (k+1)-th word
   discarded, beyond the k-word result).  Invariant (bignum_optadd template) carries the low-add
   carry in RDI as a 0/-1 mask (like NEGADD2 LOOP2): 2^(64i)*(if RDI=word 0 then 0 else 1) +
   bignum(z,i) = lowdigits zorig i + bitval msk * lowdigits b i.
   x86 reg map: mask=R9, ii=R10, cy-mask=RDI, z=RSI, m=R8, kk=sp+0.
   Deps: BIGNUM_MOD_EXEC, CARRY_MASK_DISJ/MASK_IS_ZERO_IFF/MASK_NEQ_ZERO (x86_negadd2), standard
   bignum lemmas (WORD_AND_MASK_WORD, VAL_WORD_BIGDIGIT, LOWDIGITS_SELF, ...).  Load after x86_negadd2.
   LESSONS (cont126): (a) body sim = X86_ACCSTEPS [5] (1--8) -- adc is instr 5, the loop body is 8
   instrs incl `inc r10` (RIP POST = backedge-test 0x4c5 = pc+1221 needs R10=word(i+1)); missing the
   inc (only 7 steps) lands at pc+1218 with R10=word i.  (b) the two RDI-mask DISJ branches differ
   ONLY in the incoming-carry literal (0 for cy=0, 1 for the word(2^64-1) branch: `neg rdi` re-injects
   cy=1 into the adc); the value-close accumulation is `bigdigit zorig i + bitval msk*bigdigit b i +
   CFIN` where CFIN is read off the invariant hyp `2^(64i)*CFIN + zi = ...` via cfin=rand(lhand(lhand
   ivhyp)) (ONE rand -- CFIN is the left factor of the left addend `2^(64i)*CFIN`).  (c) parenthesize
   `(REPEAT CONJ_TAC THENL [...])` after the DISJ-forking so THENL binds per-branch (THEN/THENL
   left-assoc trap, same as NEGADD2 LOOP2).  (d) word_and (word bigdigit)(word mask) = bitval msk *
   bigdigit b i via WORD_AND_MASK_WORD/WORD_MOD_SIZE/VAL_WORD_BIGDIGIT (BOOL_CASES on msk). *)

let BIGNUM_MOD_X86_OPTADD = prove
 (`!k z m msk zorig b pc stackpointer.
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      1 <= k /\ k < 2 EXP 58 /\ b < 2 EXP (64 * k) /\ zorig < 2 EXP (64 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x49c) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read R9 s = word (if msk then 2 EXP 64 - 1 else 0) /\
            bignum_from_memory (z,k) s = zorig /\
            bignum_from_memory (m,k) s = b)
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = lowdigits (zorig + bitval msk * b) k)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RDI; R9; R10] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== prefix 0x49c -> 0x4aa (xor ii/cy, load k, test/jz not-taken) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x4aa`
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read R9 s = word (if msk then 2 EXP 64 - 1 else 0) /\
        read R10 s = word 0 /\ read RDI s = word 0 /\ read CF s = F /\
        bignum_from_memory (z,k) s = zorig /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `~(k = 0)` ASSUME_TAC THENL
     [UNDISCH_TAC `1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    X86_STEPS_TAC BIGNUM_MOD_EXEC (1--5) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THEN
    (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zorig` ||
                                concl th = `bignum_from_memory (m,k) s0 = b`
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
     REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
     FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s5`) o concl)) THEN
     REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
     REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
     REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC);
    ALL_TAC] THEN
  (* ===== loop 0x4aa -> 0x4c5 (backedge-test) ; exit 0x4c5 -> 0x4cb ===== *)
  ENSURES_WHILE_AUP_TAC `0` `k:num` `pc + 0x4aa` `pc + 0x4c5`
   `\i s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
          read (memory :> bytes64 stackpointer) s = word k /\
          read R9 s = word (if msk then 2 EXP 64 - 1 else 0) /\ read R10 s = word i /\
          (read RDI s = word 0 \/ read RDI s = word (2 EXP 64 - 1)) /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (word_add z (word (8 * i)), k - i) s = highdigits zorig i /\
          2 EXP (64 * i) * (if read RDI s = word 0 then 0 else 1) + bignum_from_memory (z,i) s =
            lowdigits zorig i + bitval msk * lowdigits b i` THEN
  CONJ_TAC THENL [UNDISCH_TAC `1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** ENTRY i=0 ***)
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0; WORD_ADD_0; ARITH_RULE `8 * 0 = 0`] THEN
    ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; HIGHDIGITS_0; LOWDIGITS_0] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; ADD_CLAUSES; DIV_1]; ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** BODY i -> i+1 ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    GHOST_INTRO_TAC `zi:num` `bignum_from_memory (z,i)` THEN
    GHOST_INTRO_TAC `dimask:int64` `read RDI` THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
    ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
    REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i + 1)`; BIGNUM_FROM_MEMORY_STEP] THEN
    ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * i)))) s0 = word (bigdigit b i)`
      ASSUME_TAC THENL
     [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
      ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * i)))) s0 = word (bigdigit zorig i)`
      ASSUME_TAC THENL
     [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
      GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN SUBST_ALL_TAC o check (fun th -> is_disj(concl th))) THEN
    REWRITE_TAC[MASK_NEQ_ZERO] THEN RULE_ASSUM_TAC(REWRITE_RULE[MASK_NEQ_ZERO]) THEN
    X86_ACCSTEPS_TAC BIGNUM_MOD_EXEC [5] (1--8) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CARRY_MASK_DISJ; MASK_IS_ZERO_IFF] THEN REWRITE_TAC[COND_CLAUSES] THEN
    (REPEAT CONJ_TAC THENL
     [(* word(i+1) *) CONV_TAC WORD_RULE;
      (* m-frame *)
      FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
        then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s8`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* z-tail split *)
      REWRITE_TAC[ARITH_RULE `k <= i + 1 <=> k - (i + 1) = 0`;
                  ARITH_RULE `k - ((i + 1) + 1) = k - (i + 1) - 1`] THEN
      GEN_REWRITE_TAC I [GSYM BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0 = highdigits zorig (i+1)` MP_TAC THENL
       [UNDISCH_TAC `bignum_from_memory (word_add z (word (8 * i)),k - i) s0 = highdigits zorig i` THEN
        GEN_REWRITE_TAC LAND_CONV [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
        ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
        REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i+1)`] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s8 =
        bignum_from_memory (word_add z (word (8 * (i+1))),k - (i+1)) s0`
       (fun th -> ASM_REWRITE_TAC[th]) THEN
      REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s8`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
      (* VALUE: cfin = incoming-carry literal from the invariant, find-based (cf NEGADD2 LOOP2). *)
      REWRITE_TAC[LOWDIGITS_CLAUSES] THEN
      SUBGOAL_THEN `bignum_from_memory (z,i) s8 = bignum_from_memory (z,i) s0` SUBST1_TAC THENL
       [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
        FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s8`) o concl)) THEN
        REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
        REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
        REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `val(word_and (word (bigdigit b i))
             (word (if msk then 2 EXP 64 - 1 else 0)):int64) = bitval msk * bigdigit b i` ASSUME_TAC THENL
       [BOOL_CASES_TAC `msk:bool` THEN
        REWRITE_TAC[BITVAL_CLAUSES; MULT_CLAUSES; WORD_AND_0; VAL_WORD_0] THEN
        REWRITE_TAC[WORD_AND_MASK_WORD; GSYM DIMINDEX_64; WORD_MOD_SIZE; WORD_VAL] THEN
        REWRITE_TAC[VAL_WORD_BIGDIGIT]; ALL_TAC] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `18446744073709551615 = 2 EXP 64 - 1`]) THEN
      (fun (asl,w) ->
        let ivhyp = concl (find (fun th -> free_in `zi:num` (concl th) &&
                                           free_in `lowdigits b i` (concl th)) (map snd asl)) in
        let cfin = rand(lhand(lhand ivhyp)) in
        (SUBGOAL_THEN
          (subst [cfin,`CFIN:num`]
           `2 EXP 64 * bitval carry_s5 + val(sum_s5:int64) =
            bigdigit zorig i + bitval msk * bigdigit b i + CFIN`) ASSUME_TAC THENL
          [FIRST_X_ASSUM(MP_TAC o check (can
             (term_match [] `&2 pow 64 * &(bitval c) + &(val(s:int64)) = x`) o concl)) THEN
           ASM_REWRITE_TAC[VAL_WORD_BIGDIGIT] THEN
           REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
         SUBGOAL_THEN `(if ~carry_s5 then 0 else 1) = bitval carry_s5` SUBST1_TAC THENL
          [REWRITE_TAC[bitval] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
         FIRST_X_ASSUM(fun th -> if can (term_match []
            `2 EXP 64 * bitval carry_s5 + val(sum_s5:int64) = xxx`) (concl th) &&
            free_in `bitval msk` (concl th)
           then MP_TAC(AP_TERM `( * ) (2 EXP (64 * i))` th) else NO_TAC) THEN
         REWRITE_TAC[LEFT_ADD_DISTRIB; MULT_ASSOC] THEN
         REWRITE_TAC[GSYM EXP_ADD; ARITH_RULE `64 * i + 64 = 64 * (i + 1)`] THEN
         REWRITE_TAC[ARITH_RULE `64 * (i + 1) = 64 * i + 64`; EXP_ADD; GSYM MULT_ASSOC] THEN
         FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,i) s0 = zi`
           then REWRITE_TAC[th] else NO_TAC) THEN
         FIRST_X_ASSUM(fun th -> if free_in `zi:num` (concl th) && free_in `lowdigits b i` (concl th)
           then MP_TAC th else NO_TAC) THEN
         SPEC_TAC(`2 EXP (64 * i)`,`e:num`) THEN GEN_TAC THEN
         BOOL_CASES_TAC `msk:bool` THEN REWRITE_TAC[BITVAL_CLAUSES; MULT_CLAUSES] THEN ARITH_TAC)
        (asl,w))]);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(*** BACKEDGE 0x4c5 (cmp r10,kk ; jne taken) ***)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    X86_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    ASM_SIMP_TAC[ARITH_RULE `i < k ==> ~(i = k)`];
    (*** EXIT 0x4c5 -> 0x4cb (jne not taken -> fall through) ***)
    GHOST_INTRO_TAC `dimask:int64` `read RDI` THEN
    SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
    ENSURES_INIT_TAC "s0" THEN X86_STEPS_TAC BIGNUM_MOD_EXEC (1--2) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `bignum_from_memory (z,k) s2 = bignum_from_memory (z,k) s0` SUBST1_TAC THENL
     [REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (term_match [] `(f:x86state->x86state->bool) s0 s2`) o concl)) THEN
      REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
      REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits b k = b /\ lowdigits zorig k = zorig` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* invariant (i=k): 2^(64k)*cy + bignum(z,k) = zorig + bitval msk * b, bignum<2^(64k)
       => lowdigits(zorig + bitval msk * b) k = bignum(z,k). *)
    REWRITE_TAC[lowdigits] THEN
    FIRST_X_ASSUM(fun th -> if can (term_match []
       `2 EXP (64 * k) * cc + zz = A + B`) (concl th)
      then MP_TAC th else NO_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    ONCE_REWRITE_TAC[ADD_SYM] THEN REWRITE_TAC[MOD_MULT_ADD] THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC MOD_LT THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]]);;


(* ============================================================================
   x86_splice_37a_4cb.ml -- the full Stage-4 correction splice (x86 0x37a -> 0x4cb).
   Port of ARM BIGNUM_MOD_308_TO_428 (splice_308_428_dev.ml).  Composes
     0x37a -> 0x432  NEGADD1_LOG   (V1 = V - q1*b;  sp+64 = word h2 = window of V1)
     0x432 -> 0x49c  NEGADD2        (signed V1 - q2*b + sign mask R9; RCX = top word T)
     0x49c -> 0x4cb  OPTADD         (conditional add-back)  + NEGADD_PASSES_CLOSE (=> a MOD b)
   with the accuracy setup (PASS1_RED / WINDOW2_SMALL / MULTOP_FITS / QLE_FIT / RED2 -- all in the
   x86 scaffold Section B) and NEGADD_PASSES_CLOSE (scaffold).
   x86 reg/slot map vs ARM: X23->sp+8 (top word Ztv/zt1w), X15->sp+64 (window h1/h2), X20->sp+48 (p),
     X21->sp+40 (w), X10->RCX (top word T), X9->R9 (sign mask).  w carried as :num (my NEGADD segments
     take num w; PASS1_RED/MULTOP_FITS want val(w':int64), so instantiate them with `word w` + val(word w)=w).
   Deps: BIGNUM_MOD_X86_NEGADD1_LOG (x86_negadd1), BIGNUM_MOD_X86_NEGADD2 (x86_negadd2),
     BIGNUM_MOD_X86_OPTADD (x86_optadd), accuracy + NEGADD_PASSES_CLOSE (scaffold), ENSURES_*.
   Load AFTER x86_optadd.
   ============================================================================ *)

(* OPTADD_CLOSE_SEG (x86): 0x49c -> 0x4cb.  Flat PRE (hh,cf,zk2 concrete): R9 = sign mask,
   z-mem = zk2, value eqn zk2 + 2^(64k)*(hh+cf) + q2*b = zk1 + q2*2^(64k), two-sided accuracy bracket
   on V := 2^(64k)*zt1w+zk1 and (V==a)(mod b).  Applies BIGNUM_MOD_X86_OPTADD (msk := sign condition)
   then NEGADD_PASSES_CLOSE (lowdigits = MOD) => bignum(z,k) = a MOD b.  Port of ARM OPTADD_CLOSE_SEG. *)
let X86_OPTADD_CLOSE_SEG = prove
 (`!k z m q2 zt1w zk1 zk2 hh cf b a p pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ ~(b = 0) /\ b < 2 EXP (64 * k) /\
      zk1 < 2 EXP (64 * k) /\ zk2 < 2 EXP (64 * k) /\ zt1w < 2 EXP 64 /\ hh < 2 EXP 64 /\
      q2 < 2 EXP 64 /\
      zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk1 + q2 * 2 EXP (64 * k) /\
      q2 * b <= (2 EXP (64 * k) * zt1w + zk1) + b /\
      2 EXP (64 * k) * zt1w + zk1 < q2 * b + b /\
      (2 EXP (64 * k) * zt1w + zk1 == a) (mod b) /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x49c) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
            bignum_from_memory (z,k) s = zk2 /\ bignum_from_memory (m,k) s = b)
       (\s. read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RDI; R9; R10] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;
             `(zt1w + hh + bitval cf) MOD 2 EXP 64 < q2`;`zk2:num`;`b:num`;`pc:num`;`stackpointer:int64`]
       BIGNUM_MOD_X86_OPTADD)) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL [UNDISCH_TAC `~(k=0)` THEN ARITH_TAC; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
  EXISTS_TAC
   `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x4cb) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        bignum_from_memory (z,k) s =
        lowdigits (zk2 + bitval ((zt1w + hh + bitval cf) MOD 2 EXP 64 < q2) * b) k` THEN
  CONJ_TAC THENL
   [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[lowdigits] THEN
    MP_TAC(ISPECL [`k:num`;`zt1w:num`;`zk1:num`;`zk2:num`;`hh:num`;`cf:bool`;`q2:num`;
                   `b:num`;`2 EXP (64 * k) * zt1w + zk1`;`a:num`] NEGADD_PASSES_CLOSE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  FIRST_X_ASSUM(fun th ->
    if (try fst(dest_const(fst(strip_comb(concl th)))) = "ensures" with _ -> false)
    then EXISTS_TAC (rand(rator(rator(concl th)))) THEN
         CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]
    else NO_TAC));;


(* ENSURES_EXISTS_PRE / ENSURES_PRE_DISCH: x86 copies of the ARM splice helpers. *)
let X86_ENSURES_EXISTS_PRE = prove
 (`!step (P:A->x86state->bool) Q C.
      (!x. ensures step (\s. P x s) Q C) ==> ensures step (\s. ?x. P x s) Q C`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ensures] THEN
  DISCH_TAC THEN GEN_TAC THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN ASM_MESON_TAC[]);;

let X86_ENSURES_PRE_DISCH = prove
 (`!step P (c:bool) Q C.
      (c ==> ensures step (\s. P s) Q C) ==> ensures step (\s. P s /\ c) Q C`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ensures] THEN MESON_TAC[]);;


(* ---- the full Stage-4 splice: BIGNUM_MOD_X86_37A_TO_4CB (0x37a -> 0x4cb) ---- *)
let BIGNUM_MOD_X86_37A_TO_4CB = prove
 (`!k z m w d p a b Ztv zk pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 61 <= p /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ ~(b = 0) /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\
      zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\ d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + w) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
      w < 2 EXP 64 /\
      (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
      2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt hp hp3 hpk hbk hb0 hbp hpb hzk hZt hd hdisj hup hlo hw hcong hVlt hn1 hn2 hn3 hn4 hn5 hn6" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `val(word w:int64) = w` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `w < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `V = 2 EXP (64 * k) * Ztv + zk` THEN
  ABBREV_TAC `h1 = (V DIV 2 EXP p) MOD 2 EXP 64` THEN
  MP_TAC(SPECL [`b:num`; `p:num`; `word w:int64`; `d:num`; `h1:num`; `V:num`] PASS1_RED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q1le") (LABEL_TAC "V1lt")) THEN
  ABBREV_TAC `q1 = (w * h1) DIV 2 EXP 64 + h1` THEN
  ABBREV_TAC `V1 = V - q1 * b` THEN
  SUBGOAL_THEN `q1 < 2 EXP 64` (LABEL_TAC "q1fit") THENL
   [MATCH_MP_TAC QLE_FIT THEN MAP_EVERY EXISTS_TAC [`b:num`; `V:num`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `h2 = (V1 DIV 2 EXP (p - 61)) MOD 2 EXP 64` THEN
  SUBGOAL_THEN `h2 < 2 EXP 63` (LABEL_TAC "h2small") THENL
   [EXPAND_TAC "h2" THEN MP_TAC(SPECL [`V1:num`; `p:num`] WINDOW2_SMALL) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th; CONJUNCT1 th]); ALL_TAC] THEN
  SUBGOAL_THEN `h2 < 2 EXP 64` (LABEL_TAC "h2fit") THENL
   [TRANS_TAC LT_TRANS `2 EXP 63` THEN ASM_REWRITE_TAC[LT_EXP] THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`word w:int64`; `h2:num`] MULTOP_FITS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "q2setupfit") THEN
  ABBREV_TAC `q2 = ((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61 + 1` THEN
  MP_TAC(SPECL [`b:num`; `p:num`; `w:num`; `d:num`; `h2:num`; `V1:num`] RED2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN EXPAND_TAC "h2" THEN REFL_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM QHAT_ID] THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q2le") (LABEL_TAC "V1ltq2")) THEN
  SUBGOAL_THEN `(V1 == a) (mod b)` (LABEL_TAC "congV1") THENL
   [SUBGOAL_THEN `V1 + q1 * b = V` MP_TAC THENL
     [MAP_EVERY (fun t -> UNDISCH_TAC t) [`V - q1 * b = V1`; `q1 * b <= V`] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(SPECL [`V1:num`;`q1:num`;`V:num`;`b:num`] CONG_ADD_MULB) THEN REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(NUMBER_RULE `(V1 == V)(mod b) /\ (V == a)(mod b) ==> (V1 == a)(mod b)`) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `q2 < 2 EXP 64` (LABEL_TAC "q2fit") THENL
   [EXPAND_TAC "q2" THEN MATCH_MP_TAC(ARITH_RULE `x < 8 ==> x + 1 < 2 EXP 64`) THEN
    MATCH_MP_TAC(ARITH_RULE `y < 2 EXP 64 ==> y DIV 2 EXP 61 < 8`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== 0x37a -> 0x432 : NEGADD1_LOG (field-h).  NB ENSURES_SEQUENCE_TAC auto-prepends
     `bytes_loaded s .. /\ read RIP s = word(pc+0x432)` to this intermediate in BOTH legs, so we
     do NOT restate them here (NEGADD1_LOG's POST now carries bytes_loaded to discharge leg-1). ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x432`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h2 /\
        bignum_from_memory (m,k) s = b /\
        2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
          bignum_from_memory (z,k) s = V1` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `w:num`; `h1:num`; `p:num`;
       `b:num`; `Ztv:num`; `zk:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_LOG)) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[ASSUME `(w * h1) DIV 2 EXP 64 + h1 = q1`; ASSUME `2 EXP (64 * k) * Ztv + zk = V`] THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [EXPAND_TAC "h1" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN
    CONJ_TAC THENL [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM(ASSUME `2 EXP (64 * k) * Ztv + zk = V`);
                GSYM(ASSUME `(w * h1) DIV 2 EXP 64 + h1 = q1`)] THEN
    ASM_REWRITE_TAC[ASSUME `V - q1 * b = V1`; ASSUME `(V1 DIV 2 EXP (p - 61)) MOD 2 EXP 64 = h2`];
    ALL_TAC] THEN
  (* ===== at 0x432: GHOST sp+8/z-mem to name zt1w/zk1, lift value facts ===== *)
  GHOST_INTRO_TAC `zt1w:num` `\s. val(read (memory :> bytes64 (word_add stackpointer (word 8))) s)` THEN
  GHOST_INTRO_TAC `zk1:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
         read RIP s = word (pc + 0x432) /\
         read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
         read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
         read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
         read (memory :> bytes64 stackpointer) s = word k /\
         read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h2 /\
         read (memory :> bytes64 (word_add stackpointer (word 8))) s = word zt1w /\
         bignum_from_memory (z,k) s = zk1 /\ bignum_from_memory (m,k) s = b) /\
        (2 EXP (64 * k) * zt1w + zk1 = V1 /\ zt1w < 2 EXP 64 /\ zk1 < 2 EXP (64 * k))` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC BETA_RULE THEN
    FIRST_X_ASSUM(fun th -> if is_conj(concl th) then STRIP_ASSUME_TAC th else NO_TAC) THEN
    BETA_TAC THEN
    FIRST_X_ASSUM(fun t -> if is_eq(concl t) && rand(concl t) = `zt1w:num` &&
          (try fst(dest_const(fst(strip_comb(lhand(concl t))))) = "val" with _->false)
        then ASSUME_TAC(SYM t) else NO_TAC) THEN
    ASM_REWRITE_TAC[WORD_VAL] THEN CONJ_TAC THENL
     [REWRITE_TAC[VAL_BOUND_64];
      ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND]];
    ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  (* ===== 0x432 -> 0x49c : NEGADD2 (frame-widen), zt1w/zk1.  (bytes_loaded/read RIP auto-prepended.) ===== *)
  (* intermediate POST must EXACTLY equal NEGADD2's POST (ISPECL zt8:=word zt1w, val(word zt1w)=zt1w
     rewritten) since leg-2 reconciles PRE-only via ENSURES_PRECONDITION_THM: include the spectator
     reads sp+8=word zt1w and RBP=word q2 in NEGADD2's conjunct order. *)
  ENSURES_SEQUENCE_TAC `pc + 0x49c`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word zt1w /\
        read RBP s = word q2 /\
        bignum_from_memory (m,k) s = b /\
        ?hh cf. bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
                zk1 + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
                read RCX s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
                read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2
                                  then 2 EXP 64 - 1 else 0)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10] ,,
      MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)]` THEN
    CONJ_TAC THENL
     [SUBSUMED_MAYCHANGE_TAC;
      MP_TAC(REWRITE_RULE[SOME_FLAGS]
        (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:num`;`h2:num`;`q2:num`;`word zt1w:int64`;
                 `p + 3`;`zk1:num`;`b:num`;`pc:num`;`stackpointer:int64`] BIGNUM_MOD_X86_NEGADD2)) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `val(word zt1w:int64) = zt1w` (fun th -> REWRITE_TAC[th]) THENL
       [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th ->
        MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
        EXISTS_TAC (rand(rator(rator(concl th)))) THEN
        CONJ_TAC THENL
         [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th])];
    ALL_TAC] THEN
  (* ===== 0x49c -> 0x4cb : peel existential, OPTADD_CLOSE_SEG ===== *)
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. ?hh cf. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x49c) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
          zk1 + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
        read RCX s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
        read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
        bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_EXISTS_PRE THEN GEN_TAC THEN
  MATCH_MP_TAC X86_ENSURES_EXISTS_PRE THEN GEN_TAC THEN
  GHOST_INTRO_TAC `zk2:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [RIP; RAX; RCX; RDX; RDI; R9; R10] ,,
    MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)]` THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x49c) /\
         read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
         read (memory :> bytes64 stackpointer) s = word k /\
         read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
         bignum_from_memory (z,k) s = zk2 /\ bignum_from_memory (m,k) s = b) /\
        (zk2 < 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
         zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk1 + q2 * 2 EXP (64 * k))` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC BETA_RULE THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND];
    ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`q2:num`;`zt1w:num`;`zk1:num`;`zk2:num`;`hh:num`;`cf:bool`;
             `b:num`;`a:num`;`p + 3`;`pc:num`;`stackpointer:int64`] X86_OPTADD_CLOSE_SEG)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(fun t -> if is_eq(concl t) && rand(concl t) = `V1:num`
      then REWRITE_TAC[SYM t] else NO_TAC) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
      EXISTS_TAC (rand(rator(rator(concl th)))) THEN
      CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th])]);;


(* ============================================================================
   x86_splice_37a_4cb_small.ml -- BIGNUM_MOD_X86_37A_TO_4CB_SMALL (x86 0x37a -> 0x4cb, p<61).
   The p<61 (single-word modulus) variant of BIGNUM_MOD_X86_37A_TO_4CB (x86_splice_37a_4cb.ml).
   x86 analog of ARM BIGNUM_MOD_308_TO_428_SMALL (negadd_small.ml:117).

   Same three legs (NEGADD1_LOG_SMALL ;; NEGADD2 ;; OPTADD_CLOSE_SEG) as the LARGE splice, with the
   accuracy layer swapped to the p<61 (left-shift-window) helpers:
     PASS1_RED    -> PASS1_RED_GEN    (61<=p relaxed to 1<=p)
     WINDOW2_SMALL-> WINDOW2_SMALL_P  (h2 = (V1*2^(61-p))MOD2^64 < 2^63, no-wrap, for p<=61)
     RED2         -> RED2_SMALL       (left-shift window)
     NEGADD1_LOG  -> NEGADD1_LOG_SMALL (POST sp+64 = word((V1*2^(61-p))MOD2^64))
   NEGADD2 + X86_OPTADD_CLOSE_SEG are p-free and reused VERBATIM (q2 = ((w*h2)DIV2^64+h2)DIV2^61+1).
   PRE: 1 <= p /\ p < 61 (was 61 <= p); h2 abbreviated as (V1*2^(61-p))MOD2^64 (was V1 DIV 2^(p-61)).

   Deps: NEGADD1_LOG_SMALL (x86_negadd1_log_small), NEGADD2/OPTADD/OPTADD_CLOSE_SEG/ENSURES_* (LARGE splice),
     PASS1_RED_GEN/WINDOW2_SMALL_P/RED2_SMALL/QLE_FIT/MULTOP_FITS/QHAT_ID/NEGADD_PASSES_CLOSE (scaffold),
     CONG_ADD_MULB (scaffold).  Load AFTER x86_splice_37a_4cb + x86_negadd1_log_small.
   ============================================================================ *)

let BIGNUM_MOD_X86_37A_TO_4CB_SMALL = prove
 (`!k z m w d p a b Ztv zk pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 1 <= p /\ p < 61 /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ ~(b = 0) /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\
      zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\ d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + w) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
      w < 2 EXP 64 /\
      (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
      2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64 /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x37a) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt hp hp61 hp3 hpk hbk hb0 hbp hpb hzk hZt hd hdisj hup hlo hw hcong hVlt hn1 hn2 hn3 hn4 hn5 hn6" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `val(word w:int64) = w` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `w < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `V = 2 EXP (64 * k) * Ztv + zk` THEN
  ABBREV_TAC `h1 = (V DIV 2 EXP p) MOD 2 EXP 64` THEN
  (* PASS1_RED_GEN (1<=p): q1*b<=V, V-q1*b<2^(p+2) *)
  MP_TAC(SPECL [`b:num`; `p:num`; `word w:int64`; `d:num`; `h1:num`; `V:num`] PASS1_RED_GEN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q1le") (LABEL_TAC "V1lt")) THEN
  ABBREV_TAC `q1 = (w * h1) DIV 2 EXP 64 + h1` THEN
  ABBREV_TAC `V1 = V - q1 * b` THEN
  SUBGOAL_THEN `q1 < 2 EXP 64` (LABEL_TAC "q1fit") THENL
   [MATCH_MP_TAC QLE_FIT THEN MAP_EVERY EXISTS_TAC [`b:num`; `V:num`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* SMALL window: h2 = (V1 * 2^(61-p)) MOD 2^64 (LEFT shift) *)
  ABBREV_TAC `h2 = (V1 * 2 EXP (61 - p)) MOD 2 EXP 64` THEN
  SUBGOAL_THEN `h2 < 2 EXP 63` (LABEL_TAC "h2small") THENL
   [EXPAND_TAC "h2" THEN MP_TAC(SPECL [`V1:num`; `p:num`] WINDOW2_SMALL_P) THEN
    ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [UNDISCH_TAC `p < 61` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th; CONJUNCT1 th]); ALL_TAC] THEN
  SUBGOAL_THEN `h2 < 2 EXP 64` (LABEL_TAC "h2fit") THENL
   [TRANS_TAC LT_TRANS `2 EXP 63` THEN ASM_REWRITE_TAC[LT_EXP] THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`word w:int64`; `h2:num`] MULTOP_FITS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "q2setupfit") THEN
  ABBREV_TAC `q2 = ((w * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61 + 1` THEN
  (* RED2_SMALL (p<=61, left-shift window): q2*b<=V1+b, V1<q2*b+b *)
  MP_TAC(SPECL [`b:num`; `p:num`; `w:num`; `d:num`; `h2:num`; `V1:num`] RED2_SMALL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    (* leftover ANTE conjuncts after ASM_REWRITE (p<=61 from p<61; h2=(V1*2^(61-p))MOD2^64 refl if not
       already closed by asm).  REPEAT CONJ_TAC + per-conjunct close, guarded so a no-op if ASM_REWRITE
       already discharged everything. *)
    REPEAT CONJ_TAC THEN
    TRY(UNDISCH_TAC `p < 61` THEN ARITH_TAC) THEN
    TRY(EXPAND_TAC "h2" THEN REFL_TAC); ALL_TAC] THEN
  REWRITE_TAC[GSYM QHAT_ID] THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q2le") (LABEL_TAC "V1ltq2")) THEN
  SUBGOAL_THEN `(V1 == a) (mod b)` (LABEL_TAC "congV1") THENL
   [SUBGOAL_THEN `V1 + q1 * b = V` MP_TAC THENL
     [MAP_EVERY (fun t -> UNDISCH_TAC t) [`V - q1 * b = V1`; `q1 * b <= V`] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(SPECL [`V1:num`;`q1:num`;`V:num`;`b:num`] CONG_ADD_MULB) THEN REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(NUMBER_RULE `(V1 == V)(mod b) /\ (V == a)(mod b) ==> (V1 == a)(mod b)`) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `q2 < 2 EXP 64` (LABEL_TAC "q2fit") THENL
   [EXPAND_TAC "q2" THEN MATCH_MP_TAC(ARITH_RULE `x < 8 ==> x + 1 < 2 EXP 64`) THEN
    MATCH_MP_TAC(ARITH_RULE `y < 2 EXP 64 ==> y DIV 2 EXP 61 < 8`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== 0x37a -> 0x432 : NEGADD1_LOG_SMALL (field-h = V1*2^(61-p) window) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x432`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h2 /\
        bignum_from_memory (m,k) s = b /\
        2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
          bignum_from_memory (z,k) s = V1` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS] (ISPECL
      [`k:num`; `z:int64`; `m:int64`; `w:num`; `h1:num`; `p:num`;
       `b:num`; `Ztv:num`; `zk:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_NEGADD1_LOG_SMALL)) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[ASSUME `(w * h1) DIV 2 EXP 64 + h1 = q1`; ASSUME `2 EXP (64 * k) * Ztv + zk = V`] THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [EXPAND_TAC "h1" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN
    CONJ_TAC THENL [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM(ASSUME `2 EXP (64 * k) * Ztv + zk = V`);
                GSYM(ASSUME `(w * h1) DIV 2 EXP 64 + h1 = q1`)] THEN
    ASM_REWRITE_TAC[ASSUME `V - q1 * b = V1`; ASSUME `(V1 * 2 EXP (61 - p)) MOD 2 EXP 64 = h2`];
    ALL_TAC] THEN
  (* ===== at 0x432: GHOST sp+8/z-mem to name zt1w/zk1, lift value facts ===== *)
  GHOST_INTRO_TAC `zt1w:num` `\s. val(read (memory :> bytes64 (word_add stackpointer (word 8))) s)` THEN
  GHOST_INTRO_TAC `zk1:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
         read RIP s = word (pc + 0x432) /\
         read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
         read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
         read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (p + 3) /\
         read (memory :> bytes64 stackpointer) s = word k /\
         read (memory :> bytes64 (word_add stackpointer (word 64))) s = word h2 /\
         read (memory :> bytes64 (word_add stackpointer (word 8))) s = word zt1w /\
         bignum_from_memory (z,k) s = zk1 /\ bignum_from_memory (m,k) s = b) /\
        (2 EXP (64 * k) * zt1w + zk1 = V1 /\ zt1w < 2 EXP 64 /\ zk1 < 2 EXP (64 * k))` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC BETA_RULE THEN
    FIRST_X_ASSUM(fun th -> if is_conj(concl th) then STRIP_ASSUME_TAC th else NO_TAC) THEN
    BETA_TAC THEN
    FIRST_X_ASSUM(fun t -> if is_eq(concl t) && rand(concl t) = `zt1w:num` &&
          (try fst(dest_const(fst(strip_comb(lhand(concl t))))) = "val" with _->false)
        then ASSUME_TAC(SYM t) else NO_TAC) THEN
    ASM_REWRITE_TAC[WORD_VAL] THEN CONJ_TAC THENL
     [REWRITE_TAC[VAL_BOUND_64];
      ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND]];
    ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  (* ===== 0x432 -> 0x49c : NEGADD2 (p-free, reused verbatim; p:=p+3 in the slot) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x49c`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word zt1w /\
        read RBP s = word q2 /\
        bignum_from_memory (m,k) s = b /\
        ?hh cf. bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
                zk1 + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
                read RCX s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
                read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2
                                  then 2 EXP 64 - 1 else 0)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10] ,,
      MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)]` THEN
    CONJ_TAC THENL
     [SUBSUMED_MAYCHANGE_TAC;
      MP_TAC(REWRITE_RULE[SOME_FLAGS]
        (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:num`;`h2:num`;`q2:num`;`word zt1w:int64`;
                 `p + 3`;`zk1:num`;`b:num`;`pc:num`;`stackpointer:int64`] BIGNUM_MOD_X86_NEGADD2)) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `val(word zt1w:int64) = zt1w` (fun th -> REWRITE_TAC[th]) THENL
       [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th ->
        MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
        EXISTS_TAC (rand(rator(rator(concl th)))) THEN
        CONJ_TAC THENL
         [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th])];
    ALL_TAC] THEN
  (* ===== 0x49c -> 0x4cb : peel existential, OPTADD_CLOSE_SEG (p-free) ===== *)
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. ?hh cf. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x49c) /\
        read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
          zk1 + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
        read RCX s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
        read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
        bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_EXISTS_PRE THEN GEN_TAC THEN
  MATCH_MP_TAC X86_ENSURES_EXISTS_PRE THEN GEN_TAC THEN
  GHOST_INTRO_TAC `zk2:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [RIP; RAX; RCX; RDX; RDI; R9; R10] ,,
    MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)]` THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x49c) /\
         read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
         read (memory :> bytes64 stackpointer) s = word k /\
         read R9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
         bignum_from_memory (z,k) s = zk2 /\ bignum_from_memory (m,k) s = b) /\
        (zk2 < 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
         zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk1 + q2 * 2 EXP (64 * k))` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC BETA_RULE THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND];
    ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`q2:num`;`zt1w:num`;`zk1:num`;`zk2:num`;`hh:num`;`cf:bool`;
             `b:num`;`a:num`;`p + 3`;`pc:num`;`stackpointer:int64`] X86_OPTADD_CLOSE_SEG)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(fun t -> if is_eq(concl t) && rand(concl t) = `V1:num`
      then REWRITE_TAC[SYM t] else NO_TAC) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
      EXISTS_TAC (rand(rator(rator(concl th)))) THEN
      CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th])]);;


(* ============================================================================
   x86_splice_217_4cb.ml -- compose the main division loop with the Stage-4 correction:
     BIGNUM_MOD_X86_217_TO_4CB (pc+0x217 -> pc+0x4cb  =>  bignum(z,k) = a MOD b)
       = BIGNUM_MOD_X86_MAINLOOP (0x217->0x37a, PDOWN wrap; V := a DIV 2^(61*NB) reduced mod b)
      ;; BIGNUM_MOD_X86_37A_TO_4CB (0x37a->0x4cb, Stage-4 corrections => a MOD b).
   Port of ARM BIGNUM_MOD_1A4_TO_428 (splice_308_428_dev.ml).  x86 main-loop entry is pc+0x217
   (ARM 0x1a4); Stage-4 splice tail is pc+0x37a->0x4cb.
   MAINLOOP POST (0x37a) now carries bytes_loaded + read RSP=stackpointer (cont128 enrichment) so the
   0x37a ENSURES_SEQUENCE leg + the 37A_TO_4CB PRE both have them.  At 0x37a: GHOST sp+8->Ztv, z-mem->zk,
   lift Ztv<2^64 (VAL_BOUND_64), zk<2^(64k) (BIGNUM_FROM_MEMORY_BOUND), cong/bound from MAINLOOP POST;
   then apply 37A_TO_4CB.
   Deps: BIGNUM_MOD_X86_MAINLOOP (x86_mainloop_wrap), BIGNUM_MOD_X86_37A_TO_4CB (x86_splice_37a_4cb),
     X86_ENSURES_PRE_DISCH (x86_splice_37a_4cb), ENSURES_*.  Load AFTER x86_splice_37a_4cb.
   ============================================================================ *)

let BIGNUM_MOD_X86_217_TO_4CB = prove
 (`!k z n x m a b w d p pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\ a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\ ~(b = 0) /\
      w < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ 61 <= p /\
      p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
      (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
      d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + w) * d <= 2 EXP 128 /\ 2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (x,8 * n) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      nonoverlapping (z,8 * k) (x,8 * n) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (x,8 * n) (stackpointer,72)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x217) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read RBX s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read R12 s = word 1 /\ read R13 s = word (p DIV 64 + 1) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 56))) s = word 61 /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s = a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (\s. read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt h8k hp64 hn hn1 ha hbk hb0 hw hbp hpb h1p hp61 hp3 hpk ht0lo ht0hi hdivid hd hdisj hup hlo hn1o hn2o hn3o hn4o hn5o hn6o hn7o hn8o hn9o" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== 0x217 -> 0x37a via MAINLOOP ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x37a`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read R13 s = word (p DIV 64 + 1) /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
         bignum_from_memory (z,k) s == a) (mod b) /\
        2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
         bignum_from_memory (z,k) s < b * 2 EXP 64 /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s =
          word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                  bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
      MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
      MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
      MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
      MAYCHANGE [memory :> bignum(z,k)] ,,
      MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events]` THEN
    CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
    (* weaken MAINLOOP's fat POST onto the intermediate via ENSURES_POSTCONDITION_THM, then apply
       MAINLOOP (its frame = the subsumed C').  The weaken's Q'==>intermediate is GEN+STRIP+ASM_REWRITE. *)
    MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `w:num`; `d:num`; `p:num`; `pc:num`; `stackpointer:int64`]
       BIGNUM_MOD_X86_MAINLOOP) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN
    DISCH_THEN(fun th ->
      EXISTS_TAC (rand(rator(concl th))) THEN
      CONJ_TAC THENL
       [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]);
    ALL_TAC] THEN
  (* ===== 0x37a -> 0x4cb via 37A_TO_4CB: GHOST sp+8/z to name Ztv/zk ===== *)
  GHOST_INTRO_TAC `Ztv:num` `\s. val(read (memory :> bytes64 (word_add stackpointer (word 8))) s)` THEN
  GHOST_INTRO_TAC `zk:num` `bignum_from_memory (z,k)` THEN
  (* strengthen PRE with 37A's numeric facts (ARM idiom).  CONJ1 weaken: GEN+STRIP exposes the PRE's
     `val(read sp+8 x)=Ztv`; ASM_REWRITE[WORD_VAL] gives read sp+8=word Ztv, VAL_BOUND_64 gives Ztv<2^64,
     BIGNUM_FROM_MEMORY_BOUND gives zk<2^(64k), cong/bound are PRE conjuncts -- all pointwise (NO MESON). *)
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x37a) /\
         read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
         read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
         read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
         read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
         read (memory :> bytes64 stackpointer) s = word k /\
         read (memory :> bytes64 (word_add stackpointer (word 64))) s =
           word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
         bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b) /\
        (Ztv < 2 EXP 64 /\ zk < 2 EXP (64 * k) /\
         (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
         2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64)` THEN
  CONJ_TAC THENL
   [(* weaken: intermediate x ==> (base) /\ (Ztv<2^64 /\ zk<2^(64k) /\ cong /\ bound).  Pointwise (NO
       MESON -- it hangs on the 32-asm x86 context).  After GEN+STRIP the intermediate conjuncts are asms
       incl `val(read sp+8 x)=Ztv` and `bignum(z,k) x=zk`.  cont129: verify these two asm forms and tune. *)
    (* cont129: prove the weaken via a WHOLE-GOAL backward rewrite (NOT per-conjunct forward derivation
       -- that left residuals).  After BETA+GEN+STRIP the assumptions are the intermediate-body conjuncts
       + the two ghost eqns `val(read sp+8 s)=Ztv` and `bignum(z,k) s=zk`.  Rewrite the goal by SYM of
       both (Ztv -> val(read sp+8 s), zk -> bignum(z,k) s) and WORD_VAL: base conjuncts then match the
       assumptions verbatim (ASM_REWRITE), and Ztv<2^64 / zk<2^(64k) fall to VAL_BOUND_64 / BFM_BOUND.
       All pointwise -- NO MESON (which hangs on the 32-asm x86 context).  Verified standalone (axioms=3). *)
    BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM(fun vf -> if is_eq(concl vf) && rand(concl vf) = `Ztv:num` &&
          (try fst(dest_const(fst(strip_comb(lhand(concl vf))))) = "val" with _->false)
        then FIRST_ASSUM(fun zf -> if is_eq(concl zf) && rand(concl zf) = `zk:num` &&
              (try fst(dest_const(fst(strip_comb(lhand(concl zf))))) = "bignum_from_memory" with _->false)
            then REWRITE_TAC[SYM vf; SYM zf; WORD_VAL] THEN
                 ASM_REWRITE_TAC[VAL_BOUND_64; BIGNUM_FROM_MEMORY_BOUND]
            else NO_TAC)
        else NO_TAC);
    ALL_TAC] THEN
  (* the strengthen's `(base)/\(facts)` PRE: PRE_DISCH peels the trailing s-free facts group as one `c`. *)
  MATCH_MP_TAC X86_ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  (* Prove 37A_TO_4CB's PRE hyps as ONE conjunction (context-provable), MATCH_MP into 37A (yields bare
     `ensures`), then ENSURES_PRECONDITION reconcile.  MP_TAC(MATCH_MP ...) avoids the pathological
     blanket ASM_REWRITE over the MP'd giant ensures-implication.  NB the SUBGOAL hyp conjunction MUST be
     alpha-equal to 37A_TO_4CB's PRE (same order; nonoverlaps use 1242 = 0x4da = LENGTH tmc so
     both parse identically and MATCH_MP unifies). *)
  (* Goal PRE now = 37A_TO_4CB's PRE (base reads) and all 37A numeric side-hyps are in context.
     Widen the 217 frame C down to 37A's frame (ENSURES_FRAME_SUBSUMED), then MATCH_MP_TAC 37A directly
     (goal PRE/POST/frame now match 37A's conclusion), leaving its ~24 hyps -> REPEAT CONJ + ASM_REWRITE
     (each a context assumption; NO ensures-lambda rewriting, so fast). *)
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
    MAYCHANGE [memory :> bignum(z,k)] ,,
    MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events]` THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:num`;`d:num`;`p:num`;`a:num`;`b:num`;`Ztv:num`;`zk:num`;
             `pc:num`;`stackpointer:int64`] BIGNUM_MOD_X86_37A_TO_4CB)) THEN
  REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[]);;


(* ============================================================================
   x86_splice_217_4cb_small.ml -- BIGNUM_MOD_X86_217_TO_4CB_SMALL (pc+0x217 -> pc+0x4cb, p<61).
   The p<61 variant of BIGNUM_MOD_X86_217_TO_4CB (x86_splice_217_4cb.ml):
     BIGNUM_MOD_X86_MAINLOOP (0x217->0x37a, PDOWN wrap; MAINLOOP needs only 1<=p)
    ;; BIGNUM_MOD_X86_37A_TO_4CB_SMALL (0x37a->0x4cb, p<61 Stage-4 corrections => a MOD b).
   x86 analog of ARM BIGNUM_MOD_1A4_TO_428_SMALL (negadd_small.ml:305).

   IDENTICAL proof to the LARGE 217_TO_4CB except (a) PRE `61 <= p` -> `p < 61`, (b) the final-leg MP uses
   BIGNUM_MOD_X86_37A_TO_4CB_SMALL instead of BIGNUM_MOD_X86_37A_TO_4CB.  The MAINLOOP leg is unchanged
   (MAINLOOP's precond has 1<=p, no 61<=p).
   Deps: BIGNUM_MOD_X86_MAINLOOP (x86_mainloop_wrap), BIGNUM_MOD_X86_37A_TO_4CB_SMALL (x86_splice_37a_4cb_
     small), X86_ENSURES_PRE_DISCH (x86_splice_37a_4cb), ENSURES_*.  Load AFTER x86_splice_37a_4cb_small.
   ============================================================================ *)

let BIGNUM_MOD_X86_217_TO_4CB_SMALL = prove
 (`!k z n x m a b w d p pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\ a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\ ~(b = 0) /\
      w < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ p < 61 /\
      p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
      (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
      d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + w) * d <= 2 EXP 128 /\ 2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (x,8 * n) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      nonoverlapping (z,8 * k) (x,8 * n) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (x,8 * n) (stackpointer,72)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x217) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read RBX s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read R12 s = word 1 /\ read R13 s = word (p DIV 64 + 1) /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
            read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
            read (memory :> bytes64 (word_add stackpointer (word 56))) s = word 61 /\
            read (memory :> bytes64 (word_add stackpointer (word 64))) s =
              word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
              bignum_from_memory (z,k) s = a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (\s. read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
        MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt h8k hp64 hn hn1 ha hbk hb0 hw hbp hpb h1p hp61 hp3 hpk ht0lo ht0hi hdivid hd hdisj hup hlo hn1o hn2o hn3o hn4o hn5o hn6o hn7o hn8o hn9o" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== 0x217 -> 0x37a via MAINLOOP (unchanged; MAINLOOP needs only 1<=p) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x37a`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read R13 s = word (p DIV 64 + 1) /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        (2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
         bignum_from_memory (z,k) s == a) (mod b) /\
        2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
         bignum_from_memory (z,k) s < b * 2 EXP 64 /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s =
          word (((2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
                  bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R14; R15] ,,
      MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
      MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
      MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
      MAYCHANGE [memory :> bignum(z,k)] ,,
      MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events]` THEN
    CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
    MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `w:num`; `d:num`; `p:num`; `pc:num`; `stackpointer:int64`]
       BIGNUM_MOD_X86_MAINLOOP) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN
    DISCH_THEN(fun th ->
      EXISTS_TAC (rand(rator(concl th))) THEN
      CONJ_TAC THENL
       [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]);
    ALL_TAC] THEN
  (* ===== 0x37a -> 0x4cb via 37A_TO_4CB_SMALL: GHOST sp+8/z to name Ztv/zk ===== *)
  GHOST_INTRO_TAC `Ztv:num` `\s. val(read (memory :> bytes64 (word_add stackpointer (word 8))) s)` THEN
  GHOST_INTRO_TAC `zk:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\ read RIP s = word (pc + 0x37a) /\
         read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
         read (memory :> bytes64 (word_add stackpointer (word 40))) s = word w /\
         read (memory :> bytes64 (word_add stackpointer (word 48))) s = word p /\
         read (memory :> bytes64 (word_add stackpointer (word 8))) s = word Ztv /\
         read (memory :> bytes64 stackpointer) s = word k /\
         read (memory :> bytes64 (word_add stackpointer (word 64))) s =
           word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
         bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b) /\
        (Ztv < 2 EXP 64 /\ zk < 2 EXP (64 * k) /\
         (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
         2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64)` THEN
  CONJ_TAC THENL
   [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM(fun vf -> if is_eq(concl vf) && rand(concl vf) = `Ztv:num` &&
          (try fst(dest_const(fst(strip_comb(lhand(concl vf))))) = "val" with _->false)
        then FIRST_ASSUM(fun zf -> if is_eq(concl zf) && rand(concl zf) = `zk:num` &&
              (try fst(dest_const(fst(strip_comb(lhand(concl zf))))) = "bignum_from_memory" with _->false)
            then REWRITE_TAC[SYM vf; SYM zf; WORD_VAL] THEN
                 ASM_REWRITE_TAC[VAL_BOUND_64; BIGNUM_FROM_MEMORY_BOUND]
            else NO_TAC)
        else NO_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC X86_ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [RIP; RAX; RCX; RDX; RBP; RDI; R9; R10; R11; R13; R14; R15] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
    MAYCHANGE [memory :> bignum(z,k)] ,,
    MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events]` THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:num`;`d:num`;`p:num`;`a:num`;`b:num`;`Ztv:num`;`zk:num`;
             `pc:num`;`stackpointer:int64`] BIGNUM_MOD_X86_37A_TO_4CB_SMALL)) THEN
  REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[]);;


(* ============================================================================
   x86_splice_7c_4cb.ml -- BIGNUM_MOD_X86_7C_TO_4CB.
   The end-to-end DEV composition pc+0x7c (finder POST) -> pc+0x4cb
   (final: bignum(z,k) = a MOD b), for the nge0 (~(b=0)) path, p := bitsize b.
   x86 analog of ARM BIGNUM_MOD_68_TO_428 (splice_68_428_dev.ml).

     0x7c  -> 0xbe   BIGNUM_MOD_X86_WINUP_D    (window+roundup, exposes roundup disjunction + R11=RBX)
     0xbe  -> 0x186  BIGNUM_MOD_X86_RECIP_WIDE (word_recip; real-division bracket on val t0=RBX)
     0x186 -> 0x217  BIGNUM_MOD_X86_PREHEADER  (n/61 setup; full mainloop-entry invariant)
     0x217 -> 0x4cb  BIGNUM_MOD_X86_217_TO_4CB (main loop + negadd1/2 + optadd + MOD-close)

   x86<->ARM reg/slot map: X5->RBX (roundup t0; WINUP_D gives R11=RBX so RECIP_WIDE's RBX=t0/\R11=t0 PRE),
   X20->sp+48 (p=bitsize b), X21->sp+40 (w), X23->sp+8 (=word 0), X15->sp+64 (window), X12->R13, X19->R12,
   X17->sp+56.  Spectators sp+8/16/24/32 (=0/n/x/m) threaded through WINUP_D + RECIP_WIDE POSTs (both
   preserve them: WINUP writes sp+48, RECIP writes sp+40) so PREHEADER's PRE has them.

   RECIP_CLUSTER (scaffold, arch-indep) assembles the integer recip-of-d preconds (d:=val t0, w:=val(sp+40),
   p:=bitsize b) from the roundup disjunction + real bracket + ~(b=0); feeds 217_TO_4CB directly.

   FULL (both paths, UNCONDITIONAL): the final leg case-splits on 61<=bitsize b, dispatching 217_TO_4CB
   (LARGE) or 217_TO_4CB_SMALL (p<61); NO 61<=bitsize b precondition.

   NB precond n < 2^58 - 1.  Deps: WINUP_D, RECIP_WIDE, PREHEADER, RECIP_CLUSTER, 217_TO_4CB,
   217_TO_4CB_SMALL.  Load AFTER x86_splice_217_4cb + x86_splice_217_4cb_small + x86_winup_d +
   x86_preheader_full + x86_recip_wide_candidate.
   ============================================================================ *)

let BIGNUM_MOD_X86_7C_TO_4CB = prove
 (`!k z n x m a b pc stackpointer.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\
      a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\ ~(b = 0) /\
      nonoverlapping (word pc,0x4da) (z,8 * k) /\
      nonoverlapping (word pc,0x4da) (m,8 * k) /\
      nonoverlapping (word pc,0x4da) (x,8 * n) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      nonoverlapping (z,8 * k) (x,8 * n) /\
      nonoverlapping (z,8 * k) (stackpointer,72) /\
      nonoverlapping (m,8 * k) (stackpointer,72) /\
      nonoverlapping (x,8 * n) (stackpointer,72)
      ==> ensures x86
       (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
            read RIP s = word (pc + 0x7c) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
            read (memory :> bytes64 stackpointer) s = word k /\
            read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
            read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
            read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
            read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s = 0 /\
            (read R9 s = word 0 /\ read RAX s = word 0 /\ read RDX s = word 0 /\
             (!j. j < k ==> bigdigit b j = 0)
             \/
             val(read R9 s) < k /\
             ~(bigdigit b (val(read R9 s)) = 0) /\
             read RAX s = word(bigdigit b (val(read R9 s))) /\
             read RDX s = word(if val(read R9 s) = 0 then 0 else bigdigit b (val(read R9 s) - 1)) /\
             (!j. val(read R9 s) < j /\ j < k ==> bigdigit b j = 0)))
       (\s. read RIP s = word (pc + 0x4cb) /\
            read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
            read (memory :> bytes64 stackpointer) s = word k /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11; RBX; R12; R13; R14; R15] ,,
        MAYCHANGE [memory :> bytes(stackpointer,72)] ,,
        MAYCHANGE [memory :> bignum(z,k)] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* global bounds used repeatedly. *)
  SUBGOAL_THEN `k < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `n < 2 EXP 60` ASSUME_TAC THENL
   [UNDISCH_TAC `n < 2 EXP 58 - 1` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bitsize b <= 64 * k` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[BITSIZE_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `bitsize b < 2 EXP 64` ASSUME_TAC THENL
   [TRANS_TAC LET_TRANS `64 * k` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `bitsize b + 3 < 2 EXP 64` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2:num) EXP 64 = 64 * 2 EXP 58` ASSUME_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
      [`(2:num) EXP 64 = 64 * 2 EXP 58`; `bitsize b <= 64 * k`; `k < 2 EXP 58`] THEN ARITH_TAC;
    ALL_TAC] THEN
  (*** 0x7c -> 0xbe via WINUP_D (carries roundup disjunction + R11=RBX + spectators) ***)
  ENSURES_SEQUENCE_TAC `pc + 0xbe`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (bitsize b) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0 /\
        read R11 s = read RBX s /\
        bit 63 (read RBX s) /\
        (val(read RBX s) = (b * 2 EXP 64) DIV 2 EXP (bitsize b) + 1 \/
         (b * 2 EXP 64) DIV 2 EXP (bitsize b) = 2 EXP 64 - 1 /\
         val(read RBX s) = 2 EXP 64 - 1)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11; RBX] ,,
      MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,,
      MAYCHANGE [memory :> bytes(stackpointer,72)]` THEN
    CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_WINUP_D) THEN
    ASM_REWRITE_TAC[SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  (*** 0xbe -> 0x186 via RECIP_WIDE.  GHOST t0:=read RBX; PRE needs RBX=t0/\R11=t0 (R11=RBX from WINUP_D).
       The roundup disjunction on val(read RBX)=val t0 becomes a free fact carried forward. ***)
  GHOST_INTRO_TAC `t0:int64` `read RBX` THEN
  GLOBALIZE_PRECONDITION_TAC THEN
  ENSURES_SEQUENCE_TAC `pc + 0x186`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (bitsize b) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0 /\
        (bit 63 (t0:int64)
         ==> &2 pow 64 + &(val(read (memory :> bytes64 (word_add stackpointer (word 40))) s)) <
               &2 pow 128 / &(val t0) /\
             &2 pow 128 / &(val t0) <=
               &2 pow 64 + &(val(read (memory :> bytes64 (word_add stackpointer (word 40))) s)) + &1)` THEN
  CONJ_TAC THENL
   [ENSURES_PRECONDITION_TAC
     `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
          read RIP s = word (pc + 0xbe) /\
          read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
          read (memory :> bytes64 stackpointer) s = word k /\
          read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
          read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
          read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
          read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
          read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (bitsize b) /\
          read RBX s = t0 /\ read R11 s = t0 /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          bignum_from_memory (z,k) s = 0` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[] THEN X_GEN_TAC `s:x86state` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      (* R11=t0 from R11=RBX (WINUP_D) + RBX=t0 (ghost). *)
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC
       `MAYCHANGE [RIP; RAX; RCX; RDX; RBX; R9; R11] ,,
        MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bytes(stackpointer,72)]` THEN
      CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
      MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                    `a:num`; `b:num`; `bitsize b`; `t0:int64`; `pc:num`; `stackpointer:int64`]
             BIGNUM_MOD_X86_RECIP_WIDE) THEN
      ASM_REWRITE_TAC[SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (*** 0x186 -> 0x217 via PREHEADER.  GHOST wr:=read sp+40 (int64, ARM's X21=w analog); thread w:=val wr
       (num) so PREHEADER's `sp+40=word(val wr)`=wr via WORD_VAL, and `val wr<2^64` is VAL_BOUND_64. ***)
  GHOST_INTRO_TAC `wr:int64` `read (memory :> bytes64 (word_add stackpointer (word 40)))` THEN
  GLOBALIZE_PRECONDITION_TAC THEN
  ENSURES_SEQUENCE_TAC `pc + 0x217`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read RBX s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
        read R12 s = word 1 /\ read R13 s = word (bitsize b DIV 64 + 1) /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        read (memory :> bytes64 (word_add stackpointer (word 40))) s = word (val(wr:int64)) /\
        read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (bitsize b) /\
        read (memory :> bytes64 (word_add stackpointer (word 56))) s = word 61 /\
        read (memory :> bytes64 (word_add stackpointer (word 64))) s =
          word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP (bitsize b)) MOD 2 EXP 64) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        2 EXP (64 * k) * val(read (memory :> bytes64 (word_add stackpointer (word 8))) s) +
          bignum_from_memory (z,k) s = a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1))` THEN
  CONJ_TAC THENL
   [ENSURES_PRECONDITION_TAC
     `\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
          read RIP s = word (pc + 0x186) /\
          read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
          read (memory :> bytes64 stackpointer) s = word k /\
          read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
          read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
          read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
          read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
          read (memory :> bytes64 (word_add stackpointer (word 40))) s = word (val(wr:int64)) /\
          read (memory :> bytes64 (word_add stackpointer (word 48))) s = word (bitsize b) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          bignum_from_memory (z,k) s = 0` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[] THEN X_GEN_TAC `s:x86state` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      (* sp+40 = word(val wr) = wr via WORD_VAL, and the PRE has read sp+40 = wr. *)
      ASM_REWRITE_TAC[WORD_VAL];
      MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC
       `MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11; RBX; R12; R13] ,,
        MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bytes(stackpointer,72); memory :> bytes(z,8*k)]` THEN
      CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
      MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                    `a:num`; `b:num`; `val(wr:int64)`; `bitsize b`; `pc:num`; `stackpointer:int64`]
             BIGNUM_MOD_X86_PREHEADER) THEN
      ASM_REWRITE_TAC[SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (*** 0x217 -> 0x4cb: assemble RECIP_CLUSTER (d:=val t0, w:=wr, p:=bitsize b) then apply 217_TO_4CB with
       w:=val wr.  The carried bracket asm is on val(sp+40)=val wr; RECIP_CLUSTER's `val w` (w=wr) matches
       verbatim, and 217's `w<2^64` becomes `val wr<2^64` = VAL_BOUND_64.  No `wv<2^64` obligation. ***)
  MP_TAC(SPECL [`b:num`; `t0:int64`; `wr:int64`] RECIP_CLUSTER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* widen the outer frame down to the (shared) 217_TO_4CB frame, then CASE-SPLIT on 61<=bitsize b:
     LARGE leg = 217_TO_4CB, SMALL leg = 217_TO_4CB_SMALL (identical PRE/POST/frame, differ only in the
     61<=p vs p<61 precond).  Both close by MP + POST-weaken.  This DROPS the 61<=bitsize b precondition. *)
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [RIP; RAX; RCX; RDX; RBX; RBP; RDI; R9; R10; R11; R12; R13; R14; R15] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 8))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 48))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 56))] ,,
    MAYCHANGE [memory :> bytes64 (word_add stackpointer (word 64))] ,,
    MAYCHANGE [memory :> bignum(z,k)] ,,
    MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events]` THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `61 <= bitsize b` THENL
   [(* LARGE: 61 <= bitsize b *)
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `val(wr:int64)`; `val(t0:int64)`; `bitsize b`; `pc:num`; `stackpointer:int64`]
                 BIGNUM_MOD_X86_217_TO_4CB) THEN
    ASM_REWRITE_TAC[SOME_FLAGS] THEN REWRITE_TAC[VAL_BOUND_64] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[VAL_BOUND_64] THEN
      ASM_SIMP_TAC[ARITH_RULE `1 <= bitsize b <=> ~(bitsize b = 0)`] THEN
      UNDISCH_TAC `61 <= bitsize b` THEN ARITH_TAC;
      DISCH_THEN(fun dth ->
        MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
        EXISTS_TAC (rand(rator(concl dth))) THEN
        CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC dth])];
    (* SMALL: ~(61 <= bitsize b), i.e. bitsize b < 61 *)
    SUBGOAL_THEN `bitsize b < 61` ASSUME_TAC THENL
     [UNDISCH_TAC `~(61 <= bitsize b)` THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `val(wr:int64)`; `val(t0:int64)`; `bitsize b`; `pc:num`; `stackpointer:int64`]
                 BIGNUM_MOD_X86_217_TO_4CB_SMALL) THEN
    ASM_REWRITE_TAC[SOME_FLAGS] THEN REWRITE_TAC[VAL_BOUND_64] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[VAL_BOUND_64] THEN
      ASM_SIMP_TAC[ARITH_RULE `1 <= bitsize b <=> ~(bitsize b = 0)`];
      DISCH_THEN(fun dth ->
        MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
        EXISTS_TAC (rand(rator(concl dth))) THEN
        CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC dth])]]);;


(* ============================================================================
   x86_correct.ml -- BIGNUM_MOD_X86_CORRECT (pc+0xe -> pc+0x4cb) + SUBROUTINE.
   Full end-to-end correctness of the x86 bignum_mod core.

   PROLOGUE DECODE (tmc bytes 0x0..0x12): 0x0 push rbx; 0x1 push rbp; 0x2 push r12; 0x4 push r13;
   0x6 push r14; 0x8 push r15 (6 pushes = 48B); 0xa `48 83 ec 48` sub rsp,0x48 (72B); 0xe
   `48 89 3c 24` mov [rsp],rdi (stash kk=k at sp+0); 0x12 INIT.  Standard prologue = pushes+sub
   ends at 0xe; the kk-stash is the FIRST core instruction.

   Two-lemma structure (avoids W64_GEN word/val juggling in the wrapper):
     BIGNUM_MOD_X86_CORE_12 : pc+0x12 -> pc+0x4cb, PRE has sp+0 = word(val k) already stashed.
       Composes  INIT(0x12->0x3d) ;; n=0 early-out ;; bridge(0x3d->0x46) ;; FINDER(0x46->0x7c) ;;
       7C_TO_4CB(0x7c->0x4cb => a MOD b, both p-regimes).
     BIGNUM_MOD_X86_CORRECT : pc+0xe -> pc+0x4cb, thin wrapper = stash-leg(0xe->0x12, mov [rsp],rdi
       gives sp+0 = read RDI = k = word(val k) via WORD_VAL) ;; MP CORE_12.

   CONVENTION (matches montsqr): _CORRECT exits at 0x4cb = Lbignum_mod_end (start of teardown
   `add rsp,0x48`), RSP still = stackpointer (RSP NOT in frame).  SUBROUTINE via
   X86_PROMOTE_RETURN_STACK_TAC bignum_mod_tmc BIGNUM_MOD_X86_CORRECT [RBX;RBP;R12;R13;R14;R15] 120
   -- off = 6*8 + 72 = 120 (push bytes + sub imm; cf montsqr 5*8+72=112); n0=6, 8*6=48<>120 so 7
   prologue insns (6 pushes + sub) are stepped, landing at 0xe.

   n=0 test decode: 0x3d `48 85 D2` test rdx,rdx (->0x40); 0x40 `0F 84 85 04 00 00` jz rel32,
   taken-> 0x46+0x485 = 0x4cb, not-taken-> 0x46 (FINDER xor block).

   Port of ARM BIGNUM_MOD_CORRECT (ci_correct_edit.ml).  Deps: BIGNUM_MOD_X86_INIT (enriched:
   R8=m + x/m bignums + full frame), BIGNUM_MOD_X86_FINDER, BIGNUM_MOD_X86_7C_TO_4CB.  Load LAST.
   ============================================================================ *)

(* ---- CORE: 0x12 -> 0x4cb (kk already stashed at sp+0).  The proven end-to-end composition. ---- *)
let BIGNUM_MOD_X86_CORE_12 = prove
 (`!k z n x m a b pc stackpointer.
      nonoverlapping (word pc,0x4da) (z,8 * val k) /\
      nonoverlapping (word pc,0x4da) (x,8 * val n) /\
      nonoverlapping (word pc,0x4da) (m,8 * val k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * val k) (stackpointer,72) /\
      nonoverlapping (x,8 * val n) (stackpointer,72) /\
      nonoverlapping (m,8 * val k) (stackpointer,72) /\
      nonoverlapping (z,8 * val k) (x,8 * val n) /\
      nonoverlapping (z,8 * val k) (m,8 * val k) /\
      ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
      ==> ensures x86
           (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
                read RIP s = word(pc + 0x12) /\
                read RSP s = stackpointer /\
                read (memory :> bytes64 stackpointer) s = word(val k) /\
                C_ARGUMENTS [k;z;n;x;m] s /\
                bignum_from_memory (x,val n) s = a /\
                bignum_from_memory (m,val k) s = b)
           (\s. read RIP s = word(pc + 0x4cb) /\
                (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
           (MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11;
                       RBX; R12; R13; R14; R15] ,,
            MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
            MAYCHANGE [memory :> bignum(z,val k); memory :> bytes(stackpointer,72)])`,
  W64_GEN_TAC `k:num` THEN X_GEN_TAC `z:int64` THEN W64_GEN_TAC `n:num` THEN
  MAP_EVERY X_GEN_TAC [`x:int64`; `m:int64`; `a:num`; `b:num`; `pc:num`] THEN
  X_GEN_TAC `stackpointer:int64` THEN
  REWRITE_TAC[NONOVERLAPPING_CLAUSES; C_ARGUMENTS; SOME_FLAGS] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  BIGNUM_TERMRANGE_TAC `n:num` `a:num` THEN
  BIGNUM_TERMRANGE_TAC `k:num` `b:num` THEN
  (*** Stage 1: INIT 0x12 -> 0x3d (enriched INIT: full CORRECT frame + x/m bignums + R8=m) ***)
  ENSURES_SEQUENCE_TAC `pc + 0x3d`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read RDX s = word n /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`word k:int64`; `z:int64`; `word n:int64`; `x:int64`; `m:int64`;
                   `a:num`; `b:num`; `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_INIT) THEN
    ASM_REWRITE_TAC[NONOVERLAPPING_CLAUSES; C_ARGUMENTS; SOME_FLAGS; VAL_WORD_GALOIS] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[DE_MORGAN_THM] THEN DISJ2_TAC THEN
    REWRITE_TAC[GSYM VAL_EQ_0] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (*** Stage 2a: n = 0 early-out.  a=0, a MOD b = 0.  test rdx,rdx; jz Lend@0x4cb (jz taken). ***)
  ASM_CASES_TAC `n = 0` THENL
   [UNDISCH_THEN `n = 0` SUBST_ALL_TAC THEN
    SUBGOAL_THEN `a = 0` SUBST_ALL_TAC THENL
     [UNDISCH_TAC `a < 2 EXP (64 * 0)` THEN CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[MOD_0] THEN X86_SIM_TAC BIGNUM_MOD_EXEC (1--2);
    ALL_TAC] THEN
  (*** Stage 2b-0: n<>0 fall-through 0x3d -> 0x46 (test rdx,rdx; jz not-taken) ***)
  ENSURES_SEQUENCE_TAC `pc + 0x46`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0` THEN
  CONJ_TAC THENL
   [X86_SIM_TAC BIGNUM_MOD_EXEC (1--2);
    ALL_TAC] THEN
  (*** Stage 2b-i: FINDER 0x46 -> 0x7c (FRAME_SUBSUMED to FINDER frame; ENSURES_SEQUENCE reorders
       injected bytes_loaded/RIP so weaken via ENSURES_POSTCONDITION_THM). ***)
  ENSURES_SEQUENCE_TAC `pc + 0x7c`
   `\s. read RSP s = stackpointer /\ read RSI s = z /\ read R8 s = m /\ read RDI s = word k /\
        read (memory :> bytes64 stackpointer) s = word k /\
        read (memory :> bytes64 (word_add stackpointer (word 8))) s = word 0 /\
        read (memory :> bytes64 (word_add stackpointer (word 16))) s = word n /\
        read (memory :> bytes64 (word_add stackpointer (word 24))) s = x /\
        read (memory :> bytes64 (word_add stackpointer (word 32))) s = m /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0 /\
        (read R9 s = word 0 /\ read RAX s = word 0 /\ read RDX s = word 0 /\
         (!j. j < k ==> bigdigit b j = 0)
         \/
         val(read R9 s) < k /\ ~(bigdigit b (val(read R9 s)) = 0) /\
         read RAX s = word(bigdigit b (val(read R9 s))) /\
         read RDX s = word(if val(read R9 s) = 0 then 0 else bigdigit b (val(read R9 s) - 1)) /\
         (!j. val(read R9 s) < j /\ j < k ==> bigdigit b j = 0))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11] ,,
      MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
      MAYCHANGE [memory :> bignum(z,k)]` THEN
    CONJ_TAC THENL [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`; `a:num`; `b:num`; `pc:num`;
                  `stackpointer:int64`] BIGNUM_MOD_X86_FINDER) THEN
    REWRITE_TAC[NONOVERLAPPING_CLAUSES] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN (UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      DISCH_THEN(fun dth ->
        MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
        EXISTS_TAC (rand(rator(concl dth))) THEN
        CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC dth])];
    ALL_TAC] THEN
  (*** Stage 2c: 7C_TO_4CB 0x7c -> 0x4cb (=> a MOD b).  FRAME_SUBSUMED to 7C_TO_4CB's frame
       (keep SOME_FLAGS folded for verbatim match), MP + ANTS, then POST-weaken. ***)
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11; RBX; R12; R13; R14; R15] ,,
    MAYCHANGE [memory :> bytes(stackpointer,72)] ,,
    MAYCHANGE [memory :> bignum(z,k)] ,,
    MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events]` THEN
  CONJ_TAC THENL [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`; `a:num`; `b:num`; `pc:num`;
                `stackpointer:int64`] BIGNUM_MOD_X86_7C_TO_4CB) THEN
  REWRITE_TAC[NONOVERLAPPING_CLAUSES] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN
    TRY(UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC) THEN
    TRY(UNDISCH_TAC `~(n = 0)` THEN ARITH_TAC) THEN
    TRY(MP_TAC(ISPECL [`2 EXP 64`; `pc:num`; `1242`; `val(z:int64)`; `8 * k`]
          NONOVERLAPPING_IMP_SMALL_RIGHT_ALT) THEN
        ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC);
    DISCH_THEN(fun dth ->
      MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
      EXISTS_TAC (rand(rator(concl dth))) THEN
      CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC dth])]);;


(* ---- CORRECT: 0xe -> 0x4cb.  Thin wrapper = stash-leg (mov [rsp],rdi) ;; MP CORE_12. ---- *)
let BIGNUM_MOD_X86_CORRECT = prove
 (`!k z n x m a b pc stackpointer.
      nonoverlapping (word pc,0x4da) (z,8 * val k) /\
      nonoverlapping (word pc,0x4da) (x,8 * val n) /\
      nonoverlapping (word pc,0x4da) (m,8 * val k) /\
      nonoverlapping (word pc,0x4da) (stackpointer,72) /\
      nonoverlapping (z,8 * val k) (stackpointer,72) /\
      nonoverlapping (x,8 * val n) (stackpointer,72) /\
      nonoverlapping (m,8 * val k) (stackpointer,72) /\
      nonoverlapping (z,8 * val k) (x,8 * val n) /\
      nonoverlapping (z,8 * val k) (m,8 * val k) /\
      ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
      ==> ensures x86
           (\s. bytes_loaded s (word pc) (BUTLAST bignum_mod_tmc) /\
                read RIP s = word(pc + 0xe) /\
                read RSP s = stackpointer /\
                C_ARGUMENTS [k;z;n;x;m] s /\
                bignum_from_memory (x,val n) s = a /\
                bignum_from_memory (m,val k) s = b)
           (\s. read RIP s = word(pc + 0x4cb) /\
                (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
           (MAYCHANGE [RIP; RAX; RCX; RDX; RSI; RDI; RBP; R8; R9; R10; R11;
                       RBX; R12; R13; R14; R15] ,,
            MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
            MAYCHANGE [memory :> bignum(z,val k); memory :> bytes(stackpointer,72)])`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[NONOVERLAPPING_CLAUSES; C_ARGUMENTS; SOME_FLAGS] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (*** Stage 0: kk stash 0xe -> 0x12 (mov [rsp],rdi -> sp+0 = read RDI = k = word(val k)). ***)
  ENSURES_SEQUENCE_TAC `pc + 0x12`
   `\s. read RIP s = word(pc + 0x12) /\ read RSP s = stackpointer /\
        read (memory :> bytes64 stackpointer) s = word(val(k:int64)) /\
        C_ARGUMENTS [k;z;n;x;m] s /\
        bignum_from_memory (x,val n) s = a /\
        bignum_from_memory (m,val k) s = b` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[C_ARGUMENTS] THEN X86_SIM_TAC BIGNUM_MOD_EXEC (1--1) THEN
    ASM_REWRITE_TAC[WORD_VAL];
    (* MP CORE_12 for 0x12 -> 0x4cb.  ENSURES_SEQUENCE injects a 2nd read RIP=word(pc+18) clause
       alongside our explicit one; absorb via ENSURES_PRECONDITION_THM (X_GEN + STRIP + ASM_REWRITE
       proves our-PRE ==> CORE_12-PRE), then ACCEPT CORE_12. *)
    MP_TAC(SPECL [`k:int64`; `z:int64`; `n:int64`; `x:int64`; `m:int64`; `a:num`; `b:num`;
                  `pc:num`; `stackpointer:int64`] BIGNUM_MOD_X86_CORE_12) THEN
    ASM_REWRITE_TAC[NONOVERLAPPING_CLAUSES; SOME_FLAGS] THEN
    DISCH_THEN(fun cth ->
      MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
      EXISTS_TAC (rand(rator(rator(concl cth)))) THEN
      CONJ_TAC THENL
       [REWRITE_TAC[] THEN X_GEN_TAC `s:x86state` THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
        ACCEPT_TAC cth])]);;


(* ------------------------------------------------------------------------- *)
(* Subroutine-level correctness (System V ABI).                              *)
(*                                                                           *)
(* BIGNUM_MOD_X86_CORRECT (above) is the core correctness at the post-       *)
(* prologue entry pc+0xe / teardown-entry exit pc+0x4cb.  X86_PROMOTE_RETURN_ *)
(* STACK_TAC synthesizes the 6 callee-save pushes + `sub rsp,0x48` prologue  *)
(* and the matching `add rsp,0x48` + 6 pops + ret epilogue (frame offset     *)
(* 120 = 6*8 push bytes + 72 sub immediate).                                 *)
(* ------------------------------------------------------------------------- *)

let BIGNUM_MOD_NOIBT_SUBROUTINE_CORRECT = prove
 (`!k z n x m a b pc stackpointer returnaddress.
      nonoverlapping (word pc,LENGTH bignum_mod_tmc) (z,8 * val k) /\
      nonoverlapping (word pc,LENGTH bignum_mod_tmc) (x,8 * val n) /\
      nonoverlapping (word pc,LENGTH bignum_mod_tmc) (m,8 * val k) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (z,8 * val k) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (x,8 * val n) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (m,8 * val k) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (word pc,LENGTH bignum_mod_tmc) /\
      nonoverlapping (z,8 * val k) (x,8 * val n) /\
      nonoverlapping (z,8 * val k) (m,8 * val k) /\
      ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
      ==> ensures x86
           (\s. bytes_loaded s (word pc) bignum_mod_tmc /\
                read RIP s = word pc /\
                read RSP s = stackpointer /\
                read (memory :> bytes64 stackpointer) s = returnaddress /\
                C_ARGUMENTS [k;z;n;x;m] s /\
                bignum_from_memory (x,val n) s = a /\
                bignum_from_memory (m,val k) s = b)
           (\s. read RIP s = returnaddress /\
                read RSP s = word_add stackpointer (word 8) /\
                (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
           (MAYCHANGE [RSP] ,, MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
            MAYCHANGE [memory :> bignum(z,val k)] ,,
            MAYCHANGE [memory :> bytes(word_sub stackpointer (word 120),120)])`,
  X86_PROMOTE_RETURN_STACK_TAC bignum_mod_tmc BIGNUM_MOD_X86_CORRECT
   `[RBX; RBP; R12; R13; R14; R15]` 120);;

let BIGNUM_MOD_SUBROUTINE_CORRECT = prove
 (`!k z n x m a b pc stackpointer returnaddress.
      nonoverlapping (word pc,LENGTH bignum_mod_mc) (z,8 * val k) /\
      nonoverlapping (word pc,LENGTH bignum_mod_mc) (x,8 * val n) /\
      nonoverlapping (word pc,LENGTH bignum_mod_mc) (m,8 * val k) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (z,8 * val k) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (x,8 * val n) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (m,8 * val k) /\
      nonoverlapping (word_sub stackpointer (word 120),128) (word pc,LENGTH bignum_mod_mc) /\
      nonoverlapping (z,8 * val k) (x,8 * val n) /\
      nonoverlapping (z,8 * val k) (m,8 * val k) /\
      ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
      ==> ensures x86
           (\s. bytes_loaded s (word pc) bignum_mod_mc /\
                read RIP s = word pc /\
                read RSP s = stackpointer /\
                read (memory :> bytes64 stackpointer) s = returnaddress /\
                C_ARGUMENTS [k;z;n;x;m] s /\
                bignum_from_memory (x,val n) s = a /\
                bignum_from_memory (m,val k) s = b)
           (\s. read RIP s = returnaddress /\
                read RSP s = word_add stackpointer (word 8) /\
                (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
           (MAYCHANGE [RSP] ,, MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
            MAYCHANGE [memory :> bignum(z,val k)] ,,
            MAYCHANGE [memory :> bytes(word_sub stackpointer (word 120),120)])`,
  MATCH_ACCEPT_TAC(ADD_IBT_RULE BIGNUM_MOD_NOIBT_SUBROUTINE_CORRECT));;

(* ------------------------------------------------------------------------- *)
(* Correctness of Windows ABI version.                                       *)
(*                                                                           *)
(* The Windows machine code is the same source assembled with WINDOWS_ABI=1: *)
(* a shim (push rdi; push rsi; move the four Windows argument registers into  *)
(* the System V positions; load the 5th argument from the shadow-space slot)  *)
(* wrapping the System V body, with a matching pop rsi/pop rdi in the tail.    *)
(* ------------------------------------------------------------------------- *)

let bignum_mod_windows_mc = define_from_elf
   "bignum_mod_windows_mc" "x86/generic/bignum_mod.obj";;

let bignum_mod_windows_tmc = define_trimmed "bignum_mod_windows_tmc" bignum_mod_windows_mc;;

let BIGNUM_MOD_NOIBT_WINDOWS_SUBROUTINE_CORRECT = prove
 (`!k z n x m a b pc stackpointer returnaddress.
      ALL (nonoverlapping (z,8 * val k))
          [(word pc,LENGTH bignum_mod_windows_tmc);
           (word_sub stackpointer (word 136),144)] /\
      ALL (nonoverlapping (word_sub stackpointer (word 136),136))
          [(word pc,LENGTH bignum_mod_windows_tmc); (x,8 * val n); (m,8 * val k)] /\
      nonoverlapping (word pc,LENGTH bignum_mod_windows_tmc) (x,8 * val n) /\
      nonoverlapping (word pc,LENGTH bignum_mod_windows_tmc) (m,8 * val k) /\
      nonoverlapping (z,8 * val k) (x,8 * val n) /\
      nonoverlapping (z,8 * val k) (m,8 * val k) /\
      ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
      ==> ensures x86
           (\s. bytes_loaded s (word pc) bignum_mod_windows_tmc /\
                read RIP s = word pc /\
                read RSP s = stackpointer /\
                read (memory :> bytes64 stackpointer) s = returnaddress /\
                WINDOWS_C_ARGUMENTS [k;z;n;x;m] s /\
                bignum_from_memory (x,val n) s = a /\
                bignum_from_memory (m,val k) s = b)
           (\s. read RIP s = returnaddress /\
                read RSP s = word_add stackpointer (word 8) /\
                (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
           (MAYCHANGE [RSP] ,, WINDOWS_MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
            MAYCHANGE [memory :> bignum(z,val k)] ,,
            MAYCHANGE [memory :> bytes(word_sub stackpointer (word 136),136)])`,
  WINDOWS_X86_WRAP_STACK_TAC bignum_mod_windows_tmc bignum_mod_tmc
   BIGNUM_MOD_X86_CORRECT `[RBX; RBP; R12; R13; R14; R15]` 120);;

let BIGNUM_MOD_WINDOWS_SUBROUTINE_CORRECT = prove
 (`!k z n x m a b pc stackpointer returnaddress.
      ALL (nonoverlapping (z,8 * val k))
          [(word pc,LENGTH bignum_mod_windows_mc);
           (word_sub stackpointer (word 136),144)] /\
      ALL (nonoverlapping (word_sub stackpointer (word 136),136))
          [(word pc,LENGTH bignum_mod_windows_mc); (x,8 * val n); (m,8 * val k)] /\
      nonoverlapping (word pc,LENGTH bignum_mod_windows_mc) (x,8 * val n) /\
      nonoverlapping (word pc,LENGTH bignum_mod_windows_mc) (m,8 * val k) /\
      nonoverlapping (z,8 * val k) (x,8 * val n) /\
      nonoverlapping (z,8 * val k) (m,8 * val k) /\
      ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
      ==> ensures x86
           (\s. bytes_loaded s (word pc) bignum_mod_windows_mc /\
                read RIP s = word pc /\
                read RSP s = stackpointer /\
                read (memory :> bytes64 stackpointer) s = returnaddress /\
                WINDOWS_C_ARGUMENTS [k;z;n;x;m] s /\
                bignum_from_memory (x,val n) s = a /\
                bignum_from_memory (m,val k) s = b)
           (\s. read RIP s = returnaddress /\
                read RSP s = word_add stackpointer (word 8) /\
                (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
           (MAYCHANGE [RSP] ,, WINDOWS_MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
            MAYCHANGE [memory :> bignum(z,val k)] ,,
            MAYCHANGE [memory :> bytes(word_sub stackpointer (word 136),136)])`,
  MATCH_ACCEPT_TAC(ADD_IBT_RULE BIGNUM_MOD_NOIBT_WINDOWS_SUBROUTINE_CORRECT));;
